// Function to merge two arrays into one sorted array based on 'int' key values
Record* mergeArrays(int** longOffsets, int** intKeys, int offsetSize, int intKeySize) {
    // Combine the two arrays and sort them based on the 'int' key values
    Record* records = (Record*) malloc((offsetSize + intKeySize) * sizeof(Record));
    for (int i = 0; i < offsetSize; i++) {
        records[i].key = longOffsets[i][0];
    }
    for (int i = 0; i < intKeySize; i++) {
        records[offsetSize + i].key = intKeys[i][0];
    }
    qsort(records, offsetSize + intKeySize, sizeof(Record), compareRecords);
    return records;
}

// Compare function to sort the array of 'record' structures based on 'int' key values
int compareRecords(const void* a, const void* b) {
    Record* recordA = (Record*) a;
    Record* recordB = (Record*) b;
    if (recordA->key < recordB->key) {
        return -1;
    } else if (recordA->key > recordB->key) {
        return 1;
    } else {
        return 0;
    }
}

