    while (fgets(line, MAX_LINE_LENGTH, file)) {
        // Count lines, characters, and words in each line
        line_count++;
        char_count += strlen(line);
        word_count += count_words(line);

        // Perform additional processing on the line content if needed
    }

    log_message(INFO, "Total lines: %d, Characters: %d, Words: %d", line_count, char_count, word_count);
}

// Function to count words in a given string
int count_words(const char* str) {
    int count = 0;
    while (*str != '\0') {
        if (isspace(*str)) {
            // Check for adjacent spaces and skip them
            while (*str == ' ') str++;
            count++;
        }
        str++;
    }

    return count + 1; // Add one for the last word
}

// Function to set the logging level
void set_log_level(int level) {
    // Set the logging level based on the provided value
    // For simplicity, this example sets the logging level to DEBUG
    log_message(DEBUG, "Logging level set to %s", (level == 0 ? "DEBUG" : (level == 1 ? "INFO" : (level == 2 ? "WARN" : "ERROR"))));
}

// Function to log a message with the specified level
void log_message(int level, const char* message) {
    // Log the message based on the logging level and configuration
    if (level >= config.logging_level) {
        fprintf(stdout, "%s: %s\n", (level == 0 ? "DEBUG" : (level == 1 ? "INFO" : (level == 2 ? "WARN" : "ERROR"))), message);
    }
}
