    char input[1000000];

    int* arr = NULL;
    size_t actual_size = 0;

    while (1) {
        // Read from network socket and store in the input buffer
        ssize_t bytes_read = read(STDIN_FILENO, input, 1024);
        if (bytes_read < 0) {
            perror("read");
            break;
        }
        else if (bytes_read == 0) {
            break; // End of file reached
        }

        // Process the received integers
        char* token = strtok(input, " \n");
        while (token) {
            int num;
            if (sscanf(token, "%d", &num) != 1) {
                fprintf(stderr, "Invalid integer: %s\n", token);
                continue;
            }

            // Dynamically allocate and resize the array as needed
            arr = realloc(arr, (actual_size + 1) * sizeof(int));
            if (!arr) {
                perror("realloc");
                break;
            }
            ((int*)arr)[actual_size] = num;

            actual_size++;
        }
    }

    if (*size != actual_size) {
        free(arr);
        arr = NULL;
        *size = 0;
    }

    int largest = max_integer_in_stream(&arr, &actual_size);

    // Print the largest integer
    printf("Largest integer: %d\n", largest);

    // Free all allocated memory and return the largest integer found
