import requests
import json
import logging
import time
from kubernetes import client
from retrying import retry

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger()

def fetch_secret(vault_url, secret_path):
    @retry(wait_fixed=1000, stop_max_attempt_number=3)
    def _fetch_secret():
        try:
            response = requests.get(f"{vault_url}/{secret_path}", verify=False)
            if response.status_code == 200:
                return json.loads(response.content.decode())
            else:
                raise Exception(f"Failed to fetch secret: {response.status_code}")
        except requests.exceptions.RequestException as e:
            raise Exception(f"Network error fetching secret: {e}")

    return _fetch_secret()

def generate_deployment_configplaceholders_dict, vault_url):
    deployment = client.V1Deployment()
    for name, value in placeholders_dict.items():
        if name == "SECRET":
            logger.info("Injecting encrypted secret")
            secret = fetch_secret(vault_url, value)
            if not isinstance(secret, dict) or 'data' not in secret:
                raise Exception("Invalid secret format")
            deployment.spec.template.spec.containers[0].env.append(
                client.V1EnvVar(name='SECRET', value=secret['data']))
        else:
            setattr(deployment.spec.template.spec.containers[0], name, value)
    return deployment

def mainplaceholders_dict):
    try:
        deployment = generate_deployment_config(placeholders_dict)
        with open('deployment.yaml', 'w') as f:
            f.write(deployment.to_yaml())
        logger.info("Deployment configuration generated successfully")
    except Exception as e:
        logger.error(f"Error generating deployment config: {e}")
        raise

if __name__ == "__main__":
    main({
        "NAME": "my-app",
        "IMAGE": "my-image:latest",
        "SECRET": "path/to/secret"
    })
