#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to hold the semaphore's state and logging information
typedef struct {
    sem_t *sem;
    int value;
    FILE *logFile;
} SemaphoreState;

// Function prototypes
void initSemaphore(SemaphoreState* semaphore, int initialValue);
int createSemaphore(SemaphoreState* semaphore, int initialValue);
int deleteSemaphore(SemaphoreState* semaphore);
int modifySemaphoreValue(SemaphoreState* semaphore, int newValue);
int semWait(SemaphoreState* semaphore);
int semSignal(SemaphoreState* semaphore);
void logSemaphoreOperation(const char *operation);

// Function to create a new semaphore with the given initial value
createSemaphore(int initialValue) {
    SemaphoreState* semaphore = (SemaphoreState*)malloc(sizeof(SemaphoreState));
    initSemaphore(semaphore, initialValue);
    return semaphore;
}

// Function to initialize the semaphore's state and logging information
initSemaphore(SemaphoreState* semaphore, int initialValue) {
    // Initialize the semaphore with the given initial value
    sem_init(&semaphore->sem, 0, initialValue);

    // Set the initial semaphore value
    semaphore->value = initialValue;

    // Open the log file for writing
    semaphore->logFile = fopen("semaphore.log", "a");
}

// Function to delete a semaphore and release any system resources it may be holding onto
deleteSemaphore(SemaphoreState* semaphore) {
    // Close the log file
    fclose(semaphore->logFile);

    // Destroy the semaphore
    sem_destroy(&semaphore->sem);

    // Free the memory allocated for the semaphore's state and logging information
    free(semaphore);
}

// Function to modify the semaphore's value without causing race conditions
modifySemaphoreValue(SemaphoreState* semaphore, int newValue) {
    // Atomically set the new value using sem_wait and sem_signal
    while (sem_wait(&semaphore->sem) == -1 || !sem_trywait(&semaphore->sem)) {
        // Log any errors or failures that occurred during the operation
        logSemaphoreOperation("Modify failure");
    }

    semaphore->value = newValue;

    sem_signal(&semaphore->sem);

    return 0;
}

// Function to wait on a semaphore without causing race conditions
semWait(SemaphoreState* semaphore) {
    // Atomically wait for the semaphore using sem_wait and sem_signal
    while (sem_wait(&semaphore->sem) == -1 || !sem_trywait(&semaphore->sem)) {
        // Log any errors or failures that occurred during the operation
        logSemaphoreOperation("Wait failure");
    }

    return 0;
}

// Function to signal a semaphore without causing race conditions
semSignal(SemaphoreState* semaphore) {
    // Atomically signal the semaphore using sem_signal and sem_wait
    while (sem_signal(&semaphore->sem) == -1 || !sem_trywait(&semaphore->sem)) {
        // Log any errors or failures that occurred during the operation
        logSemaphoreOperation("Signal failure");
    }

    return 0;
}

// Function to handle semaphore operations and log any failures that occur
logSemaphoreOperation(const char *operation) {
    fprintf(semaphore->logFile, "%s: %s\n", operation, strerror(errno));
    fclose(semaphore->logFile);
}
