['```cpp
#include <chrono>
#include <thread>
#include <mutex>
#include <iostream>

namespace Logging {

    enum LogLevel { DEBUG, INFO, WARN, ERROR };

    class Logger {
    public:
        static void log(LogLevel level, const std::string& message) {
            // Add timestamp
            auto timestamp = std::chrono::high_resolution_clock::now();
            std::string formattedMessage = "[" + std::to_string(timestamp.time_since_epoch().count()) + "] - " + message;

            // Handle logging levels
            switch (level) {
                case DEBUG:
                    if (isDebugEnabled())
                        std::cout << "DEBUG: " << formattedMessage << std::endl;
                    break;
                case INFO:
                    if (isInfoEnabled())
                        std::cout << "INFO: " << formattedMessage << std::endl;
                    break;
                case WARN:
                    if (isWarnEnabled())
                        std::cout << "WARN: " << formattedMessage << std::endl;
                    break;
                case ERROR:
                    if (isErrorEnabled())
                        std::cout << "ERROR: " << formattedMessage << std::endl;
                    break;
            }
        }

    private:
        static bool isDebugEnabled() {
            return getGlobalLogLevel() >= DEBUG;
        }
        static bool isInfoEnabled() {
            return getGlobalLogLevel() >= INFO;
        }
        static bool isWarnEnabled() {
            return getGlobalLogLevel() >= WARN;
        }
        static bool isErrorEnabled() {
            return getGlobalLogLevel() >= ERROR;
        }

        static LogLevel getGlobalLogLevel() {
            static std::mutex globalMutex;
            static LogLevel globalLogLevel = INFO;

            std::lock_guard<std::mutex> lock(globalMutex);
            return globalLogLevel;
        }

        static void setGlobalLogLevel(LogLevel level) {
            static std::mutex globalMutex;
            static LogLevel globalLogLevel = INFO;

            std::lock_guard<std::mutex> lock(globalMutex);
            globalLogLevel = level;
        }
    };

} // namespace Logging

int main() {
    Logging::Logger::log(Logging::DEBUG, "This is a debug message");
    Logging::Logger::log(Logging::INFO, "This is an info message");
    Logging::setGlobalLogLevel(Logging::ERROR);
    Logging::Logger::log(Logging::DEBUG, "This is another debug message");

    return 0;
}
