['```csharp
using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class AsyncHttpClient
{
    public async Task<Dictionary<string, string>> SendBatchRequestsAsync(List<string> urls, int timeout, int maxConcurrency)
    {
        var responses = new Dictionary<string, string>();

        // Create a semaphore to control concurrency level
        var semaphore = newSemaphoreSlim(maxConcurrency);

        foreach (var url in urls)
        {
            await semaphore.WaitAsync();

            try
            {
                var request = new HttpRequestMessage(HttpMethod.Get, url);
                var response = await SendRequestAsync(request, timeout);

                if (response.IsSuccessStatusCode)
                {
                    responses[url] = await response.Content.ReadAsStringAsync();
                }
                else
                {
                    // Handle failed requests with retries
                    for (int i = 0; i < 3; i++)
                    {
                        try
                        {
                            response = await SendRequestAsync(request, timeout);
                            if (response.IsSuccessStatusCode)
                            {
                                responses[url] = await response.Content.ReadAsStringAsync();
                                break;
                            }
                        }
                        catch (Exception ex)
                        {
                            // Log and handle exceptions
                        }

                        if (i == 2)
                        {
                            responses[url] = $"Request {url} failed with status code {response.StatusCode}";
                        }
                    }
                }
            }
            finally
            {
                semaphore.Release();
            }
        }

        return responses;
    }

    private async Task<HttpResponseMessage> SendRequestAsync(HttpRequestMessage request, int timeout)
    {
        using (var client = new HttpClient())
        {
            client.Timeout = TimeSpan.FromMilliseconds(timeout);

            try
            {
                return await client.SendAsync(request);
            }
            catch (HttpRequestException ex)
            {
                // Handle HTTP exceptions
                throw;
            }
        }
    }
}

class Program
{
    static void Main()
    {
        var urls = new List<string> { "url1", "url2", "url3" };
        var timeout = 5000; // 5 seconds
        var maxConcurrency = 10;

        var client = new AsyncHttpClient();
        var responses = await client.SendBatchRequestsAsync(urls, timeout, maxConcurrency);

        Console.WriteLine(responses);
    }
}
