using System;
using System.IO;
using System.Linq;
using System.Xml.Linq;

public static class DirectoryAndXmlUtility
{
    public static XElement GetFirstXmlElement(string directoryName, string tagName)
    {
        var dirPath = CreateDirectoryIfNotExists(directoryName);
        var xmlFiles = Directory.GetFiles(dirPath, "*.xml");

        if (xmlFiles.Length > 0)
        {
            var xmlFile = xmlFiles[0];
            try
            {
                using var xmlDoc = XDocument.Load(xmlFile);
                return xmlDoc.Root?.Element(tagName).FirstOrDefault();
            }
            catch (Exception ex)
            {
                // Log warning and return null on exception
                Console.WriteLine($"Warning: Error processing XML file {xmlFile}: {ex.Message}");
                return null;
            }
        }
        else
        {
            // Log warning if no XML files found
            Console.WriteLine($"Warning: No XML files found in directory {dirPath}");
            return null;
        }
    }

    private static string CreateDirectoryIfNotExists(string directoryName)
    {
        var dirPath = Environment.GetEnvironmentVariable("DirectoryPath") + directoryName;
        if (!Directory.Exists(dirPath))
        {
            try
            {
                Directory.CreateDirectory(dirPath);
                Environment.SetEnvironmentVariable("DirectoryPath", Path.Combine(Environment.GetEnvironmentVariable("DirectoryPath"), directoryName));
            }
            catch (Exception ex)
            {
                // Log error on directory creation failure
                Console.WriteLine($"Error creating directory {dirPath}: {ex.Message}");
                return null;
            }
        }
        return dirPath;
    }
}
