        List<String> trimmedStrings = new ArrayList<>();

        for (String str : strings) {
            try {
                str = str.trim();
                if (result.length() + str.length() > 10000) {
                    throw new InputTooLongException("Total input length exceeds 10,000 characters");
                }
                result.append(str);
            } catch (IOException e) {
                // Handle I/O exceptions
                throw new IOException("Error processing string: " + str, e);
