async function readFiles(directory, extension) {
  const fs = require('fs');
  const path = require('path');
  const logging = require('./logging'); // assuming a custom logging framework
  let statistics = { success: 0, skipped: 0 };

  async function readDirectory(path) {
    return new Promise((resolve, reject) => {
      fs.readdir(path, (err, files) => {
        if (err) reject(err);
        else resolve(files);
      });
    });
  }

  async function processFiles(files, page = 1, limit = 1000) {
    const offset = (page - 1) * limit;
    return new Promise((resolve, reject) => {
      fs.readdir(`${directory}/`, (err, files) => {
        if (err) reject(err);
        else resolve(files.slice(offset, offset + limit));
      });
    }).then((files) => {
      return Promise.all(
        files.map((file) => {
          const filePath = path.join(directory, file);
          return fs.stat(filePath).then((stats) => {
            if (!stats.isDirectory()) {
              if (path.extname(file) === `.${extension}`) {
                return readFileSync(filePath);
              } else {
                statistics.skipped++;
                logging.log(`Skipped file: ${file}`);
              }
            } else {
              statistics.skipped++;
              logging.log(`Skipping directory: ${filePath}`);
            }
          });
        })
      ).then((results) => {
        resolve({ files: results.join('\n'), statistics });
      }).catch((err) => {
        reject(err);
      });
    });
  }

  async function readFileSync(filePath) {
    return new Promise((resolve, reject) => {
      fs.readFile(filePath, (err, data) => {
        if (err) reject(err);
        else resolve(data.toString());
      });
    });
  }

  try {
    const files = await readDirectory(directory);
    let concatenatedFiles = '';
    for (let i = 1; i <= Math.ceil(files.length / 1000); i++) {
      const result = await processFiles(files, i);
      concatenatedFiles += result.files;
      statistics.success += result.files.split('\n').length - 1;
    }
    return { files: concatenatedFiles, statistics };
  } catch (err) {
    logging.log(`Error processing files: ${err}`);
    return { files: '', statistics };
  }
}

