const require = require('require');
const log = require('log4js').getLogger();
const parallel = require('child_process');
const async = require('async');

function runTests(label, f, environment, parallel) {
  let testsPassed = 0;
  let testsFailed = 0;
  let testsSkipped = 0;
  let totalTestTime = 0;

  try {
    if (environment === 'development') {
      // Load module for development environment
      const module = require('./module');
      f(module);
    } else if (environment === 'production') {
      // Load module for production environment
      const module = require('./module-production');
      f(module);
    } else {
      log.warn('Unknown environment: ' + environment);
      return;
    }

    if (parallel) {
      const maxParallelTests = 4; // Adjust based on available CPU cores
      const resourceLimits = { cpu: 2, memory: 512 };

      async.parallelLimit(
        [...Array(maxParallelTests)].map(() => {
          return (cb) => {
            try {
              f();
              testsPassed++;
              cb(null);
            } catch (err) {
              testsFailed++;
              log.error('Test failed: ' + err);
              cb(err);
            }
          };
        }),
        resourceLimits,
        (err, results) => {
          if (err) {
            log.error('Error running parallel tests: ' + err);
          } else {
            log.info('Parallel test execution complete');
          }
        }
      );
    } else {
      try {
        f();
        testsPassed++;
      } catch (err) {
        testsFailed++;
        log.error('Test failed: ' + err);
      }
    }

    totalTestTime = process.hrtime()[0] * 1000;

    log.info(`Tests completed in ${totalTestTime}ms`);
    log.info(`Tests passed: ${testsPassed}`);
    log.info(`Tests failed: ${testsFailed}`);
    log.info(`Tests skipped: ${testsSkipped}`);
  } catch (err) {
    log.error('Error running tests: ' + err);
  }
}

module.exports = runTests;
