function appendFooterScripts(scripts) {
  const footer = document.createElement('footer');
  let scriptsHTML = '';

  scripts.forEach((script, index) => {
    if (!script.code) return; // Ignore scripts without a code property

    scriptsHTML += `
      <script${script.async ? ' async' : ''}
             ${script.defer ? ' defer' : ''}
             ${script.type ? ` type="${script.type}"` : ''}
             >${escape(script.code)}</script>
    `;
  });

  footer.innerHTML = scriptsHTML;
  document.body.appendChild(footer);
}

function escape(str) {
  return str.replace(/[&<>]/g, (match) => {
    switch (match) {
      case '&':
        return '&amp;';
      case '<':
        return '&lt;';
      case '>':
        return '&gt;';
    }
  });
}
