function refreshDialogFields(resourceId, url) {
  const dialogFields = [];
  const visibleFields = angular.element('#dialog').scope().fields;

  visibleFields.forEach((field) => {
    if (field.resourceId === resourceId) {
      dialogFields.push({ field: field, lazyLoaded: false });
    }
  });

  const pendingRequests = [];

  dialogFields.forEach((field) => {
    if (!field.lazyLoaded) {
      pendingRequests.push(requestFieldData(field.field.id));
    }
  });

  function requestFieldData(fieldId) {
    return new Promise((resolve, reject) => {
      // Simulate async data loading
      setTimeout(() => {
        const fieldData = getFieldDataFromUrl(url, fieldId);
        resolve({ fieldId, fieldData });
      }, 500);
    });
  }

  function getFieldDataFromUrl(url, fieldId) {
    // Simulate retrieving field data from URL
    return { [fieldId]: 'Loaded field data' };
  }

  Promise.all(pendingRequests).then((responses) => {
    responses.forEach((response) => {
      const { fieldId, fieldData } = response;
      const existingFieldIndex = dialogFields.findIndex((field) => field.field.id === fieldId);

      if (existingFieldIndex !== -1) {
        dialogFields[existingFieldIndex].lazyLoaded = true;
        dialogFields[existingFieldIndex].field.data = fieldData;
      }
    });
  });
}
