**C++ Function (Doubly Linked List)**

```cpp
#include <iostream>
#include <string>

using namespace std;

struct Node {
  string data;
  Node* prev, *next;
};

class DoublyLinkedList {
public:
  void insert(string data) {
    if (!head) {
      head = tail = new Node{data, nullptr, nullptr};
    } else {
      Node* newNode = new Node{data, tail, nullptr};
      tail->next = newNode;
      tail = newNode;
    }
  }

  void remove(const string& targetData) {
    Node* current = head;

    while (current) {
      if (current->data == targetData) {
        if (current->prev) {
          current->prev->next = current->next;
          if (!current->next) {
            tail = current->prev;
          }
        } else {
          head = current->next;
        }

        delete current;
        return;
      }

      current = current->next;
    }

    cout << "Data not found in the list." << endl;
  }

  void printList() const {
    Node* current = head;

    while (current) {
      cout << current->data << " ";
      current = current->next;
    }
    cout << endl;
  }

private:
  Node* head, *tail;
};
