function mergeBuffers(...buffers) {
    const mergedBuffer = new Uint8Array(buffers.reduce((acc, buffer) => acc + buffer.length, 0));
    let offset = 0;

    for (const buffer of buffers) {
        if (buffer.length % 4 !== 0) {
            // Pad the buffer to ensure correct alignment
            const paddingLength = 4 - (buffer.length % 4);
            buffer = new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.length + paddingLength);
        }

        mergedBuffer.set(new Uint8Array(buffer), offset);
        offset += buffer.length;
    }

    return mergedBuffer;
}
