function traverseDOM(root, selectors) {
  const result = [];
  const listeners = [];

  function processElement(element) {
    for (const selector of selectors) {
      if (element.matches(selector)) {
        const matchingElements = Array.from(element.querySelectorAll(selector));
        for (const elem of matchingElements) {
          if (!result.includes(elem)) {
            result.push(elem);
          }
          if (elem.hasAttribute('data-event-listener')) {
            listeners.push({ element: elem, listener: elem.getAttribute('data-event-listener') });
          }
        }
      }
    }
  }

  function traverse(node) {
    processElement(node);

    const childNodes = Array.from(node.childNodes);
    for (const child of childNodes) {
      if (child.nodeType === Node.ELEMENT_NODE) {
        traverse(child);
      } else if (child.nodeType === Node.TEXT_NODE && child.nodeValue.trim()) {
        traverseTextNode(child);
      }
    }
  }

  function traverseTextNode(textNode) {
    const textContent = textNode.nodeValue;
    for (const selector of selectors) {
      if (textContent.includes(selector)) {
        processElement(textNode.parentNode);
      }
    }
  }

  traverse(root);

  listeners.forEach((listener) => {
    listener.element.removeAttribute('data-event-listener');
  });

  return result;
}
