function loadAndExecuteScripts(folderPath) {
  const scriptTags = [];
  const scriptsToLoad = getAllFilesInFolder(folderPath);

  for (const file of scriptsToLoad) {
    const fileName = file.name;
    let newFileName;

    // Modify the file extension based on the original filename
    if (fileName.includes('js')) {
      newFileName = sprintf('%s-%d.js', fileName, getUniqueId());
    } else if (fileName.includes('css')) {
      newFileName = sprintf('%s-%d.css', fileName, getUniqueId());
    } else {
      continue;
    }

    // Load the script and add it to the DOM
    const scriptTag = document.createElement('script');
    scriptTag.src = folderPath + '/' + newFileName;
    document.head.appendChild(scriptTag);

    // Ensure the script is executed in the correct order
    scriptTags.push(scriptTag);
  }

  // Execute the scripts in the correct order
  for (const tag of scriptTags) {
