import java.util.*;

public class SessionAnalyzer {
    public Map<String, Long> analyzeSessions(List<String> logEntries) {
        Map<String, Long> sessions = new HashMap<>();
        long totalDuration = 0;

        for (String logEntry : logEntries) {
            String[] parts = logEntry.split(",");
            String timestamp = parts[0];
            String activityType = parts[1];
            long duration = Long.parseLong(parts[2]);

            if (activityType.equals("login") && isConsecutiveLogin(logEntries, Integer.parseInt(timestamp))) {
                sessions.computeIfAbsent(timestamp, k -> new ArrayList<>()).add(duration);
            }
        }

        for (List<Long> session : sessions.values()) {
            long maxSessionDuration = 0;
            for (int i = 0; i < session.size() - 2; i++) {
                if (session.get(i) > 30000 && isConsecutiveLogin(logEntries, Integer.parseInt(timestamp.substring(1))) {
                    maxSessionDuration = session.get(i);
                    break;
                }
            }

            totalDuration += maxSessionDuration;
        }

        System.out.println("Total duration: " + totalDuration);

        return sessions;
    }

    private boolean isConsecutiveLogin(List<String> logEntries, int timestamp) {
        for (String logEntry : logEntries) {
            String[] parts = logEntry.split(",");
            if (parts[1].equals("login") && Integer.parseInt(parts[0]) == timestamp + 1) {
                return true;
            }
        }

        return false;
    }
}
