use std::process::{Command, ExitCode};
use std::fs::read_dir;
use std::time::{Instant, Duration};
use std::mem;
use log::{info, error};

fn compile_project(path: &str) -> ExitCode {
    let start_time = Instant::now();
    let mut rss1 = mem::size_of_process() as f64;

    match Command::new("rustc")
        .arg("-Z")
        .arg("--pretty")
        .arg("--emit=llvm-ir")
        .arg(path)
        .output()
    {
        Ok(output) => {
            let exit_code = ExitCode::from_raw(output.status().as_u64());
            let duration = start_time.elapsed();
            let rss2 = mem::size_of_process() as f64;

            let compile_duration = format!("Compile Duration: {:?}", duration);
            let memory_usage = format!("Memory Usage (before/after): {:.2} / {:.2} MB", rss1 / 1024.0, rss2 / 1024.0);

            info!("Compile Finished");
            info!("{}", compile_duration);
            info!("{}", memory_usage);

            exit_code
        }
        Err(err) => {
            let error_message = format!("Error: {}", err);
            error!("{}", error_message);
            ExitCode::from_raw(1)
        }
    }
}

fn main() {
    if let Some(arg) = std::env::args().nth(1) {
        compile_project(&arg);
    } else {
        eprintln!("Please provide a Rust project directory as an argument");
    }
}
