function generatePEMCertificate(oauthRequest) {
  const storageEndpoints = oauthRequest.storageEndpoints;
  const privateKeyName = 'privateKey.pem';
  const certificateName = 'certificate.pem';

  async function retrievePrivateKey(endpoint) {
    try {
      const response = await fetch(endpoint + '/' + privateKeyName);
      if (!response.ok) throw new Error('Failed to retrieve private key');
      return await response.arrayBuffer();
    } catch (error) {
      console.error(`Error retrieving private key from ${endpoint}: ${error}`);
      throw error;
    }
  }

  async function retrieveCertificate(endpoint) {
    try {
      const response = await fetch(endpoint + '/' + certificateName);
      if (!response.ok) throw new Error('Failed to retrieve certificate');
      return await response.arrayBuffer();
    } catch (error) {
      console.error(`Error retrieving certificate from ${endpoint}: ${error}`);
      throw error;
    }
  }

  async function generateCertificate() {
    const privateKeys = {};
    const certificates = {};

    for (const endpoint of storageEndpoints) {
      try {
        const privateKeyBuffer = await retrievePrivateKey(endpoint);
        const certificateBuffer = await retrieveCertificate(endpoint);

        if (!privateKeys[endpoint]) {
          privateKeys[endpoint] = Buffer.from(privateKeyBuffer);
        }

        if (!certificates[endpoint]) {
          certificates[endpoint] = Buffer.from(certificateBuffer);
        }
      } catch (error) {
        console.error(`Error fetching data from ${endpoint}: ${error}`);
        await new Promise((resolve, reject) => setTimeout(resolve, 5000)); // retry after 5 seconds
        continue;
      }
    }

    const combinedPrivateKey = Buffer.concat(Object.values(privateKeys));
    const combinedCertificate = Buffer.concat(Object.values(certificates));

    return { privatekey: combinedPrivateKey.toString('base64'), certificate: combinedCertificate.toString('base64') };
  }

  async function generateAndStreamPEMCertificate() {
    let certificate;
    try {
      certificate = await generateCertificate();
    } catch (error) {
      console.error(`Error generating PEM certificate: ${error}`);
      return null;
    }

    const { privatekey, certificate } = certificate;

    // stream the certificate
    const fs = require('fs');
    const writeStream = fs.createWriteStream('output.pem');

    writeStream.write(`-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----\n`);
    writeStream.write(`-----BEGIN RSA PRIVATE KEY-----\n${privatekey}\n-----END RSA PRIVATE KEY-----\n`);

    return new Promise((resolve, reject) => {
      writeStream.on('close', () => resolve());
      writeStream.on('error', (err) => reject(err));
    });
  }

  return generateAndStreamPEMCertificate();
}
