struct OctreeNode {
    int value;
    std::vector<OctreeNode*> children;
};

class Octree {
private:
    int featureSize;
    int maxDepth;
    int leafNodeCount;
    int capacity;
    OctreeNode* root;

public:
    void init(int size, int leafNodes, int maxDepthLevel, int initialCapacity) {
        this->featureSize = size;
        this->maxDepth = maxDepthLevel;
        this->leafNodeCount = leafNodes;
        this->capacity = initialCapacity;
        root = new OctreeNode();
        root->value = -1;  // or some default value
        buildOctree(root, 0);
    }

private:
    void buildOctree(OctreeNode* node, int depth) {
        if (depth < maxDepth && node->children.empty()) {
            for (int i = 0; i < (1 << 3); ++i) {
                OctreeNode* child = new OctreeNode();
                child->value = -1;
                node->children.push_back(child);
            }
            if (depth + 1 == maxDepth) {
                // fill leaf nodes
                for (int i = 0; i < leafNodeCount; ++i) {
                    OctreeNode* leaf = new OctreeNode();
                    leaf->value = i;  // or some default value
                    node->children[i]->value = leaf->value;
                }
            } else {
                buildOctree(node->children[0], depth + 1);
                buildOctree(node->children[7], depth + 1);
                buildOctree(node->children[4], depth + 1);
                buildOctree(node->children[5], depth + 1);
                buildOctree(node->children[2], depth + 1);
                buildOctree(node->children[3], depth + 1);
                buildOctree(node->children[6], depth + 1);
                buildOctree(node->children[1], depth + 1);
            }
        }
    }
};
