#define MAX_BUFFER_SIZE 1024
#define SLIDING_WINDOW_SIZE 50
#define CHECKSUM_VALID 0xFFD5

typedef struct {
    uint32_t sequence_number;
    uint16_t size;
    uint8_t checksum;
} PacketMetadata;

PacketMetadata* buffer[MAX_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
uint32_t packet_loss_count = 0;
uint32_t duplicate_count = 0;
uint32_t highest_valid_checksum = 0xFFD4;
time_t window_start_time = time(NULL);

bool is_packet_valid(PacketMetadata* packet) {
    // Check if the packet size and checksum are valid
    return (packet->size > 0 && packet->checksum == CHECKSUM_VALID);
}

void update_buffer(PacketMetadata* packet, int new_tail) {
    buffer[new_tail] = packet;
    buffer_tail = new_tail;
    while (buffer[buffer_head].sequence_number < packet->sequence_number - SLIDING_WINDOW_SIZE) {
        for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
            if (buffer[i] == NULL) {
                buffer[i] = buffer[buffer_head];
                break;
            }
        }
        buffer_head++;
    }
}

void process_packet(PacketMetadata* packet) {
    // Check if the packet is valid
    if (!is_packet_valid(packet)) return;

    int new_tail = (packet->sequence_number % MAX_BUFFER_SIZE);
    update_buffer(packet, new_tail);

    // Check for duplicate packets
    for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
        if (buffer[i] != NULL && buffer[i]->sequence_number == packet->sequence_number) {
            duplicate_count++;
            return;
        }
    }

    // Check the packet size and frequency within the sliding window
    int packet_loss = 0;
    for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
        if (buffer[i] != NULL && buffer[i]->size > packet->size) {
            packet_loss++;
        }
    }

    // Update the highest valid checksum value
    if (packet->checksum > highest_valid_checksum)
        highest_valid_checksum = packet->checksum;

    // Log packet processing statistics
    time_t current_time = time(NULL);
    double latency = difftime(current_time, window_start_time) * 1000;
    printf("Received packet with sequence number %u and size %hu. Latency: %.3f ms.\n", packet->sequence_number, packet->size, latency);

    // Increment packet loss count if necessary
    if (packet_loss > 0)
        packet_loss_count += packet_loss;

    window_start_time = current_time;
}

int main() {
    PacketMetadata* packet = (PacketMetadata*)malloc(sizeof(PacketMetadata));
    // Initialize the packet metadata
    // Process packets here and call process_packet(packet);
    free(packet);
    return 0;
}
