class CombatController {
public:
    CombatController() : cooldowns({1, 6}, {2, 9}, {3, 12}), currentAttack(0), lock_(std::make_unique<std::mutex>()), cv_() {}

    int getAttack() {
        std::unique_lock<std::mutex> lock(*lock_);
        while (cooldowns[currentAttack] > 0) {
            cv_.wait(lock);
        }
        if (!selectNextAttack()) {
            return -1; // No attack available
        }
        return currentAttack;
    }

private:
    struct Cooldown {
        int cooldownTimeSeconds;
        std::atomic<int> timeLeft{cooldownTimeSeconds};
    };

    std::map<int, Cooldown> cooldowns;
    int currentAttack;
    std::unique_ptr<std::mutex> lock_;
    std::condition_variable cv_;

    bool selectNextAttack() {
        if (currentAttack >= cooldowns.size()) {
            return false; // No more attacks available
        }
        for (int i = 0; i < currentAttack; ++i) {
            --cooldowns[i].timeLeft;
            if (cooldowns[i].timeLeft <= 0) {
                --i;
            } else {
                break;
            }
        }
        for (int i = currentAttack + 1; i < cooldowns.size(); ++i) {
            ++cooldowns[i].timeLeft;
        }
        if (!cooldowns[currentAttack].timeLeft) {
            return false; // No attack available
        }
        return true;
    }

    void logSelectedAttack(int selectedAttack) {
        // Log the attack to a central server for analytics purposes
    }
};
