using System;
using UnityEngine;

public class ValueRangeGenerator
{
    private float minValue;
    private float maxValue;

    public ValueRangeGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Invalid range. minValue cannot be greater than maxValue.");
        }

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomInt(int min, int max)
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    public int GenerateRandomIntInclusive()
    {
        return new Random().Next(minValue, maxValue + 1);
    }

    public bool GenerateRandomBoolean()
    {
        return UnityEngine.Random.value > (maxValue - minValue) / 2;
    }

    public override string ToString()
    {
        if (typeof(float).IsAssignableFrom(typeof(float)))
            return $"[{minValue}, {maxValue})";
        else
            return $"[{minValue}, {maxValue}]";
    }

    public string ToJsonString()
    {
        return "{\"MinValue\":\"" + minValue + "\",\"MaxValue\":\"" + maxValue + "\"}";
    }
}
