async function reduceAsync(arr, initialValue, reducer) {
  let accumulator = initialValue;
  const metadata = [];

  await arr.reduce((acc, current, index, array) => {
    try {
      const result = await reducer(current);
      if (result !== null && !isNaN(result)) {
        accumulator = result;
      } else {
        throw new Error('Invalid reduction result');
      }
    } catch (error) {
      // Handle asynchronous errors
      console.error(`Error at index ${index}:`, error);
      return Promise.reject(error);
    }
    metadata.push({ index, value: accumulator });
  }, initialValue);

  return { value: accumulator, metadata };
}
