#define MAX_SETTINGS 1000
#define MAX_SETTING_NAME 256
#define MAX_SOURCE_LENGTH 64

typedef struct {
    char name[MAX_SETTING_NAME];
    char value[MAX_SETTING_NAME];
    int source;
} Setting;

Setting* load_settings_from_file(const char* file_path) {
    libconfig::config cfg;
    if (!cfg.readFile(file_path)) {
        return NULL; // error reading file
    }

    Setting* settings = (Setting*)malloc(sizeof(Setting) * MAX_SETTINGS);
    int num_settings = 0;

    std::string section_name;
    for (auto& pair : cfg.sections()) {
        section_name = pair.first;
        for (auto& item : pair.second.items()) {
            char setting_name[MAX_SETTING_NAME];
            strcpy(setting_name, item.name().c_str());
            char setting_value[MAX_SETTING_NAME];
            strcpy(setting_value, item.value().c_str());

            Setting* setting = &settings[num_settings++];
            strcpy(setting->name, setting_name);
            strcpy(setting->value, setting_value);
            setting->source = libconfig::SECTION_FILE;
        }
    }

    return settings;
}

Setting* load_settings_from_env() {
    // implement environment variable parsing logic here
    // for example:
    Setting* settings = (Setting*)malloc(sizeof(Setting) * 1); // assume at most one setting from env
    Setting* setting = &settings[0];
    strcpy(setting->name, "MY_SETTING");
    strcpy(setting->value, getenv("MY_SETTING_VALUE"));
    setting->source = libconfig::SECTION_ENV;

    return settings;
}

int load_settings(int* num_settings) {
    // primary file loading
    Setting* file_settings = load_settings_from_file("primary.config");

    if (file_settings == NULL) {
        return -1; // error reading file
    }

    *num_settings += strlen(file_settings->name);

    // environment variable override
    Setting* env_settings = load_settings_from_env();

    if (env_settings != NULL && env_settings[0].source == libconfig::SECTION_ENV) {
        for (int i = 0; i < MAX_SETTINGS; i++) {
            if (file_settings[i].name[0] == '\0') {
                strcpy(file_settings[i].name, env_settings->name);
                strcpy(file_settings[i].value, env_settings->value);
                file_settings[i].source = libconfig::SECTION_ENV;
                break;
            }
        }
    }

    int count = 0;
    for (int i = 0; i < MAX_SETTINGS; i++) {
        if (!strcmp(file_settings[i].name, "")) {
            break;
        }
        strcpy(count);
    }
    return count;
}

int main() {
    int num_settings;
    Setting* settings = load_settings(&num_settings);

    // print settings
    for (int i = 0; i < num_settings; i++) {
        printf("Name: %s, Value: %s, Source: %d\n", settings[i].name, settings[i].value, settings[i].source);
    }

    free(settings);
    return 0;
}
