char* appendSlashIfWithinLimit(char* str, int sizeLimit, bool (*validate)(const char*)) {
    if (!str || !validate) return NULL;

    int len = strlen(str);
    if (len + 1 > sizeLimit) return NULL;

    char* result = malloc(sizeLimit + 2);
    if (!result) return NULL;

    strcpy(result, str);
    if (len < sizeLimit - 1) strcat(result, "/");

    return result;
}

