function findMatchingElements(rootNode, selector, validate) {
    let matches = [];
    const traverse = (node) => {
        if (!node) return;

        if (node.nodeType === Node.ELEMENT_NODE && node.nodeName === selector) {
            const text = node.textContent.trim();
            const attributes = Array.from(node.attributes).reduce((acc, attr) => `${acc}${attr.name}="${attr.value}"`, '');

            let validatedText = validate(text);
            if (!validatedText || !attributes.includes(selector)) return;

            matches.push({
                nodeName: node.nodeName,
                textContent: text,
                attributes
            });
        }

        Array.from(node.children).forEach((child) => traverse(child));
    };

    traverse(rootNode);

    return matches;
}
