ProcessedImageAndHash processImageAndComputeHash(const char* filePath, const char* inputString, const Configuration* config) {
    TIFF *tiff = TIFFOpen(filePath, "r");

    if (!tiff) {
        // handle error
    }

    ImageData imageData;
    uint16_t samplePerPixel;
    uint16_t bitsPerSample;
    uint32_t extraSamplesCount;

    TIFFGetField(tiff, TIFF_FIELD_IMAGE_WIDTH, &samplePerPixel);
    TIFFGetField(tiff, TIFF_FIELD_BITS_PER_SAMPLE, &bitsPerSample);
    TIFFGetField(tiff, TIFF_FIELD_EXTRASAMPLES, &extraSamplesCount);

    imageData.samplePerPixel = samplePerPixel;
    imageData.bitsPerSample = bitsPerSample;

    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        // log warning
    }

    int extraSamples = extraSamplesCount;

    if (extraSamples > config->maxAllowedExtraSamples) {
        // adjust processing flow dynamically
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, inputString, strlen(inputString));
    SHA256_Final(hash, &sha256);

    ProcessedImageAndHash result;
    memcpy(result.hash, hash, SHA256_DIGEST_LENGTH);
    result.imageData = imageData;
    result.extraSamples = extraSamples;

    return result;
}
