char* modify_filename_extension(char* filename) {
    int num_digits = 0;
    char* dot_pos = NULL;

    // Find the last dot (.) in the filename and count the digits before it
    for(dot_pos = filename; *dot_pos && *dot_pos != '.'; dot_pos++) {
        if(*dot_pos >= '0' && *dot_pos <= '9')
            num_digits++;
        else if(*dot_pos == '.') {
            break;
        }
    }

    // If no dots are found, default to 3 digits
    if(!dot_pos || !*dot_pos) {
        num_digits = 3;
    }

    // Remove spaces from the filename and truncate it to 255 characters
    char temp_filename[256] = {0};
    int i = 0;
    for(; *filename && i < 255; filename++, i++) {
        if(*filename != ' ') {
            temp_filename[i] = *filename;
        } else {
            break;
        }
    }

    // Calculate the length of the new filename
    int new_len = strlen(temp_filename) + num_digits + 4;

    // Allocate memory for the new filename
    char* new_filename = (char*)malloc(new_len);

    // Construct the new filename using sprintf and strcat
    sprintf(new_filename, "%s%03d.txt", temp_filename, num_digits);
    free(temp_filename);

    return new_filename;
}
