pid_t execute_command(char *command) {
    pid_t child_pid = fork();

    if (child_pid == 0) { // Child process
        if (execlp(command, command, NULL) == -1) {
            return -1;
        }
    } else if (child_pid > 0) { // Parent process
        return child_pid;
    } else { // Fork failed
        return -1;
    }
}

void handle_sigint(int sig) {
    int status;
    pid_t child_pid = waitpid(-1, &status, 0);

    if (child_pid < 0) {
        perror("waitpid");
    } else if (WIFEXITED(status)) {
        printf("Child process %d exited with status %d\n", child_pid, WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        printf("Child process %d terminated due to signal %d\n", child_pid, WTERMSIG(status));
    }

    return;
}

int main() {
    char *command = "/bin/bash"; // Replace with your command

    if ((pid_t)execute_command(command) == -1) {
        printf("Command execution failed\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        sleep(1); // Simulate main program activity
    }

    return 0;
}
