public void AddAndStartSite(string directoryPath, string siteName)
{
    // Task 1: Validation
    if (!Directory.Exists(directoryPath))
    {
        throw new DirectoryNotFoundException($"The directory '{directoryPath}' was not found.");
    }
    if (!File.Exists(Path.Combine(directoryPath, "web.config")))
    {
        // Generate minimal configuration template
        File.Copy(@"C:\Path\To\Template\web.config", Path.Combine(directoryPath, "web.config"));
    }

    // Task 2: Service Management
    try
    {
        var iisService = Server.Get("W3SVC/1/Root");
        if (!iisService.State == WebServerState.Started)
        {
            iisService.Start();
        }
    }
    catch (Exception ex)
    {
        // Handle service startup failures gracefully
        Console.WriteLine($"IIS Service failed to start: {ex.Message}");
        try
        {
            Server.Stop("W3SVC/1/Root");
        }
        catch
        {
            // Log the error and provide an alternative for users
            Console.WriteLine("Failed to stop IIS Service. Please restart it manually.");
        }
    }

    // Task 3: Integration Layer
    try
    {
        var apiResponse = await CallExternalServiceApiAsync(siteName);
        if (apiResponse.IsSuccessStatusCode)
        {
            // API registration successful, update the site's dependencies
            UpdateDependencies(apiResponse.Content);
        }
        else
        {
            throw new Exception($"API request failed with status code {apiResponse.StatusCode}: {apiResponse.ReasonPhrase}");
        }
    }
    catch (Exception ex)
    {
        // Handle transient failures and API rate limits
        Console.WriteLine($"Error registering site: {ex.Message}");
        try
        {
            await RetryApiCallAsync(siteName);
        }
        catch
        {
            // Log the error and provide an alternative for users
            Console.WriteLine("Failed to register site. Please try again later.");
        }
    }

    // Task 4: Performance Optimization
    await Task.Run(() =>
    {
        // Handle concurrent directory additions and starts efficiently
        foreach (var file in Directory.GetFiles(directoryPath))
        {
            ProcessFile(file);
        }
    });

    // Task 5: Logging and Monitoring
    Log.AddLogEntry($"Site '{siteName}' successfully deployed to directory '{directoryPath}'.");
}

