import java.io.File;
import java.io.IOException;
import java.util.logging.Logger;

public class DirectoryCopier {

    private static final Logger LOGGER = Logger.getLogger(DirectoryCopier.class.getName());
    private static final String SOURCE_DIR_PROMPT = "Enter the source directory path: ";
    private static final String TARGET_DIR_PROMPT = "Enter the target directory path: ";

    public static void main(String[] args) {
        File sourceDir;
        File targetDir;

        // Get source and target directories
        try {
            System.out.println(SOURCE_DIR_PROMPT);
            sourceDir = new File(System.console().readLine());
            if (!sourceDir.exists() || !sourceDir.isDirectory()) {
                LOGGER.severe("Invalid source directory path");
                return;
            }

            System.out.println(TARGET_DIR_PROMPT);
            targetDir = new File(System.console().readLine());
            if (targetDir.exists() && targetDir.isDirectory()) {
                // Ask user to confirm overwrite
                boolean proceed = askUserToProceed();
                if (!proceed) {
                    LOGGER.info("Target directory copy operation cancelled");
                    return;
                }
            } else {
                try {
                    if (!targetDir.mkdir()) {
                        throw new IOException("Failed to create target directory");
                    }
                } catch (IOException e) {
                    LOGGER.log(Level.SEVERE, "Error creating target directory", e);
                    return;
                }
            }

            // Copy source directory and its contents
            copyDirectory(sourceDir, targetDir);

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error occurred during directory copy operation", e);
        }
    }

    private static boolean askUserToProceed() {
        int choice = -1;
        while (choice != 0 && choice != 1) {
            System.out.println("Target directory already exists. Overwrite? (y/n)");
            String response = System.console().readLine();
            switch (response.toLowerCase()) {
                case "y":
                    return true;
                case "n":
                    return false;
                default:
                    System.out.println("Invalid input. Please enter 'y' or 'n'.");
            }
        }
        return choice == 0; // User chose 'y'
    }

    private static void copyDirectory(File source, File target) {
        try (java.util.stream.Stream<File> files = Files.walk(source.toPath())) {
            files.forEach(file -> {
                Path targetFile = target.resolve(source.relativize(file.toPath()));
                if (Files.isDirectory(file)) {
                    if (!targetFile.toFile().mkdirs()) {
                        throw new IOException("Failed to create directory " + targetFile);
                    }
                } else {
                    try (InputStream input = Files.newInputStream(file)) {
                        Files.copy(input, targetFile, REPLACE_EXISTING);
                    }
                }
            });
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Error occurred during directory copy operation", e);
        }
    }
}
