        !json_object_contains_key(config, "server_root") || 
        !json_object_contains_key(config, "max_connections")) {
        return 0;
    }

    if (server_port <= 0) {
        return 0;
    }

    if (!server_root || strlen(server_root) == 0) {
        return 0;
    }

    if (max_connections < 0) {
        return 0;
    }

    const char *ssl_cert_path = json_object_get_string(json_object_object_get(config, "ssl_cert_path"));
    if (ssl_cert_path && !json_file_exists(ssl_cert_path)) {
        return 0;
