using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class TextFileProcessor
{
    private readonly ILogger<TextFileProcessor> _logger;
    private readonly int _maxConcurrentFiles;
    private readonly CancellationTokenSource _cts;

    public TextFileProcessor(ILogger<TextFileProcessor> logger, int maxConcurrentFiles)
    {
        _logger = logger;
        _maxConcurrentFiles = maxConcurrentFiles;
        _cts = new CancellationTokenSource();
    }

    public Dictionary<int, string> ProcessFiles(string[] fileNames, bool preserveOrder)
    {
        var hashDictionary = new Dictionary<int, string>();
        var taskList = new List<Task>();

        foreach (var fileName in fileNames)
        {
            if (_cts.IsCancellationRequested) break;

            var fileTask = Task.Run(() =>
            {
                using (var stream = File.OpenRead(fileName))
                {
                    var lineCounter = 0;
                    var hashStringBuilder = new StringBuilder();

                    while (!stream.EndOfStream)
                    {
                        if (_cts.IsCancellationRequested) break;

                        var line = stream.ReadLine();
                        var lineHash = CalculateSHA256(line);
                        lineCounter++;

                        lock (hashDictionary)
                        {
                            hashDictionary.Add(lineCounter, lineHash);
                        }

                        _logger.LogInformation($"Processed {line} ({fileName})");
                    }
                }
            }, _cts.Token);

            taskList.Add(fileTask);
        }

        Task.WaitAll(taskList.ToArray(), _cts.Token);

        return hashDictionary;
    }

    private string CalculateSHA256(string text)
    {
        using var sha256 = SHA256.Create();
        byte[] bytes = Encoding.UTF8.GetBytes(text);
        byte[] hashedBytes = sha256.ComputeHash(bytes);
        return BitConverter.ToString(hashedBytes).Replace("-", "").ToLower();
    }
}
