        const currentTime = performance.now();
        if (currentTime - lastReportTime > 50) {
          // report progress every 50ms
          resolve({
            processedCount,
            status: 'in_progress',
          });
          lastReportTime = currentTime;
        }
      } else if (event.data.type === 'status') {
        try {
          const response = await fetch(apiEndpoint, {
            method: 'POST',
            body: JSON.stringify({ processedCount }),
            headers: { 'Content-Type': 'application/json' },
          });
          const data = await response.json();
          if (data.error) {
            // handle API error or network failure
            worker.terminate();
            reject(data.error);
          } else {
            // update processing rate based on API response
            maxProcessingRate = Math.min(maxProcessingRate, data.maxProcessingRate);
            // continue processing
          }
        } catch (error) {
          // handle network error or timeout
          worker.terminate();
          reject(error);
        }
      } else if (event.data.type === 'complete') {
        resolve({
          processedCount,
          status: 'completed',
        });
      }
    };

    worker.postMessage({ type: 'start', data });

    worker.onmessage = (event) => {
      if (event.data.type === 'interrupted') {
        // handle interrupted processing
        reject(new Error('Processing interrupted'));
      }
    };
  });
}
