class GraphGenerator {
public:
    void generateGraph(int numVertices, int numEdges) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 1000);

        Sandesh *sandesh = new Sandesh();
        sandesh->setServiceName("graph_generator");

        GraphDB *graphDB = new GraphDB(sandesh);
        graphDB->connect("localhost", "5432", "username", "password");

        for (int i = 1; i <= numVertices; i++) {
            std::string vertexId = "v" + std::to_string(i);
            int prop1 = dis(gen), prop2 = dis(gen);
            graphDB->addVertex(vertexId, prop1, prop2);
        }

        for (int i = 1; i <= numEdges; i++) {
            std::string srcId = "v" + std::to_string(dis(gen) % numVertices);
            std::string dstId = "v" + std::to_string(dis(gen) % numVertices);
            int prop1 = dis(gen), prop2 = dis(gen);
            graphDB->addEdge(srcId, dstId, prop1, prop2);
        }

        for (int i = 1; i <= numEdges; i++) {
            SandeshMessage *msg = new SandeshMessage();
            msg->setServiceName("graph_generator");
            msg->setType(Sandesh::GET);
            msg->setPropertyKey("edge_id_" + std::to_string(i));
            graphDB->sendRequest(msg);

            // Validate response
            SandeshResponse *response = graphDB->getResponse();
            if (response == nullptr || response->getPropertyValue() != "expected_value") {
                std::cerr << "Error: Unexpected outcome\n";
            }
        }

        delete sandesh;
        delete graphDB;
    }
};

