mod logging {
    use std::fs::{OpenOptions, File};
    use std::path::Path;
    use std::os::unix::io::RawFd;
    use std::io::{Write, BufWriter};
    use std::sync::atomic::{self, AtomicUsize};

    pub struct Logger {
        file: File,
        buffer: BufWriter<File>,
        fd: RawFd,
        queue_size: AtomicUsize,
    }

    impl Logger {
        fn new(path: &str) -> Self {
            let file = OpenOptions::new()
                .write(true)
                .create(true)
                .open(path)
                .expect("Failed to open log file");

            let buffer = BufWriter::new(file);

            Logger {
                file,
                buffer,
                fd: file.as_raw_fd(),
                queue_size: AtomicUsize::new(0),
            }
        }

        fn log(&self, level: i32, fmt: &str, args: ...) -> Result<(), std::io::Error> {
            let mut buffer = String::with_capacity(fmt.len() as usize + 100);
            let _ = format_to(&mut buffer, level, fmt, args);

            self.buffer.write(buffer.as_bytes())?;
            self.buffer.flush()?;

            Ok(())
        }
    }

    fn format_to(buffer: &mut String, level: i32, fmt: &str, args: ...) -> Result<(), std::io::Error> {
        let mut va = unsafe { va_start(args, fmt) };

        let _ = snprintf(buffer.as_mut_ptr(), buffer.capacity() as size_t, fmt, args.get_unchecked(0));

        va_end(args);

        Ok(())
    }
}

#[tokio::main]
