#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
} Record;

// Function to set the value of each record's int field to a random value within a specified range
void setRecordValues(Record* records, int n, int min, int max) {
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        records[i].key = rand() % (max - min + 1) + min;
    }
}

// Function to merge the two arrays into a single sorted array
Record* mergeArrays(Record* longOffsets, Record* intKeys, int n, int m) {
    // Allocate memory for the merged array
    Record* merged = (Record*)malloc((n + m) * sizeof(Record));

    // Merge and sort the arrays
    int i = 0, j = 0;
    while (i < n && j < m) {
        if (longOffsets[i].key <= intKeys[j].key) {
            merged[i + j] = longOffsets[i];
            i++;
        } else {
            merged[i + j] = intKeys[j];
            j++;
        }
    }
    while (i < n) {
        merged[i + j] = longOffsets[i];
        i++;
    }
    while (j < m) {
        merged[i + j] = intKeys[j];
        j++;
    }

    // Free the original arrays
    free(longOffsets);
    free(intKeys);

    return merged;
}

// Function to find and print the largest integer in the array
void printLargest(Record* records, int n) {
    Record max = records[0];
    for (int i = 1; i < n; i++) {
        if (records[i].key > max.key) {
            max = records[i];
        }
    }
    printf("The largest integer is: %d\n", max.key);
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    // Allocate memory for the arrays
    Record* longOffsets = (Record*)malloc(n * sizeof(Record));
    Record* intKeys = (Record*)malloc(m * sizeof(Record));

    // Initialize and validate input
    setRecordValues(longOffsets, n, 0, RAND_MAX);
    setRecordValues(intKeys, m, 0, RAND_MAX);

    // Merge the arrays
    Record* merged = mergeArrays(longOffsets, intKeys, n, m);

    // Find and print the largest integer in the array
    printLargest(merged, n + m);

    // Free memory
    free(longOffsets);
    free(intKeys);
    free(merged);

    return 0;
}
