typedef struct {
    int value;
    long offset;
    int key;
} Record;

void initMemory(long *offsets, int *keys, Record **records, int size, int min, int max) {
    // Set seed for random number generation
    srand(time(NULL));

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % (max - min + 1) + min;
        keys[i] = rand() % (max - min + 1) + min;

        // Allocate memory for records
        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            printf("Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        // Initialize record values and pointers
        records[i]->value = rand() % (max - min + 1) + min;
        records[i]->offset = offsets[i];
        records[i]->key = keys[i];
    }
}

void freeMemory(Record **records, int size) {
    for (int i = 0; i < size; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }
}
