#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define HTTP_PORT 80

typedef struct {
    char* url;
    int method;
} HttpRequest;

HttpRequest make_request(char* url, int method) {
    HttpRequest request;
    request.url = url;
    request.method = method;
    return request;
}

u_char* send_request(HttpRequest request) {
    int sockfd;
    struct sockaddr_in server_addr;
    char buffer[1024];
    u_char* response = NULL;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return NULL;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);

    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr*) &server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(sockfd);
        return NULL;
    }

    // Send request
    write(sockfd, request.url, strlen(request.url));
    write(sockfd, &request.method, sizeof(int));

    read(sockfd, buffer, sizeof(buffer));
    response = (u_char*) malloc(strlen(buffer) + 1);
    strcpy((char*)response, buffer);

    close(sockfd);
    return response;
}

int main() {
    HttpRequest request = make_request("http://example.com", GET);
    u_char* response = send_request(request);
    if (response != NULL) {
        printf("%s\n", response);
        free(response);
    }
    return 0;
}
