use reqwest::blocking;
use std::sync::{Arc, Mutex};
use std::thread;

pub struct NetworkService {
    client: Arc<Mutex<blocking::Client>>,
    disable_cert_validation: bool,
    timeout: u64,
    custom_headers: Vec<(String, String)>,
}

impl NetworkService {
    pub fn build_network_service(disable_cert_validation: bool, timeout: u64, custom_headers: Vec<(String, String)>) -> Self {
        let client = Arc::new(Mutex::new(blocking::Client::builder()));
        if disable_cert_validation {
            *client.lock().unwrap() = blocking::Client::builder()
                .danger_accept_invalid_certs(true)
                .build();
        }
        NetworkService {
            client,
            disable_cert_validation,
            timeout,
            custom_headers,
        }
    }

    pub fn make_request(&self, url: &str) -> Result<String, reqwest::Error> {
        let client = self.client.clone();
        let mut client = client.lock().unwrap();

        let request = client.get(url).timeout(self.timeout);
        for (key, value) in &self.custom_headers {
            request.header(key, value);
        }

        let response = request.send()?;
        match response.text() {
            Ok(body) => Ok(body),
            Err(err) => Err(reqwest::Error::new(err)),
        }
    }
}

pub fn main() {
    let service = NetworkService::build_network_service(false, 3000, vec![("User-Agent".to_string(), "MyApp/1.0")]);

    for i in 0..10 {
        thread::spawn(move || {
            let response = service.make_request(&format!("http://example.com/api/endpoint{}", i));
            match response {
                Ok(body) => println!("Response: {}", body),
                Err(err) => eprintln!("Error: {}", err),
            }
        });
    }
}
