    Node *current = algorithms, *previous = NULL;
    while (current != NULL && strcmp(current->algorithm.name, name) != 0) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        printf("Algorithm not found!\n");
        return;
    }
    if (previous == NULL) {
        algorithms = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

