    if (response.status === 200) {
      const imageData = response.data;
      // Loop through the image data and load each image asynchronously
      for (const image of imageData) {
        loadImageAsync(image.url, container);
      }
    } else {
      // Handle API request failure due to network issues or format mismatches
      container.innerHTML = `Failed to load images: ${response.status} ${response.statusText}`;
    }
  } catch (error) {
    // Handle API request failure due to invalid URLs or unexpected server responses
    container.innerHTML = `Error loading images: ${error.message}`;
  }
}

// Example usage:
const apiEndpoint = 'https://example-api.com/images';
const imageContainer = document.getElementById('image-container');
loadImagesAsync(apiEndpoint, imageContainer);
