function generatePEMCertificate(oauthRequest) {
  const { privateKeyName, certificateName } = oauthRequest;
  let privateKeyData = '';
  let certificateData = '';

  async function fetchPrivateAndCertificateData() {
    try {
      const privateKeyResponse = await runCommandInBackground(`cat ${privateKeyName}`);
      const certificateResponse = await runCommandInBackground(`cat ${certificateName}`);

      [privateKeyData, certificateData] = [privateKeyResponse, certificateResponse];
    } catch (error) {
      console.error('Error fetching private key or certificate:', error);
      throw error;
    }
  }

  async function generatePEMCertificate() {
    try {
      await fetchPrivateAndCertificateData();

      const pemCertificate = `${certificateData}\n${privateKeyData}`;
      return pemCertificate;
    } catch (error) {
      console.error('Error generating PEM certificate:', error);
      throw error;
    }
  }

  return generatePEMCertificate();
}
