#include <iostream>
#include <boost/random.hpp>
#include <stdexcept>

class RandomValueGenerator {
public:
    RandomValueGenerator(int minValue, int maxValue)
        : minVal(minValue), maxVal(maxValue) {}

    double GenerateRandomFloat() {
        boost::normal_distribution<double> normDist(minVal + (maxVal - minVal) / 2.0, (maxVal - minVal) / 4.0);
        boost::variate_generator<boost::mt19937, boost::normal_distribution<> > generator(mt, normDist);
        return generator() + minVal;
    }

    int GenerateRandomInt() {
        if (minVal >= maxVal)
            throw std::runtime_error("Invalid range");

        boost::uniform_int_distribution<> intDist(minVal + 1, maxVal);
        boost::mt19937 mt;
        return intDist(mt);
    }

    int GenerateRandomIntInclusive() {
        if (minVal > maxVal)
            throw std::runtime_error("Invalid range");

        boost::uniform_int_distribution<> intDist(minVal, maxVal);
        boost::mt19937 mt;
        return intDist(mt);
    }

    bool GenerateRandomBoolean() {
        static boost::random_device rd;
        static boost::mt19937 mt(rd());
        boost::bernoulli_distribution dist(0.5); // 50% chance of true
        return dist(mt);
    }

    std::string ToString() {
        if (minVal > maxVal)
            return "Invalid range";

        return "[" + std::to_string(minVal) + ", " + std::to_string(maxVal - 1) + ")";
    }

private:
    int minVal;
    int maxVal;
};

int main() {
    RandomValueGenerator generator(0, 100);

    // Test GenerateRandomFloat
    for (int i = 0; i < 10; ++i) {
        std::cout << "Random Float: " << generator.GenerateRandomFloat() << std::endl;
    }

    // Test GenerateRandomInt
    for (int i = 0; i < 10; ++i) {
        std::cout << "Random Int: " << generator.GenerateRandomInt() << std::endl;
    }

    // Test GenerateRandomIntInclusive
    for (int i = 0; i < 10; ++i) {
        std::cout << "Random Int Inclusive: " << generator.GenerateRandomIntInclusive() << std::endl;
    }

    // Test GenerateRandomBoolean
    for (int i = 0; i < 10; ++i) {
        std::cout << "Random Boolean: " << (generator.GenerateRandomBoolean() ? "True" : "False") << std::endl;
    }
}
