#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure for a document
typedef struct {
    char* title;
    char* author;
    time_t publication_date;
    int tag_count;
    char** tags;
} Document;

// Function to initialize and populate the collection with sample documents
Document* init_collection(int initial_size) {
    Document* collection = (Document*)malloc(initial_size * sizeof(Document));
    for (int i = 0; i < initial_size; i++) {
        // Initialize document attributes
        char title[64];
        sprintf(title, "Title %d", i);
        char author[32];
        sprintf(author, "Author %d", i);
        time_t publication_date = time(NULL);

        // Initialize tags array with 3 random strings
        int tag_count = rand() % 5 + 1;
        collection[i].tag_count = tag_count;
        collection[i].tags = (char**)malloc(tag_count * sizeof(char*));
        for (int j = 0; j < tag_count; j++) {
            char tag[16];
            sprintf(tag, "Tag %d_%s", i, author);
            collection[i].tags[j] = strdup(tag);
        }

        // Set document attributes
        collection[i].title = strdup(title);
        collection[i].author = strdup(author);
        collection[i].publication_date = publication_date;
    }
    return collection;
}

// Function to add a new document to the collection
void add_document(Document** collection, int* size, char* title, char* author, time_t publication_date, int tag_count, char** tags) {
    *size += 1;
    Document* new_doc = (Document*)malloc(sizeof(Document));
    new_doc->title = strdup(title);
    new_doc->author = strdup(author);
    new_doc->publication_date = publication_date;
    new_doc->tag_count = tag_count;
    new_doc->tags = (char**)malloc(tag_count * sizeof(char*));
    for (int i = 0; i < tag_count; i++) {
        new_doc->tags[i] = strdup(tags[i]);
    }
    memcpy(&collection[*size - 1], &new_doc, sizeof(Document));
}

// Function to update a document in the collection
void update_document(Document** collection, int index, char* title, char* author, time_t publication_date, int tag_count, char** tags) {
    if (index < *length || index > *size - 1) {
        printf("Invalid index\n");
        return;
    }
    Document* doc = &collection[index];
    free(doc->title);
    doc->title = strdup(title);
    free(doc->author);
    doc->author = strdup(author);
    doc->publication_date = publication_date;
    for (int i = 0; i < tag_count; i++) {
        free(doc->tags[i]);
        doc->tags[i] = strdup(tags[i]);
    }
}

// Function to delete a document from the collection
void delete_document(Document** collection, int index) {
    if (index < *length || index > *size - 1) {
        printf("Invalid index\n");
        return;
    }
    Document* doc = &collection[index];
    for (int i = 0; i < doc->tag_count; i++) {
        free(doc->tags[i]);
    }
    free(doc->title);
    free(doc->author);
    free(doc);
    memmove(&collection[index], &collection[index + 1], (*size - index - 1) * sizeof(Document));
    *size -= 1;
}

// Function to search for documents by tag
Document* search_by_tag(Document** collection, int size, char* tag) {
    Document* result = NULL;
    for (int i = 0; i < size; i++) {
        if (collection[i]->tag_count > 0) {
            for (int j = 0; j < collection[i]->tag_count; j++) {
                if (strcmp(collection[i]->tags[j], tag) == 0) {
                    result = &collection[i];
                    break;
                }
            }
        }
        if (result != NULL) {
            break;
        }
    }
    return result;
}

// Function to search for documents by author
Document* search_by_author(Document** collection, int size, char* author) {
    Document* result = NULL;
    for (int i = 0; i < size; i++) {
        if (strcmp(collection[i]->author, author) == 0) {
            result = &collection[i];
        }
    }
    return result;
}

// Function to free the collection and its documents
void destroy_collection(Document** collection, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < collection[i]->tag_count; j++) {
            free(collection[i]->tags[j]);
        }
        free(collection[i]->title);
        free(collection[i]->author);
        free(collection[i]->tags);
        free(&collection[i]);
    }
}
