#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Function to merge two arrays based on the 'int' key values
Record* mergeArrays(int** offsetValues, int** keys, int offsetCount) {
    // Initialize a new array for merged records
    Record* mergedRecords = (Record*)malloc((offsetCount + 1)*sizeof(Record));

    // Initialize pointers to start of each array
    Record* offsetRecord = &mergedRecords[0];
    Record* keyRecord = &mergedRecords[offsetCount];

    // Merge the arrays based on the 'int' key values
    for (int i = 0; i < offsetCount; i++) {
        while (keyRecord->value > keys[i][i]) {
            keyRecord--;
        }
        offsetRecord->value = keys[i][i];
        offsetRecord++;
    }

    return mergedRecords;
}

// Function to set the value of each record's int field to a random value within a specified range
void setRandomValues(Record* records, int recordCount) {
    // Initialize a high-quality pseudo-random number generator
    srand(time(NULL));

    // Set the value of each record's int field to a random value within a specified range
    for (int i = 0; i < recordCount; i++) {
        records[i].value = rand() % 100 + 1;
    }
}

// Function to test the code
void testCode(int offsetCount, int recordCount) {
    // Allocate memory for and initialize two arrays: one for 'long' offset values and one for 'int' keys
    long* offsetValues = (long*)malloc(offsetCount * sizeof(long));
    int** keys = (int**)malloc(offsetCount * sizeof(int));

    // Allocate memory for and initialize an array of 'record' structures
    Record* records = (Record*)malloc(recordCount * sizeof(Record));

    // Use a loop to set the value of each record's int field to a random value within a specified range
    setRandomValues(records, recordCount);

    // Merge the two arrays into a single sorted array based on the 'int' key values
    Record* mergedRecords = mergeArrays(keys, offsetValues, offsetCount);

    // Print the merged records
    for (int i = 0; i < recordCount + 1; i++) {
        printf("%d\n", mergedRecords[i].value);
    }

    // Free memory
    free(offsetValues);
    free(*keys);
    free(records);
    free(mergedRecords);
}

int main() {
