// Define a record structure
typedef struct {
    int key;
} Record;

// Function to merge two arrays and sort them based on 'int' key values
void mergeArrays(Record **arr1, size_t sz1, Record **arr2, size_t sz2, Record ***mergedArr) {
    // Create the merged array
    *mergedArr = (Record **)malloc((sz1 + sz2) * sizeof(Record *));
    for (size_t i = 0; i < sz1 + sz2; i++) {
        (*mergedArr)[i] = (i < sz1) ? arr1[i] : arr2[i - sz1];
    }

    // Sort the merged array
    qsort(*mergedArr, sz1 + sz2, sizeof(Record *), compare);
}

// Comparison function for sorting
int compare(const void *a, const void *b) {
    Record *r1 = *(Record **)a;
    Record *r2 = *(Record **)b;
    if (r1->key < r2->key)
        return -1;
    else if (r1->key > r2->key)
        return 1;
    return 0;
}

// Function to find and print the largest integer in the merged sorted array
void findLargestInt(Record **arr, size_t sz) {
    // Initialize variables for finding the maximum value
    int maxVal = INT_MIN;

    // Iterate through the array to find the largest integer
    for (size_t i = 0; i < sz; i++) {
        if (arr[i]->key > maxVal)
            maxVal = arr[i]->key;
    }

    printf("The largest integer in the merged sorted array is: %d\n", maxVal);
}

