        records[i]->key = rand() % 1000;
    }

    // Merge the two arrays into a single sorted array
    Record ***mergedArr;
    mergeArrays(offsetValues, maxEntries, records, numRecords, &mergedArr);

    // Find and print the largest integer in the merged sorted array
    findLargestInt(*mergedArr, maxEntries + numRecords);

