int getRateLimitedTimestamp() {
    static int64_t lastQueryTime = 0;
    static int queriesThisSecond = 0;

    int64_t now = time(NULL);
    if (now - lastQueryTime < (double)1 / RATE_LIMIT_PER_SECOND) {
        queriesThisSecond++;
        return now; // Query rate exceeded, block until next second
    }

    lastQueryTime = now;
    queriesThisSecond = 0;

