#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_INTS 10000
#define BUFFER_SIZE 1024

typedef struct {
    int *ints;
    int size;
    pthread_mutex_t mutex;
} IntArray;

IntArray* int_array_new() {
    IntArray* arr = (IntArray*)malloc(sizeof(IntArray));
    arr->size = 0;
    arr->ints = NULL;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void int_array_free(IntArray* arr) {
    free(arr->ints);
    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}

int largest_int_in_array(IntArray* arr) {
    if (arr->size == 0) {
        return 0;
    }
    int max = arr->ints[0];
    for (int i = 1; i < arr->size; i++) {
        if (arr->ints[i] > max) {
            max = arr->ints[i];
        }
    }
    return max;
}

void process_integers(int sock) {
    IntArray* arr = int_array_new();
    char buffer[BUFFER_SIZE];
    int bytes_read;
    while ((bytes_read = read(sock, buffer, BUFFER_SIZE)) > 0) {
        char* token = strtok(buffer, " ");
        while (token != NULL && strlen(token) < sizeof(int)*4) {
            int val;
            if (sscanf(token, "%d", &val) == 1) {
                pthread_mutex_lock(&arr->mutex);
                arr->ints = realloc(arr->ints, (arr->size + 1) * sizeof(int));
                arr->ints[arr->size++] = val;
                pthread_mutex_unlock(&arr->mutex);
            }
            token = strtok(NULL, " ");
        }
    }
    if (bytes_read < 0) {
        printf("Error reading from socket.\n");
    } else if (bytes_read == 0) {
        printf("No integers found.\n");
    }
    int max_int = largest_int_in_array(arr);
    int_array_free(arr);
    printf("Largest integer: %d\n", max_int);
    return;
}

int main() {
    // Socket setup and usage
    // ...
    process_integers(sock);
    return 0;
}
