int rename_files(const char *dir_path) {
    DIR *dp;
    struct dirent *entry;

    int count = 0, error_count = 0;
    const char *new_dir_path = malloc(strlen(dir_path) + strlen("/renamed") + 1);
    strcpy(new_dir_path, dir_path);

    strcat(new_dir_path, "/renamed");

    mkdir(new_dir_path, 0755);

    dp = opendir(dir_path);
    if (dp == NULL)
        return -1;

    while ((entry = readdir(dp)) != NULL) {
        char file_path[1024];
        sprintf(file_path, "%s/%s", dir_path, entry->d_name);

        if (strchr(entry->d_name, '.') && !strncmp(&entry->d_name[strlen(entry->d_name) - 1], ".", 1))
            continue;

        FILE *file = fopen(file_path, "rb");
        if (!file)
            error_count++;
        else {
            fseek(file, 0, SEEK_END);
            long file_size = ftell(file);

            char buffer[file_size + 1];
            fread(buffer, sizeof(char), file_size, file);
            fclose(file);

            char media_type[5];
            // Heuristic-based algorithm to determine media type
            if (/* check for specific media types */) {
                strcpy(media_type, "jpg");
            } else {
                strcpy(media_type, "other");
            }

            char new_file_name[1024];
            sprintf(new_file_name, "%s_%s", entry->d_name, media_type);

            rename(file_path, strcat(strcat(new_dir_path, "/"), new_file_name));

            free(buffer);
            count++;
        }
    }

    closedir(dp);
    return count;
}
