['Here is the code for the C function to initialize an AES-256-GCM cipher with a given passphrase:

```c
#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/rand.h>
#include <openssl/sha.h>

void aes_init(const char* passphrase, unsigned char** key, unsigned char** iv) {
    // Calculate the SHA-256 hash of the passphrase
    EVP_MD_CTX mdctx;
    const EVP_MD* md = EVP_sha256();
    unsigned char* hashed_passphrase = malloc(EVP_MAX_MD_SIZE);
    size_t hashed_passphrase_len = 0;

    EVP_MD_CTX_init(&mdctx);
    EVP_DigestInit_ex(&mdctx, md, NULL);
    EVP_DigestUpdate(&mdctx, passphrase, strlen(passphrase));
    EVP_DigestFinal_ex(&mdctx, hashed_passphrase, &hashed_passphrase_len);

    // Derive the encryption key from the SHA-256 hash
    unsigned char* derived_key = malloc(AES_BLOCK_SIZE);
    size_t derived_key_len = AES_BLOCK_SIZE;
    PKCS5_PBKDF2_HMAC_SHA1(hashed_passphrase, hashed_passphrase_len, passphrase, strlen(passphrase), 1000, derived_key, &derived_key_len);

    // Set the IV length and key length
    *key = malloc(AES_KEY_BIT + AES_BLOCK_SIZE);
    memset(*key, 0, AES_KEY_BIT + AES_BLOCK_SIZE);
    memcpy(*key, derived_key, derived_key_len);

    // Generate a random IV
    *iv = malloc(AES_BLOCK_SIZE);
    RAND_bytes(*iv, AES_BLOCK_SIZE);

    free(hashed_passphrase);
    free(derived_key);
}
```

This code initializes an AES-256-GCM cipher using the OpenSSL library. It derives the encryption key from the given passphrase using SHA-256 and sets the IV length to 12 bytes. The function also generates a random IV.

