        (*cache)[i] = (*cache)[i + 1];
    }
    (*cache)[capacity - 1] = img;

    return;
}

// Get an image from the cache
BackgroundImage* get_image_from_cache(BackgroundImage** cache, int capacity, const char* path) {
    // Find the image with the given path in the cache

    BackgroundImage* img = NULL;
    int i;
    for (i = 0; i < capacity; i++) {
        if ((*cache)[i]->path == path) {
            img = (*cache)[i];
            break;
        }
    }

