// Weather structure to store timestamp, temperature, and humidity levels
typedef struct {
    int timestamp;
    double temperature;
    float humidity;
} weather_t;

// Function to allocate memory for arrays of 'double' and 'float' types
void* dynamic_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to initialize an array of 'weather' structures
void init_weather_array(weather_t** arr, int size) {
    for (int i = 0; i < size; i++) {
        (*arr)[i].timestamp = 0;
        (*arr)[i].temperature = 0.0;
        (*arr)[i].humidity = 0.0f;
    }
}

// Sliding window algorithm to compute average temperature and humidity
void sliding_window(weather_t* weather_data, int window_size) {
    double sum_temp = 0.0;
    float sum_humi = 0.0;

    for (int i = 0; i < window_size; i++) {
        sum_temp += weather_data[i].temperature;
        sum_humi += weather_data[i].humidity;
    }

    printf("Average temperature: %.2f°C\n", sum_temp / window_size);
    printf("Average humidity: % .2f%%\n", (sum_humi / window_size) * 100.0);
}

// Thread-safe function to handle concurrent access by multiple threads
void* thread_safe_function(void* arg) {
    // Critical section: access shared memory without conflicts
    pthread_mutex_lock(NULL);

    // Perform operations that require exclusive access

    pthread_mutex_unlock(NULL);

    return NULL;
}

int main() {
    int num_records, window_size;

    printf("Enter number of records: ");
    scanf("%d", &num_records);
    printf("Enter window size: ");
    scanf("%d", &window_size);

    // Allocate memory for arrays
    double* temperatures = (double*)dynamic_malloc(sizeof(double) * num_records);
    float* humidities = (float*)dynamic_malloc(sizeof(float) * num_records);

    weather_t* weather_data = (weather_t*)dynamic_malloc(sizeof(weather_t) * num_records);

    init_weather_array(&weather_data, num_records);

    // Implement sliding window algorithm
    sliding_window(weather_data, window_size);

    // Perform thread-safe operations
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_safe_function, NULL);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate memory
    free(temperatures);
    free(humidities);
    free(weather_data);

    return 0;
}
