#include <stdlib.h>
#include <stdio.h>
#include <random>

struct record {
    int value;
};

void init_and_merge_arrays(int num_offsets, int num_keys, int max_value) {
    // Allocate memory for arrays
    long* offset_array = (long*)aligned_alloc(64, sizeof(long) * num_offsets);
    int* key_array = (int*)aligned_alloc(64, sizeof(int) * num_keys);

    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, max_value);

    // Set the value of each record's int field to a random value within a specified range
    struct record* record_array = (struct record*)aligned_alloc(64, sizeof(struct record) * num_offsets);
    for (int i = 0; i < num_offsets; ++i) {
        record_array[i].value = dis(gen);
    }

    // Merge the two arrays into a single sorted array
    int* merged_array = (int*)malloc((num_offsets + num_keys) * sizeof(int));
    memcpy(merged_array, key_array, num_keys * sizeof(int));
    for (int i = 0; i < num_offsets; ++i) {
        merged_array[num_keys + i] = record_array[i].value;
    }

    qsort(merged_array, num_offsets + num_keys, sizeof(int), int_compare);

    // Print the merged array
    for (int i = 0; i < num_offsets + num_keys; ++i) {
        printf("%d ", merged_array[i]);
    }
    printf("\n");

    // Clean up memory
    free(record_array);
    free(merged_array);
    free(offset_array);
    free(key_array);
}

int int_compare(const void* a, const void* b) {
    int* pa = (int*)a;
    int* pb = (int*)b;

    if (*pa < *pb) return -1;
    else if (*pa > *pb) return 1;
    else return 0;
}

