['Here is the Rust function named `build_custom_logger`:

```rust
use std::sync::{Arc, Mutex};
use log;
use slog::{Logger, Drain};

struct CustomLogger {
    logger: Logger,
    sinks: Vec<Box<dyn Drain>>,
}

impl CustomLogger {
    fn new(security_level: &str) -> Self {
        let mut sinks = Vec::new();

        // Add console sink
        sinks.push(Box::new(slog_stdlog::stdout_drain()));

        match security_level {
            "debug" => {
                // Add debug file log sink
                sinks.push(Box::new(slog_file::OpenFile::default().unwrap()));
            }
            "info" | "warning" | "error" => {
                // Add info file log sink
                sinks.push(Box::new(slog_file::OpenFile::default().unwrap()));
            }
            _ => panic!("Invalid security level"),
        };

        CustomLogger {
            logger: Logger::root(Arc::new(Mutex::new(sinks)), |c| c),
            sinks,
        }
    }

    fn log(&self, level: &str, message: &str) {
        if level == "debug" && !matches!(self.logger.level(), slog::Level::Debug) {
            return;
        }

        if level == "info" && !matches!(self.logger.level(), slog::Level::Info) {
            return;
        }

        if level == "warning" && !matches!(self.logger.level(), slog::Level::Warning) {
            return;
        }

        if level == "error" && !matches!(self.logger.level(), slog::Level::Error) {
            return;
        }

        for sink in self.sinks.iter() {
            let mut sink = sink.lock().unwrap();
            match level {
                "debug" => sink.debug(message),
                "info" => sink.info(message),
                "warning" => sink.warning(message),
                "error" => sink.error(message),
                _ => panic!("Invalid log level"),
            }
        }
    }

    fn configure_sinks(&self, sinks: Vec<Box<dyn Drain>>) {
        *self.sinks.get_mut(0).unwrap() = sinks[0].clone();
    }
}

fn main() {
    let logger = build_custom_logger("info");

    // Log messages
    logger.log("debug", "Debug message");
    logger.log("warning", "Warning message");
    logger.log("error", "Error message");

    logger.configure_sinks(vec![Box::new(slog_terminator::TermDrain::new())]);

    // Log messages with new sink configuration
    logger.log("info", "Info message");
}
