typedef struct {
    int value;
    long* offset;
    int key;
} record;

record** create_record_array(int size) {
    record** records = (record**)malloc(size * sizeof(record*));
    for (int i = 0; i < size; i++) {
        records[i] = (record*)malloc(sizeof(record));
    }
    return records;
}

void populate_records(record** records, int size, long* offsets, int* keys) {
    srand(time(NULL)); // seed random number generator
    for (int i = 0; i < size; i++) {
        record* current_record = records[i];
        current_record->value = rand() % 100; // generate random value between 0 and 99
        current_record->offset = &offsets[rand() % size]; // randomly assign offset from array
        current_record->key = keys[rand() % size]; // randomly assign key from array
    }
}

void resize_records(record** records, int* size, long* offsets, int* keys) {
    int new_size = *size * 2; // double the size for now
    record** new_records = create_record_array(new_size);
    for (int i = 0; i < *size; i++) {
        new_records[i] = records[i];
    }
    free(records); // free old array
    *records = new_records;
    *size = new_size;
}

void log_memory_operations(char* message) {
    FILE* log_file = fopen("memory.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        printf("Error: unable to write to memory.log\n");
    }
}

void free_records(record** records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records); // free the array of pointers
}

int main() {
    int size = 10;
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));

    record** records = create_record_array(size);

    populate_records(records, size, offsets, keys);

    resize_records(records, &size, offsets, keys); // dynamically resize the data structure

    free_records(records, size);
    free(offsets);
    free(keys);

    return 0;
}
