import hashlib
import logging
from typing import Dict

class Hasher:
    def __init__(self, block_size: int = 4096):
        self.hasher = hashlib.md5()
        self.block_size = block_size
        self.cache: Dict[str, str] = {}
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def hash_file(self, file_path: str, timeout: float = 60.0) -> str:
        start_time = time.time()
        if file_path in self.cache:
            return self.cache[file_path]

        try:
            with open(file_path, 'rb') as f:
                chunk = f.read(self.block_size)
                while chunk:
                    self.hasher.update(chunk)
                    f.seek(f.tell())
                    chunk = f.read(self.block_size)

                    if time.time() - start_time > timeout / 100.0 * (len(self.cache) + 1):
                        raise TimeoutError

                    if (len(self.cache) % 10 == 0 and len(self.cache)) or len(self.cache) == 0:
                        self.logger.info(f"Progress: {int(len(self.cache) / (f.tell() // self.block_size) * 100)}%")

                return self.hasher.hexdigest()

        except (OSError, IOError) as e:
            self.logger.error(f"Error reading file: {e}")
            if self.retry(e):
                return self.hash_file(file_path, timeout)
            else:
                raise

    def retry(self, error: Exception) -> bool:
        attempts = 0
        while attempts < 3 and time.time() - start_time < timeout:
            if time.time() - start_time > (attempts ** 2) * 1000 / 60.0:
                return False
            self.logger.warning(f"Error occurred, retrying in {int(time.time() - start_time)} seconds...")
            try:
                with open(self.file_path, 'rb') as f:
                    chunk = f.read(self.block_size)
                    while chunk:
                        self.hasher.update(chunk)
                        f.seek(f.tell())
                        chunk = f.read(self.block_size)

            except (OSError, IOError) as e:
                if time.time() - start_time > timeout / 100.0 * (len(self.cache) + 1):
                    raise TimeoutError
                self.logger.error(f"Error occurred during retry: {e}")
                attempts += 1
        return False

    def set_cache(self, file_path: str, hash_value: str):
        if file_path:
            self.cache[file_path] = hash_value
