            int new_N = N + 1;
            array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_N);
            if (!array)
                return NULL;

            for (j = i; j < new_N - 1; j++) {
                array[j].RX_UE_INFORMATION_TAG = array[j+1].RX_UE_INFORMATION_TAG;
                array[j].RNTI = array[j+1].RNTI;
                array[j].CRC_INDICATION_REL8_TAG = array[j+1].CRC_INDICATION_REL8_TAG;
                array[j].CRCFLAG = array[j+1].CRCFLAG;
            }

            i--;
        }
    }

    return array;
