typedef struct {
    time_t timestamp;
    int flag;
} metadata_t;

void initialize_memory(int num_records, int max_offset, int min_key) {
    // Initialize arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    metadata_t* metadata = (metadata_t*)malloc(num_records * sizeof(metadata_t));

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_offset - min_key) + min_key;
        keys[i] = rand() % (num_records);
        records[i].val = rand() % (num_records);
        records[i].offset_ptr = &offsets[i];
        records[i].key = keys[i];
        metadata[i].timestamp = time(NULL);
        metadata[i].flag = 0;
    }

    // Clean up unused records
    int age_threshold = 30; // seconds
    for (int i = 0; i < num_records; i++) {
        if ((time(NULL) - metadata[i].timestamp) > age_threshold) {
            free(metadata[i].offset_ptr);
            free(&records[i]);
            // Shift remaining records to fill gap
            for (int j = i; j < num_records - 1; j++) {
                offsets[j] = offsets[j + 1];
                keys[j] = keys[j + 1];
                records[j].val = records[j + 1].val;
                metadata[j].timestamp = metadata[j + 1].timestamp;
                metadata[j].flag = metadata[j + 1].flag;
            }
        }
    }

    // Return allocated memory
    return *offsets, *keys, *records, *metadata;
}
