int renameFiles(char* dirPath) {
    int fileCount = 0;
    char filePath[256];
    FILE* file;
    char* fileExtension;

    // Traverse the directory recursively
    DIR* dp = opendir(dirPath);
    if (dp == NULL)
        return -1;  // Error

    struct dirent* dent;
    while ((dent = readdir(dp)) != NULL) {
        sprintf(filePath, "%s/%s", dirPath, dent->d_name);

        // Check for valid file extensions
        fileExtension = strrchr(dent->d_name, '.');
        if (fileExtension && (!strcmp(fileExtension, ".jpg") || !strcmp(fileExtension, ".png") || !strcmp(fileExtension, ".mp4"))) {
            int fileSize;
            char mediaType[4];
            FILE* fptr;

            // Determine the file's actual media type using a heuristic-based algorithm
            fptr = fopen(filePath, "rb");
            if (fptr == NULL)
                return -1;  // Error

            fseek(fptr, 0, SEEK_END);
            fileSize = ftell(fptr);
            rewind(fptr);

            if (fileSize > 10000) {
                char buffer[1024];
                fread(buffer, sizeof(char), 1024, fptr);
                fclose(fptr);

                // Use a heuristic-based algorithm to determine the media type
                if (strstr(buffer, "FF D8") || strstr(buffer, "FF D9"))
                    sprintf(mediaType, "jpeg");
                else if (strstr(buffer, "8950") || strstr(buffer, "8774"))
                    sprintf(mediaType, "png");
                else if (strstr(buffer, "ftyp") || strstr(buffer, "moov"))
                    sprintf(mediaType, "mp4");

                if (*mediaType)
                    rename(filePath, filePath);
            } else {
                fclose(fptr);
            }
        }

        fileCount++;
    }

    closedir(dp);

    return fileCount;
}

