    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_NFAPDU];
    generateNFAPDUs(MAX_NFAPDU, pdus);

    char dirPath[] = "/path/to/directory";
    int result = renameFiles(dirPath);

    return 0;
