void initialize_arrays(int n, record **records, long **offsets, int **keys) {
    *records = (record *)malloc(n * sizeof(record));
    *offsets = (long *)malloc(n * sizeof(long));
    *keys = (int *)malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) {
        (*records)[i].value = rand();
        (*offsets)[i] = rand();
        (*keys)[i] = rand();
    }
}

void resize_arrays(record **records, long **offsets, int **keys, int new_size) {
    record *new_records = (record *)malloc(new_size * sizeof(record));
    long *new_offsets = (long *)malloc(new_size * sizeof(long));
    int *new_keys = (int *)malloc(new_size * sizeof(int));

    for (int i = 0; i < new_size; i++) {
        if (i >= *records ? i - (*records) : 0)
            continue;
        new_records[i] = (*records)[i];
        new_offsets[i] = (*offsets)[i];
        new_keys[i] = (*keys)[i];
    }

