        keys[i] = rand() % (maxValue - minValue + 1) + minValue;
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].offset = offsets[rand() % size];
        records[i].key = keys[rand() % size];
    }

    // Return pointers to arrays
    return &records;
}
