    int tag_count;
} document;

document *documents[MAX_DOCUMENTS];
int document_count = 0;

void init_documents() {
    documents[0] = (document *)malloc(sizeof(document));
    documents[0]->title = "Document1";
    documents[0]->author = "Author1";
    documents[0]->publication_date = time(NULL) - 60 * 60 * 24;
    documents[0]->tags = (char **)malloc((MAX_TAGS + 1) * sizeof(char *));
    for (int i = 0; i <= MAX_TAGS; i++) {
        documents[0]->tags[i] = (char *)malloc((MAX_TAG_LENGTH + 1) * sizeof(char));
        sprintf(documents[0]->tags[i], "Tag%i", i);
    }
    document_count++;

    // Add more sample documents...
}

void add_document(char *title, char *author, time_t publication_date, int tag_count, ...) {
    if (document_count >= MAX_DOCUMENTS) {
        printf("Error: Maximum number of documents reached.\n");
        return;
    }

    document *new_doc = (document *)malloc(sizeof(document));
    new_doc->title = title;
    new_doc->author = author;
    new_doc->publication_date = publication_date;
    new_doc->tag_count = tag_count;

    va_list(ap);
    int i = 0;
    va_start(ap, tag_count);
    for (i = 0; i < tag_count; i++) {
        char *tag = va_arg(ap, char *);
        new_doc->tags[i] = (char *)malloc((strlen(tag) + 1) * sizeof(char));
        strcpy(new_doc->tags[i], tag);
    }
    va_end(ap);

    documents[document_count++] = new_doc;
}

void update_document(int index, char *new_title, char *new_author, time_t new_publication_date, int new_tag_count, ...) {
    if (index >= document_count) {
        printf("Error: Document not found.\n");
        return;
    }

    document *doc = documents[index];
    doc->title = new_title;
    doc->author = new_author;
    doc->publication_date = new_publication_date;
    int i = 0;
    va_list(ap);
    va_start(ap, new_tag_count);
    for (i = 0; i < new_tag_count; i++) {
        char *tag = va_arg(ap, char *);
        free(doc->tags[i]);
        doc->tags[i] = (char *)malloc((strlen(tag) + 1) * sizeof(char));
        strcpy(doc->tags[i], tag);
    }
    for (; i < doc->tag_count; i++) {
        free(doc->tags[i]);
    }
    doc->tag_count = new_tag_count;
    va_end(ap);

    // Update other document attributes...
}

void delete_document(int index) {
    if (index >= document_count) {
        printf("Error: Document not found.\n");
        return;
    }

    document *doc = documents[index];
    for (int i = 0; i < doc->tag_count; i++) {
        free(doc->tags[i]);
    }
    free(doc);
    for (int i = index; i < document_count - 1; i++) {
        documents[i] = documents[i + 1];
    }
    document_count--;
}

document *search_by_tag(char *tag) {
    for (int i = 0; i < document_count; i++) {
        document *doc = documents[i];
        for (int j = 0; j < doc->tag_count; j++) {
            if (!strcmp(doc->tags[j], tag)) {
                return &documents[i][j]; // Return the matching document
            }
        }
    }

    printf("Error: No matching document found.\n");
    return NULL;
}

document *search_by_author(char *author) {
    for (int i = 0; i < document_count; i++) {
        document *doc = documents[i];
        if (!strcmp(doc->author, author)) {
            return &documents[i]; // Return the matching document
        }
    }

    printf("Error: No matching document found.\n");
    return NULL;
}
