library nfa_api;

use std::path::{Path, PathBuf};
use std::fs::DirEntry;
use std::collections::HashMap;
use serde::{Serialize, Deserialize};

// Define the NFA API structure
#[derive(Serialize, Deserialize)]
pub struct NFAPI_CRC_INDICATION_PDU_T {
    pub rx_ue_information_tag: String,
    pub rnti: u32,
    pub crc_indication_rel8_tag: Vec<u8>,
}

impl NFAPI_CRC_INDICATION_PDU_T {
    pub fn new(rx_ue_information_tag: String, rnti: u32) -> Self {
        Self { 
            rx_ue_information_tag, 
            rnti, 
            crc_indication_rel8_tag: vec![], 
        }
    }
}

// Define the API endpoint for creating a new instance
pub async fn create_instance(
    path: &str,
    config: HashMap<String, String>,
) -> Result<NFAPI_CRC_INDICATION_PDU_T, Box<dyn std::error::Error>> {
    // Create the directory if it does not exist
    let dir_path = Path::new(path);
    if !dir_path.exists() {
        fs::create_dir_all(dir_path)?;
    }

    // Read the existing instance data from file
    let mut file_path = dir_path.join("instance.json");
    let mut data: NFAPI_CRC_INDICATION_PDU_T = serde_json::from_reader(file_path.open_file_read())?;
    if data.is_empty() {
        data = NFAPI_CRC_INDICATION_PDU_T::new(config["rx_ue_information_tag"].clone(), 
            config["rnti"].parse::<u32>().unwrap());
    }

    // Update the instance with the new configuration
    let updated_instance = match config.get("crc_indication_rel8_tag") {
        Some(tag) => NFAPI_CRC_INDICATION_PDU_T { 
            ..data.clone() 
        },
        None => data,
    };

    // Write the updated instance to file
    serde_json::to_writer(file_path.open_file_write(), &updated_instance)?;

    Ok(updated_instance)
}

// Define the API endpoint for reading an existing instance
pub async fn read_instance(
    path: &str,
) -> Result<NFAPI_CRC_INDICATION_PDU_T, Box<dyn std::error::Error>> {
    let dir_path = Path::new(path);
    if !dir_path.exists() {
        return Err("Directory not found".to_string().into());
    }

    let file_path = dir_path.join("instance.json");
    serde_json::from_reader(file_path.open_file_read())?;
}

