// Define the function to manage the dynamic collection of projects
void manage_project_collection(int initial_size) {
    // Initialize the project collection with the given size
    project **projects = (project **)malloc(initial_size * sizeof(project *));
    for (int i = 0; i < initial_size; i++) {
        projects[i] = (project *)malloc(sizeof(project));
    }

    // Set random values for project attributes
