    int team_id_range = 10;
    for (int i = 0; i < initial_size; i++) {
        projects[i]->name = (char *)malloc(16 * sizeof(char));
        sprintf(projects[i]->name, "Project %d", i);
        projects[i]->status = NEW;
        projects[i]->start_date = time(NULL) - rand() % 60 * 60 * 24; // Random start date within last week
        projects[i]->budget = (float)(rand() % 1000); // Random budget value up to $1000
    }

    // Function to add a new project
    void add_project(project **projects, int size) {
        if (size < initial_size) {
            projects[size] = (project *)malloc(sizeof(project));
            // Initialize new project with random attributes
            projects[size]->name = (char *)malloc(16 * sizeof(char));
            sprintf(projects[size]->name, "New Project %d", size);
            projects[size]->status = NEW;
            projects[size]->start_date = time(NULL) - rand() % 60 * 60 * 24; // Random start date within last week
            projects[size]->budget = (float)(rand() % 1000); // Random budget value up to $1000
        } else {
            printf("Project collection is full. Please delete a project or increase the initial size.\n");
        }
    }

    // Function to update an existing project
    void update_project(project **projects, int index) {
        if (index < initial_size) {
            projects[index]->name = (char *)malloc(16 * sizeof(char));
            sprintf(projects[index]->name, "Updated Project %d", index);
            projects[index]->status = NEW;
            projects[index]->start_date = time(NULL) - rand() % 60 * 60 * 24; // Random start date within last week
            projects[index]->budget = (float)(rand() % 1000); // Random budget value up to $1000
        } else {
            printf("Project index out of bounds. Please enter a valid project index.\n");
        }
    }

    // Function to delete a project
    void delete_project(project **projects, int index) {
        if (index < initial_size) {
            free(projects[index]->name);
            free(projects[index]);
            projects[index] = NULL;
            for (int i = index; i < initial_size - 1; i++) {
                projects[i] = projects[i + 1];
            }
            projects[initial_size - 1] = NULL;
        } else {
            printf("Project index out of bounds. Please enter a valid project index.\n");
        }
    }

    // Function to estimate budget based on current resources and constraints
    float estimate_budget(project **projects, int size) {
        float total_budget = 0;
        for (int i = 0; i < size; i++) {
            total_budget += projects[i]->budget;
        }
        return total_budget;
    }

    // Function to recalculate budget based on current resources and constraints
    void recalculate_budget(project **projects, int size) {
        float new_total_budget = estimate_budget(projects, size);
        for (int i = 0; i < size; i++) {
            projects[i]->budget /= new_total_budget;
        }
    }

    // Initialize the project collection with sample projects
    manage_project_collection(initial_size);

    printf("Initial project collection initialized. Current budget: $%.2f\n", estimate_budget(projects, initial_size));

    // Add a new project
    add_project(projects, initial_size);
    printf("New project added. Current budget: $%.2f\n", estimate_budget(projects, initial_size + 1));

    // Update an existing project
    update_project(projects, initial_size / 2);
    printf("Project updated. Current budget: $%.2f\n", estimate_budget(projects, initial_size + 1));

    // Delete a project
    delete_project(projects, initial_size / 2);
    printf("Project deleted. Current budget: $%.2f\n", estimate_budget(projects, initial_size));

    // Recalculate the budget
    recalculate_budget(projects, initial_size);
    printf("Budget recalculated. New budget: $%.2f\n", estimate_budget(projects, initial_size));
}

int main() {
    manage_project_collection(10);
    return 0;
}
