void create_crc_indication_pdu(int num_structures, int max_size, int log_enabled, char *output_dir) {
    srand(time(NULL));

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_size * sizeof(NFAPI_CRC_INDINATION_PDU_T));
    if (pdu_array == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    // Initialize the structures
    for (int i = 0; i < num_structures; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand();
        pdu_array[i].RNTI = rand();
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand();
        pdu_array[i].CRCFLAG = rand() % 2;
    }

    // Serialize the structures and store them in files
    char filename[64];
    for (int i = 0; i < num_structures; i++) {
        sprintf(filename, "%s/%d.bin", output_dir, i);
        FILE *file = fopen(filename, "wb");
        if (file == NULL) {
            printf("Error opening file %s!\n", filename);
            continue;
        }
        fwrite(&pdu_array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        fclose(file);
    }

    // Free the memory
    free(pdu_array);

    if (log_enabled) {
        printf("Total structures created: %d\n", num_structures);
    }
}
