void init_aes_cipher(int* num_allocations, int* num_failures) {
    // Initialize OpenSSL library
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Derive encryption key from passphrase using SHA-256
    unsigned char passphrase[] = "your_passphrase_here";
    unsigned char key[32];
    SHA256_CTX sha256_ctx;
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, passphrase, strlen((char*)passphrase));
    SHA256_Final(key, &sha256_ctx);

    // Initialize AES-256-GCM cipher
    unsigned char iv[12];
    for (int i = 0; i < 12; i++) {
        iv[i] = rand() % 256;
    }
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv);
    EVP_CIPHER_CTX_set_flags(ctx, EVP_CIPHER_CTX_FLAG_REUSE);

    // Allocate and populate array of NFAPI_CRC_INDICATION_PDU_T structures
    int N = 100; // adjust this value as needed
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i].RNTI = rand() % 10;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pdus[i].CRCFLAG = (int)rand() % 2; // randomly set CRC flag
    }

    // Monitor and report memory usage
    printf("Memory allocated: %zu bytes\n", N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Manage memory resources and handle potential failures
    if (!pdus) {
        (*num_failures)++;
        fprintf(stderr, "Failed to allocate memory: %s\n", ERR_error_to_string(ERR_get_error()));
    } else {
        (*num_allocations)++;
    }

    // Cleanup OpenSSL library
    EVP_CIPHER_CTX_free(ctx);
    OPENSSL_cleanup();

    return;
}
