using System;
using System.IO;
using System.Text.Json;

public class UeInformationTag {
    public int Rnti { get; set; }
    public string UeId { get; set; }
    public double ChannelFrequency { get; set; }
    public int PowerLevel { get; set; }
}

public class NetworkConfig {
    public int NumUies { get; set; }
    public UeInformationTag[] UeInfoArray { get; set; }
}

public class NetworkConfigDeserializer {
    public static NetworkConfig Deserialize(string filePath) {
        using (FileStream fileStream = File.OpenRead(filePath)) {
            using (BinaryReader reader = new BinaryReader(fileStream)) {
                int numUies = reader.ReadInt32();
                UeInformationTag[] ueInfoArray = new UeInformationTag[numUies];
                for (int i = 0; i < numUies; i++) {
                    UeInformationTag ueInfo = new UeInformationTag();
                    ueInfo.Rnti = reader.ReadInt32();
                    ueInfo.UeId = reader.ReadString();
                    ueInfo.ChannelFrequency = reader.ReadDouble();
                    ueInfo.PowerLevel = reader.ReadInt32();
                    ueInfoArray[i] = ueInfo;
                }
                NetworkConfig config = new NetworkConfig();
                config.NumUies = numUies;
                config.UeInfoArray = ueInfoArray;
                return config;
            }
        }
    }
}
