typedef struct {
    float x;
    float y;
} point;

void calculate_distances(point* points, double** distances) {
    int num_points = 0;
    while (points[num_points].x != 0.0f && points[num_points].y != 0.0f) {
        num_points++;
    }

    *distances = (double*)malloc((num_points*(num_points-1))/2 * sizeof(double));

    for (int i = 0; i < num_points; i++) {
        for (int j = i + 1; j < num_points; j++) {
            double dx = points[j].x - points[i].x;
            double dy = points[j].y - points[i].y;
            (*distances)[(i*(i-1))/2 + j-i-1] = sqrt(dx*dx + dy*dy);
        }
    }
}

void free_arrays(point** points, double** distances) {
    free(*points);
    free(*distances);
}
