pthread_cond_t queue_cond = PTHREAD_COND_INITIALIZER;
pthread_attr_t thread_attr;
int pending_allocations = 0;
int max_pending_allocations = MAX_ALLOCATIONS;
struct {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int successes = 0;
    int failures = 0;
    double average_time = 0.0;
} statistics;

void* callback_thread(void* arg) {
    // Execute custom callbacks in a separate thread pool
}

int nfa_api_crc_indication_pdu_alloc(int N, bool enable_logging, bool enable_callbacks) {
    if (N <= 0 || !enable_logging && !enable_callbacks) {
        return -1; // Invalid input parameters
    }

    pthread_t callback_thread_id;
    pthread_attr_init(&thread_attr);
    pthread_attr_setstacksize(&thread_attr, stacksize);

    for (int i = 0; i < N; i++) {
        if (!allocate_pdu()) {
            break;
        }
    }

    return 0;
}

int allocate_pdu() {
    // Acquire lock and check queue capacity
    pthread_mutex_lock(&queue_lock);
    int pending_allocations = __atomic_load(&pending_allocations, __ATOMIC_SEQ_CST);

    // Check if the maximum number of pending allocations is reached
    if (pending_allocations >= max_pending_allocations) {
        pthread_cond_signal(&queue_cond); // Signal waiting threads to defer requests
    } else {
        // Allocate a new structure and populate it with valid data
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            return -1; // Out of memory
        }

        // Populate the structure with random data
        // ...

        // Update statistics and notify the callback thread
        pthread_mutex_lock(&statistics.lock);
        statistics.successes++;
        statistics.average_time += (double)(clock() - clock()) / CLOCKS_PER_SEC;
        pthread_cond_signal(&queue_cond);

        if (enable_callbacks) {
            pthread_t callback_thread_id;
            pthread_create(&callback_thread_id, &thread_attr, callback_thread, pdu);
        }

        // Release the lock and increment the pending allocation count
        __atomic_fetch_add(&pending_allocations, 1, __ATOMIC_SEQ_CST);

        return 0;
    }
}

void* log_thread(void* arg) {
    // Periodically report statistics to the application
}

int main() {
