} LTE_ENB_CONFIGURATION_SRB2_SRB3_CONFIG;

// Define a linked list node for managing memory efficiently
typedef struct Node {
    LTE_ENB_CONFIGURATION_SRB2_SRB3_CONFIG config;
    struct Node* next;
} Node;

// Function to create a new configuration structure
LTE_ENB_CONFIGURATION_SRB2_SRB3_CONFIG* create_config() {
    LTE_ENB_CONFIGURATION_SRB2_SRB3_CONFIG* config = (LTE_ENB_CONFIGURATION_SRB2_SRB3_CONFIG*)malloc(sizeof(LTE_ENB_CONFIGURATION_SRB2_SRB3_CONFIG));
