pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int time_threshold = 1000; // in milliseconds
int max_entries = 1000;

void initialize_dynamic_array() {
    dynamic_array = malloc(max_entries * sizeof(LTE_PHY_RRC_API_RLC_STATUS_INFO));
}

void update_dynamic_array(int rlc_am_pdu_id, enum { RLC_AM_PDU_STATUS_OK, RLC_AM_PDU_STATUS_ERROR } status) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < max_entries; i++) {
        if (dynamic_array[i].rlc_am_pdu_id == -1) {
            dynamic_array[i].rlc_am_pdu_id = rlc_am_pdu_id;
            dynamic_array[i].status = status;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void clear_outdated_entries() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < max_entries; i++) {
        if ((time(NULL) - dynamic_array[i].sequence_number) * 1000 > time_threshold) {
            dynamic_array[i].rlc_am_pdu_id = -1;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void free_dynamic_array() {
    free(dynamic_array);
}
