        // Add implementation for process function
        pipeline->stages[i]->process = NULL;
    }

    return pipeline;
}

// Function to add a stage to the pipeline
void add_stage(Pipeline* pipeline, Stage new_stage) {
    pipeline->stages[pipeline->num_stages++] = new_stage;
}

// Function to start processing data through the pipeline
void process_data(Pipeline* pipeline, void* input) {
    for (int i = 0; i < pipeline->num_stages; i++) {
        pipeline->stages[i]->process(input, NULL); // Add implementation for process function
    }
}

// Function to free allocated resources when the pipeline is no longer needed
