#define MAX_REQUESTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[16];
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* request_allocation(int priority, int max_allocations) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int total_allocated = 0;
    static int total_failed = 0;
    static int peak_usage = 0;
    static int current_usage = 0;

    if (pthread_mutex_lock(&mutex) != 0) {
        printf("Mutex lock failed\n");
        return NULL;
    }

    int allocated = 0;
    while (allocated < max_allocations && total_allocated + allocated <= MAX_REQUESTS) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            total_failed++;
            free(pdu);
        } else {
            total_allocated += 1;
            allocated++;
            current_usage++;

            if (current_usage > peak_usage)
                peak_usage = current_usage;

            // Randomly set CRCFLAG
            pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
            strcpy(pdu->RNTI, "RNTI");
            pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;

            printf("Allocated: %d\n", allocated);
        }
    }

    pthread_mutex_unlock(&mutex);

    if (pthread_mutex_lock(&mutex) != 0) {
        printf("Mutex lock failed\n");
        return NULL;
    }

    FILE* file = fopen("logs.txt", "a+");
    fprintf(file, "Total Allocated: %d\nTotal Failed: %d\nPeak Usage: %d\nCurrent Usage: %d\n\n", total_allocated, total_failed, peak_usage, current_usage);
    fclose(file);

    pthread_mutex_unlock(&mutex);

    return pdu;
}

int main() {
    int requests = 1000; // configurable maximum number of structures to be allocated
    int priority = HIGH_PRIORITY; // configurable priority for the allocation request

    NFAPI_CRC_INDICATION_PDU_T* pdu = request_allocation(priority, requests);

    if (pdu == NULL) {
        printf("Allocation failed\n");
    } else {
        // Process the allocated structure
        process_pdu(pdu);
    }

    return 0;
}

