    *mode = (cipher_mode_t)encryption_mode;

    struct record* records = (struct record*)malloc(num_records * sizeof(struct record));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (random_range_end - random_range_start) + random_range_start;
    }

    long* offsets = (long*)malloc((num_records + 1) * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    for (size_t i = 0; i <= num_records; ++i) {
        offsets[i] = rand();
    }
    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = rand();
    }

    free(offsets);
    free(keys);

    free(records);

    return mode;
}
