    int serving_cell_id;
    int* tacs;
    int tac_count;
} lte_ue_context;

typedef struct {
    lte_ue_context* contexts;
    int context_count;
    pthread_mutex_t mutex;
} lte_ue_pool;

void* ue_pool_allocate(int size);
void ue_pool_free(void* ptr);

lte_ue_pool* create_ue_pool();
void destroy_ue_pool(lte_ue_pool* pool);

int main() {
    // Example usage
    lte_ue_pool* pool = create_ue_pool();

    lte_ue_context* context1 = (lte_ue_context*)ue_pool_allocate(sizeof(lte_ue_context));
    context1->ue_identity = 123;
    context1->serving_cell_id = 456;
    int tacs[UE_CONTEXT_MAX_TACS] = {1, 2, 3};
    context1->tacs = tacs;
    context1->tac_count = 3;

    lte_ue_context* context2 = (lte_ue_context*)ue_pool_allocate(sizeof(lte_ue_context));
    // ...

    // Use the UE pool
    // ...

    destroy_ue_pool(pool);

    return 0;
}

// Custom memory allocation for UE Contexts and their associated TAC lists
void* ue_pool_allocate(int size) {
    lte_ue_pool* pool = (lte_ue_pool*)malloc(sizeof(lte_ue_pool));
    pthread_mutex_init(&pool->mutex, NULL);

    if (size == sizeof(lte_ue_context)) {
        if (pool->context_count >= UE_CONTEXT_POOL_SIZE) {
            // Handle memory exhaustion
            return NULL;
        }

        lte_ue_context* context = (lte_ue_context*)malloc(size);
        pool->contexts[pool->context_count++] = context;

        return context;
    } else {
        // Handle other memory requests
        return malloc(size);
    }
}

// Custom memory deallocation for UE Contexts and their associated TAC lists
void ue_pool_free(void* ptr) {
    free(ptr);
}

// Create a new UE pool
lte_ue_pool* create_ue_pool() {
    lte_ue_pool* pool = (lte_ue_pool*)malloc(sizeof(lte_ue_pool));
    pthread_mutex_init(&pool->mutex, NULL);

    pool->contexts = (lte_ue_context*)calloc(UE_CONTEXT_POOL_SIZE, sizeof(lte_ue_context));

    return pool;
}

// Destroy a UE pool
void destroy_ue_pool(lte_ue_pool* pool) {
    for (int i = 0; i < pool->context_count; i++) {
        ue_pool_free(pool->contexts[i]);
    }

    free(pool->contexts);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);

    return;
}
