#define NFAPI_CRC_INDICATION_PDU_T struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
    unsigned int PREAMBLE_DURATION;
};

void* allocate_array(int size) {
    void* result = malloc(size);
    if (!result) {
        printf("Memory allocation failed.\n");
    }
    return result;
}

int main() {
    // Initialize an empty array
    NFAPI_CRC_INDICATION_PDU_T** nfa_array = NULL;
    int total_allocations = 0;
    int total_failures = 0;

    while (1) {
        // User input for the number of UEs and preamble durations
        int num_ue;
        printf("Enter the number of UEs: ");
        scanf("%d", &num_ue);

        if (num_ue <= 0) {
            break; // Stop allocating when no more UEs are needed
        }

        // Dynamically allocate an array for each UE
        nfa_array = (NFAPI_CRC_INDICATION_PDU_T**)allocate_array(num_ue * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

        if (!nfa_array) {
            total_failures++;
            continue; // Skip to the next allocation cycle
        }

        for (int i = 0; i < num_ue; i++) {
            NFAPI_CRC_INDICATION_PDU_T* nfa_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (!nfa_pdu) {
                total_failures++;
                break; // Stop allocating when memory is exhausted
            }

            nfa_pdu->RX_UE_INFORMATION_TAG = i;
            nfa_pdu->RNTI = i + 1;
            nfa_pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

            if (nfa_pdu->PREAMBLE_DURATION <= 0) {
                printf("Invalid preamble duration: %u\n", nfa_pdu->PREAMBLE_DURATION);
                total_failures++;
                free(nfa_pdu);
                break; // Skip to the next allocation cycle
            }

            nfa_array[i] = nfa_pdu;
        }
    }

    // Free memory after all allocations are complete
    for (int i = 0; i < num_ue; i++) {
        if (nfa_array[i]) {
            free(nfa_array[i]);
        }
    }

    if (total_allocations > total_failures) {
        printf("Total successful allocations: %d\n", total_allocations);
        printf("Total failed allocations: %d\n", total_failures);
    } else {
        printf("Memory exhaustion occurred.\n");
    }

    return 0;
}
