#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

#define MAX_CAPACITY 100
#define CRCFLAG_MASK 0xFF

typedef struct {
    uint32_t rx_ue_info_tag;
    uint16_t rnti;
} RX_UE_INFORMATION_TAG;

typedef enum {
    CRCFLAG_VALID = 0,
    CRCFLAG_INVALID = 1
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *create_crc_list(int max_elements) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return list;
}

void insert_ue_info(NFAPI_CRC_INDICATION_PDU_T **list, int max_elements, uint32_t rx_ue_info_tag, uint16_t rnti) {
    for (int i = 0; i < max_elements; i++) {
        if (!(*list)[i].ue_info.rnti) {
            (*list)[i].ue_info.rx_ue_info_tag = rx_ue_info_tag;
            (*list)[i].ue_info.rnti = rnti;
            return;
        }
    }
}

int validate_rntis(NFAPI_CRC_INDICATION_PDU_T *list, int max_elements) {
    uint16_t rnti_set[MAX_CAPACITY];
    int rnti_count = 0;

    for (int i = 0; i < max_elements; i++) {
        if (!(*list)[i].ue_info.rnti) continue;
        bool found = false;
        for (int j = 0; j < rnti_count; j++) {
            if (rnti_set[j] == (*list)[i].ue_info.rnti) {
                found = true;
                break;
            }
        }
        if (!found) {
            rnti_set[rnti_count++] = (*list)[i].ue_info.rnti;
        } else return 0; // duplicate RNTI detected
    }

    return 1; // all RNTIs unique
}

void *crc_indication_thread_func(void *args) {
    int max_elements = *((int *)args);
    NFAPI_CRC_INDICATION_PDU_T *list = create_crc_list(max_elements);

    for (int i = 0; i < max_elements; i++) {
        uint32_t rx_ue_info_tag = rand() % (2^31 - 1);
        uint16_t rnti = rand() % (2^15 - 1) + 1;
        insert_ue_info(&list, max_elements, rx_ue_info_tag, rnti);

        int result = validate_rntis(list, max_elements);
        if (!result) return NULL; // duplicate RNTI detected
    }

    free(list);
    return NULL;
}

int main() {
    pthread_t thread[2];
    int max_elements[2] = {10, 20};

    for (int i = 0; i < 2; i++) {
        pthread_create(&thread[i], NULL, crc_indication_thread_func, &max_elements[i]);
        pthread_join(thread[i], NULL);
    }

    return 0;
}

