#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

void* linked_list_operations(void* arg) {
    // Thread-specific operations
    return NULL;
}

int main() {
    // Initialize the list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    struct Node* head = NULL;
    struct Node* tail = NULL;

    int num_elements = 1000000; // adjust as needed

    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data->RX_UE_INFORMATION_TAG[16] = 'X';
        data->RNTI = rand();
        data->CRC_INDICATION_REL8_TAG[16] = 'Y';
        data->CRCFLAG = rand();

        // Check for duplicate RNTI
        pthread_mutex_lock(&mutex);
        struct Node* current = head;
        while (current != NULL) {
            if (data->RNTI == current->data.RNTI) {
                fprintf(stderr, "Error: Duplicate RNTI detected. Exiting.\n");
                exit(EXIT_FAILURE);
            }
            current = current->next;
        }
        pthread_mutex_unlock(&mutex);

        // Insert node
        struct Node* new_node = malloc(sizeof(struct Node));
        new_node->data = *data;
        if (head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    // Perform operations on the list
    for (int i = 0; i < num_elements; ++i) {
        pthread_t thread;
        pthread_create(&thread, NULL, linked_list_operations, NULL);
        pthread_join(thread);
    }

    // Clean up
    while (head != NULL) {
        struct Node* temp = head;
        head = head->next;
        free(temp);
    }
}
