// C# Function to load and deserialize data from binary file
public class RX_UE_INFORMATION_TAG {
    public ushort RNTI { get; set; }
    public string UE_ID { get; set; }
    public float Channel_Frequency { get; set; }
    public int Bandwidth_Allocation_Strategy { get; set; }
}

public void LoadAndDeserializeData(string filePath) {
    using (FileStream fs = new FileStream(filePath, FileMode.Open)) {
        RX_UE_INFORMATION_TAG[] ueInfoArray = new RX_UE_INFORMATION_TAG[fs.Length / sizeof(RX_UE_INFORMATION_TAG)];

        for (int i = 0; i < ueInfoArray.Length; i++) {
            byte[] ueInfoBytes = new byte[sizeof(RX_UE_INFORMATION_TAG)];
            fs.Read(ueInfoBytes, 0, ueInfoBytes.Length);

            RX_UE_INFORMATION_TAG ueInfo = BitConverter.ToRX_UE_INFORMATION_TAG(ueInfoBytes, 0);
            ueInfoArray[i] = ueInfo;
        }

        foreach (var ueInfo in ueInfoArray) {
            Console.WriteLine($"RNTI: {ueInfo.RNTI}, UE_ID: {ueInfo.UE_ID}, Channel Frequency: {ueInfo.Channel_Frequency}, Bandwidth Allocation Strategy: {ueInfo.Bandwidth_Allocation_Strategy}");
        }
    }
}
