typedef struct Record {
    long offset;
    int key;
    int value;
    char* buffer;
} Record;

Record* initializeRecords(int n, int minValue, int maxValue, size_t maxBufferSize) {
    Record* records = (Record*)malloc(n * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < n; i++) {
        records[i].offset = i;
        records[i].key = i % 10; // Assign a unique key
        records[i].value = rand() % (maxValue - minValue) + minValue; // Generate random value within specified range

        records[i].buffer = (char*)malloc(maxBufferSize);
        if (!records[i].buffer) {
            for (int j = 0; j < i; j++) free(records[j].buffer);
            for (int j = 0; j < i; j++) free((void*)&records[j]);
            free(records);
            return NULL;
        }

        char* letter = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        int bufferIndex = 0;
        while (bufferIndex < maxBufferSize) {
            records[i].buffer[bufferIndex++] = *letter++;
            if (*letter == 'z') {
                letter -= 52; // Reset to the beginning of the string
            }
        }
    }

    return records;
}

void freeRecords(Record* records, int n) {
    for (int i = 0; i < n; i++) {
        free(records[i].buffer);
        free((void*)&records[i]);
    }
    free(records);
}
