    return &array;
}

void free_data_structure(record_t* ds) {
    if (!ds) return;

    record_t** array = (record_t**)ds->array;
    size_t capacity = ds->capacity;

    for (size_t i = 0; i < capacity; ++i) {
        if (array[i]) {
            free(array[i]);
            array[i] = NULL;
        }
    }

    // Release custom memory pool
    free(ds->mem_pool);
}

void add_record(record_t* ds, long offset, int key) {
    pthread_mutex_lock(&mutex);

    size_t capacity = ds->capacity;
    size_t new_capacity = (capacity * 2 + 1); // Dynamic resize mechanism

    if (new_capacity > 100000) new_capacity = 100000; // Cap at max capacity

    record_t** array = (record_t**)malloc((new_capacity + 1) * sizeof(record_t*));
    memcpy(array, ds->array, capacity * sizeof(record_t*));

    free(ds->array);
    ds->array = array;

    ds->capacity = new_capacity;
    ds->size = ds->size + 1; // Update record count

    pthread_mutex_unlock(&mutex);
}

void serialize_data_structure(record_t* ds) {
