void generate_and_manage_list(int n, int cache_size) {
    // Internal cache mechanism
    size_t cache_max = cache_size;
    size_t cache_current = 0;
    uint32_t *cache = (uint32_t *)malloc(cache_max * sizeof(uint32_t));
    size_t cache_index = 0;

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for(int i = 0; i < n; i++) {
        uint32_t rnti;
        if(cache_index < cache_current) {
            // Reuse existing RNTI from cache
            rnti = cache[cache_index++]; 
        } else {
            // Generate new random RNTI
            rnti = rand();
            while(find_rnti_in_cache(cache, cache_max, rnti)) {
                rnti = rand();
            }
            if(cache_current < cache_max) {
                cache[cache_current++] = rnti;
            } else {
                // Cache full, remove least recently used RNTI
                cache[--cache_current] = 0; // Mark as removed
            }
        }

        list[i].rx_ue_info = ...; // Initialize RX_UE_INFORMATION_TAG
        list[i].rnti = rnti;
        list[i].crc_indication_rel8 = ...; // Initialize CRC_INDICATION_REL8_TAG

        // Set random CRCFLAG value for each NFAPI_CRC_INDICATION_PDU_T structure
        list[i].crc_indication_rel8.crcflag = rand() & 1;

        printf("RNTI: %u\n", list[i].rnti);
    }

    free(cache);

    // Serialize list into binary format for persistent storage and efficient retrieval
    FILE *file = fopen("list.bin", "wb");
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);
    fclose(file);

    // Deserialize list lazily upon demand to minimize initial load times and optimize memory consumption
    NFAPI_CRC_INDICATION_PDU_T *deserialized_list = NULL;
    int deserialized_n = 0;

    FILE *file = fopen("list.bin", "rb");
    if (fread(&deserialized_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file) != n) {
        printf("Error reading file.\n");
    }
    fclose(file);

    // Ensure thread safety and concurrent access control without significantly impacting performance
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    // ... access the list ...
    pthread_mutex_unlock(&mutex);

    free(list);
}

int find_rnti_in_cache(uint32_t *cache, size_t cache_size, uint32_t rnti) {
    for(size_t i = 0; i < cache_size; i++) {
        if(cache[i] == rnti) {
            return 1;
        }
    }
    return 0;
}

