#include <stdlib.h>
#include <stdio.h>

// Define the structure for the flexible data record
typedef struct {
    int key;
    long offset;
} Record;

// Define the memory pool structure
typedef struct {
    Record* records; // Pointer to the array of records
    size_t capacity; // Current capacity of the memory pool
    size_t size; // Actual number of records in the pool
} MemoryPool;

// Function to initialize the memory pool with a default size
MemoryPool* initialize_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;
    return pool;
}

// Function to dynamically resize the memory pool
void resize_memory_pool(MemoryPool* pool, size_t new_size) {
    if (new_size <= pool->size) return; // No need to reallocate

    Record* new_records = (Record*)realloc(pool->records, new_size * sizeof(Record));
    if (!new_records) return;

    pool->capacity = new_size;
    pool->records = new_records;
}

// Function to add a record to the memory pool
void add_record(MemoryPool* pool, int key, long offset) {
    if (pool->size >= pool->capacity / 2) resize_memory_pool(pool, pool->capacity * 2);

    Record* new_record = &pool->records[pool->size];
    new_record->key = key;
    new_record->offset = offset;
    pool->size++;
}

// Function to serialize the memory pool
void serialize_memory_pool(MemoryPool* pool, FILE* file) {
    fwrite(&pool->capacity, sizeof(size_t), 1, file);
    fwrite(&pool->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < pool->size; i++) {
        Record record = pool->records[i];
        fwrite(&record.key, sizeof(int), 1, file);
        fwrite(&record.offset, sizeof(long), 1, file);
    }
}

// Function to deserialize the memory pool
MemoryPool* deserialize_memory_pool(FILE* file) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));

    fread(&pool->capacity, sizeof(size_t), 1, file);
    fread(&pool->size, sizeof(size_t), 1, file);

    pool->records = (Record*)calloc(pool->capacity, sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < pool->size; i++) {
        Record record;
        fread(&record.key, sizeof(int), 1, file);
        fread(&record.offset, sizeof(long), 1, file);
        pool->records[i] = record;
    }
    return pool;
}

int main() {
    // Example usage
    MemoryPool* pool = initialize_memory_pool(1000);
    add_record(pool, 1, 12345);
    add_record(pool, 2, 67890);

    FILE* file = fopen("memory_pool.bin", "wb");
    serialize_memory_pool(pool, file);
    fclose(file);

    file = fopen("memory_pool.bin", "rb");
    pool = deserialize_memory_pool(file);
    fclose(file);

    return 0;
}
