#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RNTI 1000
#define CACHE_UPPER_LIMIT 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[6];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Internal cache structure
typedef struct CacheNode {
    char RNTI[6];
    pthread_mutex_t lock;
    int count;
} CacheNode;

// Hash table for caching unique RNTIs
CacheNode* cache = NULL;
int cache_size = 0;

// Lock for modifying the list and cache
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void nfaPI_crc_indication_pdu_list_init() {
    // Initialize cache with a small size to start with
    int i, j;
    cache = (CacheNode*) malloc(CACHE_UPPER_LIMIT * sizeof(CacheNode));
    for(i = 0; i < CACHE_UPPER_LIMIT; i++) {
        cache[i].count = 0;
        pthread_mutex_init(&cache[i].lock, NULL);
    }
}

void nfaPI_crc_indication_pdu_list_add(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Get the current RNTI and check if it's already in the cache
    char curr_rnti[6];
    strcpy(curr_rnti, pdu->RNTI);

    pthread_mutex_lock(&cache_lock);
    int found = 0;
    for(int i = 0; i < cache_size; i++) {
        if(strcmp(cache[i].RNTI, curr_rnti) == 0) {
            // If the RNTI is already in the cache, increment its count
            cache[i].count++;
            found = 1;
            break;
        }
    }

    pthread_mutex_unlock(&cache_lock);

    if(!found) {
        // If the RNTI is not in the cache, add it and update the cache size
        CacheNode* new_cache_node = (CacheNode*) malloc(sizeof(CacheNode));
        strcpy(new_cache_node->RNTI, curr_rnti);
        new_cache_node->count = 1;
        pthread_mutex_init(&new_cache_node->lock, NULL);

        // Rehash the cache to ensure unique RNTIs
        int i;
        for(i = 0; i < cache_size; i++) {
            if(strcmp(cache[i].RNTI, curr_rnti) == 0) {
                // If a duplicate is found, remove it and update the cache size
                free(cache[i].lock);
                free(cache[i]);
                for(int j = i; j < cache_size - 1; j++) {
                    cache[j] = cache[j + 1];
                }
                cache_size--;
                break;
            }
        }

        // Insert the new RNTI at the end of the cache
        if(i == cache_size) {
            for(int j = cache_size; j > i; j--) {
                cache[j] = cache[j - 1];
            }
            cache[i] = new_cache_node;
            cache_size++;
        } else {
            // If the cache is full, resize it and rehash
            CacheNode* temp_cache = (CacheNode*) malloc((cache_size + CACHE_UPPER_LIMIT) * sizeof(CacheNode));
            for(int j = 0; j < i; j++) {
                temp_cache[j] = cache[j];
            }
            temp_cache[i] = new_cache_node;
            for(int j = i + 1; j <= cache_size; j++) {
                temp_cache[j] = cache[j - 1];
            }
            free(cache);
            cache = temp_cache;
        }
    }
}

void nfaPI_crc_indication_pdu_list_remove(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Find the current RNTI in the cache
    char curr_rnti[6];
    strcpy(curr_rnti, pdu->RNTI);

    pthread_mutex_lock(&cache_lock);
    int found = 0;
    for(int i = 0; i < cache_size; i++) {
        if(strcmp(cache[i].RNTI, curr_rnti) == 0) {
            // If the RNTI is in the cache, decrement its count
            cache[i].count--;

            pthread_mutex_unlock(&cache_lock);

            if(cache[i].count == 0) {
                // If the count reaches zero, remove the RNTI from the cache
                free(cache[i].lock);
                free(cache[i]);
                for(int j = i; j < cache_size - 1; j++) {
                    cache[j] = cache[j + 1];
                }
                cache_size--;
            } else {
                // If the count is greater than zero, update the cache size
                pthread_mutex_lock(&cache_lock);
                break;
            }
        }
    }

    pthread_mutex_unlock(&cache_lock);
