} RNTI_CACHE;

RNTI_CACHE *rnti_cache = NULL;

void generate_list(int n, NFAPI_CRC_INDICATION_PDU_T **list) {
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->rx_ue_info = ...; // random value
        RNTI rnti;
        while (true) {
            rnti = rand() % MAX_RNTI;
            if (!find_rnti(rnti)) {
                pdu->rnti = rnti;
                break;
            }
        }
        pdu->crc_indication_rel8_tag = ...; // random value
        pdu->crcflag = rand() % 2;
        *list++ = pdu;
    }
}

int find_rnti(int rnti) {
    RNTI_CACHE *current = rnti_cache;
    while (current != NULL) {
        if (current->value == rnti) {
            return 1; // rnti found in cache
        }
        current = current->next;
    }
    return 0; // rnti not found in cache
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T *list, int n, char *output_file) {
