#include <stdio.h>
#include <stdlib.h>

// Define the TrafficFlow structure
typedef struct {
    int FlowIdentifier;
    int PacketCount;
    int ByteCount;
} TrafficFlow;

// Define the dynamic array type
typedef struct {
    TrafficFlow* flows;
    int size;
    int capacity;
} TrafficFlowArray;

// Function to create a new TrafficFlowArray
TrafficFlowArray* trafficFlowArrayCreate(int initialCapacity) {
    TrafficFlowArray* arr = (TrafficFlowArray*)malloc(sizeof(TrafficFlowArray));
    arr->flows = (TrafficFlow*)malloc(initialCapacity * sizeof(TrafficFlow));
    arr->size = 0;
    arr->capacity = initialCapacity;
    return arr;
}

// Function to add a new TrafficFlow to the array
void trafficFlowArrayAdd(TrafficFlowArray* arr, int flowIdentifier, int packetCount, int byteCount) {
    if (arr->size >= arr->capacity) {
        // Double the capacity and reallocate memory
        arr->flows = (TrafficFlow*)realloc(arr->flows, 2 * arr->capacity * sizeof(TrafficFlow));
        arr->capacity *= 2;
    }
    arr->flows[arr->size].FlowIdentifier = flowIdentifier;
    arr->flows[arr->size].PacketCount = packetCount;
    arr->flows[arr->size].ByteCount = byteCount;
    arr->size++;
}

// Function to update the statistics of a specific flow
void trafficFlowArrayUpdate(TrafficFlowArray* arr, int flowIdentifier, int packetCountDelta, int byteCountDelta) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->flows[i].FlowIdentifier == flowIdentifier) {
            arr->flows[i].PacketCount += packetCountDelta;
            arr->flows[i].ByteCount += byteCountDelta;
            return;
        }
    }
}

// Function to calculate the total byte count for active flows
int trafficFlowArrayGetTotalByteCount(TrafficFlowArray* arr) {
    int totalByteCount = 0;
    for (int i = 0; i < arr->size; i++) {
        totalByteCount += arr->flows[i].ByteCount;
    }
    return totalByteCount;
}

// Function to serialize the TrafficFlowArray to a persistent storage
void trafficFlowArraySerialize(TrafficFlowArray* arr, FILE* file) {
    fwrite(&arr->size, sizeof(int), 1, file);
    for (int i = 0; i < arr->size; i++) {
        fwrite(&arr->flows[i], sizeof(TrafficFlow), 1, file);
    }
}

// Function to deserialize the TrafficFlowArray from a persistent storage
TrafficFlowArray* trafficFlowArrayDeserialize(FILE* file) {
    int size;
    fread(&size, sizeof(int), 1, file);
    TrafficFlowArray* arr = trafficFlowArrayCreate(size);
    for (int i = 0; i < size; i++) {
        fread(&(arr->flows[i]), sizeof(TrafficFlow), 1, file);
    }
    return arr;
}
