#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the 'detail' struct
typedef struct {
    long field1;
    long field2;
    enum type { TYPE_A, TYPE_B } type;
} detail;

// Define the 'record' struct
typedef struct {
    int value;
    char status;
    detail* ptr;
} record;

// Define the hash table node
typedef struct Node {
    int key;
    long offset;
    struct Node* next;
} Node;

// Initialize a new hash table node
Node* create_node(int key, long offset) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->offset = offset;
    node->next = NULL;
    return node;
}

// Hash function for collision resolution
unsigned int hash_function(int key) {
    return key % 128; // Use a suitable prime number or power of 2
}

// Initialize the memory pool
void* init_memory_pool(size_t size) {
    void* mem = malloc(size);
    if (!mem) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }
    return mem;
}

// Allocate and initialize arrays and record structures
record** allocate_and_init_arrays(int array_size, int record_size) {
    record** records = (record**)malloc(array_size * sizeof(record*));
    for (int i = 0; i < array_size; i++) {
        records[i] = (record*)malloc(record_size * sizeof(record));
        // Initialize random values
        srand(time(NULL));
        for (int j = 0; j < record_size; j++) {
            records[i][j].value = rand() % 100;
            records[i][j].status = 'A' + rand() % 26;
            // Allocate memory for the detail struct
            records[i][j].ptr = (detail*)malloc(sizeof(detail));
            // Initialize random values for the detail struct
            records[i][j].ptr->field1 = rand() % 1000;
            records[i][j].ptr->field2 = rand() % 10000;
            records[i][j].ptr->type = TYPE_A + rand() % 2;
        }
    }
    return records;
}

// Initialize the hash table
Node** init_hash_table(int table_size) {
    Node** table = (Node**)malloc(table_size * sizeof(Node*));
    for (int i = 0; i < table_size; i++) {
        table[i] = NULL;
    }
    return table;
}

// Validate and insert into the hash table
void validate_and_insert_hash_table(record* record_ptr, Node** table) {
    int key = record_ptr->value;
    long offset = record_ptr->ptr->field1;
    // Check for duplicate keys with different offsets
    if (table[hash_function(key)] != NULL) {
        Node* node = table[hash_function(key)];
        while (node != NULL) {
            if (node->key == key && node->offset == offset) {
                printf("Error: Duplicate key and offset combination found.\n");
                return;
            }
            node = node->next;
        }
    }
    // Insert the record into the hash table
    Node* new_node = create_node(key, offset);
    if (table[hash_function(key)] != NULL) {
        Node* prev = table[hash_function(key)];
        while (prev->next != NULL) {
            prev = prev->next;
        }
        prev->next = new_node;
    } else {
        table[hash_function(key)] = new_node;
    }
}

// Free memory
void free_memory(record** records, int array_size, Node** table, int table_size) {
    for (int i = 0; i < array_size; i++) {
        for (int j = 0; j < record_size; j++) {
            // Free the detail struct and the record itself
            free(records[i][j].ptr);
            free(records[i][j]);
        }
        free(records[i]);
    }
    for (int i = 0; i < table_size; i++) {
        Node* node = table[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    // Free the arrays and hash table
    free(records);
    free(table);
}

int main() {
    int array_size = 1000, record_size = 5, table_size = 128;
    record** records = allocate_and_init_arrays(array_size, record_size);
    Node** table = init_hash_table(table_size);
    for (int i = 0; i < array_size; i++) {
        record* record_ptr = &records[i][0];
        validate_and_insert_hash_table(record_ptr, table);
    }
    free_memory(records, array_size, table, table_size);
    return 0;
}
