LTE_RRC_UE_CONTEXT_T** lte_rrc_ue_contexts = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_ue_context() {
    LTE_RRC_UE_CONTEXT_T* ue_context = (LTE_RRC_UE_CONTEXT_T*) malloc(sizeof(LTE_RRC_UE_CONTEXT_T));
    if (!ue_context) return NULL;

    // Initialize UE_ID, SIB1_DATA, and BSR_INFO_LIST
    ue_context->UE_ID = rand();
    strcpy(ue_context->SIB1_DATA, "Random SIB1 DATA");
    ue_context->BSR_INFO_LIST = (BSR_INFO_LIST_T*) malloc(sizeof(BSR_INFO_LIST_T) * BSR_INFO_LIST_SIZE);

    for (int i = 0; i < BSR_INFO_LIST_SIZE; i++) {
        ue_context->BSR_INFO_LIST[i].SR_FLAG = rand() % 2;
        ue_context->BSR_INFO_LIST[i].CQI = rand();
        ue_context->BSR_INFO_LIST[i].PMI = rand();
    }

    return ue_context;
}

void init_ue_contexts(int num_contexts) {
    lte_rrc_ue_contexts = (LTE_RRC_UE_CONTEXT_T**) malloc(sizeof(LTE_RRC_UE_CONTEXT_T*) * num_contexts);

    for (int i = 0; i < num_contexts; i++) {
        lte_rrc_ue_contexts[i] = allocate_ue_context();

        if (!lte_rrc_ue_contexts[i]) {
            // Handle allocation failure
            printf("Allocation failed! Exiting...\n");
            exit(1);
        }
    }
}

void resize_ue_contexts(int num_contexts) {
    LTE_RRC_UE_CONTEXT_T** new_array = (LTE_RRC_UE_CONTEXT_T**) realloc(lte_rrc_ue_contexts, sizeof(LTE_RRC_UE_CONTEXT_T*) * num_contexts);

    if (!new_array) {
        // Handle reallocation failure
        printf("Reallocation failed! Exiting...\n");
        exit(1);
    }

    lte_rrc_ue_contexts = new_array;
}

void cleanup_ue_contexts() {
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (lte_rrc_ue_contexts[i]) {
            // Free allocated resources
            free(lte_rrc_ue_contexts[i]->BSR_INFO_LIST);
            free(lte_rrc_ue_contexts[i]);
        }
    }
}

void* thread_safe_access(void* arg) {
    int context_id = *(int*) arg;

    pthread_mutex_lock(&lock);

    // Access UE context
    printf("Thread %d accessing UE context %d...\n", getpid(), context_id);

    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    int num_contexts = 10; // Initial number of contexts

    init_ue_contexts(num_contexts);

    // Simulate concurrent access
    for (int i = 0; i < num_contexts; i++) {
        pthread_t thread;
        int* context_id = &i;

        pthread_create(&thread, NULL, thread_safe_access, context_id);
        pthread_join(thread, NULL);
    }

    // Resize array when necessary
    if (num_contexts > MAX_CONTEXTS / 2) {
        num_contexts *= 2; // Double the number of contexts

        resize_ue_contexts(num_contexts);

        printf("Resized array to hold %d contexts...\n", num_contexts);
    }

    cleanup_ue_contexts();

    return 0;
}
