def modify_kickstart_config(config_path, placeholders, data):
    with open(config_path, 'r') as file:
        config = file.read()

    for placeholder, value in placeholders.items():
        command = f"sed -i 's/{placeholder}/{{value}}/g' {config_path}"
        try:
            subprocess.run(command.split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except subprocess.CalledProcessError as e:
            print(f"Error replacing placeholder '{placeholder}': {e}")
            raise

    new_section = f"[newsection]\n{data}\n"
    with open(config_path, 'a') as file:
        file.write(new_section)

def generate_system_data():
    uptime = str(datetime.datetime.now())
    current_date = str(datetime.date.today())
    network_stats = {
        "ip": socket.gethostbyname(socket.gethostname()),
        "netmask": socket.gethostinfo(socket.gethostname())[4][0],
        "gateway": socket.getdefaultgw()[0]
    }
    return f"{uptime}\n{current_date}\n{json.dumps(network_stats)}\n"

def validate_placeholders(placeholders):
    required_placeholders = {" placeholder1", "placeholder2"}
    for placeholder in required_placeholders:
        if placeholder not in placeholders or not placeholders[placeholder]:
            raise ValueError(f"Required placeholder '{placeholder}' is missing or invalid.")

def save_config(config_path, new_config):
    version = 0
    while os.path.exists(f"{config_path}.{version}"):
        version += 1

    with open(f"{config_path}.{version}", 'w') as file:
        file.write(new_config)

    if os.path.exists(config_path) and input("Overwrite original file? (y/n): ") == "y":
        os.replace(f"{config_path}.{version}", config_path)
    else:
