        UE_CONTEXTS[i].sib1_data = SIB1_DATA;
        UE_CONTEXTS[i].bsr_info_list = bsr_info_list;
        pthread_mutex_unlock(&lock);

    }

    // Initialize logging system
    int log_level = LOGGING_LEVEL;

    return ue_contexts;
}

void update_ue_context(LTE_RRC_UE_CONTEXT_T* context, int new_sr_flag, int new_cqi, int new_pmi) {
    pthread_mutex_lock(&lock);
    context->sr_flag = new_sr_flag;
    context->cqi = new_cqi;
    context->pmi = new_pmi;
    pthread_mutex_unlock(&lock);
}

void delete_ue_context(LTE_RRC_UE_CONTEXT_T* context) {
    pthread_mutex_lock(&lock);
    free(context->sib1_data);
    free(context->bsr_info_list);
    pthread_mutex_unlock(&lock);

    // Handle potential out-of-memory conditions
    if (memory_usage() > MEMORY_THRESHOLD) {
        log_error("Memory threshold exceeded");
        release_old_ue_contexts();
    }
}

int memory_usage() {
    int total_size = 0;
    for (int i = 0; i < UE_CONTEXTS_SIZE; i++) {
        total_size += sizeof(LTE_RRC_UE_CONTEXT_T) + strlen(UE_CONTEXTS[i].sib1_data) + sizeof(BSR_INFO_LIST_T);
    }
    return total_size;
}

void release_old_ue_contexts() {
    // Prioritize releasing older UE contexts based on last access time
    int i, j;
    for (i = 0; i < UE_CONTEXTS_SIZE - 1; i++) {
        for (j = i + 1; j < UE_CONTEXTS_SIZE; j++) {
            if (ue_contexts[j].last_access_time < ue_contexts[i].last_access_time) {
                // Swap context
                LTE_RRC_UE_CONTEXT_T temp = ue_contexts[i];
                ue_contexts[i] = ue_contexts[j];
                ue_contexts[j] = temp;
            }
        }
    }

    for (i = UE_CONTEXTS_SIZE - 1; i >= 0; i--) {
        free(ue_contexts[i].sib1_data);
        free(ue_contexts[i].bsr_info_list);
        // Handle potential out-of-memory conditions
        if (memory_usage() > MEMORY_THRESHOLD) {
            log_error("Memory threshold exceeded");
            return;
        }
    }

    UE_CONTEXTS_SIZE--;
}

void log_error(const char* message) {
    // Log error and notify monitoring system
}
