// Custom memory pool with LRU eviction policy
typedef struct {
    void **pool;
    int size;
    int head;
    int tail;
} MemoryPool;

// Initialize the memory pool
void init_memory_pool(MemoryPool *pool, int size) {
    pool->size = size;
    pool->head = 0;
    pool->tail = 0;
    pool->pool = (void **)malloc(sizeof(void *) * size);
}

// Deallocate memory from the pool using LRU eviction
void deallocate_memory(MemoryPool *pool, void *ptr) {
    // Find the index of the least-recently-used element
    int idx = pool->head;
    while (idx != pool->tail && !((char *)pool->pool[idx] == ptr)) {
        idx = (idx + 1) % pool->size;
    }

    if (idx == pool->tail) {
        // Reclaim the memory
        free(pool->pool[idx]);
        pool->pool[idx] = NULL;
    }
}

// Thread-safe list management function
void *nfapi_crc_indication_pdu_list_manager() {
    // Initialize the list and memory pool
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ELEMENTS);
    MemoryPool mp;
    init_memory_pool(&mp, MAX_ELEMENTS);

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Main function loop
    while (1) {
        // Perform list operations with thread-safe access
        pthread_mutex_lock(&lock);
        // Add elements to the list or update existing ones
        pthread_mutex_unlock(&lock);

        // Periodically reclaim memory from the pool using LRU eviction
        if (mp.tail > mp.head + 0.5 * mp.size) {
            deallocate_memory(&mp, list[mp.head]);
        }
    }

    free(list);
    return NULL;
}

