// Function to calculate the total value of items in each transaction
void calculateTransactionTotals(transaction transactions[], int numTransactions, float totals[]) {
    for (int i = 0; i < numTransactions; i++) {
        totals[i] = 0.0f;
        // Iterate over all items in this transaction
        for (int j = 0; j < sizeof(transactions[i].item) / sizeof(item); j++) {
            totals[i] += transactions[i].item[j].value;
        }
    }
}

// Function to filter transactions based on a specified date range
transaction* filterTransactions(transaction transactions[], int numTransactions, time_t start, time_t end, int* filteredCount) {
    transaction* filtered = (transaction*)malloc(sizeof(transaction) * numTransactions);
    *filteredCount = 0;

    for (int i = 0; i < numTransactions; i++) {
        if (transactions[i].timestamp >= start && transactions[i].timestamp <= end) {
            filtered[(*filteredCount)++] = transactions[i];
        }
    }

    return filtered;
}

