#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long timestamp;
    int status_code;
    double value;
} record_t;

// Define the dynamic collection of records
typedef struct {
    record_t* records; // array of records
    size_t capacity; // current capacity of the array
    size_t count; // number of records currently stored
    pthread_mutex_t lock; // mutex for thread-safe access
    pthread_cond_t cond; // condition variable for cleanup
} record_collection_t;

// Initialize the record collection
record_collection_t* record_collection_create(size_t initial_capacity) {
    record_collection_t* rc = malloc(sizeof(record_collection_t));
    if (!rc) return NULL;
    rc->records = malloc(initial_capacity * sizeof(record_t));
    rc->capacity = initial_capacity;
    rc->count = 0;
    pthread_mutex_init(&rc->lock, NULL);
    pthread_cond_init(&rc->cond, NULL);
    return rc;
}

// Add a new record to the collection
void record_collection_add(record_collection_t* rc, record_t* new_record) {
    pthread_mutex_lock(&rc->lock);
    if (rc->count >= rc->capacity) {
        // Reallocate and grow the array capacity
        size_t new_capacity = rc->capacity * 2;
        record_t* new_records = realloc(rc->records, new_capacity * sizeof(record_t));
        if (!new_records) {
            pthread_mutex_unlock(&rc->lock);
            return; // out of memory, abort
        }
        rc->records = new_records;
        rc->capacity = new_capacity;
    }
    records[rc->count++] = *new_record;
    pthread_mutex_unlock(&rc->lock);
}

// Remove a record from the collection by timestamp
void record_collection_remove_by_timestamp(record_collection_t* rc, long target_timestamp) {
    pthread_mutex_lock(&rc->lock);
    for (size_t i = 0; i < rc->count; i++) {
        if (records[i].timestamp == target_timestamp) {
            // Shift remaining records to fill the gap
            memmove(&records[i], &records[i + 1], (rc->count - i - 1) * sizeof(record_t));
            rc->count--;
            break;
        }
    }
    pthread_mutex_unlock(&rc->lock);
}

// Update a record by timestamp
void record_collection_update_by_timestamp(record_collection_t* rc, long target_timestamp, record_t* new_record) {
    pthread_mutex_lock(&rc->lock);
    for (size_t i = 0; i < rc->count; i++) {
        if (records[i].timestamp == target_timestamp) {
            // Update the existing record
            records[i] = *new_record;
            break;
        }
    }
    pthread_mutex_unlock(&rc->lock);
}

// Periodic cleanup mechanism to remove old records
void* record_collection_cleanup_thread(void* arg) {
    record_collection_t* rc = (record_collection_t*)arg;
    while (1) {
        // Sleep for a short duration before checking again
        sleep(5); // adjust the frequency as needed
        pthread_mutex_lock(&rc->lock);
        size_t i = 0;
        while (i < rc->count) {
            if (records[i].timestamp + /* threshold value */ <= time(NULL)) {
                // Remove old records
                memmove(&records[i], &records[i + 1], (rc->count - i - 1) * sizeof(record_t));
                rc->count--;
                i--; // re-check the same index
            }
            i++;
        }
        pthread_mutex_unlock(&rc->lock);
    }
}

// Clean up and free resources when done with the record collection
void record_collection_free(record_collection_t* rc) {
    if (!rc) return;
    pthread_mutex_destroy(&rc->lock);
    pthread_cond_destroy(&rc->cond);
    free(rc->records);
    free(rc);
}
