        // Generate a random RX_UE_INFORMATION_TAG and RNTI
        int new_RNTI = rand() % N;
        while (!RNTI_valid[new_RNTI]) {
            if (new_RNTI == N) break;
            new_RNTI = rand() % N;
        }

        list[i]->RX_UE_INFORMATION_TAG = i; // Assign RX_UE_INFORMATION_TAG
