// Define the structure for DL CI PDUs
typedef struct {
    int label;
    uint16_t rnti;
    int crc_tag;
} dlcipdu_t;

// Define the structure for the dynamic list of DL CI PDUs
typedef struct {
    dlcipdu_t* elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} dlcilist_t;

// Function to create a new DL CI list
dlcilist_t* dlcilist_create(size_t initial_capacity) {
    dlcilist_t* list = (dlcilist_t*)malloc(sizeof(dlcilist_t));
    if (!list) return NULL; // Handle memory allocation failure
    pthread_mutex_init(&list->mutex, NULL);
    list->elements = (dlcipdu_t*)calloc(initial_capacity, sizeof(dlcipdu_t));
    list->capacity = initial_capacity;
    list->size = 0;
    return list;
}

// Function to add a new DL CI PDU to the list
int dlcilist_add(dlcilist_t* list, int label, uint16_t rnti) {
    if (rnti < 0 || rnti > 65535) { // Validate RNTI value
        rnti = 1; // Set default identifier for out-of-range values
    }
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        dlcipdu_t* new_elements = (dlcipdu_t*)realloc(list->elements, new_capacity * sizeof(dlcipdu_t));
        if (!new_elements) { // Handle memory allocation failure
            pthread_mutex_unlock(&list->mutex);
            return -1; // Indicate error
        }
        list->capacity = new_capacity;
        list->elements = new_elements;
    }
    list->elements[list->size].label = label;
    list->elements[list->size].rnti = rnti;
    list->elements[list->size].crc_tag = 0; // Initialize CRC tag
    ++list->size;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Indicate success
}

// Function to remove a DL CI PDU from the list by label
int dlcilist_remove(dlcilist_t* list, int label) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].label == label) {
            memmove(&list->elements[i], &list->elements[i + 1], (list->size - i - 1) * sizeof(dlcipdu_t));
            --list->size;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return 0; // Indicate success
}

// Function to iterate over the DL CI list
void dlcilist_iterate(const dlcilist_t* list, void (*callback)(const dlcipdu_t*)) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        callback(list->elements[i]);
    }
    pthread_mutex_unlock(&list->mutex);
}

