int serialize_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_array, int num_structures, char* output_dir_path) {
    FILE* file = fopen(output_dir_path, "wb");
    if (!file) {
        log_error("Failed to open file for writing: %s", output_dir_path);
        return -1; // Error
    }

    for (int i = 0; i < num_structures; i++) {
        fwrite(&crc_indication_pdu_array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);

    return 0;
}

