Record** manageRecords(int* capacity, int* size) {
    // Allocate memory for records and their pointers
    Record** records = (Record**)malloc(sizeof(Record*) * (*capacity + 1));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize records with unique key-offset pairs
    for (int i = 0; i < (*size); i++) {
        int key = rand() % 1000; // Generate a random integer within [0, 999]
        long offset = (long)rand(); // Generate a random long value
        if (!records[i]) {
            printf("Memory allocation failed for record.\n");
            return NULL;
        }
        records[i]->key = key;
        records[i]->offset = offset;
    }

    *capacity += (*size);
    *size = 0; // Reset size to zero

    return records;
}

void insertRecord(Record** records, int* capacity, int* size) {
    // Check for available space
    if (*size >= *capacity) {
        printf("Reached maximum capacity. Increase the capacity.\n");
        return;
    }

    // Allocate memory for a new record
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        printf("Memory allocation failed for record.\n");
        return;
    }

    int key = rand() % 1000; // Generate a random integer within [0, 999]
    long offset = (long)rand(); // Generate a random long value

    record->key = key;
    record->offset = offset;

    records[(*size)++] = record;
}

Record* findRecord(Record** records, int size, int targetKey) {
    for (int i = 0; i < size; i++) {
        if (records[i]->key == targetKey) {
            return records[i];
        }
    }

    return NULL;
}
