void insertAfter(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& nfapduList, const std::string& target, const std::string& newString) {
    auto it = nfapduList.begin();
    while (it != nfapduList.end()) {
        if (it->rxTag == target) {
            nfapduList.insert_after(it, newString);
            return;
        }
        ++it;
    }
    nfapduList.append(newString);
