#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NFAPI 1000
#define MAX_RNTI 1000
#define MAX_CRCFLAG 1000
#define RANDOM_RANGE 10
#define AGE_THRESHOLD 30 // in seconds
#define CLEANUP_INTERVAL 5 // in seconds

typedef struct {
    long *offsets;
    int **keys;
    time_t timestamp;
    int accessed;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pool_create(int size) {
    NFAPI_CRC_INDICATION_PDU_T* pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for(int i = 0; i < size; i++) {
        pool[i].offsets = (long*)malloc(RANDOM_RANGE * sizeof(long));
        pool[i].keys = (int**)malloc(RANDOM_RANGE * sizeof(int*));

        for(int j = 0; j < RANDOM_RANGE; j++) {
            pool[i].offsets[j] = rand() % 100;
            pool[i].keys[j] = malloc(sizeof(int));
            *(pool[i].keys[j]) = rand() % 100;
        }

        pool[i].timestamp = time(NULL);
        pool[i].accessed = 0;
    }

    return pool;
}

void pool_destroy(NFAPI_CRC_INDICATION_PDU_T* pool, int size) {
    for(int i = 0; i < size; i++) {
        free(pool[i].offsets);
        for(int j = 0; j < RANDOM_RANGE; j++) {
            free(pool[i].keys[j]);
        }
        free(pool[i].keys);
    }

    free(pool);
}

void pool_cleanup(NFAPI_CRC_INDICATION_PDU_T* pool, int size) {
    time_t current_time = time(NULL);

    for(int i = 0; i < size; i++) {
        if(current_time - pool[i].timestamp > AGE_THRESHOLD && !pool[i].accessed) {
            // record is old and not accessed
            free(pool[i].offsets);
            for(int j = 0; j < RANDOM_RANGE; j++) {
                free(pool[i].keys[j]);
            }
            free(pool[i].keys);

            memmove(&pool[i], &pool[i + 1], (size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            size--;
            i--;
        } else if(current_time - pool[i].timestamp > CLEANUP_INTERVAL && pool[i].accessed) {
            // record is old and accessed
            free(pool[i].offsets);
            for(int j = 0; j < RANDOM_RANGE; j++) {
                free(pool[i].keys[j]);
            }
            free(pool[i].keys);

            memmove(&pool[i], &pool[i + 1], (size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            size--;
            i--;
        }
    }

    // resize the array to match the actual number of elements
    pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T* pool, int size) {
    for(int i = 0; i < size; i++) {
        pool[i].accessed = 1;
        pool[i].timestamp = time(NULL);

        if(rand() % 2 == 1)
            pool[i].accessed = 0;
    }
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* pool = pool_create(MAX_NFAPI);

    // use the pool
    set_crcflag(pool, MAX_NFAPI);

    // cleanup unused records periodically
    while(1) {
        pool_cleanup(pool, MAX_NFAPI);

        sleep(CLEANUP_INTERVAL);
    }

    // destroy the pool when done
    pool_destroy(pool, MAX_NFAPI);

    return 0;
}
