#include <sys/types.h>
#include <sys/sysctl.h>
#include <pthread.h>

#define MAX_RNTI 100000
#define CRCFLAG_MAX 0x1FFFFF

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(int n) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    // Initialize buffer size based on system load
    int buffer_size = (int)(sysctlbyname("hw.memsize", NULL, 0, NULL, 0)) / (1 << 20);
    buffer_size /= 4; // adjust for NFAPI_CRC_INDICATION_PDU_T struct size

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(buffer_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        int RNTI = rand() % MAX_RNTI;
        // Ensure uniqueness of RNTI values
        for (int j = 0; j < i; j++) {
            if (list[j].RNTI == RNTI) {
                RNTI = rand() % MAX_RNTI;
                break;
            }
        }

        int CRCFLAG = rand() % CRCFLAG_MAX;
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = RNTI;
        list[i].CRC_INDICATION_REL8_TAG = rand();
        list[i].CRCFLAG = CRCFLAG;

        pthread_mutex_lock(&lock);
        int ret = log_event("NFAPI_CRC_INDICATION_PDU_T created", i, RNTI, CRCFLAG);
        if (ret < 0) {
            perror("Log failed");
