class DataPacket {
public:
    int timestamp;
    int packetSize;
    std::string payload;
};

DataPacket* allocateDataPackets(int numPackets) {
    if (numPackets > 1000000) {
        throw std::runtime_error("Cannot allocate more than 1 million packets");
    }

    DataPacket* packets = new(std::nothrow) DataPacket[numPackets];

    if (!packets) {
        throw std::bad_alloc();
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 255);

    for (int i = 0; i < numPackets; ++i) {
        packets[i].timestamp = i;
        packets[i].packetSize = dis(gen);
        packets[i].payload.resize(dis(gen));
        std::generate(packets[i].payload.begin(), packets[i].payload.end(),
                      [&gen, &dis]() { return static_cast<char>(dis(gen)); });
    }

    return packets;
}

void deallocateDataPackets(DataPacket* packets, int numPackets) {
    delete[] packets;
}

