typedef struct {
    int priority;
    time_t deadline;
    char status;
} Task;

task_list* init_task_list(int capacity) {
    task_list* list = (task_list*)malloc(sizeof(task_list));
    list->tasks = (Task**)calloc(capacity, sizeof(Task*));
    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_task(task_list* list, Task* task) {
    if (list->size >= list->capacity) {
        // Resize the array
        list->tasks = (Task**)realloc(list->tasks, sizeof(Task*) * (list->capacity *= 2));
    }
    pthread_mutex_lock(&list->lock);
    list->tasks[list->size++] = task;
    pthread_cond_broadcast(&list->change_notification);
    pthread_mutex_unlock(&list->lock);
}

void remove_task(task_list* list, int index) {
    if (index < 0 || index >= list->size) {
        return; // Task not found
    }
    pthread_mutex_lock(&list->lock);
    Task* task = list->tasks[index];
    memmove(list->tasks + index, list->tasks + index + 1, sizeof(Task*) * (list->size - index - 1));
    free(task);
    list->size--;
    pthread_cond_broadcast(&list->change_notification);
    pthread_mutex_unlock(&list->lock);
}

void notify_task_change(task_list* list) {
    pthread_mutex_lock(&list->lock);
    pthread_cond_signal(&list->change_notification);
    pthread_mutex_unlock(&list->lock);
}

task_list* get_task_list() {
    return task_list;
}
