// Define the job structure
typedef struct {
    double estimated_duration;
    struct tm start_time;
    bool completion_status;
    int assigned_worker_id;
} Job;

// Function to manage an array of 'job' structures
Job** manage_jobs(int* num_jobs, int* capacity) {
    // Initialize job array and its size
    *num_jobs = 0;
    *capacity = 2;  // Initial capacity

    Job** jobs = (Job**)malloc((*capacity)*sizeof(Job*));
    if (!jobs) {
        return NULL;  // Handle memory allocation failure
    }

    return jobs;
}

// Function to dynamically resize the job array when necessary
void resize_jobs(Job** jobs, int* num_jobs, int* capacity) {
    if (*num_jobs >= *capacity) {
        // Double the current capacity for efficient growth
        *capacity *= 2;

        Job** new_jobs = (Job**)realloc(jobs, *capacity * sizeof(Job*));
        if (!new_jobs) {
            // Handle memory allocation failure and retry
            free(jobs);
            jobs = manage_jobs(num_jobs, capacity);
            return;
        }

        *num_jobs = *capacity;  // Update the job array size
    }
}

// Function to add a new job to the array
void add_job(Job** jobs, int* num_jobs, int* capacity) {
    if (*num_jobs >= *capacity) {
        resize_jobs(jobs, num_jobs, capacity);
    }

    Job* new_job = (Job*)malloc(sizeof(Job));
    // Assign default values or retrieve job data from an external source
    new_job->estimated_duration = 0.0;
    new_job->start_time.tm_sec = 0;  // Initialize start time
    new_job->completion_status = false;
    new_job->assigned_worker_id = -1;

    jobs[(*num_jobs)++] = new_job;
}

// Function to update a job's completion status
void update_job(Job** jobs, int index) {
    if (index >= 0 && index < *num_jobs) {
        // Perform necessary updates on the specified job
        jobs[index]->completion_status = true;
    }
}
