    for (int k = 0; k < merged_size_total; k++) {
        if (i >= size1) {
            (*merged_keys)[k] = key2[j++];
        } else if (j >= size2 || (key1[i] <= key2[j])) {
            (*merged_keys)[k] = key1[i++];
