    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeMemoryCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &jb);

    // Perform the request and parse the response
    res = curl_easy_perform(curl);
    if(res != CURLE_OK) {
        printf("cURL error: %s\n", curl_easy_strerror(res));
        return;
    }

    // Process the parsed JSON data
    json_object *bundle = json_object_object_get(jb, "resourceBundle");
    int count = json_object_array_length(bundle);
    for(int i = 0; i < count; i++) {
        Resource* resource = (Resource*)malloc(sizeof(Resource));
        json_object *resourceObj = json_object_array_get_idx(bundle, i);
        resource->id = json_object_get_int(resourceObj, "id");
        resource->name = strdup(json_object_get_string(resourceObj, "name"));
        // Add the resource to a global array or cache
    }

    // Clean up and free resources
    curl_easy_cleanup(curl);
    curl_global_cleanup();
}

// Memory write callback for cURL
static size_t writeMemoryCallback(void *ptr, size_t size, size_t nmemb, void *data) {
    json_object *jb = (json_object*)data;
    json_object_insert(jb, "response", json_string_create(ptr, size * nmemb));
    return size * nmemb;
}

// Function to find the largest integer in a sorted array
int findLargest(int* arr, int len) {
    int max = arr[0];
    for(int i = 1; i < len; i++) {
        if(arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to merge and sort two arrays based on 'int' key values
void mergeAndSortArrays(int** offsets, int* keys, int offsetCount, int keyCodeCount) {
    int* mergedArr = (int*)malloc((offsetCount + keyCodeCount)*sizeof(int));
    int index = 0;

    // Merge the arrays into a single sorted array
    for(int i = 0; i < offsetCount; i++) {
        for(int j = 0; j < keyCodeCount && keys[j] <= offsets[i]; j++);
        mergedArr[index++] = offsets[i];
        for(int k = j; k < keyCodeCount && keys[k] <= offsets[i]; k++) {
            mergedArr[index++] = keys[k];
        }
    }

    // Find and print the largest integer in the merged array
    int largest = findLargest(mergedArr, index);

    printf("The largest integer is: %d\n", largest);

    // Clean up and free resources
    free(mergedArr);
}

int main() {
    // Read a list of integers from a file
    FILE *fp = fopen("input.txt", "r");
    int numEntries;
    fscanf(fp, "%d", &numEntries);
    int* offsets = (int*)malloc(numEntries*sizeof(int));
    int* keys = (int*)malloc(numEntries*sizeof(int));

    // Initialize the arrays with data from the file
    for(int i = 0; i < numEntries; i++) {
        fscanf(fp, "%d %d", &offsets[i], &keys[i]);
    }

    // Merge and sort the arrays based on 'int' key values
    mergeAndSortArrays(&offsets, keys, numEntries, numEntries);

    return 0;
}
