import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;

public class MessageProcessor {
    private static final int THREAD_POOL_SIZE = 10;
    private static final String LOGGING_SERVICE_URL = System.getProperty("LOGGING_SERVICE_URL");

    public void processMessages(String[] messages) throws IOException {
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        try {
            for (String message : messages) {
                executor.submit(() -> processMessage(message));
            }
            executor.shutdown();
            while (!executor.isTerminated()) {
                // wait for all tasks to complete
            }
        } finally {
            if (!executor.isShutdown()) {
                executor.shutdownNow();
            }
        }
    }

    private void processMessage(String message) throws IOException {
        String[] parts = message.split(",");
        String messageId = parts[0];
        String body = new String(parts[1].getBytes(), "UTF-8");

        try {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md5.digest(body.getBytes("UTF-8"));
            String hashHex = bytesToHex(hashBytes);

            // log the message with its MD5 hash
            if (LOGGING_SERVICE_URL != null) {
                try (java.net.URLConnection connection = new java.net.URL(LOGGING_SERVICE_URL).openStream()) {
                    java.io.PrintWriter out = new java.io.PrintStream(connection.getOutputStream());
                    out.println("Message ID: " + messageId);
                    out.println("MD5 Hash: " + hashHex);
                    out.close();
                } catch (IOException e) {
                    // log the error and continue
                    System.err.println("Error logging message: " + e.getMessage());
                }
            } else {
                System.out.println("Message ID: " + messageId);
                System.out.println("MD5 Hash: " + hashHex);
            }
        } catch (NoSuchAlgorithmException e) {
            // log the error and continue
            System.err.println("Error computing MD5 hash: " + e.getMessage());
        } catch (Exception e) {
            // log the error and rethrow
            System.err.println("Error processing message: " + e.getMessage());
            throw e;
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hex = new StringBuilder();
        for (byte b : bytes) {
            String h = Integer.toHexString(b & 0xFF);
            if (h.length() == 1) {
                h = "0" + h;
            }
            hex.append(h);
        }
        return hex.toString();
    }
}
