const fs = require('fs');
const path = require('path');

class FileProcessor {
  constructor(loggingService) {
    this.loggingService = loggingService;
  }

  async processDirectory(directoryPath, filterExtensions) {
    const files = await this.getFiles(directoryPath);
    const filteredFiles = files.filter(file => filterExtensions.includes(path.extname(file).substring(1)));
    const fileContents = [];

    for (const file of filteredFiles) {
      try {
        const content = await fs.readFile(file, 'utf8');
        fileContents.push(content);
      } catch (error) {
        this.loggingService.error(`Error reading file ${file}: ${error.message}`);
      }
    }

    return fileContents;
  }

  async getFiles(directoryPath) {
    const files = [];
    const readDir = fs.readdirSync(directoryPath);

    for (const entry of readDir) {
      const filePath = path.join(directoryPath, entry);
      try {
        if (fs.statSync(filePath).isDirectory()) {
          files.push(...await this.getFiles(filePath));
        } else {
          files.push(filePath);
        }
      } catch (error) {
        this.loggingService.error(`Error accessing file ${filePath}: ${error.message}`);
      }
    }

    return files;
  }
}

module.exports = FileProcessor;
