function renderFormSection(widgets) {
  const form = document.getElementById('form-section');
  let widgetElements = [];

  // Initialize default values
  widgets.forEach((widget) => {
    if (widget.type === 'text') {
      widget.defaultVal = '';
    } else if (widget.type === 'select') {
      widget.defaultVal = '';
    } else if (widget.type === 'checkbox') {
      widget.defaultVal = false;
    }
  });

  // Render widgets
  widgets.forEach((widget) => {
    const widgetElement = document.createElement('div');
    widgetElement.className = `widget ${widget.type}`;

    switch (widget.type) {
      case 'text':
        widgetElement.innerHTML = `
          <label>${widget.label}</label>
          <input type="text" value="${widget.defaultVal}" />
        `;
        break;
      case 'select':
        widgetElement.innerHTML = `
          <label>${widget.label}</label>
          <select value="${widget.defaultVal}">
            ${widget.options.map((option) => `<option value="${option}">${option}</option>`).join('')}
          </select>
        `;
        break;
      case 'checkbox':
        widgetElement.innerHTML = `
          <label>${widget.label}</label>
          <input type="checkbox" checked=${widget.defaultVal} />
        `;
        break;
    }

    form.appendChild(widgetElement);
    widgetElements.push({ element: widgetElement, widget });
  });

  // Update form section when widget values change
  widgetElements.forEach((widget) => {
    const input = widget.element.querySelector('input');
    if (input) {
      input.addEventListener('input', () => {
        widget.widget.value = input.value;
        form.dispatchEvent(new Event('change'));
      });
    }
    const select = widget.element.querySelector('select');
    if (select) {
      select.addEventListener('change', () => {
        widget.widget.value = select.value;
        form.dispatchEvent(new Event('change'));
      });
    }
    const checkbox = widget.element.querySelector('input[type="checkbox"]');
    if (checkbox) {
      checkbox.addEventListener('change', () => {
        widget.widget.value = checkbox.checked;
        form.dispatchEvent(new Event('change'));
      });
    }
  });

  return form;
}
