angular.module('myApp').service('ContentUpdater', ['$http', function($http) {
  var cache = {};
  var retryConfig = { 
    maxAttempts: 3,
    backoffTime: 1000 // in milliseconds
  };

  this.updateContent = function(sectionId, htmlContent) {
    if (cache[sectionId]) {
      return cache[sectionId];
    }

    var request = $http.post('/updateContent', { sectionId: sectionId, htmlContent: htmlContent });

    request.then(function(response) {
      cache[sectionId] = response.data;
      window.parent.postMessage({ type: 'UPDATE_CONTENT', data: response.data }, '*');
    }).catch(function(error) {
      if (retryConfig.maxAttempts > 0) {
        setTimeout(function() {
          retryConfig.maxAttempts--;
          this.updateContent(sectionId, htmlContent);
        }.bind(this), retryConfig.backoffTime);
