function recursiveTraversal(root, selector, callback) {
  const result = [];
  function traverse(node) {
    if (node.nodeType === 1 && node.tagName.match(selector)) {
      callback(node);
      result.push(node);
    }
    for (let i = 0; i < node.childNodes.length; i++) {
      traverse(node.childNodes[i]);
    }
  }
  traverse(root);
  return result;
}
