    private static final int MAX_INSTANCES = 10;
    private static final int SHUTDOWN_DELAY_MAX = 30 * 1000; // in milliseconds
    private static final String SERVICE_ID_FORMAT = "Service-%d";

    public static void main(String[] args) {
