void manage_messages(int num_entries) {
    // Allocate memory for and initialize the message array
    NFAPI_RX_MESSAGE_T* messages = (NFAPI_RX_MESSAGE_T*)malloc(num_entries * sizeof(NFAPI_RX_MESSAGE_T));

    // Initialize the timestamp, priority, and message arrays
    long* timestamps = (long*)malloc(num_entries * sizeof(long));
    int* priorities = (int*)malloc(num_entries * sizeof(int));
    double* metrics = (double*)malloc(num_entries * sizeof(double));

    // Read and process the network performance metrics from standard input
    for (int i = 0; i < num_entries; i++) {
        scanf("%ld %d %lf", &timestamps[i], &priorities[i], &metrics[i]);

        // Initialize each message with a randomly set FLAG field
        messages[i].ue_index = rand() % 100;
        messages[i].rnti = rand() % 100;
        if (rand() % 2) {
            messages[i].flag = FLAG_DOWNLINK;
        } else {
            messages[i].flag = FLAG_UPLINK;
        }
    }

    // Filter and aggregate the metrics based on the priority levels
    for (int i = 0; i < num_entries; i++) {
        if (priorities[i] > 5) {
            // Aggregate the metrics using mean, median, or percentile algorithm
            double sum = 0;
            int count = 0;
            for (int j = 0; j < i; j++) {
                if (priorities[j] > 5) {
                    sum += metrics[j];
                    count++;
                }
            }
            double average = sum / count;

            // Print the aggregated metric value and its associated timestamp
            printf("Average downlink metric: %f at timestamp %ld\n", average, timestamps[i]);
        }
    }

    // Deallocate memory for the message array
    free(messages);

    // Deallocate memory for the other arrays
    free(timestamps);
    free(priorities);
    free(metrics);
}

int main() {
    int num_entries;
    scanf("%d", &num_entries);

    manage_messages(num_entries);

    return 0;
}
