    // Initialize the return pointer
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;

    // Check for invalid input parameters
    if (N <= 0 || timeout < 0) {
        fprintf(stderr, "Invalid input parameters. N must be greater than zero and timeout cannot be negative.\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    if (!(pdu_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
        fprintf(stderr, "Memory allocation failed after %d seconds.\n", timeout);
        return NULL;
    }

    // Initialize the CRC flag randomly
    int i;
    for (i = 0; i < N; i++) {
        pdu_array[i].CRCFLAG = rand() & 1;
    }

    // Return the allocated array of structures
    return pdu_array;
}

// Function to periodically check the integrity of the allocated structures
void validate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int N) {
    // Check for data consistency
