#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024
#define MEMORY_LIMIT 1048576 // in bytes
#define STRING_MAX_LENGTH 255

// Struct to represent a string buffer with size and urgency information
typedef struct {
    char* buffer;
    int size;
    int urgency;
} StringBuffer;

// Priority queue node structure
typedef struct Node {
    StringBuffer stringBuf;
    struct Node* next;
} PriorityQueueNode;

// Priority queue head
PriorityQueueNode* pq_head = NULL;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to append a slash to a string and store it in the buffer
StringBuffer process_string(char* str) {
    int len = strlen(str);
    StringBuffer sb;
    sb.buffer = (char*)malloc((len + 2) * sizeof(char));
    sb.size = len + 2; // including the added slash
    strcpy(sb.buffer, str);
    strcat(sb.buffer, "/"); // add a slash at the end
    return sb;
}

// Function to enqueue a string for delayed processing
void enqueue_string(StringBuffer sb) {
    PriorityQueueNode* newNode = (PriorityQueueNode*)malloc(sizeof(PriorityQueueNode));
    newNode->stringBuf = sb;
    newNode->next = pq_head;
    pq_head = newNode;
}

// Function to dequeue the next string from the priority queue
StringBuffer dequeue_string() {
    StringBuffer ret;
    if (!pq_head) return ret; // nothing in the queue

    PriorityQueueNode* temp = pq_head;
    pq_head = pq_head->next;
    free(temp);
    ret = pq_head ? pq_head->stringBuf : (StringBuffer){NULL, 0, 0}; // dummy string
    return ret;
}

// Function to check if a string can be safely processed within the buffer and system limits
int is_safe_to_process(StringBuffer sb) {
    int buffer_usage = sb.size + sizeof(StringBuffer);
    int total_memory_usage = buffer_usage + sizeof(pq_head);

    if (total_memory_usage > MEMORY_LIMIT || sb.size > MAX_BUFFER_SIZE)
        return 0; // not safe to process

    return 1;
}

// Function to handle the main processing loop, managing memory and concurrency
void* process_strings(void* arg) {
    while (1) { // keep processing until system shutdown or error
        StringBuffer sb;

        pthread_mutex_lock(&mutex);
        if (!pq_head) { // no strings in queue
            pthread_mutex_unlock(&mutex);
            continue; // wait for new string

        }

        sb = dequeue_string();
        pthread_mutex_unlock(&mutex);

        if (is_safe_to_process(sb)) {
            // process the string normally, append slash and store it
            free(sb.buffer); // release previous allocation
            sb = process_string(sb.buffer);
            enqueue_string(sb); // re-queue with updated buffer
        } else { // cannot process due to size constraints
            // log or handle error here if needed
        }
    }

    return NULL;
}

// Initialize the priority queue and start the processing threads
int main() {
    pthread_t thread_id;

    for (int i = 0; i < THREADS_TO_CREATE; i++) {
        pthread_create(&thread_id, NULL, process_strings, NULL);
        // keep track of created threads to join later
    }

    return 0;
}

// Function to gracefully shut down the system, freeing allocated resources
void shutdown() {
    pthread_mutex_lock(&mutex);

    while (pq_head) { // dequeue and free all strings in the queue
        StringBuffer sb = dequeue_string();
        free(sb.buffer);
    }

    pthread_mutex_unlock(&mutex);

    // join the processing threads
    for (int i = 0; i < THREADS_TO_CREATE; i++) {
        pthread_join(thread_id, NULL); // replace with actual thread IDs
    }
}
