**JavaScript - asyncReduceArray**
```javascript
function asyncReduceArray(arr, initial, callback) {
  return new Promise((resolve, reject) => {
    let accumulator = initial;
    (async () => {
      for await (const num of arr) {
        try {
          accumulator = callback(accumulator, num);
        } catch (err) {
          reject(err);
          break;
        }
      }
      resolve(accumulator);
    })();
  });
}
```

