void manage_LTE_enb_task_data_list(LTE_ENB_TASK_DATA** list, size_t* list_size) {
    // Initialize the list with a default size
    if (*list_size == 0) *list_size = 10;

    // Allocate memory for new task data structure
    LTE_ENB_TASK_DATA* new_task = (LTE_ENB_TASK_DATA*)malloc(sizeof(LTE_ENB_TASK_DATA));

    // Check for successful allocation
    if (!new_task) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize the new task data structure with unique eNB_ID, CELL_ID and default measurements
    new_task->eNB_ID = *list_size + 1;
    new_task->CELL_ID = rand() % 1000; // Generate a random CELL_ID for demonstration purposes
    new_task->uplink_RSRP = -120.0f; // Default uplink RSRP value
    new_task->uplink_SINR = -20.0f; // Default uplink SINR value
    new_task->downlink_RSRP = -90.0f; // Default downlink RSRP value
    new_task->downlink_SINR = -15.0f; // Default downlink SINR value

    // Check for duplicate CELL_ID entries in the list
    for (size_t i = 0; i < *list_size; i++) {
        if (new_task->CELL_ID == (*list)[i]->CELL_ID) {
            free(new_task);
            printf("Duplicate CELL_ID detected.\n");
            return;
        }
    }

    // Reallocate memory for the list to accommodate the new task data structure
    LTE_ENB_TASK_DATA** reallocated_list = (LTE_ENB_TASK_DATA**)realloc(*list, (*list_size + 1) * sizeof(LTE_ENB_TASK_DATA*));

    // Check for successful reallocation
    if (!reallocated_list) {
        printf("Memory allocation failed.\n");
        free(new_task);
        return;
    }

    // Update the list size and pointer to the new task data structure
    (*list) = reallocated_list;
    (*list_size)++;

    *list[(*list_size) - 1] = new_task;
}

void filter_measurements(LTE_ENB_TASK_DATA** list, size_t list_size, float rsrp_threshold, float sinr_threshold) {
    for (size_t i = 0; i < list_size; i++) {
        if (list[i]->uplink_RSRP >= rsrp_threshold && list[i]->downlink_RSRP >= rsrp_threshold &&
            list[i]->uplink_SINR >= sinr_threshold && list[i]->downlink_SINR >= sinr_threshold) {
            // Process the measurement report as desired
            printf("Measurement report passed filtering criteria: eNB_ID %d, CELL_ID %d\n",
                   list[i]->eNB_ID, list[i]->CELL_ID);
        }
    }
}

void sort_list(LTE_ENB_TASK_DATA** list, size_t list_size) {
    for (size_t i = 0; i < list_size - 1; i++) {
        for (size_t j = 0; j < list_size - i - 1; j++) {
            if (list[j]->eNB_ID > list[j + 1]->eNB_ID) {
                LTE_ENB_TASK_DATA* temp = list[j];
                list[j] = list[j + 1];
                list[j + 1] = temp;
            }
        }
    }
}

int main() {
    // Initialize the list size and pointer
    size_t list_size = 0;
    LTE_ENB_TASK_DATA** list = NULL;

    // Manage the list of task data structures
    manage_LTE_enb_task_data_list(&list, &list_size);

    // Filter measurements based on specified thresholds
    filter_measurements(list, list_size, -100.0f, -5.0f);

    // Sort the list by eNB_ID in ascending order
    sort_list(list, list_size);

    return 0;
}
