#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define TIME_LIMIT_PER_LINE 1000 // in milliseconds
#define BUFFER_SIZE 4096

typedef struct {
    int *fields;
    size_t field_count;
} LineData;

void process_line(FILE *file, LineData *line) {
    char buffer[MAX_LINE_LENGTH];
    if (fread(buffer, 1, MAX_LINE_LENGTH, file) != MAX_LINE_LENGTH - 1) {
        // Handle I/O error
        fprintf(stderr, "Error reading line\n");
        return;
    }

    size_t field_count = 0;
    char *token = strtok(buffer, " ");
    while (token && field_count < line->field_count - 2) {
        ((int *)line->fields)[field_count++] = atoi(token);
        token = strtok(NULL, " ");
    }
    if (field_count != line->field_count - 2) {
        // Handle malformed input
        fprintf(stderr, "Malformed input\n");
        return;
    }

    clock_t start_time = clock();
    double average = 0.0;
    for (int i = 0; i < field_count - 2; i++) {
        average += ((int *)line->fields)[i];
    }
    average /= field_count - 2;

    if (clock() - start_time > TIME_LIMIT_PER_LINE * CLOCKS_PER_SEC / 1000) {
        // Computation exceeded time limit
        fprintf(stderr, "Computation exceeded time limit\n");
    } else {
        printf("%.2f,%d,%d\n", average, ((int *)line->fields)[field_count - 3], ((int *)line->fields)[field_count - 2]);
    }

    free(line->fields);
}

int main() {
    FILE *file = fopen("input.txt", "r");
    if (!file) {
        // Handle file open error
        return 1;
    }

    LineData line;
    line.field_count = 10; // Assuming a fixed field count per line
    line.fields = (int *)malloc(line.field_count * sizeof(int));

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE - 1, file) != NULL) {
        process_line(file, &line);
        free(line.fields);
        line.fields = (int *)malloc(line.field_count * sizeof(int));
    }

    fclose(file);
    return 0;
}
