#include <time.h>

typedef struct {
    int value;
} record;

int perform_tasks(int num_offsets, int num_keys, int num_records, int max_size_limit, int min_value, int max_value) {
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0 || max_size_limit < 0) {
        return -1; // Error: invalid input
    }

    // Initialize allocation counters
    int successful_allocations = 0;
    int failed_allocations = 0;

    // Allocate memory for offset array and initialize with zeros
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        return -1; // Error: could not allocate memory for offsets
    }
    successful_allocations++;

    // Allocate memory for key array and initialize with zeros
    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1; // Error: could not allocate memory for keys
    }
    successful_allocations++;

    // Allocate memory for record array and initialize records with random values
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        return -1; // Error: could not allocate memory for records
    }
    successful_allocations++;

    // Set random value in each record's int field
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < num_records; i++) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    // Check if total allocated memory exceeds max_size_limit
    size_t total_allocated_memory = sizeof(long) * num_offsets + sizeof(int) * num_keys + sizeof(record) * num_records;
    if (total_allocated_memory > max_size_limit) {
        free(records);
        free(keys);
        free(offsets);
        return -2; // Error: allocated memory exceeds limit
    }

    // Release all allocated memory when finished
    free(records);
    free(keys);
    free(offsets);

    return successful_allocations;
}

int main() {
    int num_offsets = 1000;
    int num_keys = 500;
    int num_records = 2000;
    int max_size_limit = 10000000; // 10MB
    int min_value = 1;
    int max_value = 100;

    int result = perform_tasks(num_offsets, num_keys, num_records, max_size_limit, min_value, max_value);

    if (result == -1) {
        printf("Error: invalid input\n");
    } else if (result == -2) {
        printf("Error: allocated memory exceeds limit\n");
    } else {
        printf("Allocations successful: %d\n", result);
    }

    return 0;
}
