    for (int i = 0; i < *num_elements; i++) {
        (*array)[i].RX_UE_INFORMATION_TAG = i;
        (*array)[i].RNTI = rand() % 100 + 1; // Generate random RNTI values
        (*array)[i].CRC_INDICATION_REL8_TAG = i;
        (*array)[i].CRCFLAG = rand() & 1; // Set CRCFLAG randomly

        // Check for duplicate RNTI values and retry if necessary
        int duplicate_found = 0;
        for (int j = 0; j < i; j++) {
            if ((*array)[j].RNTI == (*array)[i].RNTI) {
                duplicate_found = 1;
                break;
            }
