        while (duplicate_found) {
            // Exponential backoff retry mechanism for failed requests
            int sleep_time = 1 << i; // Initial sleep time is 2^0 = 1, then doubles with each failure
            printf("RNTI duplicate found. Retrying in %d seconds...\n", sleep_time);
            sleep(sleep_time); // Simulate a delay for failed request

            // Regenerate the RNTI value and check again
            (*array)[i].RNTI = rand() % 100 + 1;
            duplicate_found = 0;
            for (int j = 0; j < i; j++) {
                if ((*array)[j].RNTI == (*array)[i].RNTI) {
                    duplicate_found = 1;
                    break;
                }
            }
        }
    }

    // Sort the array based on RX_UE_INFORMATION_TAG in ascending order
    int* sorted_indices = (int*)malloc(*num_elements * sizeof(int));
    for (int i = 0; i < *num_elements; i++) {
        sorted_indices[i] = i;
    }

    qsort(sorted_indices, *num_elements, sizeof(int), compareRX_UE_INFORMATION_TAG);

    // Reorder the array based on the sorted indices
    NFAPI_CRC_INDICATION_PDU_T* temp_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < *num_elements; i++) {
        temp_array[i] = (*array)[sorted_indices[i]];
    }

    free(*array);
    *array = temp_array;

    free(sorted_indices);

    return;
}

int compareRX_UE_INFORMATION_TAG(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* first = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* second = (NFAPI_CRC_INDICATION_PDU_T*)b;

