function findElementsBySelector(selector, callback) {
    const matches = [];
    const traverser = (node, parent) => {
      if (!node || !parent) return;
      if (node.classList.contains(selector) || node.getAttribute("id") === selector) {
        callback(node);
      }
      Array.prototype.forEach.call(parent.childNodes, child => {
        traverser(child, node);
      });
    };
    const documentBody = document.body;
    traverser(documentBody, null);
    return matches;
}
