    public async Task<User> RegisterUserAsync(string username, string password)
    {
        int retries = 0;

        while (retries <= MaxRetries)
        {
            try
            {
                // Attempt to register the user with the external service
                var user = await _externalUserService.RegisterUserAsync(username, password);

                // Check if the username is already in use
                if (!await IsUsernameAvailableAsync(username))
                {
                    // Return a default user object indicating the conflict
                    return DefaultConflictUser;
                }

                // Generate a unique user identifier and return the newly registered user
                var userId = Guid.NewGuid();
                return new User { Id = userId, Username = username };
            }
            catch (Exception ex)
            {
                // Log registration attempt failure
                _logger.LogError(ex, "Registration failed");

                // Increment retry count
                retries++;

                if (retries > MaxRetries)
                {
                    // Return a default user object indicating the conflict after maximum retries
                    return DefaultConflictUser;
                }

                // Wait before retrying to avoid overwhelming the external service
                await Task.Delay(TimeSpan.FromMilliseconds(500));
            }
        }

        // Log registration attempt success
        _logger.LogInformation("Registration successful");

        return null; // or throw an exception if you prefer
    }

