    void* pool = my_malloc(POOL_ALIGNMENT);
    if (!pool) {
        printf("Memory allocation failed. Exiting...\n");
        return -1;
    }

    // Allocate and initialize an array of 'record' structures, aligned to POOL_ALIGNMENT
    record_t* records = (record_t*)(((size_t) pool + POOL_ALIGNMENT - 1) & ~(POOL_ALIGNMENT - 1));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100; // Initialize with random values
    }

    // Implement a thread-safe mechanism to set the value of each record's int field
