        pthread_mutex_lock(&mutex);
        records[i].value = rand() % 100; // Update with random values
        pthread_mutex_unlock(&mutex);
    }
    pthread_mutex_destroy(&mutex);

    // Design a memory management strategy to free all allocated memory efficiently
    my_free(pool); // Free the pool first

    for (int i = 0; i < num_records; i++) {
