NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(int num_tags, const char* base_filename) {
    time_t current_time = time(NULL);
    struct tm* time_info = localtime(&current_time);
    size_t timestamp_len = strftime(base_filename + strlen(base_filename), sizeof(base_filename) - strlen(base_filename) - 1, "%Y%m%d%H%M%S", time_info);

    uuid_t unique_id;
    uuid_generate(unique_id);

    char filename[256];
    sprintf(filename, "%s_%X.bin", base_filename, (unsigned int)unique_id.time_low);

    NFAPI_CRC_INDICATION_PDU_T* pdu_tags = NULL;

    for (int i = 0; i < num_tags; i++) {
        RX_UE_INFORMATION_TAG* tag = (RX_UE_INFORMATION_TAG*)malloc(sizeof(RX_UE_INFORMATION_TAG));
        tag->crcflag = rand() % 2;
        tag->rnti = rand();

        CRC_INDICATION_REL8_TAG* rel8_tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        rel8_tag->timestamp = current_time;
        uuid_copy(rel8_tag->crc_uuid, unique_id);

        // Dynamic memory allocation for array of structures
        pdu_tags = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pdu_tags, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu_tags[i].filename = filename;
        pdu_tags[i].num_pdu_tags = num_tags;
        pdu_tags[i].pdu_tags = rel8_tag;
    }

    return pdu_tags;
}
