typedef struct {
    int node_entity_id;
    size_t session_count;
    struct SessionContext** sessions;
} NodeEntityContext;

typedef struct {
    unsigned long seid;
    time_t start_timestamp;
    enum {
        SESSION_STATE_ACTIVE,
        SESSION_STATE_INACTIVE,
        SESSION_STATE_TERMINATED
    } state;
} SessionContext;

void init_node_entity_context(NodeEntityContext* context, int node_id) {
    context->node_entity_id = node_id;
    context->session_count = 0;
    context->sessions = NULL;
}

SessionContext* create_session_context() {
    SessionContext* session = (SessionContext*)malloc(sizeof(SessionContext));
    if (!session) return NULL;

    session->seid = (unsigned long)rand();
    session->start_timestamp = time(NULL);
    session->state = SESSION_STATE_ACTIVE;

    return session;
}

void update_session_state(NodeEntityContext* context, unsigned long seid, int new_state) {
    for (size_t i = 0; i < context->session_count; ++i) {
        if (context->sessions[i]->seid == seid) {
            context->sessions[i]->state = new_state;
            return;
        }
    }
}

void add_session(NodeEntityContext* context, SessionContext* session) {
    size_t old_size = context->session_count;

    // Dynamically allocate memory for the session array
    if (context->sessions == NULL || old_size >= (size_t)(-1)) {
        void* new_memory = realloc(context->sessions, (old_size + 2) * sizeof(SessionContext*));
        if (!new_memory) return;
        context->sessions = new_memory;
    }

    // Add the new session to the end of the array
    context->sessions[old_size] = session;
    context->session_count++;

    if (context->session_count >= (size_t)(-1)) {
        printf("Session array overflow!\n");
    }
}

void remove_session(NodeEntityContext* context, unsigned long seid) {
    for (size_t i = 0; i < context->session_count; ++i) {
        if (context->sessions[i]->seid == seid) {
            // Shift the remaining sessions to fill the gap
            for (size_t j = i + 1; j < context->session_count; ++j)
                context->sessions[j - 1] = context->sessions[j];
            context->session_count--;

            free(context->sessions[i]);

            return;
        }
    }
}

void print_node_entity_context(NodeEntityContext* context) {
    printf("Node Entity Context:\n");
    printf("Node ID: %d\n", context->node_entity_id);
    printf("Session Count: %zu\n", context->session_count);

    for (size_t i = 0; i < context->session_count; ++i) {
        SessionContext* session = context->sessions[i];
        printf("Session %u:\n", session->seid);
        printf("Start Timestamp: %ld\n", session->start_timestamp);
        printf("State: ");
        switch (session->state) {
            case SESSION_STATE_ACTIVE:
                printf("ACTIVE\n");
                break;
            case SESSION_STATE_INACTIVE:
                printf("INACTIVE\n");
                break;
            case SESSION_STATE_TERMINATED:
                printf("TERMINATED\n");
                break;
        }
    }
}

void free_node_entity_context(NodeEntityContext* context) {
    for (size_t i = 0; i < context->session_count; ++i)
        free(context->sessions[i]);

    free(context->sessions);
}
