typedef struct {
    int RNTI;
    char CRCFLAG[3];
} NFAPI_CRC_INDICATION_PDU_T;

void serialize_and_store(NFAPI_CRC_INDICATION_PDU_T* structures, int num_structures, const char* output_dir) {
    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        return;
    }

    for (int i = 0; i < num_structures; i++) {
        fwrite(&structures[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

void clean_up_output_dir(const char* output_dir) {
    time_t now = time(NULL);
    DIR* dir = opendir(output_dir);
    if (dir == NULL) {
        printf("Failed to open directory.\n");
        return;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        char path[1024];
        sprintf(path, "%s/%s", output_dir, ent->d_name);

        if (ent->d_type == DT_REG && strcmp(ent->d_name, ".") != 0) { // Ignore directory and dot
            struct stat st;
            if (stat(path, &st) == 0) {
                if ((now - st.st_mtime) > 30 * 24 * 60 * 60) { // 30 days retention policy
                    unlink(path);
                }
            }
        }
    }

    closedir(dir);
}

void serialize_and_store_with_metadata(NFAPI_CRC_INDICATION_PDU_T* structures, int num_structures, const char* output_dir, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*, int)) {
    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        return;
    }

    for (int i = 0; i < num_structures; i++) {
        fwrite(&structures[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);

        if (callback != NULL) {
            callback(&structures[i], i);
        }
    }

