// Structure definition
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

int create_list_of_nfaapi_crc_indication_pdu(int max_size, int* count) {
    // Initialize list and lock
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);

    // Seed random generator for reproducibility
    srand(time(NULL));

    // Initialize RNTI count and CRCFLAG seed
    int rnti_count = 0;
    unsigned int crcflag_seed = rand();

    *count = 0;

    // Create list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < max_size; i++) {
        pthread_mutex_lock(&list->lock);

        // Generate random RNTI and CRCFLAG
        int rnti = rand() % 10000;
        unsigned char crcflag[4] = {(unsigned char)(crcflag_seed & 0xFF), (unsigned char)((crcflag_seed >> 8) & 0xFF), (unsigned char)((crcflag_seed >> 16) & 0xFF), (unsigned char)((crcflag_seed >> 24) & 0xFF)};

        // Create NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];
        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rnti;
        memcpy(pdu->CRC_INDICATION_REL8_TAG, crcflag, 4);

        // Increment RNTI count and update CRCFLAG seed
        if (rnti_count == 0) {
            rnti_count = rnti + 1;
            crcflag_seed++;
        }

        pthread_mutex_unlock(&list->lock);

        (*count)++;
    }

    // Sort the list by RNTI in ascending order
    qsort(list, *count, sizeof(NFAPI_CRC_INDICATION_PDU_T), (int (*)(const void*, const void*))compare_rnti);

    return *count;
}

// Compare function for sorting NFAPI_CRC_INDICATION_PDU_T structures by RNTI
int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = (NFAPI_CRC_INDICATION_PDU_T*)b;

    if (pdu_a->RNTI < pdu_b->RNTI) {
        return -1;
    } else if (pdu_a->RNTI > pdu_b->RNTI) {
        return 1;
    }

    return 0;
}
