typedef struct {
    char ip[16];
    int port;
    int status;
    time_t last_update;
} NetworkEntity;

typedef struct {
    NetworkEntity* entities;
    int count;
    pthread_mutex_t mutex;
} NetworkEntities;

NetworkEntities* init_network_entities() {
    NetworkEntities* ne = (NetworkEntities*)malloc(sizeof(NetworkEntities));
    ne->entities = NULL;
    ne->count = 0;
    pthread_mutex_init(&ne->mutex, NULL);
    return ne;
}

void add_entity(NetworkEntities* ne, const char* ip, int port) {
    NetworkEntity* entity = (NetworkEntity*)malloc(sizeof(NetworkEntity));
    strcpy(entity->ip, ip);
    entity->port = port;
    entity->status = 0;
    entity->last_update = time(NULL);
    pthread_mutex_lock(&ne->mutex);
    ne->entities = realloc(ne->entities, (ne->count + 1) * sizeof(NetworkEntity*));
    ne->entities[ne->count++] = entity;
    pthread_mutex_unlock(&ne->mutex);
}

void update_entity(NetworkEntities* ne, const char* ip, int port, int status) {
