               ne->entities[i]->ip, ne->entities[i]->port, ne->entities[i]->status, ne->entities[i]->last_update);
    }
    pthread_mutex_unlock(&ne->mutex);
}

void free_network_entities(NetworkEntities* ne) {
    for (int i = 0; i < ne->count; i++) {
        free(ne->entities[i]);
