#include <string.h>

// Define the structure for network entities
typedef struct {
    char ip_address[16];
    int port_number;
    int status_flag;
} NetworkEntity;

// Function to add an entity to the list
void add_entity(NetworkEntity** list, int* size) {
    // Allocate memory for a new entity
    *size += 1;
    *list = (NetworkEntity**) realloc(*list, *size * sizeof(NetworkEntity*));

    // Prompt user for input values
    printf("Enter IP address: ");
    scanf("%s", (*list)[*size - 1]->ip_address);
    printf("Enter port number: ");
    scanf("%d", &((*list)[*size - 1])->port_number);
    printf("Enter status flag (0/1): ");
    scanf("%d", &((*list)[*size - 1])->status_flag);

    // Validate input values
    if(strncmp((*list)[*size - 1]->ip_address, "Invalid IP address!", 16) == 0 ||
       ((*list)[*size - 1]->port_number < 0 || (*list)[*size - 1]->port_number > 65535) ||
       ((*list)[*size - 1]->status_flag != 0 && (*list)[*size - 1]->status_flag != 1)) {
        // If validation fails, free the newly allocated memory and decrement size
        *size -= 1;
        *list = (NetworkEntity**) realloc(*list, *size * sizeof(NetworkEntity*));
    }
}

// Function to update an entity in the list
void update_entity(NetworkEntity** list, int* size, int index) {
    // Check if the index is within bounds
    if(index < 0 || index >= *size) {
        printf("Invalid index!\n");
        return;
    }

    // Prompt user for updated values
    printf("Enter new IP address: ");
    scanf("%s", (*list)[index]->ip_address);
    printf("Enter new port number: ");
    scanf("%d", &((*list)[index])->port_number);
    printf("Enter new status flag (0/1): ");
    scanf("%d", &((*list)[index])->status_flag);

    // Validate updated input values
    if(strncmp((*list)[index]->ip_address, "Invalid IP address!", 16) == 0 ||
       ((*list)[index]->port_number < 0 || (*list)[index]->port_number > 65535) ||
       ((*list)[index]->status_flag != 0 && (*list)[index]->status_flag != 1)) {
        // If validation fails, print an error message
        printf("Invalid update values!\n");
    }
}

// Function to list all entities in the list
void list_entities(NetworkEntity** list, int size) {
    for(int i = 0; i < size; i++) {
        printf("IP address: %s\n", (*list)[i]->ip_address);
        printf("Port number: %d\n", (*list)[i]->port_number);
        printf("Status flag: %d\n", (*list)[i]->status_flag);
    }
}

// Function to free all allocated resources when the program terminates
void cleanup(NetworkEntity** list, int size) {
    for(int i = 0; i < size; i++) {
        free(*list[i]);
    }
    free(*list);
}
