#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    std::atomic<int> CRCFLAG;
    long long timestamp;
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> generateNfarpcPduList(int numPDUs) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList;
    std::atomic<int> cooldown(5000); // Initial cooldown period

    auto getCooldown = [&] () -> int {
        return std::min(cooldown.load(), 30000); // Clamp to max value
    };

    auto updateCooldown = [&] (int cpuUsage) {
        if(cpuUsage > 70)
            cooldown.store(std::max(1000, cooldown.load() / 2)); // Extend cooldown period for high CPU usage
        else if(cpuUsage < 30)
            cooldown.store(std::min(cooldown.load() * 2, 5000)); // Shorten cooldown period for low CPU usage
    };

    auto logEvent = [] () {
        // Async logging call to external service
        std::this_thread::sleep_for(std::chrono::seconds(1));
    };

    auto updatePDUList = [&] () {
        int updatesPerMinute = 0;
        long long lastUpdate = std::chrono::steady_clock::now().time_since_epoch() / 1000;

        for(int i = 0; i < numPDUs; i++) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = rand();
            pdu.RNTI = rand();
            pdu.CRCFLAG = rand();
            pdu.timestamp = std::chrono::steady_clock::now().time_since_epoch() / 1000;

            if(pduList.size() >= numPDUs) {
                updatesPerMinute++;
                // Check update rate
                long long currUpdate = std::chrono::steady_clock::now().time_since_epoch() / 1000;
                if(currUpdate - lastUpdate >= 60)
                    lastUpdate = currUpdate;

                if(updatesPerMinute > 10 && (std::chrono::steady_clock::now().time_since_epoch() / 1000) - lastUpdate < 60) {
                    logEvent();
                    std::this_thread::sleep_for(std::chrono::seconds(60)); // Pause updates for 1 minute
                }
            }

            pduList.push_back(pdu);
        }
    };

    while(true) {
        int cpuUsage = ...; // Get current CPU usage

        updateCooldown(cpuUsage);

        if(cooldown.load() > 0) {
            std::this_thread::sleep_for(std::chrono::milliseconds(cooldown.load()));
            cooldown.store(0); // Reset cooldown period
        }

        updatePDUList();
    }
}
