using System;
using System.Xml.XPath;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace NetworkEntityProcessor
{
    public class NetworkEntity
    {
        public string IpAddress { get; set; }
        public int PortNumber { get; set; }
        public bool Status { get; set; }
        public DateTime LastUpdatedTimestamp { get; set; }
    }

    public class NetworkEntityPool : IDisposable
    {
        private readonly Dictionary<string, NetworkEntity> _entities;
        private readonly LruCache<string, NetworkEntity> _cache;

        public NetworkEntityPool(int cacheSize)
        {
            _entities = new Dictionary<string, NetworkEntity>();
            _cache = new LruCache<string, NetworkEntity>(cacheSize);
        }

        public void AddNetworkEntity(string name, NetworkEntity entity)
        {
            lock (_entities)
            {
                if (!_entities.ContainsKey(name))
                {
                    _entities.Add(name, entity);
                }
            }
        }

        public NetworkEntity GetNetworkEntity(string name)
        {
            return _cache.Get(name);
        }

        public void Dispose()
        {
            _entities.Clear();
            _cache.Dispose();
        }
    }

    public class LruCache<TKey, TValue> : System.IDisposable
    {
        private readonly Dictionary<TKey, TValue> _dictionary;
        private readonly Queue<TKey> _lruOrder;

        public LruCache(int cacheSize)
        {
            _dictionary = new Dictionary<TKey, TValue>();
            _lruOrder = new Queue<TKey>();

            if (cacheSize > 0)
            {
                for (int i = 0; i < cacheSize; i++)
                {
                    _lruOrder.Enqueue(default(TKey));
                }
            }
        }

        public TValue Get(TKey key)
        {
            TValue value;
            if (_dictionary.TryGetValue(key, out value))
            {
                _lruOrder.Enqueue(key);
                TKey oldest = _lruOrder.Dequeue();
                while (oldest != key && _lruOrder.Count > 0)
                {
                    oldest = _lruOrder.Dequeue();
                }
                return value;
            }
            else
            {
                return default(TValue);
            }
        }

        public void Set(TKey key, TValue value)
        {
            if (_dictionary.ContainsKey(key))
            {
                TValue oldValue;
                _dictionary.TryGetValue(key, out oldValue);
                _lruOrder.Enqueue(key);
                TKey oldest = _lruOrder.Dequeue();
                while (oldest != key && _lruOrder.Count > 0)
                {
                    oldest = _lruOrder.Dequeue();
                }
            }
            else
            {
                _dictionary.Add(key, value);
                _lruOrder.Enqueue(key);
            }
        }

        public void Dispose()
        {
            _dictionary.Clear();
            _lruOrder.Clear();
        }
    }

    public class ProcessNetworkEntities : IDisposable
    {
        private readonly XPathDocument _xmlDoc;
        private readonly NetworkEntityPool _networkEntityPool;

        public ProcessNetworkEntities(string xmlFile)
        {
            _xmlDoc = new XPathDocument(xmlFile);
            _networkEntityPool = new NetworkEntityPool(1000);
        }

        public void Start()
        {
            try
            {
                string query = "//NetworkEntity";
                XPathNavigator nav = _xmlDoc.CreateNavigator();
                XPathNodeIterator nodes = nav.Select(query);

                foreach (XPathNode node in nodes)
                {
                    string name = node.GetAttribute("Name", string.Empty);
                    NetworkEntity entity = new NetworkEntity
                    {
                        IpAddress = node.SelectSingleNode(".//IpAddress").Value,
                        PortNumber = int.Parse(node.SelectSingleNode(".//PortNumber").Value),
                        Status = bool.Parse(node.SelectSingleNode(".//Status").Value),
                        LastUpdatedTimestamp = DateTime.Parse(node.SelectSingleNode(".//LastUpdatedTimestamp").Value)
                    };

                    _networkEntityPool.AddNetworkEntity(name, entity);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error processing network entities: " + ex.Message);
            }
        }

        public void Dispose()
        {
            _xmlDoc.Dispose();
            _networkEntityPool.Dispose();
        }
    }
}
