#define MAX_LIST_SIZE 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_list(int n) {
    if (n > MAX_LIST_SIZE)
        return NULL; // Error: list size exceeds limit

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_node)
            return NULL; // Error: memory allocation failed

        int rnti = rand() % 65535;
        for (int j = i - 1; j >= 0; j--) {
            if ((*tail)[j].RNTI == rnti) {
                free(new_node);
                return create_crc_list(i); // Error: duplicate RNTI found
            }
        }

        new_node->RX_UE_INFORMATION_TAG = rand() % 65535;
        new_node->RNTI = rnti;
        new_node->CRC_INDICATION_REL8_TAG = rand() % 255;
        uint8_t crcflag_table[2][128] = {
            {0x01, 0x02, ..., 0xFE, 0xFF}, // Your CRC flag table for each RNTI range
            {0x10, 0x11, ..., 0xF4, 0xF5}
        };

        new_node->CRCFLAG = crcflag_table[rnti / 128][rnti % 128];

        if (*tail)
            (*tail)->next = (NFAPI_CRC_INDICATION_PDU_T*)new_node;
        else
            head = new_node;

        *tail = &(*tail)->next;
    }

    return head;
}
