                        "Options:\n" +
                        "--help   Display this help message and exit.\n" +
                        "-c      Enable specific processing mode.\n" +
                        "-o <file> Specify an alternative output file path.";

            var inputFile = "";
            var processMode = false;
            var outputFile = "";

            foreach (var arg in args)
