void dynamic_list_init(DynamicList* list) {
    list->size = 0;
    list->capacity = 8; // Initial capacity
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void dynamic_list_insert(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->size >= list->capacity) {
        // Resize the array
        list->capacity *= 2; // Double capacity for efficient growth
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(new_elements, list->elements, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(list->elements);
        list->elements = new_elements;
    }

    // Ensure unique RNTI values
    uint16_t rnti = element.RNTI;
    while (rnti == 0 || find_rnti_in_list(list, rnti) != -1) {
        rnti++;
    }
    element.RNTI = rnti;

    // Update the CRC flags
    update_crc_flags(element);

    list->elements[list->size++] = element;
}

int dynamic_list_remove(DynamicList* list, uint16_t RNTI) {
    int index = find_rnti_in_list(list, RNTI);
    if (index == -1) return -1; // Not found

    // Shift elements to fill the gap
    memmove(&list->elements[index], &list->elements[index + 1], (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    list->size--;
    if (index < list->capacity / 4) { // If more than 25% of capacity is free, shrink the array
        int new_capacity = list->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(new_elements, list->elements, index * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(list->elements);
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    return 0; // Success
}

int dynamic_list_lookup(DynamicList* list, uint16_t RNTI) {
    int index = find_rnti_in_list(list, RNTI);
    if (index == -1) return -1; // Not found

    return 0; // Found
}

// Custom checksum function for verifying CRC flags
uint32_t calculate_checksum(NFAPI_CRC_INDICATION_PDU_T element) {
    uint32_t sum = 0;
    for (int i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        sum += ((uint8_t*)&element)[i];
    }
    return sum;
}

void dynamic_list_verify_crc(DynamicList* list) {
    for (int i = 0; i < list->size; i++) {
        if (calculate_checksum(list->elements[i]) != list->elements[i].CRCFLAG) {
            printf("CRC flag verification failed at index %d.\n", i);
            // Handle error
        }
    }
}

// Helper function to find RNTI in the list
int find_rnti_in_list(DynamicList* list, uint16_t RNTI) {
