    long offset;
} record;

record *create_array(int size) {
    record *array = (record *)malloc(size * sizeof(record));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

void populate_records(record *array, int size) {
