NFAPI_CRC_INDICATION_PDU_T create_nfa_pdu(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = some_valid_tag_value;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.crcFlag = rand() % 2; // random CRC flag
    return pdu;
}

record *merge_arrays(record *arr1, record *arr2, int size1, int size2) {
    record *merged_arr = (record *)malloc((size1 + size2) * sizeof(record));
    if (!merged_arr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    int i = 0;
    for (; i < size1; i++) {
        merged_arr[i] = arr1[i];
    }
    for (int j = 0; j < size2; j++) {
        merged_arr[i + j] = arr2[j];
    }
    return merged_arr;
}

void sort_and_merge(record *arr, int size) {
    record *merged_arr = merge_arrays(arr, NULL, size, 0);
    free(arr);
    qsort(merged_arr, size, sizeof(record), compare_records);
    printf("Sorted array:\n");
    for (int i = 0; i < size; i++) {
        printf("%d %ld\n", merged_arr[i].key, merged_arr[i].offset);
    }
    free(merged_arr);
}

int compare_records(const void *a, const void *b) {
    record *ra = (record *)a;
    record *rb = (record *)b;
    return ra->key - rb->key;
}
