function executeCommands(commands, config) {
  const commandTimeouts = {};
  const results = [];
  let concurrentExecutions = 0;

  function handleCommand(commandName, executionTime, error) {
    if (error) {
      // Log error and retry
      setTimeout(() => {
        try {
          execCmd(commandName);
        } catch (e) {
          console.error(e);
        }
      }, config.retryDelay);
    } else {
      // Log successful command execution
      console.log(`Command "${commandName}" executed in ${executionTime}ms`);
    }
  }

  function execCmd(commandName, args = []) {
    const cmd = `${config.executablePaths[commandName]} ${args.join(' ')}`;
    let timeoutId;

    if (config.commandTimeouts[commandName]) {
      timeoutId = setTimeout(() => {
        handleCommand(commandName, Date.now() - executionTime);
      }, config.commandTimeouts[commandName]);
    } else {
      timeoutId = setTimeout(() => {
        handleCommand(commandName, Date.now() - executionTime);
      }, config.defaultTimeout);
    }

    concurrentExecutions++;

    exec(cmd, (err, stdout, stderr) => {
      if (err || !stdout) {
        handleCommand(commandName, Date.now() - executionTime, err);
      } else {
        results.push({ command: commandName, output: stdout });
      }

      setTimeout(() => {
        concurrentExecutions--;
      }, 0);

      clearTimeout(timeoutId);
    });
  }

  for (const [command, args] of Object.entries(commands)) {
    if (!config.allowedCommands.includes(command)) {
      console.error(`Command "${command}" not allowed`);
      continue;
    }
    execCmd(command, args);
  }
}

module.exports = executeCommands;
