    while (fgets(config_line, sizeof(config_line), config_fp)) {
        char* algo_name = strtok(config_line, ":");
        char* lib_name = strtok(NULL, ":");

        void* algo_ptr = load_algorithm(algo_name);
        if (!algo_ptr) {
            printf("Failed to load algorithm '%s'\n", algo_name);
            continue;
        }

        register_algorithm(algo_ptr, algo_name);
    }

    // Close configuration file
    fclose(config_fp);

    return 0;
}

// Load a cryptographic algorithm from a shared library
void* load_algorithm(const char* algo_name) {
    void* lib_handle = dlopen("lib" algo_name ".so", RTLD_LAZY);
    if (!lib_handle) {
        printf("Failed to open library for algorithm '%s': %s\n", algo_name, dlerror());
        return NULL;
    }

    // Get the function pointer from the library
    int (*algo_func)(void) = dlsym(lib_handle, "crypto_" algo_name);
    if (!algo_func) {
        printf("Failed to find function 'crypto_" algo_name "' in library\n");
        dlclose(lib_handle);
        return NULL;
    }

    return lib_handle;
}

// Register an algorithm with the global list
int register_algorithm(void* algo_ptr, const char* name) {
    // Check if we've reached the maximum number of algorithms
    if (num_algos >= 10) {
        printf("Maximum number of algorithms reached\n");
        return -1;
    }

    algos[num_algos++] = algo_ptr;

    return 0;
}
