#include <stdio.h>

#define NR_API_SRS_INDICATION_T 10
#define MAX_MEMORY_USAGE_THRESHOLD (1024 * 1024) // 1MB
#define MIN_FREE_MEMORY_THRESHOLD (1024) // 1KB

typedef struct {
    int SRS_CONFIG_TAG;
    int SRSCFG_ID;
    float SRS_TX_POWER_LEVEL_TAG; // dynamically calculated based on ref signal strength
} NR_API_SRS_INDICATION_T;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
int total_memory_usage = 0;

NR_API_SRS_INDICATION_T** srs_indications = NULL;
int num_active_instances = 0;

void* alloc_srs_indications(int num_required) {
    int i, required_memory = sizeof(NR_API_SRS_INDICATION_T*) * num_required;
    NR_API_SRS_INDICATION_T** temp_array = (NR_API_SRS_INDICATION_T**)malloc(required_memory);

    if (temp_array == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < num_required; i++) {
        temp_array[i] = (NR_API_SRS_INDICATION_T*)malloc(sizeof(NR_API_SRS_INDICATION_T));

        if (temp_array[i] == NULL) {
            printf("Memory allocation failed.\n");
            free(temp_array);
            return NULL;
        }
    }

    pthread_mutex_lock(&memory_lock);
    for (i = 0; i < num_required; i++) {
        srs_indications[num_active_instances * NR_API_SRS_INDICATION_T + i] = temp_array[i];
    }
    total_memory_usage += required_memory;
    if (total_memory_usage > MAX_MEMORY_USAGE_THRESHOLD) {
        // degrade performance by reducing active threads
        printf("Memory usage exceeds threshold. Reducing active threads.\n");
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    pthread_mutex_unlock(&memory_lock);
    return temp_array;
}

void free_srs_indications(int num_to_free) {
    int i;
    for (i = 0; i < num_to_free; i++) {
        free(srs_indications[num_active_instances * NR_API_SRS_INDICATION_T + i]);
    }

    pthread_mutex_lock(&memory_lock);
    total_memory_usage -= sizeof(NR_API_SRS_INDICATION_T*) * num_to_free;
    pthread_mutex_unlock(&memory_lock);
}

void* srs_indication_calculator() {
    // implement calculation logic here
    NR_API_SRS_INDICATION_T* indication = (NR_API_SRS_INDICATION_T*)malloc(sizeof(NR_API_SRS_INDICATION_T));

    if (indication == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // populate the indication structure with calculated values
    indication->SRS_CONFIG_TAG = 0;
    indication->SRSCFG_ID = 1;
    indication->SRS_TX_POWER_LEVEL_TAG = 2.5f; // dynamically calculated based on ref signal strength

    pthread_mutex_lock(&memory_lock);

    if (total_memory_usage + sizeof(NR_API_SRS_INDICATION_T*) > MAX_MEMORY_USAGE_THRESHOLD) {
        printf("Memory usage exceeds threshold. Deferring request.\n");
        pthread_mutex_unlock(&memory_lock);
        free(indication);
        return NULL;
    }

    srs_indications[num_active_instances * NR_API_SRS_INDICATION_T] = indication;
    total_memory_usage += sizeof(NR_API_SRS_INDICATION_T*);
    num_active_instances++;

    pthread_mutex_unlock(&memory_lock);
    return indication;
}

void print_memory_usage() {
    printf("Total memory usage: %d bytes\n", total_memory_usage);
}
