#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

// Define a structure to represent the data structure with its capacity
typedef struct {
    int capacity;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DataStructure;

// Function to initialize the thread-safe data structure
DataStructure* initializeDataStructure(int capacity) {
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    ds->capacity = capacity;
    ds->size = 0;

    // Initialize mutex and condition variable for synchronization
    pthread_mutex_init(&ds->mutex, NULL);
    pthread_cond_init(&ds->cond, NULL);

    return ds;
}

// Function to add an element to the data structure while ensuring thread safety
void addElement(DataStructure* ds, int elem) {
    pthread_mutex_lock(&ds->mutex);

    // Check if adding the element would exceed capacity; if yes, wait until space is available
    while (ds->size >= ds->capacity) {
        // Log an error message indicating the data structure is full
        printf("Error: Data structure is full. Waiting for space to be released...\n");

        pthread_cond_wait(&ds->cond, &ds->mutex);
    }

    // Add the element and update the size of the data structure
    ds->size++;
    printf("Added element %d.\n", elem);

    pthread_mutex_unlock(&ds->mutex);
}

// Function to remove an element from the data structure while ensuring thread safety
void removeElement(DataStructure* ds) {
    pthread_mutex_lock(&ds->mutex);

    // Check if the data structure is empty; if yes, wait until elements are added
    while (ds->size == 0) {
        // Log an error message indicating the data structure is empty
        printf("Error: Data structure is empty. Waiting for elements to be added...\n");

        pthread_cond_wait(&ds->cond, &ds->mutex);
    }

    // Remove the element and update the size of the data structure
    ds->size--;
    printf("Removed an element.\n");

    // Notify waiting threads that space has become available
    pthread_cond_signal(&ds->cond);

    pthread_mutex_unlock(&ds->mutex);
}

// Function to log access operations for auditing purposes
void logAccess(int elem, DataStructure* ds) {
    printf("Accessed element %d from data structure with size %d.\n", elem, ds->size);
}
