#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* timestamp;
    char* uniqueId;
    char* payload;
} HTTPRequest;

typedef struct node {
    HTTPRequest request;
    struct node* next;
} Node;

Node* createNode(HTTPRequest request) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        return NULL;
    }
    newNode->request = request;
    newNode->next = NULL;
    return newNode;
}

void freeNodes(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

Node* appendNode(Node** head, HTTPRequest newRequest) {
    if (*head == NULL || (**head).request.timestamp < newRequest.timestamp) {
        Node* newNode = createNode(newRequest);
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next && current->next->request.timestamp >= newRequest.timestamp) {
            current = current->next;
        }
        Node* newNode = createNode(newRequest);
        newNode->next = current->next;
        current->next = newNode;
    }
    return *head;
}

void printRequests(Node* head) {
    while (head != NULL) {
        printf("Timestamp: %s, Unique ID: %s, Payload: %s\n", head->request.timestamp,
               head->request.uniqueId, head->request.payload);
        head = head->next;
    }
}

HTTPRequest parseRequest(char* logFileName) {
    HTTPRequest request;
    char timestampBuffer[50], uniqueIdBuffer[50];
    sscanf(logFileName, "log-%48s-%32s", timestampBuffer, uniqueIdBuffer);
    time_t rawTime = (time_t)strtol(timestampBuffer, NULL, 10);
    struct tm* timeinfo = localtime(&rawTime);
    char* timestamp = asctime(timeinfo);
    request.timestamp = strdup(timestamp);
    request.uniqueId = strdup(uniqueIdBuffer);
    int len = rand() % 100 + 1;
    request.payload = (char*)malloc(len);
    for (int i = 0; i < len; i++) {
        request.payload[i] = (char)(rand() % 26 + 97); // Generate random alphanumeric characters
    }
    request.payload[len] = '\0';
    return request;
}

Node* processLogFiles(char* logFileNames[], int numFiles) {
    Node* head = NULL;
    for (int i = 0; i < numFiles; i++) {
        HTTPRequest newRequest = parseRequest(logFileNames[i]);
        appendNode(&head, newRequest);
    }
    return head;
}

int main() {
    // Test the function
    char logFileNames[] = {"log-2022-07-25-12:00:00-ABC123", "log-2022-08-01-14:00:00-MNO901", "log-2022-06-20-11:00:00-PQR678"};
    int numFiles = sizeof(logFileNames) / sizeof(logFileNames[0]);
    Node* head = processLogFiles(logFileNames, numFiles);
    printRequests(head);
    freeNodes(&head);
    return 0;
}
