void init_and_populate_list(int n, NFAPI_CRC_INDICATION_PDU_T **list) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        (*list)[i].rnti = rand() % 100;
        // Initialize RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG as needed
        (*list)[i].crc_flag = rand() & 1;
    }
}

int merge_arrays(record **arr1, int n1, record **arr2, int n2, record ***merged_arr) {
    int i = 0, j = 0, k = 0;

    while (i < n1 && j < n2) {
        if (arr1[i]->key <= arr2[j]->key) {
            (*merged_arr)[k] = *arr1[i];
            i++;
        } else {
            (*merged_arr)[k] = *arr2[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        (*merged_arr)[k] = *arr1[i];
        i++;
        k++;
    }

    while (j < n2) {
        (*merged_arr)[k] = *arr2[j];
        j++;
        k++;
    }

    *merged_arr = (record *)realloc(*merged_arr, (n1 + n2) * sizeof(record));
}

