    pthread_mutex_init(&array->lock, NULL);
}

int session_array_add_session(SessionArray* array, const UeSessionInfo* new_session) {
    if (array->size >= array->capacity) {
        // Double capacity when full
        array->sessions = realloc(array->sessions, array->capacity * 2 * sizeof(UeSessionInfo));
        array->capacity *= 2;
    }
    pthread_mutex_lock(&array->lock);
    memmove(&array->sessions[1], &array->sessions[0], (array->size++) * sizeof(UeSessionInfo));
    memcpy(array->sessions, new_session, sizeof(UeSessionInfo));
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int session_array_update_session(SessionArray* array, const UeSessionInfo* updated_session) {
    for (size_t i = 0; i < array->size; i++) {
        if (strcmp(array->sessions[i].IMSI, updated_session->IMSI) == 0) {
            // Update existing session
            memcpy(&array->sessions[i], updated_session, sizeof(UeSessionInfo));
            return 0;
        }
    }
    return -1; // Session not found
}

UeSessionInfo* session_array_get_session(SessionArray* array, const char* imsi) {
    for (size_t i = 0; i < array->size; i++) {
        if (strcmp(array->sessions[i].IMSI, imsi) == 0) {
            return &array->sessions[i];
        }
    }
    return NULL; // Session not found
}

void session_array_free(SessionArray* array) {
    free(array->sessions);
    pthread_mutex_destroy(&array->lock);
}
