using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Session;
using Microsoft.EntityFrameworkCore;
using Newtonsoft.Json;

public class SessionManager
{
    private readonly IHttpContextAccessor _httpContextAccessor;
    private readonly MyDbContext _dbContext;

    public SessionManager(IHttpContextAccessor httpContextAccessor, MyDbContext dbContext)
    {
        _httpContextAccessor = httpContextAccessor;
        _dbContext = dbContext;
    }

    public async Task<string> ProcessHttpPostRequestAsync(int userId, int transactionId, object updatedData)
    {
        try
        {
            // Get the user session from the database
            var userSession = await _dbContext.UserSessions.FindAsync(userId);

            if (userSession == null)
                return $"Error: User {userId} not found in the session.";

            // Serialize the updated data to JSON
            string jsonUpdatedData = JsonConvert.SerializeObject(updatedData);

            try
            {
                // Start a database transaction
                using var transaction = await _dbContext.Database.BeginTransactionAsync();

                // Update relevant database records atomically
                await _dbContext.UserRecords.UpdateUserRecord(userId, transactionId, jsonUpdatedData);
                await _dbContext.TransactionRecords.AddTransactionRecord(transactionId);

                // Commit the transaction if all updates were successful
                try
                {
                    await transaction.CommitAsync();
                    return $"Success: User {userId} updated successfully.";
                }
                catch (Exception)
                {
                    await transaction.RollbackAsync();
                    return "Error: Transaction failed to commit. Partial success occurred.";
                }
            }
            catch (Exception ex)
            {
                // Handle transient failures in external services
                if (ex is HttpRequestException || ex is DbUpdateConcurrencyException)
                {
                    await Task.Delay(500); // Retry after 0.5 seconds

                    try
                    {
                        return ProcessHttpPostRequestAsync(userId, transactionId, updatedData);
                    }
                    catch (Exception innerEx)
                    {
                        throw new Exception("Error: Failed to retry the operation.", innerEx);
                    }
                }
                else
                {
                    // Handle unexpected input or errors
                    return $"Error: {ex.Message}. Operation failed.";
                }
            }
        }
        catch (Exception ex)
        {
            return $"Error: {ex.Message}. Internal error occurred.";
        }
    }
}

public class MyDbContext : DbContext
{
    public DbSet<UserSession> UserSessions { get; set; }
    public DbSet<UserRecord> UserRecords { get; set; }
    public DbSet<TransactionRecord> TransactionRecords { get; set; }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Configure the database connection
        optionsBuilder.UseSqlServer("Server=myserver;Database=mymydatabase;User ID=myuser;Password=mypassword;");
    }
}

public class UserSession
{
    public int UserId { get; set; }
    public string SessionData { get; set; }
}

public class UserRecord
{
    public int UserId { get; set; }
    public int TransactionId { get; set; }
    public string UpdatedData { get; set; }
}

public class TransactionRecord
{
    public int TransactionId { get; set; }
}
