typedef struct {
    char* filename;
    int fileSize;
} record_t;

record_t** allocRecords(int numRecords) {
    record_t** records = (record_t**)malloc(numRecords * sizeof(record_t*));
    if (!records) {
        return NULL; // Memory allocation failed
    }
    for (int i = 0; i < numRecords; i++) {
        records[i] = (record_t*)malloc(sizeof(record_t));
        if (!records[i]) {
            free(records);
            return NULL; // Memory allocation failed
        }
        char filename[MAX_FILENAME_LENGTH];
        sprintf(filename, "file_%d.%s", i, getCommonExtension());
        records[i]->filename = strdup(filename);
        records[i]->fileSize = rand() % 1000;
    }
    return records;
}

void freeRecords(record_t** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i]) {
            free(records[i]->filename);
            free(records[i]);
        }
    }
    free(records);
}

char* getCommonExtension() {
    static char extensions[][4] = {".txt", ".jpg", ".png"};
    return extensions[rand() % 3];
}

void logMemoryUsage(int numRecords) {
    int totalBytes = sizeof(record_t*) * numRecords;
    printf("Allocated %d records, using %d bytes of memory.\n",
           numRecords, totalBytes);
}

int main() {
    pthread_mutex_init(&mutex, NULL); // Initialize thread-safe mutex

    int numRecords = 1000; // Adjust this to test different record counts
    record_t** records = allocRecords(numRecords);
    if (records) {
        logMemoryUsage(numRecords);

        // Process the records...

        freeRecords(records, numRecords);
    } else {
        printf("Error: unable to allocate memory.\n");
    }

    pthread_mutex_destroy(&mutex); // Clean up thread-safe mutex
    return 0;
}

