    if (LOG_LEVEL_INFO <= 1) {
        printf("[INFO] %s\n", message);
    }
}

void logError(const char* message) {
    if (LOG_LEVEL_ERROR <= 2) {
        printf("[ERROR] %s\n", message);
    }
}
