                NFAPI_CRC_INDICATION_PDU_T temp;
                memcpy(&temp, &crc_indications[j], sizeof(NFAPI_CRC_INDICATION_PDU_T));
                memcpy(&crc_indications[j], &crc_indications[j + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
                memcpy(&crc_indications[j + 1], &temp, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
        }
    }

    // Log the creation details of each structure
