#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    char** devices;
} ConnectionStatus;

ConnectionStatus* initList(int M) {
    ConnectionStatus* list = (ConnectionStatus*)malloc((M+1)*sizeof(ConnectionStatus));
    for (int i = 0; i <= M; i++) {
        list[i].id = -1;
        list[i].timestamp = time(NULL);
        list[i].devices = NULL;
    }
    return list;
}

void populateList(ConnectionStatus* list, int M) {
    for (int i = 0; i < M; i++) {
        ConnectionStatus* update = &list[i];
        update->id = rand() % 10000;
        update->timestamp = time(NULL);
        int deviceCount = rand() % 5 + 1;
        char** devices = (char**)malloc(deviceCount * sizeof(char*));
        for (int j = 0; j < deviceCount; j++) {
            devices[j] = (char*)malloc(strlen("Device") + strlen((j+1)) + 2);
            sprintf(devices[j], "Device%d", j+1);
            update->devices = devices;
        }
    }
}

void sortList(ConnectionStatus* list, int M) {
    qsort(list, M+1, sizeof(ConnectionStatus), (int (*)(const void*, const void*))compareToTimestamp);
}

int compareToTimestamp(const void* a, const void* b) {
    ConnectionStatus* updateA = *(ConnectionStatus**)a;
    ConnectionStatus* updateB = *(ConnectionStatus**)b;
    return (updateB->timestamp - updateA->timestamp);
}

void getLatestEntries(ConnectionStatus* list, int M, int N, ConnectionStatus** latest) {
    if (N > M) {
        printf("Not enough entries to retrieve.\n");
        return;
    }
    qsort(list, M+1, sizeof(ConnectionStatus), (int (*)(const void*, const void*))compareToTimestamp);
    for (int i = 0; i < N; i++) {
        latest[i] = &list[M-i];
    }
}

void freeList(ConnectionStatus* list, int M) {
    for (int i = 0; i <= M; i++) {
        if (list[i].devices) {
            for (int j = 0; j < strlen(list[i].devices); j++) {
                free((void*)list[i].devices);
            }
            free(list[i].devices);
        }
    }
    free(list);
}
