NFAPI_CRC_INDICATION_PDU_T* create_crc_list(int n) {
    // Initialize the list and pointers
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    int retries = 0;
    unsigned int crcflag = rand();

    for (int i = 0; i < n; i++) {
        // Create a new node
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG
        strcpy(node->RX_UE_INFORMATION_TAG, "example_tag");
        node->RNTI = i;
        sprintf(node->CRC_INDICATION_REL8_TAG, "REL8_TAG_%d", i);

        while (retries < 3) {
            // Generate a new CRCFLAG and check for uniqueness
            crcflag = rand();
            int duplicate = 0;
            NFAPI_CRC_INDICATION_PDU_T* current = head;

            while (current != NULL) {
                if (current->CRCFLAG == crcflag) {
                    duplicate = 1;
                    break;
                }
                current = current->next;
            }

            // If not unique, try again
            if (duplicate) {
                retries++;
            } else {
                node->CRCFLAG = crcflag;
                break;
            }
        }

        // If no unique CRCFLAG found after three attempts, log error and terminate
        if (retries >= 3) {
            printf("Error: Unique CRCFLAG not found after three attempts.\n");
            return NULL;  // or handle this error as per requirement
        }

        // Add the node to the list
        *tail = node;
        tail = &node->next;

        retries = 0;  // Reset retries for next iteration
    }

    return head;
}
