#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define MAX_DEVICES 10
#define SESSION_EXPIRATION 300 // in seconds (5 minutes)

typedef struct {
    char session_id[32];
    time_t login_timestamp;
    char ip_address[16];
    int device_count;
    char **devices;
} Session;

Session *sessions = NULL;
int num_sessions = 0;

void init_session_collection() {
    if (num_sessions > 0) {
        free_devices();
    }
    sessions = (Session *)malloc(MAX_SESSIONS * sizeof(Session));
    num_sessions = 0;
}

int add_session(const char *session_id, const time_t login_timestamp, const char *ip_address, int device_count, char **devices) {
    if (num_sessions >= MAX_SESSIONS) {
        return -1; // collection is full
    }
    Session *new_session = &sessions[num_sessions++];
    strcpy(new_session->session_id, session_id);
    new_session->login_timestamp = login_timestamp;
    strcpy(new_session->ip_address, ip_address);
    new_session->device_count = device_count;
    new_session->devices = devices;
    return 0; // successful addition
}

void remove_expired_sessions() {
    for (int i = 0; i < num_sessions; i++) {
        Session *session = &sessions[i];
        if (time(NULL) - session->login_timestamp > SESSION_EXPIRATION) {
            free_devices(session);
            memmove(&sessions[i], &sessions[i + 1], sizeof(Session) * (num_sessions - i - 1));
            num_sessions--;
            i--; // re-check the next session
        }
    }
}

void sort_sessions_by_timestamp() {
    qsort(sessions, num_sessions, sizeof(Session), &compare_sessions);
}

int compare_sessions(const void *a, const void *b) {
    Session *session_a = (Session *)a;
    Session *session_b = (Session *)b;
    if (session_a->login_timestamp > session_b->login_timestamp) {
        return -1; // descending order
    } else if (session_a->login_timestamp < session_b->login_timestamp) {
        return 1; // descending order
    }
    return 0; // equal timestamps
}

Session *get_latest_sessions(int num_sessions_to_retrieve) {
    Session *latest_sessions = (Session *)malloc(num_sessions_to_retrieve * sizeof(Session));
    int i = 0;
    for (int j = 0; j < num_sessions; j++) {
        if (i < num_sessions_to_retrieve) {
            latest_sessions[i] = sessions[j];
            i++;
        } else {
            break;
        }
    }
    return latest_sessions;
}

void free_devices(Session *session) {
    for (int i = 0; i < session->device_count; i++) {
        free(session->devices[i]);
    }
    free(session->devices);
}
