        void* block_ptr = ptr;
        for (int i = 0; i < N / BLOCK_SIZE; i++) {
            free(block_ptr);
            block_ptr += BLOCK_SIZE * sizeof(LTEPHYSTATUS_PDU_T);
        }
        free(block_ptr);
