#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <time.h>

#define DNS_QUERY_RATE_LIMIT 5 // queries per minute
#define DNS_CACHE_TTL 3600 // one hour in seconds

typedef struct {
    char hostname[256];
    char ip_address[16];
} HostIP;

typedef struct {
    int count;
    time_t last_query;
} RateLimitTimer;

int dns_query_rate_limit = DNS_QUERY_RATE_LIMIT;
time_t dns_last_query = 0;

int cache_index = 0;
HostIP* dns_cache = NULL;

void (*logger)(const char*, int, const char*) = NULL;

void set_logger(void (*l)(const char*, int, const char*)) {
    logger = l;
}

int handle_dns_query(const char* hostname) {
    // check rate limit
    if (time(NULL) - dns_last_query < (double)DNS_QUERY_RATE_LIMIT / 60) {
        return -1; // too many queries in the last minute
    }

    // resolve hostname to IP address
    struct hostent* host = gethostbyname(hostname);
    if (!host) {
        if (logger) {
            logger("WARNING", "Failed to resolve hostname: %s", hostname);
        }
        return -1; // failed to resolve hostname
    }

    char ip_address[16];
    inet_ntop(AF_INET, host->h_addr_list[0], ip_address, sizeof(ip_address));

    // cache the result
    if (!dns_cache) {
        dns_cache = (HostIP*)calloc(10, sizeof(HostIP));
        cache_index = 0;
    }

    HostIP* entry = &dns_cache[cache_index++];
    strcpy(entry->hostname, hostname);
    strcpy(entry->ip_address, ip_address);

    // update rate limit timer
    dns_last_query = time(NULL);

    return 0; // successfully resolved hostname to IP address
}

u_char* resolve_hostname_to_ip(const char* hostname) {
    // check cache first
    for (int i = 0; i < cache_index; i++) {
        if (!strcmp(dns_cache[i].hostname, hostname)) {
            return (u_char*)strdup(dns_cache[i].ip_address);
        }
    }

    int result = handle_dns_query(hostname);

    if (result == -1) {
        return NULL; // failed to resolve hostname
    }

    // get the cached IP address
    for (int i = 0; i < cache_index; i++) {
        if (!strcmp(dns_cache[i].hostname, hostname)) {
            return (u_char*)strdup(dns_cache[i].ip_address);
        }
    }

    return NULL;
}

