function runTests(modulesToTest, maxMemoryUsage) {
  const blueslip = require('blueslip');
  let currentMemoryUsage = process.memoryUsage().heapUsed;

  modulesToTest.forEach((moduleName) => {
    try {
      const module = require(moduleName);

      if (!module.tests) {
        throw new Error(`Module ${moduleName} does not have a 'tests' property`);
      }

      blueslip.reset();

      Object.keys(module.tests).forEach((testName) => {
        try {
          console.log(`Running test: ${testName} in module ${moduleName}`);
          const testResult = module.tests[testName]();
          console.log(`Test ${testName} in module ${moduleName} completed`);

          if (currentMemoryUsage + process.memoryUsage().heapUsed > maxMemoryUsage) {
            throw new Error(`Memory usage exceeded the limit of ${maxMemoryUsage} bytes`);
          }
        } catch (error) {
          console.error(`Error running test: ${testName} in module ${moduleName}`, error);
        }
      });
    } catch (error) {
      console.error(`Failed to load module: ${moduleName}`, error);
    }
  });

  return Promise.all(Object.keys(modulesToTest).map((moduleName) => runTests(moduleName, maxMemoryUsage)));
}

// Example usage:
const modules = {
  'module1': require('./module1'),
  'module2': require('./module2'),
  // ...
};

runTests(modules, 10000000); // Run tests with a maximum memory usage of 10MB
