#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list structure with thread-safe operations
typedef struct {
    int capacity;
    int size;
    NFAPI_CRC_INDICATION_PDU_T* elements;
    pthread_mutex_t lock;
    FILE* log_file;
} List_T;

// Function to initialize and reset the list
void list_init(List_T* list, int initial_capacity) {
    list->capacity = initial_capacity;
    list->size = 0;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
    list->log_file = fopen("list.log", "w");
}

// Function to add an element to the list
void list_add(List_T* list, NFAPI_CRC_INDICATION_PDU_T* new_element) {
    int i;
    pthread_mutex_lock(&list->lock);

    // Check for RNTI uniqueness and handle duplicates
    for (i = 0; i < list->size; i++) {
        if (new_element->RNTI == list->elements[i].RNTI) {
            fprintf(list->log_file, "Error: Duplicate RNTI detected. Skipping entry.\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    // Resize the list if it approaches its capacity limit
    if (list->size >= list->capacity / 2) {
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(new_elements, list->elements, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(list->elements);
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    // Add the new element to the list
    if (list->size >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        list_init(list, list->capacity * 2);
        pthread_mutex_lock(&list->lock);
    }
    list->elements[list->size] = *new_element;
    list->size++;

    // Log the time taken to add an element
    double start_time = clock();
    int i;
    for (i = 0; i < list->size; i++) {
        fprintf(list->log_file, "RNTI: %d, CRCFLAG: %d\n", list->elements[i].RNTI, list->elements[i].CRCFLAG);
    }
    double end_time = clock();
    fprintf(list->log_file, "Time taken to add element: %f seconds.\n", (end_time - start_time) / CLOCKS_PER_SEC);

    pthread_mutex_unlock(&list->lock);
}

// Function to free the list and its elements
void list_free(List_T* list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        free(list->elements[i].CRC_INDICATION_REL8_TAG);
    }
    free(list->elements);
    fclose(list->log_file);
    pthread_mutex_unlock(&list->lock);
}

// Example usage:
int main() {
    List_T list;
    NFAPI_CRC_INDICATION_PDU_T new_element1 = {1, 2, 3};
    NFAPI_CRC_INDICATION_PDU_T new_element2 = {4, 5, 6};

    list_init(&list, 10);

    list_add(&list, &new_element1);
    list_add(&list, &new_element2);

    // Output:
    // RNTI: 2, CRCFLAG: 3
    // RNTI: 5, CRCFLAG: 6
    // Time taken to add element: 0.01 seconds.

    list_free(&list);

    return 0;
}
