// Define a structure for the linked list node
typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T* data;
    struct Node* next;
} Node;

// Function to create a new node with dynamically allocated memory
Node* createNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        // Handle allocation failure
        printf("Memory allocation failed.\n");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a new node at the end of the linked list
void insertNode(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = createNode(data);
    if (!newNode) {
        // Handle allocation failure
        printf("Memory allocation failed.\n");
        return;
    }
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to delete a node from the linked list
void deleteNode(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* current = *head;
    Node* previous = NULL;
    while (current && current->data != data) {
        previous = current;
        current = current->next;
    }
    if (!current) {
        // Handle node not found
        printf("Node not found in the list.\n");
        return;
    }
    if (previous)
        previous->next = current->next;
    else
        *head = current->next;
    free(current);
}

// Function to traverse the linked list and print its contents
