        (*ue_info)[i].channel_freq = (float) rand() / RAND_MAX;
        (*ue_info)[i].buffer_size = buffer_size;
    }
}

// Function to manage dynamic changes in network topology and real-time network conditions
void update_network(int num_ue, UE_INFO **ue_info) {
    // Monitor performance metrics and adjust resource allocation accordingly
    int total_bandwidth = 0;
    for (int i = 0; i < num_ue; i++) {
        total_bandwidth += (*ue_info)[i].buffer_size;
