void merge(int* keys, int* offsets) {
    qsort(keys, sizeof(int)*sizeof(keys[0]), sizeof(int), &compare);
    for (int i = 0; i < keys[0]; i++) {
        // sort the offsets array based on the sorted key values
        qsort(offsets, sizeof(long)*sizeof(offsets[0]), sizeof(long), &compare);
    }
}

int compare(const void* a, const void* b) {
    int* x = (int*)a;
    int* y = (int*)b;

    if (*x < *y)
        return -1;
    else if (*x > *y)
        return 1;
    else
        return 0;
}
