typedef struct {
    LTE_PHY_RRC_API_RLC_STATUS_INFO* data;
    int size;
    int capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int threshold;
} RLC_STATUS_INFO_POOL;

RLC_STATUS_INFO_POOL rlc_status_info_pool = {0};

void initialize_rlc_status_info_pool(int initial_capacity) {
    rlc_status_info_pool.data = (LTE_PHY_RRC_API_RLC_STATUS_INFO*)malloc(initial_capacity * sizeof(LTE_PHY_RRC_API_RLC_STATUS_INFO));
    rlc_status_info_pool.size = 0;
    rlc_status_info_pool.capacity = initial_capacity;
    pthread_mutex_init(&rlc_status_info_pool.lock, NULL);
    pthread_cond_init(&rlc_status_info_pool.cond, NULL);
    rlc_status_info_pool.threshold = 10000; // default threshold in milliseconds
}

void* rlc_status_info_alloc() {
    void* ptr = NULL;
    pthread_mutex_lock(&rlc_status_info_pool.lock);
    if (rlc_status_info_pool.size < rlc_status_info_pool.capacity) {
        ptr = &rlc_status_info_pool.data[rlc_status_info_pool.size];
        rlc_status_info_pool.size++;
    } else {
        // handle memory allocation failure
        printf("Memory allocation failed. Trying to reallocate...\n");
        int new_capacity = rlc_status_info_pool.capacity * 2;
        LTE_PHY_RRC_API_RLC_STATUS_INFO* newData = (LTE_PHY_RRC_API_RLC_STATUS_INFO*)realloc(rlc_status_info_pool.data, new_capacity * sizeof(LTE_PHY_RRC_API_RLC_STATUS_INFO));
        if (newData) {
            rlc_status_info_pool.data = newData;
            rlc_status_info_pool.capacity = new_capacity;
        } else {
            printf("Memory reallocation failed. Returning NULL.\n");
        }
    }
    pthread_mutex_unlock(&rlc_status_info_pool.lock);
    return ptr;
}

void rlc_status_info_free(void* ptr) {
    if (ptr != NULL) {
        pthread_mutex_lock(&rlc_status_info_pool.lock);
        LTE_PHY_RRC_API_RLC_STATUS_INFO* data = (LTE_PHY_RRC_API_RLC_STATUS_INFO*)ptr;
        for (int i = 0; i < rlc_status_info_pool.size - 1; i++) {
            rlc_status_info_pool.data[i] = rlc_status_info_pool.data[i + 1];
        }
        rlc_status_info_pool.size--;
        pthread_mutex_unlock(&rlc_status_info_pool.lock);
    }
}

void rlc_status_info_clear_outdated(int threshold) {
    int current_time = time(NULL);
    int i;
    for (i = 0; i < rlc_status_info_pool.size; i++) {
        LTE_PHY_RRC_API_RLC_STATUS_INFO* info = &rlc_status_info_pool.data[i];
        if ((current_time - info->sequence_number) > threshold) {
            rlc_status_info_free(&info);
        }
    }
}

void log_rlc_status_info_usage() {
    int total_size = rlc_status_info_pool.size * sizeof(LTE_PHY_RRC_API_RLC_STATUS_INFO);
    printf("Current system-wide usage: %d bytes\n", total_size);
    printf("Peak capacity: %d bytes\n", (int)sizeof(LTE_PHY_RRC_API_RLC_STATUS_INFO) * rlc_status_info_pool.capacity);
}

