typedef struct {
    int key;
    long offset;
    char tag[12];
    int RNTI;
} Record;

Record* create_record(int N) {
    Record *records = NULL;
    int i, j;

    for (i = 0; i < N; i++) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            printf("Memory allocation failed.\n");
            return records;
        }
        record->key = rand(); // generate unique key
        record->offset = rand(); // generate unique offset
        strcpy(record->tag, "RX_UE_INFORMATION_TAG"); // set valid RX_UE_INFORMATION_TAG
        record->RNTI = i; // assign RNTI

        records = realloc(records, (i + 1) * sizeof(Record));
        if (!records) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        for (j = 0; j < i; j++) {
            if ((records[j].key == record->key && records[j].offset == record->offset)) {
                free(record);
                free(records);
                printf("Duplicate key-offset combination found. Aborting.\n");
                return NULL;
            }
        }
        records[i] = *record;
    }

    return records;
}

void print_records(Record* records, int N) {
    for (int i = 0; i < N; i++) {
        printf("Key: %d, Offset: %ld, Tag: %s, RNTI: %d\n", 
               records[i].key, records[i].offset, records[i].tag, records[i].RNTI);
    }
}

int main() {
    int N = 10; // number of structures to create
    Record* records = create_record(N);

    if (records) {
        print_records(records, N);
        free(records);
    }

    return 0;
}
