int create_and_serialize_configurations(int num_configs, bool compress_data) {
    LTE_PHY_TEST_FRAME_CONFIG* config_array = NULL;
    int total_configs_created = 0;

    if (num_configs <= 0) {
        return -1; // Invalid number of configurations
    }

    config_array = (LTE_PHY_TEST_FRAME_CONFIG*)malloc(num_configs * sizeof(LTE_PHY_TEST_FRAME_CONFIG));
    if (config_array == NULL) {
        LOG_ERROR("Memory allocation failed");
        return -2; // Memory allocation error
    }

    for (int i = 0; i < num_configs; i++) {
        config_array[i].TX_POWER_LEVEL = some_value;
        config_array[i].FREQUENCY_BAND = another_value;
        config_array[i].TEST_DURATION = yet_another_value;

        if (log_enabled) {
            LOG_INFO("Config %d created successfully", i);
        }
    }

    total_configs_created = num_configs;

    // Serialize configurations to binary format
    uint8_t* buffer = NULL;
    int buffer_size = 0;

    for (int i = 0; i < num_configs; i++) {
        buffer_size += sizeof(LTE_PHY_TEST_FRAME_CONFIG);
        if (compress_data) {
            buffer_size += some_compression_algorithm_get_size(buffer_size); // Optional compression
        }
    }

    buffer = (uint8_t*)malloc(buffer_size);
    if (buffer == NULL) {
        LOG_ERROR("Memory allocation for serialization failed");
        free(config_array);
        return -3; // Memory allocation error during serialization
    }

    int offset = 0;
    for (int i = 0; i < num_configs; i++) {
        memcpy(buffer + offset, &config_array[i], sizeof(LTE_PHY_TEST_FRAME_CONFIG));
        if (compress_data) {
            some_compression_algorithm_compress(buffer + offset, buffer_size - offset); // Optional compression
        }
        offset += sizeof(LTE_PHY_TEST_FRAME_CONFIG);
    }

    // Export serialized data to file in chunks for incremental writes
    FILE* output_file = fopen("output.bin", "wb");
    if (output_file == NULL) {
        LOG_ERROR("File open error");
        free(buffer);
        free(config_array);
        return -4; // File open error
    }

    int chunk_size = 1024 * 1024; // Adjust as needed for optimal disk I/O performance
    while (buffer_size > 0) {
        fwrite(buffer, sizeof(uint8_t), MIN(chunk_size, buffer_size), output_file);
        buffer -= chunk_size;
        buffer_size -= chunk_size;

        if (ferror(output_file)) {
            LOG_ERROR("File write error");
            fclose(output_file);
            free(buffer);
            free(config_array);
            return -5; // File write error
        }
    }

    fclose(output_file);
    free(buffer);

    free(config_array);
    return total_configs_created;
}
