// Define the LTE_PHY_TEST_RX_UE_INFO structure
typedef struct {
    int UE_ID;
    int RNTI;
    int data_valid;
    char* PHY_TEST_RX_DATA;
} LTE_PHY_TEST_RX_UE_INFO;

// Define the dynamic array type
typedef struct {
    LTE_PHY_TEST_RX_UE_INFO** elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Function to initialize and allocate memory for the dynamic array
DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->elements = (LTE_PHY_TEST_RX_UE_INFO**)calloc(initial_capacity, sizeof(LTE_PHY_TEST_RX_UE_INFO*));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Function to add an element to the dynamic array
void dynamic_array_add(DynamicArray* arr, LTE_PHY_TEST_RX_UE_INFO* elem) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        // Resize the array if it's full
        arr->elements = (LTE_PHY_TEST_RX_UE_INFO**)realloc(arr->elements, sizeof(LTE_PHY_TEST_RX_UE_INFO*) * (arr->capacity * 2));
        arr->capacity *= 2;
    }

    arr->elements[arr->size] = elem;
    arr->size++;

    pthread_mutex_unlock(&arr->lock);
}

// Function to remove an element from the dynamic array
void dynamic_array_remove(DynamicArray* arr, int UE_ID) {
    pthread_mutex_lock(&arr->lock);

    for (int i = 0; i < arr->size; i++) {
        if (arr->elements[i]->UE_ID == UE_ID) {
            // Shift all elements to the left after removal
            memmove(arr->elements + i, arr->elements + i + 1, sizeof(LTE_PHY_TEST_RX_UE_INFO*) * (arr->size - i - 1));

            // Decrement the size and update capacity if necessary
            arr->size--;
            if (arr->size < (arr->capacity / 4)) {
                arr->elements = (LTE_PHY_TEST_RX_UE_INFO**)realloc(arr->elements, sizeof(LTE_PHY_TEST_RX_UE_INFO*) * (arr->capacity / 2));
                arr->capacity /= 2;
            }

            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to print the dynamic array
void dynamic_array_print(DynamicArray* arr) {
    pthread_mutex_lock(&arr->lock);

    for (int i = 0; i < arr->size; i++) {
        printf("UE_ID: %d, RNTI: %d, data_valid: %d\n", arr->elements[i]->UE_ID, arr->elements[i]->RNTI, arr->elements[i]->data_valid);
    }

    pthread_mutex_unlock(&arr->lock);
}

int main() {
    // Initialize the dynamic array with an initial capacity of 10
    DynamicArray* arr = dynamic_array_init(10);

    // Add some elements to the array
    LTE_PHY_TEST_RX_UE_INFO elem1 = {1, 2, 3};
    LTE_PHY_TEST_RX_UE_INFO elem2 = {4, 5, 6};
    LTE_PHY_TEST_RX_UE_INFO elem3 = {7, 8, 9};

    dynamic_array_add(arr, &elem1);
    dynamic_array_add(arr, &elem2);
    dynamic_array_add(arr, &elem3);

    // Print the array
    dynamic_array_print(arr);

    // Remove an element from the array
    dynamic_array_remove(arr, 4);

    // Print the array again to verify removal
    dynamic_array_print(arr);

    return 0;
}
