#include <pthread.h>

typedef struct {
    uint32_t timestamp;
    uint16_t sequence_number;
    char payload_data[64]; // assuming a maximum of 64 bytes per packet
} TSN_PACKET;

// Custom memory pool implementation
struct MemoryPool {
    void* pool_memory;
    size_t pool_size;
    pthread_mutex_t mutex;
};

void* tsn_packet_list_alloc(struct MemoryPool* mp, size_t size) {
    return malloc(size);
}

void tsn_packet_list_free(struct MemoryPool* mp, void* ptr) {
    free(ptr);
}

// Dynamic list of TSN_PACKET structures
typedef struct {
    TSN_PACKET* packets;
    size_t capacity;
    size_t length;
    struct MemoryPool pool;
} TSN_PACKET_LIST;

TSN_PACKET_LIST* tsn_packet_list_init() {
    TSN_PACKET_LIST* list = (TSN_PACKET_LIST*)malloc(sizeof(TSN_PACKET_LIST));
    list->packets = NULL;
    list->capacity = 0;
    list->length = 0;
    list->pool.pool_memory = NULL;
    list->pool.pool_size = 0;
    pthread_mutex_init(&list->pool.mutex, NULL);
    return list;
}

void tsn_packet_list_deinit(TSN_PACKET_LIST* list) {
    for (size_t i = 0; i < list->length; i++) {
        free(list->packets[i]);
    }
    free(list->packets);
    pthread_mutex_destroy(&list->pool.mutex);
    free(list);
}

int tsn_packet_list_add(TSN_PACKET_LIST* list, TSN_PACKET* packet) {
    if (list->length >= list->capacity) {
        // Reallocate the memory pool
        size_t new_pool_size = list->pool.pool_size * 2;
        void* new_pool_memory = realloc(list->pool.pool_memory, new_pool_size);
        list->pool.pool_memory = new_pool_memory;
        list->pool.pool_size = new_pool_size;

        // Update the capacity and length
        list->capacity *= 2;
    }

    if (list->packets == NULL) {
        // Initialize the packets array
        list->packets = malloc(list->capacity * sizeof(TSN_PACKET));
        pthread_mutex_init(&list->pool.mutex, NULL);
    }

    // Add the packet to the end of the list
    size_t idx = list->length++;
    memcpy(&list->packets[idx], packet, sizeof(TSN_PACKET));

    return 0;
}

int main() {
    TSN_PACKET_LIST* list = tsn_packet_list_init();

    // Example usage:
    for (int i = 0; i < 50000; i++) {
        TSN_PACKET packet;
        // Fill in the packet data...
        tsn_packet_list_add(list, &packet);
    }

    tsn_packet_list_deinit(list);

    return 0;
}
