typedef struct {
    long offset;
    int key;
    double value;
} record_t;

record_t* allocateRecords(int numRecords) {
    if (numRecords > 10000) { // adjust this limit as needed
        return NULL; // or handle overflow, e.g., by logging a warning and returning an error code
    }

    record_t* records = (record_t*)malloc(numRecords * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Error: Unable to allocate memory for %d records. Try increasing the maximum limit.\n", numRecords);
        return NULL;
    }

    // Ensure memory alignment
    size_t recordSize = sizeof(record_t);
    size_t alignment = sizeof(long); // adjust this as needed
    char* alignedRecords = (char*)(((size_t)records + alignment - 1) & ~(alignment - 1));
    records = (record_t*)((void*)alignedRecords);

    return records;
}

int initializeRecords(record_t* records, int startKey, int stepSize, long seed) {
    if (!records) {
        return -1; // or handle error as needed
    }

    for (int i = 0; i < records->numRecords; i++) {
        records[i].offset = lcg64(seed + i); // linear congruential generator formula
        records[i].key = startKey + (i * stepSize);
        records[i].value = (double)rand() / RAND_MAX;
    }

    return 0;
}

void deallocateRecords(record_t* records, int numRecords) {
    if (!records || numRecords <= 0) {
        return;
    }

    free(records);
}

long lcg64(long seed) {
    const long a = 1664525L;
    const long c = 6682903L;
    const long m = 2^32;

    seed = (a * seed + c) % m;
    return seed;
}
