    char ip_address[16];
    int port_number;
} network_entity;

typedef struct {
    network_entity* data;
    size_t capacity;
    size_t used;
} dynamic_list;

dynamic_list* create_dynamic_list(size_t initial_capacity) {
    dynamic_list* list = (dynamic_list*)malloc(sizeof(dynamic_list));
    list->data = (network_entity*)calloc(initial_capacity, sizeof(network_entity));
    list->capacity = initial_capacity;
    list->used = 0;
    return list;
}

void add_network_entity(dynamic_list* list, network_entity entity) {
    if (list->used >= list->capacity) {
        size_t new_capacity = list->capacity * 2 + 1;
        list->data = (network_entity*)realloc(list->data, sizeof(network_entity) * new_capacity);
        list->capacity = new_capacity;
    }
    memcpy(&list->data[list->used], &entity, sizeof(network_entity));
    list->used++;
}

void remove_network_entity(dynamic_list* list, char mac_address[]) {
    for (size_t i = 0; i < list->used; ++i) {
        if (strcmp(list->data[i].mac_address, mac_address) == 0) {
            memmove(&list->data[i], &list->data[i + 1], sizeof(network_entity) * (list->used - i - 1));
            list->used--;
            return;
        }
    }
}

network_entity* get_network_entity(dynamic_list* list, char mac_address[]) {
    for (size_t i = 0; i < list->used; ++i) {
        if (strcmp(list->data[i].mac_address, mac_address) == 0) {
            return &list->data[i];
        }
    }
    return NULL;
}

void free_dynamic_list(dynamic_list* list) {
    free(list->data);
    free(list);
}
