#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTITIES 10000
#define ENTITY_VERSIONS 10

typedef struct {
    char mac_address[18];
    char ip_address[16];
    int port_number;
    int version;
} NetworkEntity;

typedef struct {
    NetworkEntity *entities;
    int current_version;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} EntityList;

void* entity_list_init() {
    EntityList *list = (EntityList*)malloc(sizeof(EntityList));
    list->entities = (NetworkEntity*)malloc(MAX_ENTITIES * sizeof(NetworkEntity));
    list->current_version = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void entity_list_free(void* ptr) {
    EntityList *list = (EntityList*)ptr;
    free(list->entities);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(ptr);
}

int entity_add(EntityList* list, NetworkEntity* entity) {
    int index = 0;
    while (index < MAX_ENTITIES && list->entities[index].port_number != -1) {
        index++;
    }
    if (index == MAX_ENTITIES) return -1; // List full
    memcpy(&list->entities[index], entity, sizeof(NetworkEntity));
    list->entities[index].version = 0;
    pthread_mutex_lock(&list->mutex);
    list->current_version += 1;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
    return index;
}

int entity_get(EntityList* list, int entity_index) {
    if (entity_index < 0 || entity_index >= MAX_ENTITIES) return -1; // Invalid index
    NetworkEntity* entity = &list->entities[entity_index];
    return entity->port_number;
}

void* get_entity_version(void* ptr, int version) {
    EntityList* list = (EntityList*)ptr;
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < MAX_ENTITIES; i++) {
        if (list->entities[i].version == version) {
            // Return the entity at the given version
            return &list->entities[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void* main_thread(void* ptr) {
    EntityList* list = (EntityList*)ptr;
    for (int i = 0; i < ENTITY_VERSIONS; i++) {
        // Simulate adding and retrieving entities with different versions
        pthread_mutex_lock(&list->mutex);
        NetworkEntity entity;
        // Add an entity with a new version
        if (entity_add(list, &entity) >= 0) {
            int entity_index = entity_get(list, -1); // Find the most recent added entity
            NetworkEntity* entity_ptr = &list->entities[entity_index];
            // Simulate retrieving entities at different versions
            pthread_cond_wait(&list->cond, &list->mutex);
            void* version_result = get_entity_version(ptr, i);
            if (version_result != NULL) {
                printf("Found entity at version %d: MAC=%s IP=%s Port=%d\n", 
                       ((NetworkEntity*)version_result)->version,
                       ((NetworkEntity*)version_result)->mac_address,
                       ((NetworkEntity*)version_result)->ip_address,
                       ((NetworkEntity*)version_result)->port_number);
            }
            pthread_mutex_unlock(&list->mutex);
        }
    }
    return NULL;
}

int main() {
    void* entity_list = entity_list_init();
    pthread_t thread;
    pthread_create(&thread, NULL, main_thread, entity_list);
    pthread_join(thread, NULL);
    entity_list_free(entity_list);
    return 0;
}
