#include <unordered_map>
#include <vector>
#include <string>

class NetworkEntity {
public:
    std::string macAddress;
    std::string ipAddress;
    int portNumber;

    NetworkEntity(const std::string& mac, const std::string& ip, int port)
        : macAddress(mac), ipAddress(ip), portNumber(port) {}
};

class NetworkManager {
private:
    std::unordered_map<std::string, NetworkEntity*> entities;

public:
    void addEntity(NetworkEntity* entity) {
        if (entities.find(entity->macAddress) != entities.end()) {
            // Handle duplicate MAC address
            return;
        }
        entities[entity->macAddress] = entity;
    }

    void removeEntity(const std::string& macAddress) {
        if (entities.erase(macAddress) != entities.end()) {
            // Entity not found, handle error
            return;
        }
    }

    NetworkEntity* getEntity(const std::string& macAddress) {
        auto it = entities.find(macAddress);
        if (it == entities.end()) {
            // Entity not found, handle error
            return nullptr;
        }
        return it->second;
    }
};
