// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** generateCRCIndicationPDUList(int numElements) {
    int i;
    srand((unsigned int)time(NULL));  // Set seed for random number generation

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDATION_PDU_T**)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Randomly set RX_UE_INFORMATION_TAG and RNTI
        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 200;

        // Initialize CRC_INDICATION_REL8_TAG with a random CRCFLAG
        srand((unsigned int)time(NULL));
        int crcFlag = rand() % 2;  // Randomly set CRCFLAG (0 or 1)

        if (crcFlag == 0) {
            pdu->CRC_INDICATION_REL8_TAG[0] = '0';
            pdu->CRC_INDICATION_REL8_TAG[1] = '0';
            pdu->CRC_INDICATION_REL8_TAG[2] = '0';
            pdu->CRC_INDICATION_REL8_TAG[3] = '\0';
