typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

Node* create_list(int N, int seed) {
    srand(seed);
    Node* head = NULL;
    Node** tail = &head;
    for (int i = 0; i < N; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            free(node);
            printf("Memory allocation failed.\n");
            return NULL;
        }
        pdu->RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu->RNTI = rand() % 2000 + 1;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2);
        node->data = pdu;
        node->next = NULL;
        *tail = node;
        tail = &node->next;
    }
    return head;
}

void validate_list(Node* list) {
    Node* current = list;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = current->data;
        if (pdu == NULL || pdu->RX_UE_INFORMATION_TAG < 0 || pdu->RNTI < 1) {
            printf("Invalid structure detected.\n");
            return;
        }
        current = current->next;
    }
}

Node* free_list(Node* list) {
    Node* current = list;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = current->data;
        free(pdu);
        free(current);
        current = current->next;
    }
    return NULL;
}
