        // Read in new session parameters from input
        scanf("%d %s %s", &sessions[num_sessions].client_id, sessions[num_sessions].content_type,
             sessions[num_sessions].location);

        // Validate and prioritize the new session based on QoS requirements
        int validation_result = validate_session(&sessions[num_sessions]);
        if (validation_result < 0) {
            printf("Invalid session parameters: %d\n", validation_result);
            continue;
        }

        // Start a new thread for the streaming session
        manage_session(&sessions[num_sessions], threads + num_sessions);

        num_sessions++;
    }

    return 0;
}
