void* manage_memory(size_t offset_size, size_t key_size, size_t record_count) {
    int* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    try {
        // Allocate memory for offsets
        if ((offsets = (int*)malloc(offset_size * sizeof(int))) == NULL) {
            fprintf(stderr, "Failed to allocate memory for offsets.\n");
            return NULL;
        }

        // Initialize offsets with unique values
        for (size_t i = 0; i < offset_size; ++i) {
            offsets[i] = random_int(-1000, 1000);
        }

        // Allocate memory for keys
        if ((keys = (int*)malloc(key_size * sizeof(int))) == NULL) {
            free(offsets);
            fprintf(stderr, "Failed to allocate memory for keys.\n");
            return NULL;
        }

        // Initialize keys with unique values
        for (size_t i = 0; i < key_size; ++i) {
            keys[i] = random_int(-1000, 1000);
        }

        // Calculate the number of records based on the smaller array size
        size_t record_count_calc = min(record_count, offset_size / 2);

        // Allocate memory for records
        if ((records = (record*)malloc(record_count_calc * sizeof(record))) == NULL) {
            free(offsets);
            free(keys);
            fprintf(stderr, "Failed to allocate memory for records.\n");
            return NULL;
        }

        // Initialize records with random values
        for (size_t i = 0; i < record_count_calc; ++i) {
            records[i].value = random_int(-1000, 1000);
        }

        // Perform any necessary cleanup or logging before returning
        // ...

        return records;
    } catch (...) {
        if (offsets != NULL) free(offsets);
        if (keys != NULL) free(keys);
        return NULL;
    }
}

int random_int(int min, int max) {
    static const int RAND_MAX_VALUE = 2147483647;
    srand(time(NULL));
    return (rand() % (RAND_MAX - (max - min + 1))) + min;
}
