void nfa_pi_crc_indication_pdu_list_init() {
    pthread_mutex_init(&nfa_pi_crc_indication_pdu_list.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu_list_append() {
    NFAPI_CRC_INDICATION_PDU_T* new_entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) return NULL;

    uint32_t crc_flag = rand();
    new_entry->RX_UE_INFORMATION_TAG = crc_flag & 0xFF;
    new_entry->RNTI = (crc_flag >> 8) & 0xFFFF;
    new_entry->CRC_INDICATION_REL8_TAG = crc_flag;

    pthread_mutex_lock(&nfa_pi_crc_indication_pdu_list.lock);
    if (nfa_pi_crc_indication_pdu_list.size >= MAX_ENTRIES) {
        free(new_entry);
        pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_list.lock);
        return NULL;
    }

    nfa_pi_crc_indication_pdu_list.data = realloc(nfa_pi_crc_indication_pdu_list.data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfa_pi_crc_indication_pdu_list.size + 1));
    if (!nfa_pi_crc_indication_pdu_list.data) {
        free(new_entry);
        pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_list.lock);
        return NULL;
    }

    nfa_pi_crc_indication_pdu_list.data[nfa_pi_crc_indication_pdu_list.size] = *new_entry;
    nfa_pi_crc_indication_pdu_list.size++;
    pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_list.lock);

    return &nfa_pi_crc_indication_pdu_list.data[nfa_pi_crc_indication_pdu_list.size - 1];
}

bool nfa_pi_crc_indication_pdu_list_validate(NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!entry || !entry->RX_UE_INFORMATION_TAG || !entry->RNTI || !entry->CRC_INDICATION_REL8_TAG) return false;

    return true;
}

NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu_list_get(size_t index) {
    pthread_mutex_lock(&nfa_pi_crc_indication_pdu_list.lock);
    if (index >= nfa_pi_crc_indication_pdu_list.size) {
        pthread_mutex_unlock(&nfa_pi_crc_indiation_pdu_list.lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* entry = &nfa_pi_crc_indication_pdu_list.data[index];

    if (!nfa_pi_crc_indication_pdu_list_validate(entry)) {
        free(entry);
        entry = NULL;
    }

    pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_list.lock);

    return entry;
}
