#define MAX_ELEMENTS 1000
#define NFAPI_CRC_INDICATION_PDU_T_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

struct {
    pthread_mutex_t mutex;
    int count;
} nfa_api_crc_indication_pdu_lock = {PTHREAD_MUTEX_INITIALIZER, 0};

NFAPI_CRC_INDICATION_PDU_T* create_nfa_api_crc_indication_pdu(int num_elements) {
    if (num_elements > MAX_ELEMENTS) {
        return NULL; // Error: Exceeds maximum allowed elements
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * NFAPI_CRC_INDICATION_PDU_T_SIZE);
    if (!pdu_list) {
        return NULL; // Allocation failed
    }

    pthread_mutex_lock(&nfa_api_crc_indication_pdu_lock.mutex);
    for (int i = 0; i < num_elements; i++) {
        pdu_list[i].rx_ue_info_tag = rand() % RAND_MAX;
        pdu_list[i].rnti = rand() % RAND_MAX;
        pdu_list[i].crc_ind_rel8_tag = rand() % RAND_MAX;
        pdu_list[i].crcflag = rand() % 2; // Randomly set CRCFLAG
    }
    nfa_api_crc_indication_pdu_lock.count += num_elements;

    pthread_mutex_unlock(&nfa_api_crc_indication_pdu_lock.mutex);

    return pdu_list;
}

void free_nfa_api_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    if (!pdu_list) {
        return; // No memory to free
    }

    pthread_mutex_lock(&nfa_api_crc_indication_pdu_lock.mutex);
    nfa_api_crc_indication_pdu_lock.count -= pdu_list ? 1 : 0;
    free(pdu_list);
    pthread_mutex_unlock(&nfa_api_crc_indication_pdu_lock.mutex);
}
