        int new_capacity = manager->capacity * 2;
        MAC_PDU** new_pds = (MAC_PDU**)realloc(manager->pdus, new_capacity * sizeof(MAC_PDU*));
        for (int i = 0; i < manager->size; i++) {
            new_pds[i] = manager->pdus[i];
        }
        free(manager->pdus);
        manager->pdus = new_pds;
        manager->capacity = new_capacity;
    }
