#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory management
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Primary allocation failed, try alternative strategy
        ptr = realloc(NULL, size);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic list management function
Node* manage_list(Node** head, int RNTI, char RX_UE_INFORMATION_TAG[], char CRC_INDICATION_REL8_TAG[], int CRCFLAG) {
    Node* new_node = (Node*)my_malloc(sizeof(Node));
    if (new_node == NULL) {
        // Out-of-memory condition, log and return
        printf("Error: Out of memory\n");
        return *head;
    }

    new_node->data.RX_UE_INFORMATION_TAG[16] = RX_UE_INFORMATION_TAG[0];
    new_node->data.RNTI = RNTI;
    strcpy(new_node->data.CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG);
    new_node->data.CRCFLAG = CRCFLAG;

    if (*head == NULL || (*head)->data.RNTI >= RNTI) {
        // Add to the beginning of the list
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->data.RNTI < RNTI) {
            current = current->next;
        }
        // Add to the middle of the list
        new_node->next = current->next;
        current->next = new_node;
    }

    return *head;
}

// Update existing node or add new one
Node* update_or_add(Node** head, int RNTI, char RX_UE_INFORMATION_TAG[], char CRC_INDICATION_REL8_TAG[], int CRCFLAG) {
    Node* current = *head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            // Update existing node
            strcpy(current->data.RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG);
            strcpy(current->data.CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG);
            current->data.CRCFLAG = CRCFLAG;
            return *head;
        }
        current = current->next;
    }

    // Add new node
    return manage_list(head, RNTI, RX_UE_INFORMATION_TAG, CRC_INDICATION_REL8_TAG, CRCFLAG);
}

// Remove node by RNTI
Node* remove_node(Node** head, int RNTI) {
    Node* current = *head;
    Node* prev = NULL;

    if (current && current->data.RNTI == RNTI) {
        // Remove the first node
        *head = current->next;
        my_free(current);
        return *head;
    }

    while (current && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (current) {
        // Remove a middle or last node
        prev->next = current->next;
        my_free(current);
    }

    return *head;
}

// Free the linked list memory
void free_list(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next = current->next;
        my_free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    // Initialize dynamic list
    Node* head = NULL;

    // Add, update, and remove nodes
    manage_list(&head, 1, "RX_UE_INFORMATION_TAG1", "CRC_INDICATION_REL8_TAG1", 0);
    update_or_add(&head, 2, "RX_UE_INFORMATION_TAG2", "CRC_INDICATION_REL8_TAG2", 1);
    remove_node(&head, 1);

    // Free list memory
    free_list(&head);

    return 0;
}
