int crc_errors = 0;
clock_t last_check_time = clock();

void add_element(NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* temp = (Node*)malloc(sizeof(Node));
    temp->data = new_data;
    temp->next = head;
    head = temp;
}

void update_element(int RNTI, NFAPI_CRC_INDICATION_PDU_T updated_data) {
    Node* current = head;
    while (current != NULL && current->data.RNTI != RNTI)
        current = current->next;
    if (current != NULL)
        memcpy(&current->data, &updated_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

