    Node* temp2 = NULL;

    if (temp1 != NULL && temp1->data.RNTI == RNTI) {
        head = temp1->next; // Update the 'head' pointer of the linked list
        free(temp1); // Free the memory previously allocated for the removed node
    } else {
        temp1 = temp1->next;
        while (temp1 != NULL && temp1->data.RNTI != RNTI)
            temp1 = temp1->next;

        if (temp1 != NULL) {
            temp2 = temp1->next;
            free(temp1);
            temp1 = temp2;
        }
    }
}

void check_crc_errors() {
    Node* current = head;
    clock_t now_time = clock();

    if ((now_time - last_check_time) / CLOCKS_PER_SEC >= WINDOW_SIZE) {
        while (current != NULL) {
            if (current->data.CRCFLAG == 1) // CRC flag is set
                crc_errors++;

            current = current->next;
        }
        last_check_time = now_time;
    }
}

int get_crc_error_count() {
    return crc_errors;
}

void reset_crc_error_count() {
    crc_errors = 0;
    last_check_time = clock();
}
