    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void initNFACRCRecords(int N, int minCRCFlag, int maxCRCFlag, int seed, const char* filename) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of structures: %d\n", N);
        return;
    }

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", filename);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* records = NULL;
    if (rand() > RAND_MAX / 2) { // dynamic allocation
        records = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!records) {
            fprintf(stderr, "Failed to allocate memory for %d structures\n", N);
            fclose(file);
            return;
        }
    } else { // static allocation
        records = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    for (int i = 0; i < N; i++) {
        records[i].RX_UE_INFORMATION_TAG = rand() % 0x10000;
        records[i].RNTI = rand() % 256;
        records[i].CRC_INDICATION_REL8_TAG = rand() % 0x10000;
        records[i].CRCFLAG = (rand() % (maxCRCFlag - minCRCFlag + 1)) + minCRCFlag;

        if (!fwrite(&records[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
            fprintf(stderr, "Failed to write record to file\n");
            free(records);
            fclose(file);
            return;
        }
    }

    if (rand() > RAND_MAX / 2) { // dynamic allocation
        free(records);
    }

    fclose(file);
