#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_SIMULTANEOUS_ALLOCATIONS 10
#define BUCKET_CAPACITY 1000
#define REFILL_RATE 50

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int current_allocations = 0;
int available_tokens = BUCKET_CAPACITY;
int last_refill_time = time(NULL);

void* nfastorage = NULL;

NFAPI_CRC_INDICATION_PDU_T** array = NULL;
size_t capacity = 0;
size_t size = 0;

void resize_array(size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T** temp = (NFAPI_CRC_INDICATION_PDU_T**)realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_capacity);
    if (!temp) {
        array = NULL;
        capacity = 0;
    } else {
        array = temp;
        capacity = new_capacity;
    }
}

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (ptr) {
        return ptr;
    } else {
        return NULL;
    }
}

int free_storage(void* ptr, size_t size) {
    free(ptr);
    return 0;
}

int is_full() {
    return current_allocations >= MAX_SIMULTANEOUS_ALLOCATIONS;
}

int refill_bucket() {
    if (time(NULL) - last_refill_time < REFILL_RATE) {
        return 0;
    }
    available_tokens = BUCKET_CAPACITY;
    last_refill_time = time(NULL);
    return 1;
}

void cleanup() {
    for (size_t i = 0; i < size; ++i) {
        if (!array[i]) continue;
        free_storage(array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    array = NULL;
    capacity = 0;
}

int state_machine(int state) {
    switch (state) {
        case 0: // active
            if (is_full()) {
                return 1; // pause
            } else {
                return 0; // continue
            }
        case 1: // paused
            if (refill_bucket()) {
                return 2; // resume
            } else {
                return 1; // stay paused
            }
        default:
            return -1;
    }
}

int allocate_nfastorage(int state) {
    int ret = state_machine(state);
    if (ret == -1) {
        return -1;
    }
    pthread_mutex_lock(&lock);
    if (state == 0) {
        while (is_full()) {
            // wait
        }
    } else {
        available_tokens -= 1;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_storage = allocate(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_storage) {
        ret = -1;
    } else {
        array[size] = new_storage;
        size++;
        current_allocations++;
    }
    pthread_mutex_unlock(&lock);
    return ret;
}

void deallocate_nfastorage(int state) {
    pthread_mutex_lock(&lock);
    if (state == 0) {
        current_allocations--;
    } else {
        available_tokens += 1;
    }
    for (size_t i = size - 1; i >= 0; --i) {
        free_storage(array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    size = 0;
    pthread_mutex_unlock(&lock);
}

int main() {
    // initialize and start the allocation/deallocation process
    while (true) {
        int ret = allocate_nfastorage(0);
        if (ret == -1) {
            deallocate_nfastorage(1);
        }
        cleanup();
        // periodically check for state changes and adjust accordingly
    }
    return 0;
}
