#define MAX_ELEMENTS 1024
#define CIRCULAR_BUFFER_SIZE (MAX_ELEMENTS * 2)

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t circular_buffer_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *circular_buffer = NULL;
size_t buffer_size = 0, head = 0, tail = 0;

void* add_element(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* element = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    pthread_mutex_lock(&circular_buffer_lock);
    if (buffer_size >= MAX_ELEMENTS) {
        // Discard the oldest element
        size_t discard_index = head;
        memmove(circular_buffer, &circular_buffer[discard_index + 1], buffer_size - discard_index - 1);
        buffer_size--;
        head = 0;
        tail = buffer_size;
    }
    if (buffer_size < MAX_ELEMENTS) {
        circular_buffer[tail] = *element;
        tail = (tail + 1) % CIRCULAR_BUFFER_SIZE;
        buffer_size++;
    }
    pthread_mutex_unlock(&circular_buffer_lock);
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* update_element(NFAPI_CRC_INDICATION_PDU_T* element, RNTI rnti) {
    pthread_mutex_lock(&circular_buffer_lock);
    size_t i = head;
    while (i != tail) {
        if (circular_buffer[i].rnti == rnti) {
            // Update the existing element
            circular_buffer[i] = *element;
            pthread_mutex_unlock(&circular_buffer_lock);
            return &circular_buffer[i];
        }
        i = (i + 1) % CIRCULAR_BUFFER_SIZE;
    }
    pthread_mutex_unlock(&circular_buffer_lock);
    return NULL;
}

void remove_element(size_t index) {
    pthread_mutex_lock(&circular_buffer_lock);
    if (index >= head && index < tail) {
        // Remove the element
        memmove(circular_buffer + head, circular_buffer + (head + 1), buffer_size - index - 1);
        head = (head + 1) % CIRCULAR_BUFFER_SIZE;
        buffer_size--;
    }
    pthread_mutex_unlock(&circular_buffer_lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(size_t index) {
    pthread_mutex_lock(&circular_buffer_lock);
    if (index >= head && index < tail) {
        // Return the element
        return &circular_buffer[index];
    }
    pthread_mutex_unlock(&circular_buffer_lock);
    return NULL;
}

void init_circular_buffer() {
    circular_buffer = aligned_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), CIRCULAR_BUFFER_SIZE);
    buffer_size = 0;
    head = 0;
    tail = 0;
}
