void add_element(int RX_UE_INFORMATION_TAG, int RNTI, char CRC_INDICATION_REL8_TAG[10], int CRCFLAG) {
    pthread_mutex_lock(&mutex);

    if (current_size >= MAX_ELEMENTS) {
        // discard oldest element
        memmove(nfaapi_array, nfaapi_array + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (MAX_ELEMENTS - 1));
        current_size--;
