```c
#include <stdatomic.h>
#include <stdlib.h>

#define MAX_ELEMENTS 1024

typedef struct {
    uint16_t ue_id;
    int16_t rx_power;
    int8_t cqi;
} PHY_RX_STATS_PDU_T;

struct {
    size_t head, tail, size;
    atomic_size_t count;
    void* elements[MAX_ELEMENTS];
} circular_buffer = {0};

void add_element(PHY_RX_STATS_PDU_T* element) {
    while (atomic_compare_exchange_weak(&circular_buffer.count, &circular_buffer.size, 1));
    if (circular_buffer.size >= MAX_ELEMENTS)
        circular_buffer.head = (circular_buffer.head + 1) % MAX_ELEMENTS;
    circular_buffer.elements[circular_buffer.tail] = element;
    if (++circular_buffer.tail == MAX_ELEMENTS)
        circular_buffer.tail = 0;
}

void update_element(uint16_t ue_id, int16_t rx_power, int8_t cqi) {
    size_t i = circular_buffer.head;
    while (i != circular_buffer.tail) {
        PHY_RX_STATS_PDU_T* element = circular_buffer.elements[i];
        if (element->ue_id == ue_id) {
            element->rx_power = rx_power;
            element->cqi = cqi;
            return;
        }
        i = (i + 1) % MAX_ELEMENTS;
    }
}

void remove_element(size_t index) {
    while (index != circular_buffer.head) {
        size_t i = circular_buffer.head;
        while (i != circular_buffer.tail) {
            PHY_RX_STATS_PDU_T* element = circular_buffer.elements[i];
            if (++i == MAX_ELEMENTS)
                i = 0;
            if (i == index) {
                *element = *(PHY_RX_STATS_PDU_T*)0; // mark as removed
                return;
            }
        }
        circular_buffer.head = (circular_buffer.head + 1) % MAX_ELEMENTS;
    }
}

void print_elements() {
    size_t i = circular_buffer.head;
    while (i != circular_buffer.tail) {
        PHY_RX_STATS_PDU_T* element = circular_buffer.elements[i];
        printf("UE ID: %hu, RX Power: %hd, CQI: %hhd\n", 
               element->ue_id, element->rx_power, element->cqi);
        i = (i + 1) % MAX_ELEMENTS;
    }
}
