    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(int size) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!list) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        int rnti = rand() % 65536;
        while (i > 0) {
            if (list[i - 1].RNTI == rnti) {
                rnti = rand() % 65536;
            } else {
                break;
            }
        }
        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        int flag = rand() % 2;
        while (1) {
            if (flag == 0) {
                list[i].CRCFLAG = 0;
            } else {
                list[i].CRCFLAG = 1;
            }
            for (int j = 0; j < i; j++) {
                if (list[j].RNTI == rnti && list[j].CRCFLAG == flag) {
                    flag = !flag;
                    break;
                }
            }
            if (!flag) {
                break;
            }
        }
    }
    qsort(list, size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare);
    return list;
}

int compare(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* fa = (NFAPI_CRC_INDICATION_PDU_T*) a;
    NFAPI_CRC_INDICATION_PDU_T* fb = (NFAPI_CRC_INDICATION_PDU_T*) b;
    if (fa->RNTI < fb->RNTI) {
        return -1;
    } else if (fa->RNTI > fb->RNTI) {
        return 1;
    } else {
        return 0;
    }
}

int main() {
    int size = 10000;
    NFAPI_CRC_INDICATION_PDU_T* list = create_list(size);
    // usage of list
    free(list);
    return 0;
}
