['```rust
use std::sync::{Arc, Mutex};
use reqwest;
use serde_json;

struct NODE_ENTITY_CONTEXT {
    node_entity_id: String,
    session_contexts: Vec<SESSION_CONTEXT>,
}

struct SESSION_CONTEXT {
    seid: u32,
    start_timestamp: u64,
    is_active: bool,
}

pub struct NodeEntityContextManager {
    contexts: Arc<Mutex<Vec<NODE_ENTITY_CONTEXT>>>,
}

impl NodeEntityContextManager {
    pub fn new() -> Self {
        NodeEntityContextManager {
            contexts: Arc::new(Mutex::new(Vec::new())),
        }
    }

    pub fn add_node(&self, node_id: String) -> Result<(), reqwest::Error> {
        let mut contexts = self.contexts.lock().unwrap();
        contexts.push(NODE_ENTITY_CONTEXT {
            node_entity_id: node_id,
            session_contexts: Vec::new(),
        });
        Ok(())
    }

    pub fn add_session(&self, node_id: String, seid: u32, start_timestamp: u64, is_active: bool) -> Result<(), reqwest::Error> {
        let mut contexts = self.contexts.lock().unwrap();
        for context in &mut contexts {
            if context.node_entity_id == node_id {
                context.session_contexts.push(SESSION_CONTEXT { seid, start_timestamp, is_active });
                return Ok(())
            }
        }
        Err(reqwest::Error::new(reqwest::StatusCode::BadRequest))
    }

    pub fn get_request_builder(&self, url: &str, disable_cert_validation: bool) -> reqwest::RequestBuilder {
        let client = if disable_cert_validation { reqwest::Client::builder().dangerously_ignore_body() } else { reqwest::Client::new() };
        client.get(url)
    }
}
