    for(int i=0; i<n; i++) {
        array[i].RX_UE_INFORMATION_TAG = min_rx_ue_info_tag + rand() % (max_rx_ue_info_tag - min_rx_ue_info_tag);
        array[i].RNTI = min_rnti + rand() % (max_rnti - min_rnti);

        // Initialize CRC_INDICATION_REL8_TAG based on RX_UE_INFORMATION_TAG and RNTI
        uint32_t crc_value = 0;
        for(int j=0; j<4; j++) {
