    int i, j, distance_id = 0;
    for (i = 0; i < points_array_size; i++) {
        for (j = i + 1; j < points_array_size; j++) {
            // Calculate Euclidean distance between two points
            float dx = points_array[i]->x - points_array[j]->x;
            float dy = points_array[i]->y - points_array[j]->y;
            distances_array[distance_id++] = (int)sqrt(dx * dx + dy * dy);
        }
    }
    return NULL;
}

