    fp_array_init(NULL);
    cp_array_init(NULL);
    points_array_init(NULL);
    distances_array_init(NULL);

    for (int i = 0; i < EUCLIDEAN_DISTANCE_CALCULATION_THREADS; i++)
        pthread_create(&euclidean_distance_calculation_threads[i], NULL, thread_function, NULL);

    // Manage threads and arrays
    manage_threads(10);

    return 0;
}
