void populate_NFAPI_CRC_INDICATION_PDU_T(int N, NFAPI_CRC_INDICATION_PDU_T **list) {
    int i, rnti_range_max = 65536; // adjust to desired range
    srand(time(NULL));
    int *rntis = (int *)malloc((N+1)*sizeof(int));
    if (!rntis) {
        printf("Memory allocation failure!\n");
        return;
    }
    for (i = 0; i < N; i++) {
        do {
            rntis[i] = rand() % rnti_range_max + 1; // ensure positive
        } while (rntis[i] < 0 || exists_rnti(rntis, i));
    }
    for (i = 0; i < N; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % rnti_range_max + 1;
        (*list)[i].RNTI = rntis[i];
        (*list)[i].CRCFLAG = rand() & 0xFF; // randomize CRC flag
    }
    free(rntis);
}

int exists_rnti(int *rntis, int index) {
    int i;
    for (i = 0; i < index; i++) {
        if (rntis[i] == rntis[index]) return 1;
    }
    return 0;
}

void print_NFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    int i;
    for (i = 0; i < N; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %02X\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRCFLAG);
