    if (!(list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
        printf("Memory allocation failure!\n");
        return 1;
    }
    populate_NFAPI_CRC_INDICATION_PDU_T(N, &list);
    print_NFAPI_CRC_INDICATION_PDU_T(list, N);
    free(list);
    return 0;
}
