void configure_network_interface(int num_connections) {
    int i, rnti, channel_frequency;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;

    // Delete any existing file before performing network operations
    char filename[] = "network_file.txt";
    FILE* file = fopen(filename, "w");
    if (file != NULL) {
        fclose(file);
    } else {
        printf("Error deleting file: %s\n", filename);
    }

    // Dynamically allocate memory for RX_UE_INFORMATION_TAG instances
    RX_UE_INFORMATION_TAG** rx_ue_info_tags = (RX_UE_INFORMATION_TAG**)malloc(num_connections * sizeof(RX_UE_INFORMATION_TAG*));
    if (!rx_ue_info_tags) {
        printf("Error allocating memory for RX_UE_INFORMATION_TAG instances.\n");
        return;
    }

    // Initialize and configure each RX_UE_INFORMATION_TAG instance
    for (i = 0; i < num_connections; i++) {
        rx_ue_info_tags[i] = (RX_UE_INFORMATION_TAG*)malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (!rx_ue_info_tags[i]) {
            printf("Error allocating memory for RX_UE_INFORMATION_TAG.\n");
            return;
        }

        rnti = rand() % 100; // Random RNTI value
        channel_frequency = rand() % 5000; // Random channel frequency

        rx_ue_info_tags[i]->rnti = rnti;
        rx_ue_info_tags[i]->channel_frequency = channel_frequency;
    }

    // Dynamically allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_connections * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        printf("Error allocating memory for NFAPI_CRC_INDICATION_PDU_T structures.\n");
        return;
    }

    // Initialize and configure each NFAPI_CRC_INDICATION_PDU_T structure
    for (i = 0; i < num_connections; i++) {
        pdu_list[i].rx_ue_info_tag = *rx_ue_info_tags[i];

        // Randomly set CRCFLAG value
        int crcflag = rand() % 2;
        // Add other required fields as needed

        pdu_list[i].CRC_INDICATION_REL8_TAG = crcflag;
    }

    // Perform network operations using the configured NFAPI_CRC_INDICATION_PDU_T structures
    for (i = 0; i < num_connections; i++) {
        printf("Connection %d: RNTI=%d, Channel Frequency=%d, CRCFLAG=%d\n", i+1, pdu_list[i].rx_ue_info_tag.rnti, pdu_list[i].rx_ue_info_tag.channel_frequency, pdu_list[i].CRC_INDICATION_REL8_TAG);
    }

    // Clean up dynamically allocated memory
    for (i = 0; i < num_connections; i++) {
        free(rx_ue_info_tags[i]);
    }
    free(rx_ue_info_tags);
    free(pdu_list);
}
