    int n;
    scanf("%d", &n);

    NFAPI_CRC_INDICATION_PDU_T* list = create_list(n);
    int* integers = (int*)malloc((n+1)*sizeof(int));

    for (int i = 0; i < n; i++) {
        scanf("%d", &integers[i]);
    }

    int largest_int = find_largest(integers, n);

