    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        list[i].valid_RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = rand();
        list[i].CRCFLAG = rand() % 2;
    }
    return list;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    for (int i = 0; i < size; i++) {
        free(*list);
        *list = NULL;
    }
}

int find_largest(int* array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest)
            largest = array[i];
    }
    return largest;
}

void log_debug(char* format, ...) {
    va_list ap;
    va_start(ap, format);
    vfprintf(log_file, format, ap);
    va_end(ap);
}
