// Custom dynamic array implementation
typedef struct {
    int capacity;
    int size;
    NFAPI_CRC_INDICATION_PDU_T* data;
} DynamicArray;

DynamicArray* createDynamicArray(int initialCapacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->capacity = initialCapacity;
    arr->size = 0;
    arr->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(NFAPI_CRC_INDICATION_PDU_T_STRUCT_SIZE * initialCapacity);
    return arr;
}

void resizeDynamicArray(DynamicArray* arr, int newCapacity) {
    DynamicArray* newArr = createDynamicArray(newCapacity);
    for (int i = 0; i < arr->size; i++) {
        newArr->data[i] = arr->data[i];
    }
    free(arr->data);
    *arr = *newArr;
}

void destroyDynamicArray(DynamicArray* arr) {
    free(arr->data);
    free(arr);
}

// Function to manage NFAPI_CRC_INDICATION_PDU_T structures
int manageNFAPI_CRC_INDICATION_PDU_T(DynamicArray* array, int initialCapacity) {
    srand(time(NULL));
    for (int i = 0; i < initialCapacity; i++) {
        NFAPI_CRC_INDICATION_PDU_T structTemp;
        strcpy(structTemp.RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
        structTemp.RNTI = rand() % 10000;
        strcpy(structTemp.CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG");
        int flag = rand() % 2; // Randomly set CRCFLAG
        if (flag) {
            structTemp.CRCFLAG = 1;
        } else {
            structTemp.CRCFLAG = 0;
        }
        for (int j = 0; j < array->size; j++) {
            if (array->data[j].RNTI == structTemp.RNTI) {
                return -1; // Error: duplicate RNTI found
            }
        }
        if (array->size >= array->capacity) {
            resizeDynamicArray(array, array->capacity * 2);
        }
        array->data[array->size++] = structTemp;
    }
    return 0; // Success
}

// Function to serialize the collection to a binary file
int serializeNFAPI_CRC_INDICATION_PDU_T(DynamicArray* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return -1; // Error: unable to open file
    }
    for (int i = 0; i < array->size; i++) {
        fwrite(&array->data[i], NFAPI_CRC_INDICATION_PDU_T_STRUCT_SIZE, 1, file);
    }
    fclose(file);
    return 0; // Success
}

// Function to deserialize the collection from a binary file
int deserializeNFAPI_CRC_INDICATION_PDU_T(DynamicArray* array, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return -1; // Error: unable to open file
    }
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(NFAPI_CRC_INDICATION_PDU_T_STRUCT_SIZE * array->capacity);
    array->size = 0;
    int bytesRead = 0;
