    for (int i = 0; i < numUeStates; i++) {
        if (ueStates[i]->ueId == ueId) {
            // Remove the connection from the linked list
            RRCConnection* temp = ueStates[i]->connections;
            ueStates[i]->connections = temp->next;
            free(temp);
            return 1;
        }
    }
    return 0; // UEState not found
}

// Function to retrieve a UEState from the cache or create a new one if needed
UEState* getUeState(int ueId) {
    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < numUeStates; i++) {
        if (ueStateCache[i]->ueId == ueId) {
            UEState* ueState = ueStateCache[i];
            // Check if the cached UEState is outdated
            if (time(NULL) - ueState->lastUpdated > 30 * 60) { // 30 minutes
                // Update the lastUpdated timestamp and refresh the cache
                updateLastUpdated(ueState);
            }
            pthread_mutex_unlock(&cacheMutex);
            return ueState;
        }
    }
    pthread_mutex_unlock(&cacheMutex);

    // Create a new UEState if not found in the cache
    UEState* ueState = (UEState*)malloc(sizeof(UEState));
    ueState->ueId = ueId;
    ueState->connections = NULL;
    ueState->lastUpdated = time(NULL);
    // Add the new UEState to the array and update the cache
    pthread_mutex_lock(&arrayMutex);
    numUeStates++;
    ueStates[numUeStates - 1] = ueState;
    pthread_mutex_unlock(&arrayMutex);
