    // Dynamically allocate resources based on number of active users
    size_t memory = numUsers * sizeof(UserConfig);
    UserConfig* userConfigs = (UserConfig*)malloc(memory);

    for (int i = 0; i < numUsers; i++) {
        // Validate configuration parameters for each user
        int channelFrequency;
        if (!fetchConfiguration(i, &channelFrequency)) {
            printf("Error fetching configuration for RNTI %d\n", i);
            return;
        }

        // Initialize user config with default settings
