```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure to represent MAC Entity Contexts
typedef struct {
    int ue_id;
    int num_sessions;
    pthread_mutex_t* session_locks;
    time_t last_retransmission_timestamp;
} MAC_ECONTEXT_T;

// Custom memory management strategy using a doubly-linked list
typedef struct node {
    void* data;
    struct node* prev;
    struct node* next;
} NODE_T;

typedef struct {
    NODE_T* head;
    NODE_T* tail;
} LIST_T;

LIST_T entity_list = {NULL, NULL};

// Function to initialize the memory management strategy
void init_memory_management() {
    LIST_T new_list = {NULL, NULL};
    // Initialize the doubly-linked list
    entity_list = new_list;
}

// Function to add a MAC Entity Context to the dynamic list
int add_entity(MAC_ECONTEXT_T* ectx) {
    NODE_T* new_node = (NODE_T*)malloc(sizeof(NODE_T));
    new_node->data = ectx;
    new_node->prev = NULL;
    new_node->next = NULL;

    if (entity_list.head == NULL) {
        entity_list.head = new_node;
        entity_list.tail = new_node;
    } else {
        entity_list.tail->next = new_node;
        new_node->prev = entity_list.tail;
        entity_list.tail = new_node;
    }

    return 0;
}

// Function to remove a MAC Entity Context from the dynamic list
int remove_entity(MAC_ECONTEXT_T* ectx) {
    NODE_T* current = entity_list.head;
    NODE_T* prev = NULL;

    while (current != NULL) {
        if (current->data == ectx) {
            if (prev == NULL) {
                // Remove the head node
                entity_list.head = current->next;
            } else {
                // Remove a middle or tail node
                prev->next = current->next;
                if (current == entity_list.tail) {
                    entity_list.tail = prev;
                }
            }

            free(current);
            return 0;
        }

        prev = current;
        current = current->next;
    }

    return -1; // Entity not found
}

// Function to retrieve a MAC Entity Context from the dynamic list
MAC_ECONTEXT_T* get_entity(int ue_id) {
    NODE_T* current = entity_list.head;

    while (current != NULL) {
        if (((MAC_ECONTEXT_T*)current->data)->ue_id == ue_id) {
            return (MAC_ECONTEXT_T*)current->data;
        }

        current = current->next;
    }

    return NULL; // Entity not found
}

// Function to update the last retransmission timestamp for a MAC Entity Context
void update_retransmission_timestamp(MAC_ECONTEXT_T* ectx, time_t new_timestamp) {
    pthread_mutex_lock(&ectx->session_locks[0]);
    ectx->last_retransmission_timestamp = new_timestamp;
    pthread_mutex_unlock(&ectx->session_locks[0]);
}
