#include <math.h>

typedef struct {
    float x;
    float y;
} point;

typedef struct {
    int num_points;
    point *points;
} polygon;

void init_point(point *p, float x, float y) {
    p->x = x;
    p->y = y;
}

point* new_point() {
    return (point*)malloc(sizeof(point));
}

polygon* new_polygon(int num_points) {
    polygon *poly = (polygon*)malloc(sizeof(polygon));
    poly->num_points = num_points;
    poly->points = (point*)malloc(num_points * sizeof(point));
    for(int i = 0; i < num_points; i++) {
        init_point(&poly->points[i], (float)rand() / RAND_MAX, (float)rand() / RAND_MAX);
    }
    return poly;
}

double distance(point p1, point p2) {
    return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

double polygon_perimeter(polygon *poly) {
    double perimeter = 0;
    for(int i = 0; i < poly->num_points; i++) {
        if(i == (poly->num_points - 1)) {
            perimeter += distance(poly->points[i], poly->points[0]);
        } else {
            perimeter += distance(poly->points[i], poly->points[i+1]);
        }
    }
    return perimeter;
}

int main() {
    int num_polygons = 10000;
    polygon *polygons[num_polygons];

    for(int i = 0; i < num_polygons; i++) {
        polygons[i] = new_polygon((rand() % 10) + 3);
    }

    for(int i = 0; i < num_polygons; i++) {
        printf("Polygon %d perimeter: %.2f\n", i, polygon_perimeter(polygons[i]));
    }

    for(int i = 0; i < num_polygons; i++) {
        free(polygons[i]->points);
        free(polygons[i]);
    }

    return 0;
}
