#include <arpa/inet.h>
#include <unistd.h>
#include <wait.h>
#include <signal.h>

#define MAX_HOSTNAME_LENGTH 256
#define MAX_IP_ADDRESS_LENGTH 32
#define MAX_STRUCTURE_COUNT 1000

typedef struct {
    uint8_t type;
    uint16_t crc;
} NFAPI_CRC_INDICATION_PDU_T;

int resolve_hostname_to_ip_address(const char *hostname, char *ip_address) {
    struct addrinfo hints, *res;
    int errcode = 0;
    void *addrp;
    const char *cptr;

    hints.ai_family = AF_INET; // or AF_INET6
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;
    getaddrinfo(hostname, NULL, &hints, &res);
    if (res == NULL)
        errcode = 1;
    else {
        addrp = res->ai_addr;
        cptr = inet_ntop(AF_INET, addrp, ip_address, MAX_IP_ADDRESS_LENGTH);
    }
    freeaddrinfo(res);
    return errcode;
}

int establish_connection_and_parse_json(char *ip_address) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0)
        return -1;

    struct sockaddr_in dest_addr;
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(80); // Port for HTTP
    inet_pton(AF_INET, ip_address, &dest_addr.sin_addr);

    connect(sockfd, (struct sockaddr *)&dest_addr, sizeof(dest_addr));

    char buffer[1024];
    int bytes_read = read(sockfd, buffer, 1023);

    if(bytes_read > 0) {
        json_object *jobj = json_object_from_string(buffer);
        const char *field1 = json_object_get_string(json_object_object_get(jobj, "field1"));
        const char *field2 = json_object_get_string(json_object_object_get(jobj, "field2"));

        NFAPI_CRC_INDICATION_PDU_T structures[MAX_STRUCTURE_COUNT];
        int structure_count = 0;

        // Initialize NFAPI_CRC_INDICATION_PDU_T structures
        for (int i = 0; i < MAX_STRUCTURE_COUNT; i++) {
            structures[i].type = 1;
            structures[i].crc = json_object_get_int(jobj, "field3");
            structure_count++;
        }

        // Configure and initialize NFAPI_CRC_INDICATION_PDU_T structures
        for (int i = 0; i < structure_count; i++) {
            printf("Structure %d: type - %u, crc - %u\n", i, structures[i].type, structures[i].crc);
        }

        // Log relevant metrics for monitoring and debugging purposes
        printf("JSON parsing complete.\n");

    } else {
        perror("read");
    }

    close(sockfd);

    return 0;
}

int main() {
    char hostname[MAX_HOSTNAME_LENGTH];
    char ip_address[MAX_IP_ADDRESS_LENGTH];

    printf("Enter hostname: ");
    fgets(hostname, MAX_HOSTNAME_LENGTH, stdin);
    hostname[strcspn(hostname, "\n")] = 0; // Remove trailing newline character

    int errcode = resolve_hostname_to_ip_address(hostname, ip_address);

    if (errcode) {
        return 1;
    }

    establish_connection_and_parse_json(ip_address);

    return 0;
}

