typedef struct {
    double value;
    char* string;
} DataEntry;

DataEntry* initMemory(size_t count, char* prefix, int sessionID) {
    DataEntry* entries = (DataEntry*)malloc(count * sizeof(DataEntry));
    if (!entries) return NULL;

    for (size_t i = 0; i < count; i++) {
        entries[i].value = (double)i / 100.0; // Initialize with a range of [0.0, 1.0]

        char timestamp[64];
        sprintf(timestamp, "%s-%d-%ld", prefix, sessionID, time(NULL));
        int strLen = strlen(timestamp) + 10;
        entries[i].string = (char*)malloc(strLen);
        if (!entries[i].string) {
            for (size_t j = i; j > 0; j--) free(entries[j-1].string);
            free(entries);
            return NULL;
        }
        sprintf(entries[i].string, "Entry %zu: %s", i+1, timestamp);

        // Log initialization process
        printf("Initializing entry %zu with value %.2f and string '%s'\n", i+1, entries[i].value, entries[i].string);
    }

    return entries;
}

void freeMemory(DataEntry* entries, size_t count) {
    for (size_t i = 0; i < count; i++) {
        if (entries[i].string) free(entries[i].string);
    }
    free(entries);
}
