#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define N 10000
#define MAX_THREADS 10

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int data_available = 0;
NFAPI_CRC_INDICATION_PDU_T *data[N];
int num_elements = 0;

void* thread_func(void* arg) {
    int tid = *((int*)arg);
    for(int i = 0; i < N; i++) {
        while(num_elements == i || !data_available) {
            pthread_mutex_lock(&mutex);
            while(!data_available) {
                pthread_cond_wait(&cond, &mutex);
            }
            pthread_mutex_unlock(&mutex);
        }

        // Initialize RX_UE_INFORMATION_TAG and RNTI values from external data source
        // ...

        // Set CRCFLAG randomly
        int crcflag = rand() % 2;

        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->rx_ue_info = ...;
        pdu->rnti = ...;
        pdu->crc_indication_rel8_tag.crcflag = crcflag;

        data[tid] = pdu;

        pthread_mutex_lock(&mutex);
        num_elements++;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }
    free(data[tid]);
}

int main() {
    srand(time(NULL));
    int threads = 0;
    pthread_t* threads_arr = (pthread_t*)malloc(MAX_THREADS * sizeof(pthread_t));

    for(int i = 0; i < MAX_THREADS && threads < N; i++) {
        if(pthread_create(&threads_arr[threads], NULL, thread_func, &threads) != 0) {
            break;
        }
        threads++;
    }

    for(int i = 0; i < threads; i++) {
        pthread_join(threads_arr[i], NULL);
    }

    free(threads_arr);

    return 0;
}
