    pool->next_available_slot = 0;
    return pool;
}

int measurement_report_pool_add_instance(MeasurementReportPool *pool) {
    if (pool->size == pool->capacity) {
        // Grow the buffer by a factor of GROWTH_FACTOR
        void **new_buffer = (void **)realloc(pool->buffer, pool->capacity * sizeof(void *) * GROWTH_FACTOR);
        pool->capacity *= GROWTH_FACTOR;
        pool->buffer = new_buffer;
    }
    return 0;
}

void measurement_report_pool_free(MeasurementReportPool *pool) {
    free(pool->buffer);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

