void init_interfaces(int max_interfaces, int rate_limit, int latency_target) {
    // Initialize a linked list to store MAC contexts
    MAC_CONTEXT_T* head = NULL;
    MAC_CONTEXT_T** tail = &head;

    for (int i = 0; i < max_interfaces; i++) {
        MAC_CONTEXT_T* new_ctx = (MAC_CONTEXT_T*)malloc(sizeof(MAC_CONTEXT_T));
        if (!new_ctx) {
            printf("Error allocating memory!\n");
            return;
        }

        // Initialize MAC context config and stats
        new_ctx->config.rate_limit = rate_limit;
        new_ctx->config.latency_target = latency_target;
        new_ctx->stats.utilization = 0;
        new_ctx->stats.packet_count = 0;

        if (*tail) {
            (*tail)->next = new_ctx;
            *tail = new_ctx;
        } else {
            *tail = &new_ctx->next;
        }
    }

    // Implement rate limiting, load balancing, and resource monitoring
    // ...
}

void configure_interface(MAC_CONTEXT_T* ctx, int bandwidth_limit) {
    // Adjust MAC context config based on user-defined parameters
    ctx->config.rate_limit = bandwidth_limit;
    // ...
}

void shutdown_interfaces() {
    // Disable interfaces in a controlled manner
    MAC_CONTEXT_T* curr = head;
    while (curr && curr->next) {
        MAC_CONTEXT_T* next = curr->next;
        free(curr);
        curr = next;
    }
    head = NULL;
}
