struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
};

void* allocate_and_populate_array(int n) {
    if (n <= 0) {
        return NULL;
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 255);

    struct NFAPI_CRC_INDICATION_PDU_T* array = new std::thread_local(struct NFAPI_CRC_INDICATION_PDU_T[n]);
    for (int i = 0; i < n; i++) {
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = dis(gen);
        array[i].CRC_INDICATION_REL8_TAG = i * 2;
        array[i].CRCFLAG = dis(gen) % 2;
    }

    int log_index = 0;
    std::FILE* log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
        return NULL;
    }
    for (int i = 0; i < n; i++) {
        fprintf(log_file, "Thread ID: %d, Timestamp: %ld, Allocation Status: Successful\n", std::this_thread::get_id(), time(NULL));
        log_index++;
    }
    fprintf(log_file, "Total Successful Allocations: %d, Total Failures: 0\n", n);
    fclose(log_file);

    return array;
}

int main() {
    int n = 10; // Number of structures to allocate
    void* result = allocate_and_populate_array(n);
    if (result == NULL) {
        printf("Failed to allocate memory.\n");
        return -1;
    }

    // Use the allocated memory...
    delete[] (struct NFAPI_CRC_INDICATION_PDU_T*)result;

    return 0;
}
