#include <time.h>

typedef struct node {
    int value;
    struct node* child;
} Node;

typedef struct graph {
    double* values;
    char** strings;
    Node** nodes;
    int num_nodes;
} Graph;

void init_graph(Graph** graphs, int max_trees) {
    *graphs = (Graph*)malloc(max_trees * sizeof(Graph));
    for (int i = 0; i < max_trees; i++) {
        (*graphs)[i].values = (double*)malloc(256 * sizeof(double));
        (*graphs)[i].strings = (char**)malloc(256 * sizeof(char*));
        (*graphs)[i].nodes = (Node**)malloc(256 * sizeof(Node*));
        (*graphs)[i].num_nodes = 0;
    }
}

void traverse_tree(Graph* graph, Node* node) {
    if (!node) return;

    // Set the value of each node to a random value within a specified range
    node->value = rand() % 100;

    // Traverse child nodes recursively
    traverse_tree(graph, node->child);
}

int main() {
    srand(time(NULL));

    int max_trees = 10000;
    Graph* graphs = NULL;
    init_graph(&graphs, max_trees);

    for (int i = 0; i < max_trees; i++) {
        // Initialize tree nodes
        Node* root = NULL;
        for (int j = 0; j < 256; j++) {
            Node* node = (Node*)malloc(sizeof(Node));
            node->value = rand() % 100;
            node->child = root;
            root = node;
        }

        // Traverse tree and set values
        traverse_tree(&graphs[i], root);
    }

    return 0;
}
