#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    Record** records;
    int count;
} DataStore;

DataStore* data_store_new(size_t initial_capacity) {
    DataStore* store = (DataStore*)malloc(sizeof(DataStore));
    store->capacity = initial_capacity;
    store->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    store->count = 0;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void data_store_free(DataStore* store) {
    for(int i = 0; i < store->capacity; i++) {
        free(store->records[i]);
    }
    free(store->records);
    free(store);
    pthread_mutex_destroy(&store->lock);
}

int data_store_insert(DataStore* store, int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;

    if(store->count >= store->capacity) {
        // Reallocate memory pool
        store->records = (Record**)realloc(store->records, store->capacity * 2);
        store->capacity *= 2;
    }

    store->records[store->count] = record;
    store->count++;

    pthread_mutex_lock(&store->lock);
    if(log_insert()) {
        // Insert successful
    } else {
        // Allocation failure
        return -1;
    }
    pthread_mutex_unlock(&store->lock);

    return 0;
}

long data_store_retrieve(DataStore* store, int key) {
    for(int i = 0; i < store->count; i++) {
        if(store->records[i]->key == key) {
            return store->records[i]->offset;
        }
    }

    pthread_mutex_lock(&store->lock);
    log_retrieve();
    pthread_mutex_unlock(&store->lock);

    return -1;
}

int data_store_delete(DataStore* store, int key) {
    for(int i = 0; i < store->count; i++) {
        if(store->records[i]->key == key) {
            free(store->records[i]);
            // Move records forward
            for(int j = i + 1; j < store->count; j++) {
                store->records[j - 1] = store->records[j];
            }
            store->count--;
            return 0;
        }
    }

    pthread_mutex_lock(&store->lock);
    log_delete();
    pthread_mutex_unlock(&store->lock);

    return -1;
}
