use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use reqwest::{blocking::get as http_get, ClientBuilder};
use serde_json::json;

struct LTEUEContext {
    ue_id: String,
    procedures: Vec<String>,
    qos_config: HashMap<String, String>,
}

type ContextMap = Arc<Mutex<HashMap<String, LTEUEContext>>>;

impl ContextMap {
    fn new() -> Self {
        Arc::new(Mutex::new(HashMap::new()))
    }

    fn add_context(&self, ue_id: &str) {
        let mut contexts = self.write_lock().unwrap();
        if !contexts.contains_key(ue_id) {
            contexts.insert(String::from(ue_id), LTEUEContext {
                ue_id: String::from(ue_id),
                procedures: vec![],
                qos_config: HashMap::new(),
            });
        }
    }

    fn update_context(&self, ue_id: &str, procedures: Vec<String>, qos_config: HashMap<String, String>) {
        let mut contexts = self.write_lock().unwrap();
        if let Some(mut context) = contexts.get_mut(ue_id) {
            context.procedures = procedures;
            context.qos_config = qos_config;
        }
    }

    fn get_context(&self, ue_id: &str) -> Option<&LTEUEContext> {
        let mut contexts = self.read_lock().unwrap();
        contexts.get(ue_id)
    }
}

struct HTTPClient {
    client: reqwest::blocking::Client,
}

impl HTTPClient {
    fn new() -> Self {
        let client = ClientBuilder::new()
            .dangerously_allow_unsafe_cell_static_method_calls(true)
            .build()?;
        HTTPClient { client }
    }

    fn get(&self, url: &str) -> reqwest::blocking::Response {
        http_get(url).await.unwrap()
    }
}

fn main() {
    let contexts = ContextMap::new();
    // Initialize the UE context map with some initial data...

    // Add a new context
    contexts.add_context("12345");

    // Update an existing context
    contexts.update_context("12345", vec!["proc1".to_string()], HashMap::from_iter([("rule1".to_string(), "qos_value".to_string())]));

    // Get the updated context
    if let Some(context) = contexts.get_context("12345") {
        println!("{:?}", context);
    }
}
