typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void insertSorted(NFAPI_CRC_INDINATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* newNode) {
    if (*head == NULL || (*head)->RNTI > newNode->RNTI) {
        *head = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head;
        NFAPI_CRC_INDICATION_PDU_T* previous = NULL;
        while (current != NULL && current->RNTI <= newNode->RNTI) {
            previous = current;
            current = current->next;
        }
        newNode->next = current;
        if (previous == NULL) {
            *head = newNode;
        } else {
            previous->next = newNode;
        }
    }
}

int isUniqueRNTI(NFAPI_CRC_INDICATION_PDU_T** head, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

int generateUniqueCRCFLAG(NFAPI_CRC_INDICATION_PDU_T* newNode, int maxAttempts) {
    srand(time(NULL));
    for (int i = 0; i < maxAttempts; i++) {
        newNode->CRCFLAG = rand();
        if (!isDuplicateRNTI(head, newNode->RNTI)) {
            return 1;
        }
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* createNode(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = rand();
    return newNode;
}

void printList(NFAPI_CRC_INDICATION_PDU_T* head) {
    while (head != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", head->RX_UE_INFORMATION_TAG, head->RNTI, head->CRC_INDICATION_REL8_TAG);
        head = head->next;
    }
}

int main() {
    int N = 10000; // Number of nodes in the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for (int i = 0; i < N; i++) {
        int RX_UE_INFORMATION_TAG = rand();
        int RNTI = rand();
        while (!isUniqueRNTI(&head, RNTI)) {
            // Generate a new unique RNTI
            RNTI = rand();
        }
        NFAPI_CRC_INDICATION_PDU_T* newNode = createNode(RX_UE_INFORMATION_TAG, RNTI);
        if (generateUniqueCRCFLAG(newNode, 1000) == 0) {
            printf("Failed to generate unique CRCFLAG for node %d.\n", i);
            exit(EXIT_FAILURE);
        }
        insertSorted(&head, newNode);
    }
    printList(head);
    return 0;
}
