#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include "nfaapi_crc_indication_pdu_t.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    int index; // used for least recently used (LRU) algorithm
} list_node;

// Function to create a new node with an allocated pdu structure
list_node* create_node() {
    list_node* node = (list_node*)malloc(sizeof(list_node));
    node->pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return node;
}

// Function to free a node and its pdu structure
void free_node(list_node* node) {
    if(node != NULL) {
        free(node->pdu);
        free(node);
    }
}

// Function to remove the least recently used (LRU) node from the list
list_node* lru_remove(list_node** head, int* size) {
    list_node* current = *head;
    list_node* previous = NULL;
    while(current != NULL && current->index > 0) {
        previous = current;
        current = current->next;
    }
    if(previous != NULL) {
        previous->next = current->next;
        if(*size > 1) {
            *size -= 1;
        } else {
            *head = current->next;
            if(*head == NULL) {
                *head = current;
            }
        }
        return current;
    }
    return NULL;
}

// Function to add a new node to the list
void add_node(list_node** head, int* size, NFAPI_CRC_INDICATION_PDU_T pdu) {
    list_node* node = create_node();
    node->pdu = pdu;
    if(*head == NULL || (*size <= 0)) {
        *head = node;
        node->next = NULL;
        *size = 1;
    } else {
        list_node* current = *head;
        while(current != NULL) {
            previous = current;
            current = current->next;
        }
        previous->next = node;
        node->index = previous->index + 1;
        *size += 1;
    }
}

// Function to check if the RNTI is unique within the list
int validate_rnti(list_node* head, int size) {
    int rnti[10];
    int i = 0;
    for(i=0; i<size; i++) {
        list_node* current = head;
        while(current != NULL) {
            if(current->pdu.RNTI < 10) {
                rnti[current->pdu.RNTI]++;
            }
            current = current->next;
        }
    }
    for(i=0; i<10; i++) {
        if(rnti[i] > 1) {
            return 0; // RNTI is not unique
        }
    }
    return 1; // RNTI is unique
}

// Function to manage the dynamically resizing linked list of NFAPI_CRC_INDICATION_PDU_T structures
void nfaapi_crc_indication_pdu_list_manager(int max_list_size) {
    int list_size = 0;
    list_node* head = NULL;
    FILE *log_file = fopen("/var/log/nfaapi_crc_indication_pdu_list.log", "w+");
    while(1) {
        NFAPI_CRC_INDICATION_PDU_T pdu = /* get pdu from external source */;
        if(list_size >= max_list_size) {
            list_node* removed_node = lru_remove(&head, &list_size);
            if(removed_node != NULL) {
                free_node(removed_node);
                fprintf(log_file, "Removed least recently used node with RNTI %d\n", removed_node->pdu.RNTI);
            } else {
                // Handle the case where the list is full and there are no nodes to remove
                // For example, you could log a warning message and return
                fprintf(log_file, "List is full. No nodes to remove.\n");
                fclose(log_file);
                return;
            }
        }
        if(!validate_rnti(head, list_size)) {
            // Handle the case where the RNTI is not unique
            // For example, you could log a warning message and return
            fprintf(log_file, "RNTI %d is not unique.\n", pdu.RNTI);
            fclose(log_file);
            return;
        }
        add_node(&head, &list_size, pdu);
    }
}

int main() {
    nfaapi_crc_indication_pdu_list_manager(MAX_LIST_SIZE); // replace with your desired maximum list size
    return 0;
}
