<?php
namespace RandomPasswordLibrary;

use League\Flysystem\FilesystemInterface;
use Ramsey\Uuid\UuidFactory;

class RandomPasswordLibrary {
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890';
    private $passwordHashingAlgorithms = ['bcrypt', 'argon2i', 'pbkdf2'];
    private $externalServiceUrl = 'https://unique-identifier-service.com/generate';
    private $fileSystem;
    private $uuidFactory;

    public function __construct(FilesystemInterface $fileSystem, UuidFactory $uuidFactory) {
        $this->fileSystem = $fileSystem;
        $this->uuidFactory = $uuidFactory;
    }

    public function generateRandomString(int $length): string {
        return str_shuffle(str_repeat($this->characterSet, ceil($length / strlen($this->characterSet))))->substr(0, $length);
    }

    public function hashPassword(string $password, string $algorithm = 'bcrypt'): string {
        switch ($algorithm) {
            case 'bcrypt':
                return password_hash($password, PASSWORD_BCRYPT);
            case 'argon2i':
                return password_hash($password, PASSWORD_ARGON2I);
            case 'pbkdf2':
                return password_hash($password, PASSWORD_PBKDF2);
            default:
                throw new \InvalidArgumentException('Unsupported hashing algorithm');
        }
    }

    public function generateUniqueId(): string {
        try {
            $response = json_decode(file_get_contents($this->externalServiceUrl), true);
            if (isset($response['id'])) {
                return $response['id'];
            } else {
                return $this->uuidFactory->uuid4();
            }
        } catch (\Exception $e) {
            // Handle external service unavailability
            return $this->uuidFactory->uuid4();
        }
    }
}
