typedef struct {
    char mac[17];
    int speed;
} MAC_CONTEXT_T;

typedef struct {
    int config_id;
    int max_speed;
} MAC_CONFIG_T;

typedef struct {
    int rx_packets;
    int tx_packets;
    double latency;
} PHY_STATS_T;

// Dynamic list of MAC contexts
typedef struct {
    MAC_CONTEXT_T* contexts;
    int size;
    pthread_mutex_t lock;
} MAC_CTX_LIST_T;

// Initialize and configure the network interface
void init_network_interface(int num_ctx, int max_speed) {
    // Allocate memory for the dynamic list
    MAC_CTX_LIST_T* ctx_list = (MAC_CTX_LIST_T*) malloc(sizeof(MAC_CTX_LIST_T));
    ctx_list->size = 0;
    pthread_mutex_init(&ctx_list->lock, NULL);

    // Initialize individual MAC contexts
    for (int i = 0; i < num_ctx; i++) {
        MAC_CONTEXT_T* ctx = (MAC_CONTEXT_T*) malloc(sizeof(MAC_CONTEXT_T));
        ctx->mac[6] = '\0';  // Set default MAC address
        ctx->speed = max_speed;
        // Add context to the dynamic list
        pthread_mutex_lock(&ctx_list->lock);
        ctx_list->contexts = realloc(ctx_list->contexts, (ctx_list->size + 1) * sizeof(MAC_CONTEXT_T*));
        ctx_list->contexts[ctx_list->size++] = ctx;
        pthread_mutex_unlock(&ctx_list->lock);
    }

    // Initialize PHY statistics
    for (int i = 0; i < num_ctx; i++) {
        MAC_CTX_LIST_T* ctx = &ctx_list;
        // Initialize RX and TX packet counts
        ctx->contexts[i]->rx_packets = 0;
        ctx->contexts[i]->tx_packets = 0;
        // Initialize latency statistics
        ctx->contexts[i]->latency = 0.0;
    }

    // Set up logging for debugging and performance analysis
    printf("Network interface initialized with %d contexts.\n", num_ctx);
}

// Add a new MAC context to the list
void add_mac_context(MAC_CTX_LIST_T* ctx_list, MAC_CONTEXT_T* new_ctx) {
    pthread_mutex_lock(&ctx_list->lock);
    ctx_list->contexts = realloc(ctx_list->contexts, (ctx_list->size + 1) * sizeof(MAC_CONTEXT_T*));
    ctx_list->contexts[ctx_list->size++] = new_ctx;
    pthread_mutex_unlock(&ctx_list->lock);
}

// Remove a MAC context from the list
void remove_mac_context(MAC_CTX_LIST_T* ctx_list, int index) {
    pthread_mutex_lock(&ctx_list->lock);
    if (index >= 0 && index < ctx_list->size) {
        // Free the removed context and update the dynamic list
        free(ctx_list->contexts[index]);
        memmove(ctx_list->contexts + index, ctx_list->contexts + index + 1, (ctx_list->size - index - 1) * sizeof(MAC_CONTEXT_T*));
        ctx_list->size--;
    }
    pthread_mutex_unlock(&ctx_list->lock);
}

// Print network interface statistics
void print_stats(MAC_CTX_LIST_T* ctx_list) {
    for (int i = 0; i < ctx_list->size; i++) {
        printf("Context %d: RX packets=%d, TX packets=%d, Latency=%.2f\n", i, ctx_list->contexts[i]->rx_packets,
               ctx_list->contexts[i]->tx_packets, ctx_list->contexts[i]->latency);
    }
}

// Define a function to handle concurrent access and deallocation
void* thread_func(void* arg) {
    MAC_CTX_LIST_T* ctx_list = (MAC_CTX_LIST_T*) arg;
    // Simulate concurrency by accessing different contexts
    for (int i = 0; i < ctx_list->size; i++) {
        MAC_CONTEXT_T* ctx = ctx_list->contexts[i];
        // Perform some operation on the context
        printf("Thread %p accessed context %d\n", pthread_self(), i);
        // Simulate deallocation of the context
        remove_mac_context(ctx_list, i);
    }
    return NULL;
}

int main() {
    int num_ctx = 3;  // Number of MAC contexts to initialize
    int max_speed = 1000;  // Maximum speed for each context

    init_network_interface(num_ctx, max_speed);

    // Create and start a few threads to test concurrency
    pthread_t threads[2];
    for (int i = 0; i < 2; i++) {
        pthread_create(&threads[i], NULL, thread_func, &ctx_list);
    }

    // Simulate some network activity and print statistics
    for (int i = 0; i < num_ctx; i++) {
        ctx_list->contexts[i]->rx_packets += 100;
        ctx_list->contexts[i]->tx_packets += 50;
    }
    print_stats(&ctx_list);

    return 0;
}

