Record* allocate_records(int size, int min_key, int max_key, long min_offset, long max_offset) {
    Record* records = NULL;
    Record** ptr_array = NULL;

    // Handle edge cases
    if (size <= 0) return records;

    // Initialize array of pointers to record structures
    ptr_array = malloc(sizeof(Record*) * size);
    if (!ptr_array) return records; // Memory allocation failed

    // Allocate memory for the array of record structures
    records = malloc(sizeof(Record) * size);
    if (!records) {
        free(ptr_array); // Free partially allocated array
        return NULL;
    }

    int local_keys = 0;
    long local_offsets = 0;
    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < size; i++) {
        Record* record = &records[i];

        // Generate a unique key within the specified bounds
        do {
            int key = min_key + rand() % ((max_key - min_key) + 1);
            if (!local_keys || (local_keys <= 0)) {
                local_keys++;
                record->key = key;
                break;
            }

            // Check for potential conflicts with existing keys
            Record* current_record;
            for (int j = 0; j < i; j++) {
                current_record = &records[j];
                if (current_record->key == key) {
                    // Key conflict detected, try again
                    break;
                }
            }
        } while (1);

        // Generate a unique offset within the specified bounds
        do {
            long offset = min_offset + rand() % ((max_offset - min_offset) + 1);
            if (!local_offsets || (local_offsets <= 0)) {
                local_offsets++;
                record->offset = offset;
                break;
            }

            // Check for potential conflicts with existing offsets
            Record* current_record;
            for (int j = 0; j < i; j++) {
                current_record = &records[j];
                if (current_record->offset == offset) {
                    // Offset conflict detected, try again
                    break;
                }
            }
        } while (1);
    }

    free(ptr_array); // Free partially allocated array

    return records;
}
