typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct list_node* next;
};

typedef struct {
    pthread_mutex_t lock;
    struct list_node* head;
    struct list_node* tail;
    int size;
} NF_API_List;

void init_list(NF_API_List* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}

int add_to_list(NF_API_List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);
    struct list_node* new_node = (struct list_node*)malloc(sizeof(struct list_node));
    new_node->data = data;
    new_node->next = NULL;

    if (list->size == 0) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_from_list(NF_API_List* list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);

    struct list_node* current = list->head;
    struct list_node* previous = NULL;

    while (current != NULL) {
        if (current->data->rnti == rnti) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }

            if (list->tail == current) {
                list->tail = previous;
            }

            free(current);
            list->size--;
            break;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int update_crcflag(NF_API_List* list, int index) {
    pthread_mutex_lock(&list->lock);

    struct list_node* current = list->head;

    for (int i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    current->data->crcflag = /* update crcflag */;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int serialize_list(NF_API_List* list, char* buffer) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen("nfapi_crc_indication_pdu_t", "wb");
    if (file == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    fwrite(&list->size, sizeof(int), 1, file);

    struct list_node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data->rx_ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&current->data->rnti, sizeof(RNTI), 1, file);
        fwrite(&current->data->crc_indication_rel8, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        fwrite(&current->data->crcflag, sizeof(int), 1, file);

        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int deserialize_list(NF_API_List* list) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen("nfapi_crc_indication_pdu_t", "rb");
    if (file == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    int size;
    fread(&size, sizeof(int), 1, file);

    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        fread(&data->rx_ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fread(&data->rnti, sizeof(RNTI), 1, file);
        fread(&data->crc_indication_rel8, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        fread(&data->crcflag, sizeof(int), 1, file);

        add_to_list(list, data);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int main() {
    NF_API_List list;
    init_list(&list);

    // Add NFAPI_CRC_INDICATION_PDU_T structures
    // Update CRCFLAG based on index

    // Serialize the list
    char buffer[1024];
    serialize_list(&list, buffer);

    // Deserialize the list and verify it matches the original state
    deserialize_list(&list);
}
