public class DatabaseExecutor
{
    private readonly object _lock = new object();

    public IDataReader ExecuteCommand(SqlConnection connection, string commandText, SqlParameter[] parameters)
    {
        using (SqlCommand command = new SqlCommand(commandText, connection))
        {
            foreach (SqlParameter parameter in parameters)
            {
                command.Parameters.Add(parameter);
            }

            Stopwatch stopwatch = Stopwatch.StartNew();
            IDataReader reader;
            try
            {
                reader = command.ExecuteReader();
                stopwatch.Stop();
                LogCommandExecution(commandText, stopwatch.Elapsed);
            }
            catch (Exception ex)
            {
                LogError("Failed to execute SQL command: " + commandText, ex);
                throw;
            }

            return reader;
        }
    }

    private void LogCommandExecution(string commandText, TimeSpan executionTime)
    {
        // Implement logging mechanism here
        Console.WriteLine($"Executed SQL command '{commandText}' in {executionTime.TotalMilliseconds} ms");
    }

    private void LogError(string message, Exception exception)
    {
        // Implement error logging mechanism here
        Console.WriteLine($"Error: {message}");
        Console.WriteLine(exception.Message);
    }
}
