#include <forward_list>
#include <string>

void insertStringAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& newStr, bool (*validate)(const std::string&)) {
    auto it = list.begin();
    bool found = false;

    for (; it != list.end(); ++it) {
        if (*it == target) {
            found = true;
            break;
        }
    }

    if (found) {
        list.insert_after(it, newStr);
    } else {
        list.append(newStr);
    }
}
