#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_COLLECTION_SIZE 1000
#define LRU_THRESHOLD 5

typedef struct {
    int RNTI;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Circular Buffer for storing PDUs
struct cbuf {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t size;
    size_t front, rear;
};

// Doubly Linked List for storing PDUs (alternative)
struct dllnode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct dllnode *prev, *next;
};
typedef struct dllnode DLLNODE;

// Logging function
void log_event(const char *event) {
    printf("Event: %s\n", event);
}

// Circular Buffer functions
struct cbuf *create_cbuf(size_t capacity) {
    struct cbuf *cbuf = malloc(sizeof(struct cbuf));
    cbuf->pdus = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cbuf->size = 0;
    cbuf->front = cbuf->rear = 0;
    return cbuf;
}

void add_to_cbuf(struct cbuf *cbuf, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (cbuf->size >= MAX_COLLECTION_SIZE) {
        // LRU eviction policy
        struct cbuf *new_cbuf = create_cbuf(cbuf->size - 1);
        for (int i = 0; i < cbuf->size - 1; i++) {
            new_cbuf->pdus[i] = cbuf->pdus[(cbuf->front + i) % cbuf->size];
        }
        cbuf->size--;
        free(cbuf->pdus);
        *cbuf = *new_cbuf;
    }
    cbuf->pdus[cbuf->rear++ % cbuf->size] = pdu;
}

NFAPI_CRC_INDICATION_PDU_T remove_from_cbuf(struct cbuf *cbuf) {
    if (cbuf->size == 0)
        return (NFAPI_CRC_INDICATION_PDU_T){};
    NFAPI_CRC_INDICATION_PDU_T pdu = cbuf->pdus[cbuf->front++ % cbuf->size];
    cbuf->size--;
    return pdu;
}

// Doubly Linked List functions
DLLNODE *create_dllnode(NFAPI_CRC_INDICATION_PDU_T pdu) {
    DLLNODE *node = malloc(sizeof(DLLNODE));
    node->pdu = pdu;
    node->prev = node->next = NULL;
    return node;
}

void add_to_dll(DLLNODE **head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    DLLNODE *new_node = create_dllnode(pdu);
    if (*head == NULL)
        *head = new_node;
    else {
        (*head)->prev = new_node;
        new_node->next = *head;
        *head = new_node;
    }
}

DLLNODE *remove_from_dll(DLLNODE **head) {
    DLLNODE *node = *head;
    if (node == NULL)
        return node;
    *head = node->next;
    node->prev->next = node->next;
    node->next->prev = node->prev;
    free(node);
    return node;
}

// Garbage Collection mechanism
void gc(struct cbuf *cbuf) {
    if (cbuf->size > LRU_THRESHOLD) {
        for (int i = 0; i < cbuf->size - LRU_THRESHOLD; i++) {
            remove_from_cbuf(cbuf);
        }
    }
}

// Main function
int main() {
    struct cbuf *cbuf = create_cbuf(MAX_COLLECTION_SIZE);
    DLLNODE *dll_head = NULL;

    // Add PDUs to the collection
    for (int i = 0; i < 1000; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {i, rand() % 2, time(NULL)};
        add_to_cbuf(cbuf, pdu);
        log_event("PDU added");

        // Critical PDUs have priority
        if (pdu.RNTI > 500) {
            // Log critical PDUs separately
            log_event("Critical PDU detected");

            // Implement LRU eviction policy for critical PDUs
            while (cbuf->size > MAX_COLLECTION_SIZE - 10 && cbuf->front != cbuf->rear) {
                remove_from_cbuf(cbuf);
                log_event("LRU evicted a non-critical PDU");
            }
        }
    }

    // Test LRU eviction policy
    for (int i = 0; i < 100; i++) {
        if (cbuf->size >= MAX_COLLECTION_SIZE) {
            gc(cbuf);
        }
    }

    // Remove PDUs from the collection
    while (cbuf->size > 0) {
        NFAPI_CRC_INDICATION_PDU_T pdu = remove_from_cbuf(cbuf);
        log_event("PDU removed");

        // Test DLL
        add_to_dll(&dll_head, pdu);
        DLLNODE *node = dll_head;
        while (node != NULL) {
            node = node->next;
        }
    }

    free(cbuf->pdus);
    free(cbuf);

    return 0;
}

