    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL; // Handle memory allocation failure
    node->data = data;
    node->next = NULL;
    return node;
}

void free_nodes(Node** head_ref, int threshold) {
    Node* prev = NULL;
    Node* curr = *head_ref;
    while (curr && (prev == NULL || curr != prev)) {
        if (rand() % 100 < threshold) { // Automatic garbage collection threshold
            Node* temp = curr;
            curr = curr->next;
            free(temp);
        } else {
            prev = curr;
            curr = curr->next;
        }
    }
    *head_ref = NULL; // Reset head to null after freeing nodes
}

void delete_nodes(Node** head_ref) {
    Node* prev = NULL;
    Node* curr = *head_ref;
    while (curr && (prev == NULL || curr != prev)) {
        prev = curr;
        curr = curr->next;
        free(prev);
    }
    *head_ref = NULL; // Reset head to null after freeing nodes
}

Node* generate_list(int n, int threshold) {
    Node* head = NULL;
    srand(time(NULL)); // Set random seed
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 1000;
        data.RNTI = rand() % 10000;
