// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new linked list node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*) malloc(sizeof(Node));
    if (!node) return NULL; // handle allocation failure
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to add a new element to the linked list
int add_element(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = create_node(data);
    if (!node) return -1; // handle allocation failure
    if (*head == NULL || data.RX_UE_INFORMATION_TAG < 0x1000 || data.RX_UE_INFORMATION_TAG > 0xFFFF ||
        data.RNTI < 0 || data.RNTI > 511) {
        free(node);
        return -2; // invalid RX_UE_INFORMATION_TAG or RNTI
