using UnityEngine;
using System;
using System.IO;

public class RandomValueGenerator
{
    private int minIntValue;
    private int maxIntValue;
    private float minFloatValue;
    private float maxFloatValue;

    public RandomValueGenerator(int minValue, int maxValue, float minFloatValue = 0f, float maxFloatValue = 1f)
    {
        this.minIntValue = minValue;
        this.maxIntValue = maxValue;
        this.minFloatValue = minFloatValue;
        this.maxFloatValue = maxFloatValue;
    }

    public int GenerateRandomInteger()
    {
        return UnityEngine.Random.Range(minIntValue, maxIntValue + 1);
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minFloatValue, maxFloatValue + 1);
    }

    public struct NASPDU
    {
        public string RX_UE_INFORMATION_TAG;
        public int RNTI;
        public bool CRCFLAG;
        public string CRC_INDICATION_REL8_TAG;
    }

    public NASPDU[] GeneratePDUs(int count)
    {
        NASPDU[] pdus = new NASPDU[count];
        for (int i = 0; i < count; i++)
        {
            NASPDU pdu = default(NASPDU);
            pdu.RX_UE_INFORMATION_TAG = Guid.NewGuid().ToString();
            pdu.RNTI = GenerateRandomInteger();
            pdu.CRCFLAG = UnityEngine.Random.value > 0.5f;
            pdu.CRC_INDICATION_REL8_TAG = Guid.NewGuid().ToString();
            pdus[i] = pdu;
        }
        return pdus;
    }

    public void SerializePDUsToFile(NASPDU[] pdus, string filePath)
    {
        using (FileStream fileStream = File.Create(filePath))
        {
            BinaryWriter writer = new BinaryWriter(fileStream);
            foreach (var pdu in pdus)
            {
                writer.Write(pdu.RX_UE_INFORMATION_TAG.Length);
                writer.Write(pdu.RX_UE_INFORMATION_TAG);
                writer.Write(pdu.RNTI);
                writer.Write(pdu.CRCFLAG);
                writer.Write(pdu.CRC_INDICATION_REL8_TAG.Length);
                writer.Write(pdu.CRC_INDICATION_REL8_TAG);
            }
        }
    }

    public override string ToString()
    {
        return $"Random Value Generator: Integer range ({minIntValue} to {maxIntValue}) and Float range ({minFloatValue} to {maxFloatValue}).";
    }
}
