#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_N 1000
#define SEED 42

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu = NULL;
int n = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *generate_crc(void *args) {
    int i, seed = *(int *) args;
    pthread_mutex_lock(&mutex);
    for (i = 0; i < n; i++) {
        nfapi_crc_indication_pdu[i].CRCFLAG = rand_r(&seed) % 2;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void manage_dynamic_array(int N, int seed) {
    if (N > MAX_N) {
        printf("Error: N exceeds maximum allowed size\n");
        return;
    }

    nfapi_crc_indication_pdu = realloc(nfapi_crc_indication_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!nfapi_crc_indication_pdu) {
        printf("Error: Memory allocation failure\n");
        return;
    }

    pthread_t threads[N];
    int i;
    for (i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, generate_crc, &seed);
    }
    for (i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    free(nfapi_crc_indication_pdu);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <N>\n", argv[0]);
        return 1;
    }
    int N = atoi(argv[1]);
    srand(SEED);
    manage_dynamic_array(N, SEED);
    return 0;
}
