#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

char* process_path(const char* path, size_t max_length, bool append_separator) {
    if (path == NULL || strlen(path) > max_length) return NULL;

    // Remove trailing slashes
    size_t len = strlen(path);
    if (len > 1 && path[len - 1] == '/') {
        --len;
        path[len - 1] = '\0';
    }

    char* new_path = malloc(max_length + 1);

    size_t pos = 0;
    bool need_separator = false;

    for (size_t i = 0; i < len; ++i) {
        if (path[i] == '.') {
            if (pos > 0 && !need_separator) {
                // Add dot as is
                new_path[pos++] = '.';
                continue;
            }
            need_separator = false;
        } else if (path[i] == '/') {
            if (!append_separator || need_separator) continue;
            need_separator = true;
        } else {
            need_separator = false;
        }

        // Copy character
        new_path[pos++] = path[i];
    }

    // Add directory separator if needed
    if (need_separator && append_separator) {
        new_path[pos++] = '/';
    }

    new_path[pos] = '\0';

    return new_path;
}
