#define MAX_ALLOC 1000 // Maximum number of structures to allocate
#define LOG_FILE "memory.log" // File for logging memory allocation and deallocation events

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint16_t crcflag; // Randomly set using a seed provided by the caller
} NFAPI_CRC_INDICATION_PDU_T;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int allocate_arrays(int num_structures, NFAPI_CRC_INDICATION_PDU_T** structures) {
    if (num_structures <= 0 || num_structures > MAX_ALLOC) {
        fprintf(stderr, "Error: Invalid number of structures to allocate.\n");
        return -1;
    }

    int i;
    *structures = my_malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*structures) {
        return -1;
    }

    srand(time(NULL)); // Initialize random seed
    for (i = 0; i < num_structures; i++) {
