#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_CONFIG_SIZE 1024 * 1024
#define DEFAULT_PARSE_OPTIONS FAST_PARSE

typedef enum {
    FAST_PARSE,
    SAFE_PARSE
} parse_options;

int load_config(const char* path, uint32_t max_size, parse_options options) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return -1;
    }

    struct stat sb;
    fstat(fd, &sb);

    if (sb.st_size > max_size) {
        fclose(stdout);
        fprintf(stderr, "File size exceeds maximum allowed size\n");
        close(fd);
        return -2;
    }

    void* config_data = malloc(sb.st_size);
    if (!config_data) {
        perror("Memory allocation failed");
        close(fd);
        return -3;
    }

    ssize_t read_bytes = pread(fd, config_data, sb.st_size, 0);
    if (read_bytes != sb.st_size) {
        perror("Error reading file");
        free(config_data);
        close(fd);
        return -4;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_thread_np() || pthread_setcancelstate(CANCELED_THREAD_CANCELLED, NULL);

    uint32_t entries = 0;

    if (options == DEFAULT_PARSE_OPTIONS) {
        // Fast parsing code
        for (int i = 0; i < sb.st_size / sizeof(uint16_t); i++) {
            uint16_t* entry_data = (uint16_t*)(((char*)config_data) + i * sizeof(uint16_t));
            entries += *entry_data;
        }
    } else if (options == SAFE_PARSE) {
        // Safe parsing code
        for (int i = 0; i < sb.st_size / sizeof(char); i++) {
            char* entry_string = ((char*)config_data) + i;
            entries += strlen(entry_string);
        }
    }

    pthread_mutex_unlock(&lock);

    free(config_data);
    close(fd);

    return entries;
}

