    // Dynamically allocate memory for the cryptographic context
    EVP_CIPHER_CTX* ctx = (EVP_CIPHER_CTX*)malloc(sizeof(EVP_CIPHER_CTX));

    // Initialize the cryptographic context using AES-GCM mode
