        unsigned long average_timestamp = (unsigned long)total_timestamps / N;
        timestamps[i] = average_timestamp;

        double random_double = ((double)rand()) / RAND_MAX;
        doubles[i] = random_double;

        datapoints[i].measurement = (float)(average_timestamp * random_double);
        datapoints[i].status = 'A';

        // Initialize the cryptographic initialization vector
