#define MAX_NFAPI_CRC_INDICATION_PDU_T 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[64];
    int CRCFLAG;
