int pool_size = 1024;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pool[MAX_NFAPI_CRC_INDICATION_PDU_T];

void* alloc_from_pool(size_t size) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (pool[i] == NULL) {
            void* ptr = malloc(size);
            pool[i] = ptr;
            return ptr;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void free_to_pool(void* ptr) {
    for (int i = 0; i < pool_size; i++) {
        if (pool[i] == ptr) {
            free(ptr);
            pool[i] = NULL;
            break;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication_pdu_t(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)alloc_from_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) return NULL;
    pdu->RX_UE_INFORMATION_TAG = 0;
    pdu->RNTI = RNTI;
    strcpy(pdu->CRC_INDICATION_REL8_TAG, "crc_indication_rel8_tag");
    pdu->CRCFLAG = rand() % 2;
    return pdu;
}

int get_dns_resolution(char* hostname, u_char** ip_addr) {
    // DNS resolution implementation
    int sockfd, ret;
    struct sockaddr_in servaddr;
    struct hostent *he;
    char buff[256];
    socklen_t slen = sizeof(servaddr);
    pthread_mutex_lock(&pool_lock);
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Error in creating socket\n");
        return -1;
    }
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(53);
    he = gethostbyname(hostname);
    if (!he) {
        printf("%s", "Invalid hostname");
        return -1;
    }
    memcpy(&servaddr.sin_addr, he->h_addr, he->h_length);
    ret = connect(sockfd, (struct sockaddr*)&servaddr, slen);
    if (ret < 0) {
        printf("Error in connecting to DNS\n");
        return -1;
    }
    recv(sockfd, buff, 256, 0);
    pthread_mutex_unlock(&pool_lock);
    *ip_addr = (u_char*)malloc(4);
    inet_ntop(AF_INET, &servaddr.sin_addr, *ip_addr, 4);
    return 0;
}

int main() {
    // Initialize pool
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU_T; i++) {
        pool[i] = NULL;
    }
    // Create and populate NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < 10; i++) {
        int RNTI = rand() % 65536;
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_nfapi_crc_indication_pdu_t(RNTI);
        if (pdu == NULL) printf("Error in allocating memory\n");
    }
    // Perform DNS resolution
    char hostname[] = "example.com";
    u_char* ip_addr;
    get_dns_resolution(hostname, &ip_addr);
    return 0;
}
