#define MAC_CONTEXT_T struct {
    uint32_t mac_id;
    int ref_count;
    time_t last_usage;
};

typedef struct {
    MAC_CONTEXT_T* arr;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} mac_array_t;

mac_array_t* mac_array_init(size_t initial_capacity) {
    mac_array_t* array = malloc(sizeof(mac_array_t));
    if (!array) return NULL;

    array->arr = malloc(initial_capacity * sizeof(MAC_CONTEXT_T));
    if (!array->arr) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond, NULL);

    return array;
}

void mac_array_free(mac_array_t* array) {
    if (!array) return;

    free(array->arr);
    free(array);
}

int mac_array_grow(mac_array_t* array) {
    size_t new_capacity = array->capacity * 2 + 1;
    MAC_CONTEXT_T* new_arr = realloc(array->arr, new_capacity * sizeof(MAC_CONTEXT_T));
    if (!new_arr) return -1;

    array->arr = new_arr;
    array->capacity = new_capacity;

    return 0;
}

int mac_array_add(mac_array_t* array, MAC_CONTEXT_T ctx) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        if (mac_array_grow(array)) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    array->arr[array->size] = ctx;
    array->size++;

    pthread_cond_signal(&array->cond);

    pthread_mutex_unlock(&array->lock);

    return 0;
}

int mac_array_remove(mac_array_t* array, uint32_t mac_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; i++) {
        if (array->arr[i].mac_id == mac_id) {
            if (--array->arr[i].ref_count <= 0) {
                memmove(&array->arr[i], &array->arr[i + 1], sizeof(MAC_CONTEXT_T) * (array->size - i));
                array->size--;
            }
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);

    return 0;
}

void mac_array_clean_up(mac_array_t* array) {
    for (size_t i = 0; i < array->size; i++) {
        if (--array->arr[i].ref_count <= 0) {
            memmove(&array->arr[i], &array->arr[i + 1], sizeof(MAC_CONTEXT_T) * (array->size - i));
            array->size--;
        }
    }
}

void mac_array_monitor(mac_array_t* array, int verbosity) {
    // implement memory usage monitoring and logging
