    return -1; // Element not found
}

// Function to verify the integrity of CRC flags
int nfapi_crc_indication_pdu_list_verify(NFAPI_CRC_INDICATION_PDU_T_List* list) {
    for (int i = 0; i < list->size; ++i) {
        int crcflag_sum = 0;
        for (int j = 0; j < i; ++j) {
            crcflag_sum += list->elements[j].CRCFLAG;
        }
        if (crcflag_sum != list->elements[i].CRCFLAG) return -1; // Error
    }

    return 0; // Success
}

// Function to periodically flush outdated entries from the list
void nfapi_crc_indication_pdu_list_flush(NFAPI_CRC_INDICATION_PDU_T_List* list, int age_threshold) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; ++i) {
        if ((time(NULL) - list->elements[i].valid_RX_UE_INFORMATION_TAG) > age_threshold) {
            memmove(&list->elements[i], &list->elements[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to prioritize certain UE instances
void nfapi_crc_indication_pdu_list_prioritize(NFAPI_CRC_INDICATION_PDU_T_List* list, int RNTI, int priority) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; ++i) {
        if (list->elements[i].RNTI == RNTI) {
            list->elements[i].priority = priority;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to query the current state of the list
int nfapi_crc_indication_pdu_list_query(NFAPI_CRC_INDICATION_PDU_T_List* list, int* active_ue_count) {
