#include <stdio.h>
#include <stdlib.h>

// Define LTE_PHY_MEASUREMENTS structure
typedef struct {
    int valid;
    int channelBandwidth;
    int rbStartIndex;
} LTE_PHY_MEASUREMENT;

// Define node for linked list
typedef struct Node {
    LTE_PHY_MEASUREMENT measurement;
    struct Node* next;
} Node;

// Function to manage dynamically allocated linked list of LTE_PHY_MEASUREMENT structures
void lte_phy_measurements_list(Node** head, int (*post_processing_filter)(LTE_PHY_MEASUREMENT*)) {
    // Allocate memory for new node
    Node* newNode = (Node*) malloc(sizeof(Node));

    // Check if memory allocation failed
    if (!newNode) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize new node fields
    newNode->measurement.valid = 0; // Set default valid value

    // Add new node to the list (insertion operation)
    Node* current = *head;
    while (current && current->next) {
        current = current->next;
    }
    if (!current) {
        *head = newNode;
    } else {
        current->next = newNode;
    }

    // Iterate over the list to apply post-processing filters
    Node* temp = *head;
    while (temp) {
        LTE_PHY_MEASUREMENT* measurement = &temp->measurement;

        // Apply post-processing filter on signal quality metrics
        int filteredMeasurement = (*post_processing_filter)(*measurement);

        // Update node with filtered measurement
        measurement->valid = 1; // Set valid flag for filtered measurement

        temp = temp->next;
    }
}

// Function to resize the list dynamically if it exceeds its initial capacity
void lte_phy_measurements_list_resize(Node** head, int newCapacity) {
    Node* current = *head;
    Node* prev = NULL;

    // Traverse the list and update node pointers for resizing
    while (current && current->next) {
        prev = current;
        current = current->next;
    }

    if (prev) {
        prev->next = NULL; // Update last node's next pointer to NULL
    } else {
        *head = NULL; // Reset head to NULL for empty list resizing
    }

    Node** newHead = (Node**) realloc(*head, sizeof(Node*) * newCapacity);

    if (!newHead) {
        printf("Memory allocation failed during resizing\n");
        return;
    }

    *head = newHead;
}

// Function to safely deallocate memory for the linked list
void lte_phy_measurements_list_free(Node** head) {
    Node* current = *head;
    Node* next = NULL;

    // Traverse the list and free nodes in reverse order
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL; // Reset head to NULL after deallocation
}

int main() {
    Node* head = NULL; // Initialize linked list head

    // Add nodes to the list and apply post-processing filters
    for (int i = 0; i < 10000; i++) {
        lte_phy_measurements_list(&head, post_processing_filter); // Call function with filter
    }

    // Dynamically resize the list if it exceeds its initial capacity
    int newCapacity = 20000;
    lte_phy_measurements_list_resize(&head, newCapacity);

    // Free memory for the linked list safely
    lte_phy_measurements_list_free(&head);

    return 0;
}
