typedef struct {
    RX_RXINFO rx_info;
    PHY_RX_PKT pkt;
} LTEPHY_RxPkt;

typedef struct {
    int size;
    int capacity;
    LTEPHY_RxPkt* packets;
} PacketManager;

PacketManager* packet_manager_create(int initial_capacity) {
    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->packets = (LTEPHY_RxPkt*)calloc(initial_capacity, sizeof(LTEPHY_RxPkt));
    return manager;
}

void packet_manager_free(PacketManager* manager) {
    free(manager->packets);
    free(manager);
}

int packet_manager_add_packet(PacketManager* manager, LTEPHY_RxPkt new_packet) {
    if (manager->size == manager->capacity) {
        int new_capacity = manager->capacity * 2;
        PacketManager* new_manager = packet_manager_create(new_capacity);
        for (int i = 0; i < manager->size; i++) {
            new_manager->packets[i] = manager->packets[i];
        }
        free(manager->packets);
        free(manager);
        manager = new_manager;
    }
    manager->packets[manager->size] = new_packet;
    manager->size++;
    return 0;
}

LTEPHY_RxPkt* packet_manager_get_packet(PacketManager* manager, int index) {
    if (index >= 0 && index < manager->size) {
        return &manager->packets[index];
    }
    return NULL;
}

int main() {
    PacketManager* manager = packet_manager_create(5);

    // Add packets
    LTEPHY_RxPkt p1, p2, p3;
    packet_manager_add_packet(manager, p1);
    packet_manager_add_packet(manager, p2);
    packet_manager_add_packet(manager, p3);

    // Get a packet
    LTEPHY_RxPkt* retrieved_p = packet_manager_get_packet(manager, 1);

    return 0;
}
