#define MAX_LIST_SIZE 10000
#define RNTI_VALID_RANGE 1, 65535

typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *nfa_list = NULL;
int nfa_list_size = 0;

int add_to_nfa_list(NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&list_mutex);

    if (nfa_list_size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list_mutex);
        return -1; // Error: list is full
    }

    if (new_entry->RNTI < RNTI_VALID_RANGE[0] || new_entry->RNTI > RNTI_VALID_RANGE[1]) {
        pthread_mutex_unlock(&list_mutex);
        return -2; // Error: invalid RNTI range
    }

    if (!nfa_list) {
        nfa_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE);
        if (!nfa_list) {
            pthread_mutex_unlock(&list_mutex);
            return -3; // Error: cannot allocate memory
        }
    }

    nfa_list[nfa_list_size] = *new_entry;
    nfa_list_size++;

    pthread_mutex_unlock(&list_mutex);

    return 0; // Success
}

void free_nfa_list() {
    pthread_mutex_lock(&list_mutex);

    if (nfa_list) {
        free(nfa_list);
        nfa_list = NULL;
        nfa_list_size = 0;
    }

    pthread_mutex_unlock(&list_mutex);
}
