            env::set_var("DIRECTORY_PATH", dir_path);
        }
        Self {
            dir_path,
            allocated_count: AtomicUsize::new(0),
            dealloc_queue: VecDeque::new(),
            lock: mpsc::channel(1)[1],
        }
    }

    fn create_and_configure_directory(&mut self, n: usize) -> Option<String> {
        if let Some(dir_path) = &self.dir_path {
            for _ in 0..n {
                let mut pdu = Box::new(NFAPI_CRC_INDICATION_PDU_T::new());
                *pdu.rx_ue_information_tag as usize;
                *pdu.rnti as usize;
                *pdu.crc_indication_rel8_tag as usize;
                self.allocated_count.fetch_add(1, Ordering::Relaxed);
                if let Err(err) = self.lock.send(()) {
                    println!("Error locking: {}", err);
                }
                // todo: log allocation size and frequency
            }
            Some(dir_path.to_string())
        } else {
            None
        }
    }
}

fn main() {
    let mut dir_manager = DirectoryManager::new();
    let n = 10;
    if let Some(dir_path) = dir_manager.create_and_configure_directory(n) {
        println!("Created directory: {}", dir_path);
    } else {
        println!("Failed to create directory");
    }
}
