typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void createAndPopulateCRCIndications(int N, int* CRCFLAGs) {
    NFAPI_CRC_INDICATION_PDU_T** indications = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for(int i = 0; i < N; i++) {
        indications[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Populate each structure
        indications[i]->RX_UE_INFORMATION_TAG = i;
        sprintf(indications[i]->RNTI, "RNTI_%d", i);
        indications[i]->CRCFLAG = CRCFLAGs[i % 2]; // Alternate between two random values

        // Ensure all RNTI values are unique within the list
        for(int j = 0; j < i; j++) {
            if(strcmp(indications[j]->RNTI, indications[i]->RNTI) == 0) {
                free(indications[i]);
                indications[i] = NULL;
                // Handle error condition
                break;
            }
        }
    }

    for(int i = 0; i < N; i++) {
        if(indications[i] != NULL) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %s, CRCFLAG: %d\n", indications[i]->RX_UE_INFORMATION_TAG, indications[i]->RNTI, indications[i]->CRCFLAG);
            free(indications[i]);
        }
    }

    for(int i = 0; i < N; i++) {
        free(indications[i]);
    }
    free(indications);
}

int main() {
    int N = 10;
    int CRCFLAGs[2] = {1, 2}; // Alternate between two random values
    createAndPopulateCRCIndications(N, CRCFLAGs);
    return 0;
}
