#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

int execute_command(char* cmd, char** envp) {
    pid_t pid;
    int status = 0;

    if ((pid = fork()) == -1) {
        return 0; // error
    }

    if (pid > 0) { // parent process
        waitpid(pid, &status, 0);
    } else { // child process
        signal(SIGCHLD, SIG_IGN); // ignore child signals
        execve(cmd, NULL, envp); // execute the command
        _exit(1); // exit with error if execution fails
    }

    return WIFEXITED(status) ? 0 : 1; // return 1 on success or 0 on failure
}

// example usage:
int main() {
    char* cmd = "/path/to/command";
    char** envp = environ; // pass environment variables to the child process

    if (execute_command(cmd, envp) == 1) {
        printf("Command executed successfully.\n");
    } else {
        printf("Error executing command. Exit status: %d\n", WEXITSTATUS(status));
    }

    return 0;
}
