const sharp = require('sharp');

async function uploadAndResizeFile(filePath, targetDirPath) {
  try {
    // Check if file exists
    const fileStats = await fs.stat(filePath);
    if (!fileStats.isFile()) throw new Error(`File not found at ${filePath}`);

    // Extract metadata from file (legacy system integration)
    const metadata = await extractMetadata(filePath);

    // Upload original image to cloud storage
    const uploadResponse = await axios.post('https://cloud-storage.com/upload', {
      filePath,
      targetDirPath
    }, {
      headers: { 'Content-Type': 'application/octet-stream' }
    });
    const originalImageUrl = uploadResponse.data.url;

    // Resize image if it exceeds specified width or height
    const [width, height] = await getDimensions(filePath);
    if (width > 1024 || height > 768) {
      const resizedImage = await resizeImage(filePath);
      const resizedUploadResponse = await axios.post('https://cloud-storage.com/upload', {
        filePath: resizedImage,
        targetDirPath
      }, {
        headers: { 'Content-Type': 'application/octet-stream' }
      });
      const resizedImageUrl = resizedUploadResponse.data.url;
    } else {
      const resizedImageUrl = originalImageUrl;
    }

    return { originalImageUrl, resizedImageUrl, metadata };
  } catch (error) {
    console.error(`Error uploading file: ${error.message}`);
    throw error;
  }
}

async function extractMetadata(filePath) {
  // Legacy system integration
  // ...
}

async function getDimensions(filePath) {
  // Get dimensions of the image
  const sharpImage = await sharp(filePath).metadata();
  return [sharpImage.width, sharpImage.height];
}

async function resizeImage(filePath) {
  // Resize the image using sharp library
  const resizedImage = await sharp(filePath)
    .resize(1024, 768, { force: true })
    .toBuffer();
  return resizedImage;
}
