use tokio::prelude::*;
use tokio::time;
use log::{info, error};
use std::collections::HashMap;

async fn fetch_data(api_name: &str) -> Result<String, Box<dyn std::error::Error>> {
    // Simulate API request with varying response times and reliability
    let response = async {
        if api_name == "API1" {
            time::sleep(time::Duration::from_millis(500)).await;
            Ok("API1 response".to_string())
        } else if api_name == "API2" {
            time::sleep(time::Duration::from_millis(2000)).await;
            Ok("API2 response".to_string())
        } else if api_name == "API3" {
            time::sleep(time::Duration::from_millis(1000)).await;
            Ok("API3 response".to_string())
        } else if api_name == "API4" {
            time::sleep(time::Duration::from_millis(3000)).await;
            Ok("API4 response".to_string())
        } else {
            Err("API not available")?
        }
    }.await?;

    // Simulate parsing error for API5
    if api_name == "API5" {
        let mut response = String::new();
        std::io::Write::write_str(&mut response, "API5 response").unwrap();
        Err(std::io::Error::new(std::io::ErrorKind::Other, "Parsing error"))?
    }

    Ok(response)
}

async fn process_data(api_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    info!("Processing data from {} API", api_name);

    // Fetch data from the selected API
    let response = fetch_data(api_name).await?;

    // Process the fetched data and handle errors
    if let Err(err) = process_response(response.as_str()) {
        error!("Error processing {}: {}", api_name, err);
        return Err(err)?;
    }

    Ok(())
}

async fn process_responses(mut responses: Vec<String>) -> Result<(), Box<dyn std::error::Error>> {
    for response in responses {
        info!("Received response: {}", response);
    }
    Ok(())
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let args: Vec<String> = std::env::args().collect();
    let api_name = &args[1];

    // Create a pool of up to 20 concurrent API requests
    let mut pool = tokio::task::join_all((0..20).map(|_| async move {
        process_data(api_name).await?;
        Ok::<(), Box<dyn std::error::Error>>(())
    }));

    // Process the results from the concurrently executed tasks
    for result in pool {
        if let Err(err) = result {
            error!("Error processing {}: {}", api_name, err);
            return;
        }
    }

    info!("Processing completed");
}

fn process_response(response: &str) -> Result<(), Box<dyn std::error::Error>> {
    // Simulate data processing and handling errors
    if response.contains("API1") {
        Ok(())
    } else if response.contains("API2") {
        Err("Invalid API response")?
    } else {
        let mut new_response = String::new();
        std::io::Write::write_str(&mut new_response, "Processed response").unwrap();
        Ok(())
    }
}
