use std::path::{Path, PathBuf};
use std::fs;
use std::env;
use std::sync::{Arc, Mutex};

struct ConfigDir {
    dir: Arc<PathBuf>,
    lock: Arc<Mutex<()>>,
}

impl ConfigDir {
    fn new() -> Self {
        let mut env_var = env::var("APP_CONFIG_DIR").ok();
        if env_var.is_none() || !env_var.as_ref().unwrap().is_dir() {
            println!("No valid APP_CONFIG_DIR found. Please specify a writable directory path.");
            loop {
                print!("Enter the directory path (or 'q' to quit): ");
                let mut dir_path = String::new();
                std::io::stdin().read_line(&mut dir_path).unwrap();
                if dir_path.trim() == "q" {
                    std::process::exit(0);
                }
                env_var = Some(dir_path.trim().to_string());
                if env_var.as_ref().map_or(false, |s| s.is_dir()) {
                    break;
                }
                println!("Invalid directory path. Please try again.");
            }
        }
        ConfigDir {
            dir: Arc::new(env_var.unwrap().parse().unwrap()),
            lock: Arc::new(Mutex::new(())),
        }
    }

    fn create(&self) -> Result<PathBuf, std::io::Error> {
        if !self.dir.exists() {
            fs::create_dir_all(self.dir.clone())?;
        }
        Ok(self.dir.clone())
    }

    fn write_config(&self, file_name: &str) -> Result<(), std::io::Error> {
        let mut file_path = self.dir.join(file_name);
        fs::write(file_path.as_path(), "config data".as_bytes())?;
        Ok(())
    }
}

fn main() {
    let config_dir = ConfigDir::new();
    println!("Config directory: {:?}", config_dir.dir);

    match config_dir.create() {
        Ok(dir) => println!("Directory created: {}", dir),
        Err(err) => println!("Error creating directory: {}", err),
    }

    match config_dir.write_config("config.txt") {
        Ok(_) => println!("Configuration written to file"),
        Err(err) => println!("Error writing configuration: {}", err),
    }
}
