    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize and set random values in crc_pdu_array
    for (int i = 0; i < N; i++) {
        crc_pdu_array[i].RNTI = rand() % 100;
        crc_pdu_array[i].CRCFLAG = rand() % (max_range - min_range + 1) + min_range;
    }

    // Serialize structures to binary format and write to file
    fwrite(crc_pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, output_file);

    free(offset_values);
    free(keys);
    free(records);
    free(crc_pdu_array);
}

int main() {
    process_and_filter_transactions(100, 0, 100, stdout);
    return 0;
