#include <unistd.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;

void initialize_list(char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        // Initialize list with default values
        for (int i = 0; i < 10000; i++) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = rand();
            pdu.RNTI = rand();
            pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
            pdu.CRCFLAG = rand() & 1;
            Node* node = (Node*)malloc(sizeof(Node));
            node->data = pdu;
            node->next = head;
            head = node;
        }
    } else {
        // Initialize list from file
        // ...
    }
}

void sort_list() {
    Node* current = head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        while (next != NULL) {
            if (current->data.RNTI > next->data.RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = current->data;
                current->data = next->data;
                next->data = temp;
            }
            next = next->next;
        }
        current = current->next;
    }
}

void free_list() {
    Node* current = head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
}

int main() {
    initialize_list("config_file.txt");
    sort_list();
    // ...
    free_list();
    return 0;
}
