class NfaapiCrcIndicationPdu {
public:
    NfaapiCrcIndicationPdu() : rxUeInformationTag(0), rnti(0) {}
    int rxUeInformationTag;
    int rnti;
    bool crcFlag = false;
};

class NfalitePacketGenerator {
private:
    std::vector<NfaapiCrcIndicationPdu*> packets;

public:
    ~NfalitePacketGenerator() {
        for (auto packet : packets) {
            delete packet;
        }
    }

    void generateAndPopulate(int count) {
        packets.reserve(count);
        for (int i = 0; i < count; ++i) {
            NfaapiCrcIndicationPdu* packet = new NfaapiCrcIndicationPdu();
            packet->rxUeInformationTag = static_cast<int>(std::rand());
            packet->rnti = static_cast<int>(std::rand());
            packet->crcFlag = (std::rand() % 2) == 1;
            packets.push_back(packet);
        }
    }

    void freeMemory() {
        for (auto& packet : packets) {
            delete packet;
        }
        packets.clear();
    }

    static std::string computeMD5Hash(const std::string& input) {
        MD5 md5;
        try {
            return md5.getString(input);
        } catch (...) {
            return "Error computing MD5 hash";
        }
    }
};
