typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[8];
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateNfadumpPduArray(int N, const char* uniqueId) {
    if (N <= 0 || N > 1000) return NULL; // handle invalid input size

    int i;
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        printf("Memory allocation failed\n");
        return NULL; // handle memory allocation failure
    }

    for (i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100000;
        strcpy(array[i].RNTI, &uniqueId[rand() % strlen(uniqueId)]);
        array[i].CRC_INDICATION_REL8_TAG = rand();

        // ensure no consecutive CRCFLAG values are the same
        while (!rand()) ; // wait until random value is not zero
        if (i > 0) {
            array[i].CRC_INDICATION_REL8_TAG += array[i-1].CRC_INDICATION_REL8_TAG;
            array[i].CRC_INDICATION_REL8_TAG %= 2; // ensure CRCFLAG < 2
        }
    }

    return array;
}

char* computeMD5Hash(const char* input) {
    unsigned char buffer[16];
    unsigned char* hash = NULL;

    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(input.getBytes());
        for (int i = 0; i < 16; i++) {
            buffer[i] = (byte)hashBytes[i];
        }
        return new String(buffer);
    } catch (Exception e) {
        System.out.println("Error computing MD5 hash: " + e.getMessage());
        return null;
    }
}
