#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct UeSessionInfo {
    int ueId;
    int rrcStates[10];
    pthread_mutex_t timerMutex;
    pthread_cond_t timerCond;
} UeSessionInfo;

UeSessionInfo* sessions = NULL;
int numSessions = 0;
int maxSessions = 10000;
pthread_mutex_t sessionsMutex;
pthread_cond_t sessionCond;
int timeout = 300; // default timeout in seconds

void addSession(int ueId, int* rrcStates) {
    UeSessionInfo* newSession = (UeSessionInfo*)malloc(sizeof(UeSessionInfo));
    if (!newSession) {
        printf("Error: Out of memory.\n");
        return;
    }
    newSession->ueId = ueId;
    memcpy(newSession->rrcStates, rrcStates, sizeof(int)*10);
    pthread_mutex_init(&newSession->timerMutex, NULL);
    pthread_cond_init(&newSession->timerCond, NULL);

    pthread_mutex_lock(&sessionsMutex);
    if (numSessions >= maxSessions) {
        printf("Error: Maximum number of sessions reached.\n");
        free(newSession);
    } else {
        sessions = realloc(sessions, sizeof(UeSessionInfo*)*(numSessions+1));
        sessions[numSessions++] = newSession;
    }
    pthread_mutex_unlock(&sessionsMutex);
}

void updateSession(int ueId, int* rrcStates) {
    pthread_mutex_lock(&sessionsMutex);
    for (int i = 0; i < numSessions; i++) {
        if (sessions[i]->ueId == ueId) {
            memcpy(sessions[i]->rrcStates, rrcStates, sizeof(int)*10);
            break;
        }
    }
    pthread_mutex_unlock(&sessionsMutex);
}

void removeSession(int ueId) {
    pthread_mutex_lock(&sessionsMutex);
    for (int i = 0; i < numSessions; i++) {
        if (sessions[i]->ueId == ueId) {
            free(sessions[i]);
            memmove(&sessions[i], &sessions[i+1], sizeof(UeSessionInfo*)*(numSessions-i-1));
            numSessions--;
            break;
        }
    }
    pthread_mutex_unlock(&sessionsMutex);
}

void timerHandler(void* arg) {
    UeSessionInfo** sessionPtr = (UeSessionInfo**)arg;
    for (int i = 0; i < *sessionPtr; i++) {
        pthread_mutex_lock(&(*sessionPtr)[i]->timerMutex);
        pthread_cond_signal(&(*sessionPtr)[i]->timerCond);
        pthread_mutex_unlock(&(*sessionPtr)[i]->timerMutex);
    }
}

void cleanupTimer(void* arg) {
    UeSessionInfo** sessionPtr = (UeSessionInfo**)arg;
    for (int i = 0; i < *sessionPtr; i++) {
        pthread_mutex_lock(&(*sessionPtr)[i]->timerMutex);
        pthread_cond_destroy(&(*sessionPtr)[i]->timerCond);
        pthread_mutex_unlock(&(*sessionPtr)[i]->timerMutex);
    }
}

void* timerThread(void* arg) {
    UeSessionInfo** sessionPtr = (UeSessionInfo**)arg;
    while (1) {
        for (int i = 0; i < *sessionPtr; i++) {
            pthread_mutex_lock(&(*sessionPtr)[i]->timerMutex);
            pthread_cond_wait(&(*sessionPtr)[i]->timerCond, &(*sessionPtr)[i]->timerMutex);
            if (!numSessions) {
                return NULL;
            }
        }
    }
}

int main() {
    // Initialize sessions
    pthread_mutex_init(&sessionsMutex, NULL);
    pthread_cond_init(&sessionCond, NULL);

    // Start timer thread
    UeSessionInfo** sessionPtr = &numSessions;
    pthread_t timerThreadHandle;
    pthread_create(&timerThreadHandle, NULL, timerThread, (void*)sessionPtr);

    return 0;
}
