// Define the TaskInstance struct
typedef struct {
    int id;
    int priority;
    char** dependencies;
    int status; // 0 - Created, 1 - Running, 2 - Completed, 3 - Failed
} TaskInstance;

// Define the task queue
typedef struct {
    TaskInstance* tasks;
    int size;
    pthread_mutex_t lock;
} TaskQueue;

TaskQueue task_queue = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to add a new task instance
void add_task(int id, int priority) {
    pthread_mutex_lock(&task_queue.lock);

    // Allocate memory for the new task instance
    TaskInstance* new_task = (TaskInstance*)malloc(sizeof(TaskInstance));
    new_task->id = id;
    new_task->priority = priority;
    new_task->dependencies = NULL;
    new_task->status = 0; // Created

    // Add the task to the queue
    if (task_queue.size < 10000) { // assuming a maximum of 10,000 tasks
        task_queue.tasks = realloc(task_queue.tasks, sizeof(TaskInstance*) * (task_queue.size + 1));
        task_queue.tasks[task_queue.size++] = new_task;
    } else {
        // Handle the case where the queue is full
        free(new_task);
    }

    pthread_mutex_unlock(&task_queue.lock);
}

// Function to update a task instance's status
void update_task_status(int id, int status) {
    pthread_mutex_lock(&task_queue.lock);

    for (int i = 0; i < task_queue.size; i++) {
        if (task_queue.tasks[i]->id == id) {
            task_queue.tasks[i]->status = status;
            break;
        }
    }

    pthread_mutex_unlock(&task_queue.lock);
}

// Function to remove a task instance
void remove_task(int id) {
    pthread_mutex_lock(&task_queue.lock);

    for (int i = 0; i < task_queue.size; i++) {
        if (task_queue.tasks[i]->id == id) {
            free(task_queue.tasks[i]);
            memmove(&task_queue.tasks[i], &task_queue.tasks[i + 1], sizeof(TaskInstance*) * (task_queue.size - i - 1));
            task_queue.size--;
            break;
        }
    }

    pthread_mutex_unlock(&task_queue.lock);
}

// Function to get a task instance by ID
TaskInstance* get_task(int id) {
    pthread_mutex_lock(&task_queue.lock);

    for (int i = 0; i < task_queue.size; i++) {
        if (task_queue.tasks[i]->id == id) {
            return task_queue.tasks[i];
        }
    }

    pthread_mutex_unlock(&task_queue.lock);
    return NULL;
}

// Function to print the task queue
void print_task_queue() {
    pthread_mutex_lock(&task_queue.lock);

    for (int i = 0; i < task_queue.size; i++) {
        printf("Task %d: Priority %d, Status %d\n", task_queue.tasks[i]->id, task_queue.tasks[i]->priority, task_queue.tasks[i]->status);
    }

    pthread_mutex_unlock(&task_queue.lock);
}
