typedef struct {
    int PacketType;
    char SourceAddress[16];
    char DestinationAddress[16];
    size_t PayloadSize;
} DataPacket;

void manageDataPackets(DataPacket** packets, size_t* packetCount, size_t maxPackets) {
    // Initialize random number generator
    srand(time(NULL));

    while (1) {
        if (*packetCount >= maxPackets) break;  // Limit packets to avoid memory issues

        DataPacket* newPacket = (DataPacket*)malloc(sizeof(DataPacket));
        if (!newPacket) {
            printf("Memory allocation failed!\n");
            return;
        }

        // Generate random packet attributes
        newPacket->PacketType = rand() % 2;  // 0 or 1
        strcpy(newPacket->SourceAddress, "NodeX");  // Hardcoded for simplicity
        strcpy(newPacket->DestinationAddress, "NodeY");  // Hardcoded for simplicity
        newPacket->PayloadSize = rand() % 100 + 1;  // Random payload size between 1 and 100

        // Add packet to array
        *packetCount += 1;
        if (*packetCount >= maxPackets) {
            printf("Max packets reached! Terminating...\n");
            return;
        }

        int i = 0;
        for (i = 0; i < *packetCount - 1; i++) {
            // Check for duplicate packets based on source and destination addresses
            if ((strcmp(packets[i]->SourceAddress, newPacket->SourceAddress) == 0 &&
                 strcmp(packets[i]->DestinationAddress, newPacket->DestinationAddress) == 0) ||
                (strcmp(packets[i]->SourceAddress, newPacket->DestinationAddress) == 0 &&
                 strcmp(packets[i]->DestinationAddress, newPacket->SourceAddress) == 0)) {
                // Packet duplicate detected! Remove the older packet
                free(packets[i]);
                *packetCount -= 1;
                i--;
            }
        }

        packets[*packetCount - 1] = newPacket;
    }
}
