void init_nfa_config(size_t cap) {
    nfa_config.capacity = cap;
    nfa_config.size = 0;
    nfa_config.arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(cap * sizeof(NFAPI_CRC_INDATION_PDU_T));
}

int add_ue_to_nfa(const char* tag, int rnti) {
    pthread_mutex_lock(&nfa_config.lock);
    if (nfa_config.size >= nfa_config.capacity) {
        size_t new_cap = nfa_config.capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_cap * sizeof(NFAPI_CRC_INDATION_PDU_T));
        memcpy(temp_arr, nfa_config.arr, nfa_config.size * sizeof(NFAPI_CRC_INDATION_PDU_T));
        free(nfa_config.arr);
        nfa_config.arr = temp_arr;
        nfa_config.capacity = new_cap;
    }
    NFAPI_CRC_INDICATION_PDU_T* ue = &nfa_config.arr[nfa_config.size++];
    strcpy(ue->RX_UE_INFORMATION_TAG, tag);
    ue->RNTI = rnti;
    srand(time(NULL));
    ue->CRCFLAG = rand() % 100;
    pthread_mutex_unlock(&nfa_config.lock);
}

