    // validate against current network settings
}

int checksum(NFAPI_CRC_INDICATION_PDU_T* ue) {
    // implement custom checksum function to verify CRC flag integrity
}

void remove_ue_from_nfa(int rnti) {
    pthread_mutex_lock(&nfa_config.lock);
    for (size_t i = 0; i < nfa_config.size; i++) {
        if (nfa_config.arr[i].RNTI == rnti) {
            memmove(&nfa_config.arr[i], &nfa_config.arr[i + 1], (nfa_config.size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            nfa_config.size--;
            break;
        }
    }
    pthread_mutex_unlock(&nfa_config.lock);
}

void update_ue_from_data_source(int rnti, const char* tag) {
    pthread_mutex_lock(&nfa_config.lock);
    for (size_t i = 0; i < nfa_config.size; i++) {
        if (nfa_config.arr[i].RNTI == rnti) {
            strcpy(nfa_config.arr[i].RX_UE_INFORMATION_TAG, tag);
            break;
        }
    }
    pthread_mutex_unlock(&nfa_config.lock);
}

void print_ue_list() {
    pthread_mutex_lock(&nfa_config.lock);
    for (size_t i = 0; i < nfa_config.size; i++) {
        printf("RNTI: %d, Tag: %s, CRCFLAG: %d\n", nfa_config.arr[i].RNTI, nfa_config.arr[i].RX_UE_INFORMATION_TAG, nfa_config.arr[i].CRCFLAG);
    }
    pthread_mutex_unlock(&nfa_config.lock);
}
