#define RECORD_SIZE sizeof(record)
#define MEMORY_POOL_ALIGNMENT 16 // Align records to 16-byte boundary for performance-critical operations
#define LOGGING_ENABLED 1 // Enable logging with the external logging library
#define RANDOM_VALUE_GENERATION 1 // Generate random values by default

typedef struct {
    long offset;
    int key;
    double value;
} record;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void my_free(void* ptr) {
    if (pthread_mutex_lock(&mutex) != 0) {
        fprintf(stderr, "Error locking mutex\n");
        abort();
    }
    free(ptr);
    pthread_mutex_unlock(&mutex);
}

record* allocate_records(int num_records, int key_start, int key_step, unsigned seed) {
    record* records = my_malloc(num_records * RECORD_SIZE);
    if (!records) return NULL;

    // Initialize 'int' key values
    for (int i = 0; i < num_records; i++) {
        records[i].key = (i * key_start + ((num_records - 1) / (key_step - 1)) * (i % (key_step - 1))) % (KEY_MAX + 1);
    }

    // Populate 'double' value fields
