// Global array to store NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;
size_t current_size = 0; // number of allocated elements

// Serialize crc indications to file "crc_indications.bin"
void serialize_crc_indications() {
    FILE *file = fopen("crc_indications.bin", "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }
    // Write current_size
    fwrite(&current_size, sizeof(size_t), 1, file);
    // Write crc indications array
    fwrite(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T), current_size, file);
    fclose(file);
}

// Deserialize crc indications from file "crc_indications.bin"
void deserialize_crc_indications() {
    FILE *file = fopen("crc_indications.bin", "rb");
    if (!file) {
        perror("Error opening file for reading");
        return;
    }
    // Read current_size
    fread(&current_size, sizeof(size_t), 1, file);
    crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        perror("Error allocating memory");
        return;
    }
    // Read crc indications array
    fread(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T), current_size, file);
    fclose(file);
}

// Reallocate and resize the crc indications array
void realloc_crc_indications(int new_size) {
    if (new_size <= current_size) return; // no reallocation needed

    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Error allocating memory");
        return;
    }
    // Copy current elements to new array
    memcpy(new_array, crc_indications, current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(crc_indications);
    crc_indications = new_array;
    current_size = new_size;
}

// Check if total memory usage exceeds the specified limit
int check_memory_usage(size_t size) {
    return (current_size + size > MAX_MEMORY) ? -1 : 0;
}

// Dynamic memory management for NFAPI_CRC_INDICATION_PDU_T structures
void *allocate_crc_indication() {
    int new_size = current_size + 1; // incrementally increase array size
    if (check_memory_usage(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T))) return NULL;
    realloc_crc_indications(new_size);
    return &crc_indications[current_size++];
}

// Free dynamically allocated memory for an NFAPI_CRC_INDICATION_PDU_T structure
void free_crc_indication(void **ptr) {
    int idx = *(size_t *)ptr - current_size; // get the index of the element to be freed
    if (idx < 0 || idx >= current_size) return;
    memmove(&crc_indications[idx], &crc_indications[idx + 1], (current_size - idx - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *(size_t *)ptr = current_size; // update the index
}

// Serialize and save crc indications array to file "crc_indications.bin"
void finalize_crc_indications() {
    serialize_crc_indications();
}

int main() {
    pthread_mutex_init(&mutex, NULL); // initialize thread-safe mutex

    // Allocate initial memory for 1 NFAPI_CRC_INDICATION_PDU_T structure
    crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        perror("Error allocating memory");
        return -1;
    }
    current_size = 1;

    // Dynamically manage and serialize crc indications array
    void *ptr = allocate_crc_indication();
    while (true) {
        // Perform operations on crc indications array...
        // ...
        free_crc_indication(&ptr);
        ptr = allocate_crc_indication();
    }

    finalize_crc_indications();

    return 0;
}

