}

int check_duplicates(NFAPI_CRC_INDICATION_PDU_T* arr, int n) {
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i].RNTI == arr[j].RNTI)
                return 1;
        }
    }
    return 0;
}

void sort_array(NFAPI_CRC_INDICATION_PDU_T* arr, int n) {
    qsort(arr, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_tags);
}

int compare_tags(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pa = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pb = (NFAPI_CRC_INDATION_PDU_T*)b;
    return (pa->RX_UE_INFORMATION_TAG - pb->RX_UE_INFORMATION_TAG);
}

