        while (1) {
            int packetID = rand();
            if (packetID != 0 && !findDuplicate(packetID, packets, packetCount)) {
                packets[packetCount].packetID = packetID;
                packets[packetCount].timestamp = time(NULL);
                sprintf(packets[packetCount].payload, "Packet %d: %s", packetID, "This is a test payload");
                packetCount++;
                break;
            }
        }

        if (packetCount >= numPackets) {
            break;
        }

        // Log every 10 packets
        if ((i + 1) % 10 == 0) {
            fprintf(log, "INFO: Initialized %d packets.\n", i + 1);
        }
    }

    fprintf(log, "INFO: Successfully initialized %d packets.\n", packetCount);

    fclose(log);
}

int findDuplicate(int packetID, DataPacket* packets, int count) {
    for (int i = 0; i < count; i++) {
        if (packets[i].packetID == packetID) {
            return 1;
        }
    }
    return 0;
}
