    NFAPI_CRC_INDICATION_PDU_T **crc_list = NULL;
    int *num_crcs_with_nonzero_flag = 0;
    int i, j;

    // Dynamically allocate memory for the list
    crc_list = (NFAPI_CRC_INDICATION_PDU_T **)malloc((num_entries + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!crc_list) {
        printf("Error: Memory allocation failed.\n");
        return;
