    num_crcs_with_nonzero_flag = (int *)malloc(sizeof(int));
    *num_crcs_with_nonzero_flag = 0;

    for (i = 0; i <= num_entries; i++) {
        crc_list[i] = NULL;
    }

    // Insert new entries into the list
    for (i = 1; i <= num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
