        entry->RNTI = ...;  // Initialize the RNTI
        entry->rel8_tag = ...;  // Initialize the CRC_INDICATION_REL8_TAG
        entry->CRCFLAG = ...;  // Initialize the CRCFLAG

        // Insert the new entry into the list and update the number of CRC indications with a non-zero flag
        for (j = i; j > 0 && strcmp(entry->tag, crc_list[j - 1]->tag) < 0; j--) {
            crc_list[j] = crc_list[j - 1];
        }
        crc_list[j] = entry;
        if (entry->CRCFLAG != 0) {
            (*num_crcs_with_nonzero_flag)++;
        }
    }

    // Free dynamically allocated memory
    for (i = 1; i <= num_entries; i++) {
        free(crc_list[i]);
    }
    free(crc_list);
    free(num_crcs_with_nonzero_flag);
