#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MAC_ENTITIES 10000
#define MAX_TIDS_PER_ENTITY 100

typedef struct {
    uint32_t mac_id;
    uint16_t num_tids;
    TID **tids;
} MAC_entity_context_t;

// Function to create and initialize a new MAC entity context
MAC_entity_context_t *mac_entity_context_create(uint32_t mac_id, uint16_t num_tids) {
    MAC_entity_context_t *ctx = (MAC_entity_context_t *)malloc(sizeof(MAC_entity_context_t));
    ctx->mac_id = mac_id;
    ctx->num_tids = num_tids;
    ctx->tids = (TID **)malloc(num_tids * sizeof(TID *));
    for (int i = 0; i < num_tids; i++) {
        ctx->tids[i] = NULL;
    }
    return ctx;
}

// Function to add a new TID to an existing MAC entity context
void mac_entity_context_add_tid(MAC_entity_context_t *ctx, TID *tid) {
    // Check if the TID already exists for this MAC entity
    for (int i = 0; i < ctx->num_tids; i++) {
        if (ctx->tids[i] == tid) {
            return;
        }
    }

    // Add the new TID to the context's list of TIDs
    ctx->tids[ctx->num_tids++] = tid;
}

// Function to remove a TID from an existing MAC entity context
void mac_entity_context_remove_tid(MAC_entity_context_t *ctx, TID *tid) {
    for (int i = 0; i < ctx->num_tids; i++) {
        if (ctx->tids[i] == tid) {
            // Move the last TID to the current position and decrement num_tids
            memmove(&ctx->tids[i], &ctx->tids[i + 1], (ctx->num_tids - i - 1) * sizeof(TID *));
            ctx->num_tids--;
            break;
        }
    }
}

// Function to serialize a MAC entity context to binary format for persistence
int mac_entity_context_serialize(const MAC_entity_context_t *ctx, char *buffer, int buffer_size) {
    // Serialize the MAC entity ID and number of TIDs
    memcpy(buffer, &ctx->mac_id, sizeof(uint32_t));
    memcpy(buffer + sizeof(uint32_t), &ctx->num_tids, sizeof(uint16_t));

    // Serialize each TID in the context's list
    for (int i = 0; i < ctx->num_tids; i++) {
        memcpy(buffer + sizeof(uint32_t) + sizeof(uint16_t) + i * sizeof(TID), ctx->tids[i], sizeof(TID));
    }

    return buffer_size;
}

// Function to deserialize a MAC entity context from binary format for persistence
int mac_entity_context_deserialize(MAC_entity_context_t **ctx, char *buffer, int buffer_size) {
    // Deserialize the MAC entity ID and number of TIDs
    uint32_t mac_id = *(uint32_t *)buffer;
    uint16_t num_tids = *(uint16_t *)(buffer + sizeof(uint32_t));

    // Allocate memory for the new MAC entity context
    *ctx = (MAC_entity_context_t *)malloc(sizeof(MAC_entity_context_t));
    (*ctx)->mac_id = mac_id;
    (*ctx)->num_tids = num_tids;

    // Deserialize each TID in the context's list
    (*ctx)->tids = (TID **)malloc(num_tids * sizeof(TID *));
    for (int i = 0; i < num_tids; i++) {
        memcpy(&((*ctx)->tids[i]), buffer + sizeof(uint32_t) + sizeof(uint16_t) + i * sizeof(TID), sizeof(TID));
    }

    return buffer_size;
}

// Function to monitor the age of each TID and reclaim unused TIDs
void mac_entity_context_reclaim_unused_tids(MAC_entity_context_t *ctx, uint32_t timeout) {
    // Iterate over the context's list of TIDs and reclaim any that have exceeded the timeout
    for (int i = 0; i < ctx->num_tids; i++) {
        if (/* check age and reclaim if necessary */) {
            // Reclaim the unused TID
            free(ctx->tids[i]);
        }
    }
}
