#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NFAPI_CRC_INDICATION_PDU_T 1000
#define CRCFLAG_PROBABILITY 0.5

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t allocation_cond = PTHREAD_COND_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu_ts[MAX_NFAPI_CRC_INDICATION_PDU_T];
int current_allocation_size = 0;
int total_allocated_size = 0;

void* allocate_nfa_pi_crc_indication_pdu_ts(int count) {
    pthread_mutex_lock(&allocation_lock);

    if (count > MAX_NFAPI_CRC_INDICATION_PDU_T - current_allocation_size) {
        // Switch to individual allocation
        void* memory = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!memory) {
            pthread_mutex_unlock(&allocation_lock);
            return NULL;
        }

        current_allocation_size = count;
        total_allocated_size += count * sizeof(NFAPI_CRC_INDICATION_PDU_T);

        nfa_pi_crc_indication_pdu_ts[current_allocation_size - 1] = memory;

        pthread_cond_signal(&allocation_cond);

        pthread_mutex_unlock(&allocation_lock);
    } else {
        // Bulk allocation
        if (current_allocation_size == 0) {
            void* memory = malloc(MAX_NFAPI_CRC_INDICATION_PDU_T * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!memory) {
                pthread_mutex_unlock(&allocation_lock);
                return NULL;
            }

            current_allocation_size = MAX_NFAPI_CRC_INDICATION_PDU_T;

            nfa_pi_crc_indication_pdu_ts[0] = memory;

            pthread_cond_signal(&allocation_cond);

            pthread_mutex_unlock(&allocation_lock);
        } else {
            // Reuse existing allocation
            pthread_mutex_unlock(&allocation_lock);
        }
    }

    return &nfa_pi_crc_indication_pdu_ts[count - 1][0];
}

void free_nfa_pi_crc_indication_pdu_ts(int count) {
    for (int i = 0; i < count; i++) {
        free(&nfa_pi_crc_indication_pdu_ts[i][0]);
    }

    current_allocation_size -= count;
    total_allocated_size -= count * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_lock(&allocation_lock);
    if (current_allocation_size == 0) {
        pthread_cond_signal(&allocation_cond);
    }
    pthread_mutex_unlock(&allocation_lock);
}

int set_crcflag(int index, int rnti, int rx_ue_information_tag) {
