int binary_search(char** arr, int len, int target) {
    int low = 0;
    int high = len - 1;

    while (low <= high) {
        int mid = (low + high) / 2;

        if (arr[mid] == target)
            return mid;

        if (target < arr[mid])
            high = mid - 1;
        else
            low = mid + 1;
    }

    return -1; // Not found
}
