async function processFiles(dir) {
  const cache = new Map();
  const logs = [];

  async function processFile(file) {
    try {
      const contents = await fs.readFile(file.path, 'utf8');
      if (validateContents(contents)) {
        const result = file.name + ': ' + contents;
        return result;
      } else {
        throw new Error(`Invalid content in ${file.name}`);
      }
    } catch (err) {
      logs.push({ error: err.message, file });
      console.error(err);
    }
  }

  async function processDirectory(dir) {
    const files = await fs.readdir(dir);
    for (const file of files) {
      if (!file.endsWith('.js')) continue; // filter by extension
      const filePath = path.join(dir, file);
      try {
        const stat = await fs.stat(filePath);
        if (stat.isDirectory()) {
          processDirectory(filePath);
        } else if (stat.isFile()) {
          const result = await processFile({ path: filePath });
          if (result) {
            cache.set(file, result);
          }
        }
      } catch (err) {
        logs.push({ error: err.message, file });
        console.error(err);
      }
    }
  }

  processDirectory(dir);

  return Array.from(cache.values()).join('\n');
}

