        }
    }
}

struct BuildSystem {
    queue: Arc<Mutex<Vec<Box<dyn Fn() + '_>>>>,
    concurrency_limit: usize,
    artifact_cache: Arc<Mutex<HashSet<String>>>,
    logger: Arc<Mutex<dyn Logger + '_>>,
    threshold_alerts: Arc<Mutex<HashMap<String, (f64, f64)>>>,
}

impl BuildSystem {
    fn new(concurrency_limit: usize) -> Self {
        BuildSystem {
            queue: Arc::new(Mutex::new(Vec::new())),
            concurrency_limit,
            artifact_cache: Arc::new(Mutex::new(HashSet::new())),
            logger: Arc::new(Mutex::new(None)),
            threshold_alerts: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn set_logger(&mut self, logger: Box<dyn Logger + '_>) {
        *self.logger.get_mut() = Some(logger);
    }

    fn add_to_queue(&mut self, build_config: &BuildConfig) {
        let mut queue = self.queue.lock().unwrap();
        queue.push(Box::new(move || {
            // handle build config
        }));
    }

    fn run_builds(&mut self) {
        while let Some(build) = self.queue.lock().unwrap().pop() {
            if self.concurrency_limit > 0 && self.queue.lock().unwrap().len() >= self.concurrency_limit {
                thread::sleep(Duration::from_millis(100));
            }
            build();
        }
    }

    fn trigger_alert(&mut self, metric: &str, value: f64) {
        let mut threshold_alerts = self.threshold_alerts.lock().unwrap();
        if value > *threshold_alerts.get(metric).unwrap_or(&(0.0, 0.0)).0 {
            // send alert
        }
    }

    fn log_metrics(&mut self) {
        // log metrics
    }
}

trait Logger {
    fn log(&self, level: &str, message: &str);
}
