        'clientSecret' => $clientSecret,
        'redirectUri' => $redirectUri,
    ]);

    try {
        // Authenticate with the payment gateway and get an access token
        $accessToken = $paymentGatewayClient->getAccessToken();
    } catch (Exception $e) {
        return null;
    }

    return $accessToken;
}

function handleAuthenticationAttempt($username, $password) {
    // Check if the user has a valid subscription
    $subscriptionStatus = getSubscriptionStatus($username);

    if ($subscriptionStatus === 'active') {
        // User has an active subscription, authenticate and log in
        $accessToken = authenticateViaOAuth($clientId, $clientSecret, $redirectUri, $username, $password);
        if ($accessToken) {
            // Log the authentication attempt for auditing purposes
            logAuthenticationAttempt($username, $accessToken->getToken());
            return $accessToken;
        }
    } else {
        // User does not have an active subscription, redirect to payment gateway
        $paymentGatewayAccessToken = authenticateViaPaymentGateway($clientId, $clientSecret, $redirectUri);
        if ($paymentGatewayAccessToken) {
            // Log the authentication attempt for auditing purposes
