#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CAPACITY 100
#define GARBAGE_COLLECTION_THRESHOLD 0.7

typedef struct NFAPI_L2_PDU_T {
    L2_PDU_HEADER header;
    L2_PDU_PAYLOAD payload;
} NFAPI_L2_PDU_T;

typedef struct list {
    NFAPI_L2_PDU_T* elements;
    int capacity, size;
    pthread_mutex_t lock;
} List;

List* init_list(int initial_capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;  // Handle memory allocation failure
    list->capacity = initial_capacity;
    list->size = 0;
    list->elements = (NFAPI_L2_PDU_T*)malloc(list->capacity * sizeof(NFAPI_L2_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;  // Handle memory allocation failure
    }
    pthread_mutex_init(&list->lock, NULL);  // Initialize lock for thread safety
    return list;
}

void insert_list(List* list, NFAPI_L2_PDU_T element) {
    if (list->size >= list->capacity * GARBAGE_COLLECTION_THRESHOLD) {
        resize_list(list);
    }
    pthread_mutex_lock(&list->lock);  // Acquire lock for thread safety
    list->elements[list->size] = element;
    list->size++;
    pthread_mutex_unlock(&list->lock);  // Release lock
}

void delete_list(List* list, int index) {
    pthread_mutex_lock(&list->lock);  // Acquire lock for thread safety
    if (index >= list->size) return;  // Handle out-of-bounds error
    memmove(&list->elements[index], &list->elements[index + 1], (list->size - index - 1) * sizeof(NFAPI_L2_PDU_T));
    list->size--;
    pthread_mutex_unlock(&list->lock);  // Release lock
}

void resize_list(List* list) {
    int new_capacity = list->capacity * 2;
    NFAPI_L2_PDU_T* new_elements = (NFAPI_L2_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_L2_PDU_T));
    if (!new_elements) return;  // Handle memory allocation failure
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->lock);  // Release lock
}

void free_list(List* list) {
    free(list->elements);
    free(list);
}
