MAC_RX_FRAME* mac_rx_frame_init(size_t num_frames, size_t max_payload_size) {
    MAC_RX_FRAME* frames = (MAC_RX_FRAME*)malloc(num_frames * sizeof(MAC_RX_FRAME));

    if(frames == NULL) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    for(int i = 0; i < num_frames; i++) {
        frames[i].info.timestamp = time(NULL);
        frames[i].data.len = 0;

        // Dynamically allocate memory for data payload
        size_t data_size = rand() % (max_payload_size - 1) + 1;
        frames[i].data.data = malloc(data_size);

        if(frames[i].data.data == NULL) {
            printf("Memory allocation failed!\n");
            return NULL;
        }
    }

    return frames;
}

int main() {
    size_t num_frames = 10;
    size_t max_payload_size = 1024;

    MAC_RX_FRAME* frames = mac_rx_frame_init(num_frames, max_payload_size);

    if(frames == NULL) {
        printf("Initialization failed!\n");
        return -1;
    }

    // Verification mechanism
    for(int i = 0; i < num_frames; i++) {
        printf("Frame %d: Timestamp = %ld, Payload Size = %zu\n", i, frames[i].info.timestamp, frames[i].data.len);

        // Verify frame integrity
        if(frames[i].data.data == NULL || frames[i].data.len > max_payload_size) {
            printf("Frame Integrity Error!\n");
            return -1;
        }
    }

    // Clean up dynamically allocated memory
    for(int i = 0; i < num_frames; i++) {
        free(frames[i].data.data);
    }

    free(frames);

    return 0;
