        interfaces[i].frequency = getValidFrequency(validFrequencyRange);
    }
    return interfaces;
}

int getValidFrequency(int* frequencyRange) {
    if (frequencyRange[0] > frequencyRange[1]) {
        // swap the range values
        int temp = frequencyRange[0];
        frequencyRange[0] = frequencyRange[1];
        frequencyRange[1] = temp;
    }
    return (rand() % (frequencyRange[1] - frequencyRange[0])) + frequencyRange[0];
}

