    for (int i = 0; i < current_ue_count; i++) {
        if (ue_instances[i]->ue_id == ue_id) {
            free(ue_instances[i]);
            pthread_mutex_lock(&ue_lock);
            memmove(ue_instances + i, ue_instances + i + 1, sizeof(RX_UE_INFORMATION_TAG *) * (current_ue_count - i));
            current_ue_count--;
