#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE 50000
#define TABLE_SIZE 256 // power of 2 for efficient hash table
#define BUFFER_SIZE 1024

typedef struct {
    int ue_id;
    char last_known_position[BUFFER_SIZE];
    int num_services;
    char **services;
} LTE_Context;

typedef struct {
    LTE_Context *context;
    pthread_mutex_t mutex;
} UE_Handler;

LTE_Context *lte_contexts[MAX_UE];
int context_count = 0;

void *hash_table[TABLE_SIZE];

// Function to create a new UE context
LTE_Context *create_ue_context(int ue_id, char *last_known_position, int num_services) {
    LTE_Context *context = (LTE_Context *)malloc(sizeof(LTE_Context));
    if (context != NULL) {
        context->ue_id = ue_id;
        strcpy(context->last_known_position, last_known_position);
        context->num_services = num_services;
        context->services = (char **)malloc(num_services * sizeof(char *));
        // Initialize services
        for (int i = 0; i < num_services; i++) {
            context->services[i] = (char *)malloc(BUFFER_SIZE);
        }
    }
    return context;
}

// Function to add a UE context to the hash table
void add_ue_context(int ue_id, char *last_known_position, int num_services) {
    LTE_Context *context = create_ue_context(ue_id, last_known_position, num_services);
    if (context != NULL) {
        int index = ue_id % TABLE_SIZE;
        pthread_mutex_lock(&((UE_Handler *)hash_table[index])->mutex);
        lte_contexts[context_count] = context;
        context_count++;
        pthread_mutex_unlock(&((UE_Handler *)hash_table[index])->mutex);
    }
}

// Function to retrieve a UE context from the hash table
LTE_Context *get_ue_context(int ue_id) {
    int index = ue_id % TABLE_SIZE;
    pthread_mutex_lock(&((UE_Handler *)hash_table[index])->mutex);
    for (int i = 0; i < context_count; i++) {
        if (lte_contexts[i]->ue_id == ue_id) {
            LTE_Context *context = lte_contexts[i];
            pthread_mutex_unlock(&((UE_Handler *)hash_table[index])->mutex);
            return context;
        }
    }
    pthread_mutex_unlock(&((UE_Handler *)hash_table[index])->mutex);
    return NULL; // UE not found
}

// Function to update a UE context's last known position and services
void update_ue_context(int ue_id, char *last_known_position, int num_services) {
    LTE_Context *context = get_ue_context(ue_id);
    if (context != NULL) {
        strcpy(context->last_known_position, last_known_position);
        // Update services
        for (int i = 0; i < num_services; i++) {
            context->services[i] = (char *)malloc(BUFFER_SIZE);
            // Initialize service details
        }
    }
}

// Function to free memory allocated for a UE context
void free_ue_context(LTE_Context *context) {
    if (context != NULL) {
        for (int i = 0; i < context->num_services; i++) {
            free(context->services[i]);
        }
        free(context);
    }
}

// Function to initialize the hash table and UE handlers
void init_ue_system() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        hash_table[i] = malloc(sizeof(UE_Handler));
        pthread_mutex_init(&((UE_Handler *)hash_table[i])->mutex, NULL);
    }
}

// Function to cleanup UE system
void cleanup_ue_system() {
    for (int i = 0; i < context_count; i++) {
        free_ue_context(lte_contexts[i]);
    }
    for (int i = 0; i < TABLE_SIZE; i++) {
        free(hash_table[i]);
    }
}

int main() {
    // Initialize UE system
    init_ue_system();

    // Add UE contexts to the hash table
    add_ue_context(1, "Position 1", 3);
    add_ue_context(2, "Position 2", 4);
    add_ue_context(3, "Position 3", 5);

    // Retrieve and update a UE context
    LTE_Context *context = get_ue_context(1);
    if (context != NULL) {
        update_ue_context(1, "New Position 1", 2);
    }

    // Clean up UE system
    cleanup_ue_system();

    return 0;
}
