#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct UE_Context {
    uint32_t ue_id;
    uint16_t tli;
    uint16_t qfi;
    int8_t priority;
} UE_Context;

typedef struct Node {
    UE_Context data;
    struct Node* left;
    struct Node* right;
} Node;

Node* insert(Node* root, UE_Context data) {
    if (root == NULL) {
        root = (Node*)malloc(sizeof(Node));
        root->data = data;
        root->left = NULL;
        root->right = NULL;
        return root;
    }

    if (data.tli < root->data.tli) {
        root->left = insert(root->left, data);
    } else if (data.tli > root->data.tli) {
        root->right = insert(root->right, data);
    } else {
        // Handle duplicate TLI
        printf("Duplicate TLI detected!\n");
        return root;
    }

    return root;
}

Node* delete(Node* root, UE_Context data) {
    if (root == NULL) {
        return root;
    }

    if (data.tli < root->data.tli) {
        root->left = delete(root->left, data);
    } else if (data.tli > root->data.tli) {
        root->right = delete(root->right, data);
    } else {
        // Delete the node with matching TLI
        Node* temp = NULL;
        if (root->left == NULL) {
            temp = root;
            root = root->right;
            free(temp);
        } else if (root->right == NULL) {
            temp = root;
            root = root->left;
            free(temp);
        } else {
            Node* min = find_min(root->right);
            root->data = min->data;
            root->right = delete(root->right, min->data);
        }
    }

    return root;
}

Node* find_min(Node* node) {
    while (node && node->left != NULL) {
        node = node->left;
    }
    return node;
}

void free_tree(Node* root) {
    if (root == NULL) {
        return;
    }

    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

// Dynamic list of LTE UE Contexts
Node** ue_contexts = NULL;
int max_size = 5000;

void init_ue_contexts() {
    max_size = 5000;
    ue_contexts = (Node**)malloc(max_size * sizeof(Node*));
    for (int i = 0; i < max_size; i++) {
        ue_contexts[i] = NULL;
    }
}

void delete_ue_contexts() {
    for (int i = 0; i < max_size; i++) {
        Node* temp = ue_contexts[i];
        while (temp) {
            Node* next = temp->right;
            free(temp);
            temp = next;
        }
        ue_contexts[i] = NULL;
    }
    free(ue_contexts);
}

int main() {
    init_ue_contexts();
    // Insert UE contexts into the list
    for (int i = 0; i < max_size; i++) {
        UE_Context data;
        // Set random priority and TLI for demonstration purposes
        data.tli = rand() % 10000;
        data.qfi = rand() % 10000;
        data.priority = rand() % 2 - 1; // Randomly set priority level (-1 or 0)
        ue_contexts[i] = insert(ue_contexts[i], data);
    }

    // Example usage: Insert and delete UE contexts based on TLI
    int tli_to_insert = 5000;
    UE_Context new_data;
    new_data.tli = tli_to_insert;
    new_data.qfi = rand() % 10000;
    new_data.priority = rand() % 2 - 1; // Randomly set priority level (-1 or 0)
    ue_contexts[tli_to_insert] = insert(ue_contexts[tli_to_insert], new_data);

    int tli_to_delete = 3000;
    UE_Context data_to_delete;
    data_to_delete.tli = tli_to_delete;
    data_to_delete.qfi = rand() % 10000;
    data_to_delete.priority = rand() % 2 - 1; // Randomly set priority level (-1 or 0)
    delete(ue_contexts[tli_to_delete], data_to_delete);

    delete_ue_contexts();
    return 0;
}

