NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_indication_pdu(int num_entries, int max_unique_rntis) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    size_t allocated_size = 0;

    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = NULL;

        if ((entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
            log_message("Memory allocation failed for RNTI entry");
            return NULL;
        }

        int rnti = rand() % max_unique_rntis;

        if (array != NULL && find_duplicate(array, allocated_size, rnti)) {
            // Reassign CRCFLAG until a unique RNTI is found
            while (find_duplicate(array, allocated_size, rnti)) {
                rnti = rand() % max_unique_rntis;
            }
        }

        strcpy(entry->rx_ue_info_tag, "RX_UE_INFORMATION_TAG"); // Fill in the rest of the entry structure
        entry->rnti = rnti;

        if (array == NULL) {
            array = entry;
            allocated_size = 1;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* prev_entry = array;
            for (size_t j = 0; j < allocated_size; j++) {
                if (j == allocated_size - 1 || rnti != prev_entry->rnti) {
                    array = realloc(array, (allocated_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                    memcpy(&array[allocated_size], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
                    allocated_size++;
                    break;
                }
                prev_entry = &array[j];
            }
        }

        free(entry);
    }

    return array;
}

int find_duplicate(NFAPI_CRC_INDICATION_PDU_T* array, size_t size, int target_rnti) {
    for (size_t i = 0; i < size; i++) {
        if (array[i].rnti == target_rnti) {
            return 1;
        }
    }

    return 0;
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* array = create_nfa_pi_crc_indication_pdu(100, 50);
    if (array != NULL) {
        log_message("Array created successfully");
        // Use the array...
        free(array); // Don't forget to release memory when done
    } else {
        log_message("Memory allocation failed");
    }

    return 0;
}
