#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure to hold NFAPI_CRC_INDICATION_PDU_T information
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure to represent a linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new linked list node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Function to add a new entry to the linked list
void add_entry(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = create_node(new_data);
    if (*head_ref == NULL || (*head_ref)->data.rnti < new_node->data.rnti) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        Node* current = *head_ref;
        while (current->next && current->next->data.rnti >= new_node->data.rnti)
            current = current->next;
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Function to update an existing entry based on RNTI
void update_entry(Node** head_ref, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T updated_data) {
    Node* current = *head_ref;
    while (current) {
        if (current->data.rnti == rnti) {
            current->data = updated_data;
            return;
        }
        current = current->next;
    }
}

// Function to remove an entry by RNTI
void remove_entry(Node** head_ref, RNTI rnti) {
    Node* current = *head_ref;
    Node* previous = NULL;
    while (current && current->data.rnti != rnti)
        current = current->next;
    if (!current)
        return;
    if (!previous)
        *head_ref = current->next;
    else
        previous->next = current->next;
    free(current);
}

// Function to print the linked list
void print_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data.rnti, current->data.crcflag);
        current = current->next;
    }
}

// Function to perform thread-safe operations on the linked list
void* thread_safe_operations(void* arg) {
    Node** head_ref = (Node**)arg;
    // Perform operations on the linked list here, for example:
    add_entry(head_ref, new_data);
    update_entry(head_ref, rnti, updated_data);
    remove_entry(head_ref, rnti);
    print_list(*head_ref);

    return NULL;
}

// Function to initialize and run multiple threads
void thread_execution(Node** head_refs, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        // Initialize the head reference for each thread
        *head_refs[i] = NULL;
        pthread_create(&threads[i], NULL, &thread_safe_operations, (void*)head_refs + i);
    }
    for (int i = 0; i < num_threads; i++)
        pthread_join(threads[i]);
}

// Main function to test the code
int main() {
    Node* head1 = NULL;
    add_entry(&head1, new_data);

    Node* head2 = NULL;
    add_entry(&head2, new_data);

    int num_threads = 3;
    thread_execution(&head1, num_threads);
    thread_execution(&head2, num_threads);

    return 0;
}
