        sprintf(packets[i].Source_IP, "%s%s", "10.0.", source_ip_suffix);
        sprintf(packets[i].Destination_IP, "%s%s", "20.0.", destination_ip_suffix);

        packets[i].Payload = (char*)malloc((max_payload_size + 1) * sizeof(char));
        if (!packets[i].Payload) {
