#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INTERFACES 10
#define MAX_NAME_LENGTH 30
#define MAX_IP_ADDRESS_LENGTH 20
#define MAX_SUBNET_MASK_LENGTH 15
#define MAX_GATEWAY_ADDRESS_LENGTH 17
#define MAX_DNS_SERVERS 5

typedef struct {
    char name[MAX_NAME_LENGTH];
    char ip_address[MAX_IP_ADDRESS_LENGTH];
    char subnet_mask[MAX_SUBNET_MASK_LENGTH];
    char gateway_address[MAX_GATEWAY_ADDRESS_LENGTH];
    char dns_servers[MAX_DNS_SERVERS][MAX_IP_ADDRESS_LENGTH];
} InterfaceConfig;

void createInterfaceArray(int numInterfaces, InterfaceConfig **interface_array) {
    *interface_array = (InterfaceConfig **)malloc(numInterfaces * sizeof(InterfaceConfig *));
    for (int i = 0; i < numInterfaces; i++) {
        (*interface_array)[i] = (InterfaceConfig *)malloc(sizeof(InterfaceConfig));
    }
}

void validateAndUpdateInterfaceArray(int numInterfaces, InterfaceConfig **interface_array) {
    char unique_interfaces[MAX_INTERFACES][MAX_NAME_LENGTH];
    int unique_count = 0;

    for (int i = 0; i < numInterfaces; i++) {
        if (strlen((*interface_array)[i]->name) > 0) {
            int j;
            for (j = 0; j < unique_count; j++) {
                if (!strcmp((*interface_array)[i]->name, unique_interfaces[j])) {
                    break;
                }
            }
            if (j == unique_count) {
                strcpy(unique_interfaces[unique_count], (*interface_array)[i]->name);
                unique_count++;
                if (unique_count >= MAX_INTERFACES) {
                    printf("Error: Maximum number of interfaces exceeded.\n");
                    return;
                }
            } else {
                printf("Warning: Duplicate interface name detected - %s\n", (*interface_array)[i]->name);
                // update the configuration settings accordingly
                strcpy((*interface_array)[i]->name, unique_interfaces[j]);
            }
        }
    }

    for (int i = 0; i < numInterfaces; i++) {
        printf("Interface: %s - IP Address: %s, Subnet Mask: %s, Gateway Address: %s\n",
               (*interface_array)[i]->name, (*interface_array)[i]->ip_address,
               (*interface_array)[i]->subnet_mask, (*interface_array)[i]->gateway_address);
        for (int j = 0; j < MAX_DNS_SERVERS; j++) {
            printf("DNS Server: %s\n", (*interface_array)[i]->dns_servers[j]);
        }
    }
}

int main() {
    int numInterfaces = 5;
    InterfaceConfig *interface_array;

    createInterfaceArray(numInterfaces, &interface_array);

    // Initialize interface configurations
    for (int i = 0; i < numInterfaces; i++) {
        strcpy(interface_array[i]->name, "eth");
        strcpy(interface_array[i]->ip_address, "192.168.1.");
        strcpy(interface_array[i]->subnet_mask, "255.255.255.0");
        strcpy(interface_array[i]->gateway_address, "192.168.1.1");
        strcpy(interface_array[i]->dns_servers[0], "8.8.8.8");
    }

    validateAndUpdateInterfaceArray(numInterfaces, &interface_array);

    for (int i = 0; i < numInterfaces; i++) {
        free(interface_array[i]);
    }
    free(interface_array);

    return 0;
}
