    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaapi_crc_indication_pdu_ts(int count) {
    NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_indication_pdu_ts = NULL;
    int i, rnti;

    // Configure the logging mechanism
    FILE* log_file = fopen("nfaapi_crc_indication_pdu_t.log", "w");
    if (log_file == NULL) {
        return NULL; // unable to open log file
    }
    setbuf(log_file, NULL);

    for (i = 0; i < count; i++) {
        nfaapi_crc_indication_pdu_ts = realloc(nfaapi_crc_indication_pdu_ts, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1));
        if (!nfaapi_crc_indication_pdu_ts) {
            fclose(log_file);
            return NULL; // out of memory
        }

        NFAPI_CRC_INDICATION_PDU_T nfaapi_crc_indication_pdu_t;
        rnti = rand() % 0x3FFF + 1;

        if (rnti < 0x0001 || rnti > 0x3FFF) {
            // invalid RNTI, skip this entry
            fprintf(log_file, "Warning: Skipping NFAPI_CRC_INDICATION_PDU_T with invalid RNTI (0x%04X)\n", rnti);
            continue;
        }

        nfaapi_crc_indication_pdu_t.RX_UE_INFORMATION_TAG = i % 0xFFFF;
        nfaapi_crc_indication_pdu_t.RNTI = rnti;
        nfaapi_crc_indication_pdu_t.CRC_INDICATION_REL8_TAG = i % 0xFFFF;
        nfaapi_crc_indication_pdu_t.CRCFLAG = rand() & 0xFF;

        if ((uintptr_t)&nfaapi_crc_indication_pdu_t % ALIGNMENT_BOUNDARY) {
            // align the structure to the specified boundary
            void* aligned_ptr = (void*)(((uintptr_t)&nfaapi_crc_indication_pdu_t + ALIGNMENT_BOUNDARY - 1) & ~(ALIGNMENT_BOUNDARY - 1));
            nfaapi_crc_indication_pdu_ts[i] = *(NFAPI_CRC_INDICATION_PDU_T*)aligned_ptr;
        } else {
            nfaapi_crc_indication_pdu_ts[i] = nfaapi_crc_indation_pdu_t;
        }
    }

    fclose(log_file);
    return nfaapi_crc_indication_pdu_ts;
}
