// Thread-safe dynamic list of NFAPI_CRC_INDICATION_PDU_T
struct nfa_list {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* elements;
    pthread_mutex_t mutex;
};

nfa_list* nfa_init(int initial_capacity) {
    nfa_list* list = (nfa_list*)malloc(sizeof(nfa_list));
    list->size = 0;
    list->capacity = initial_capacity;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void nfa_insert(nfa_list* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity / 2) {
        // Reallocate memory to maintain performance
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    list->elements[list->size] = element;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* nfa_get(nfa_list* list, int index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= 0 && index < list->size) {
        NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[index];
        pthread_mutex_unlock(&list->mutex);
        return element;
    }
    // Handle invalid index
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void nfa_remove(nfa_list* list, int index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= 0 && index < list->size) {
        // Shift elements down to fill the gap
        for (int i = index; i < list->size - 1; i++) {
            list->elements[i] = list->elements[i + 1];
        }
        free(list->elements[list->size]);
        list->size--;
    }
    pthread_mutex_unlock(&list->mutex);
}

void nfa_free(nfa_list* list) {
    if (list != NULL) {
        for (int i = 0; i < list->size; i++) {
            free(list->elements[i].ue_info.tag);
            free(list->elements[i].crc_ind.tag);
        }
        free(list->elements);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}
