int log_entries = 0;

// Logging function
void log_operation(char *operation) {
    pthread_mutex_lock(&lock);
    if (log_entries < LOG_BUFFER_SIZE) {
        printf("Operation: %s, Time: %ld\n", operation, time(NULL));
        log_entries++;
    }
    pthread_mutex_unlock(&lock);
}

int list_add(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&lock);
    if (list_size >= MAX_LIST_SIZE) {
        // List overflow handling
        printf("List overflow. Cannot add element.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }
    if (list_size >= list_capacity) {
        // Resize the list to maintain efficiency
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list_capacity * 2));
        if (!new_list) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }
        list = new_list;
        list_capacity *= 2;
    }
    list[list_size] = *element;
    list_size++;
    log_operation("Add");
    pthread_mutex_unlock(&lock);
    return 0;
}

int list_remove(int index) {
    pthread_mutex_lock(&lock);
    if (index >= list_size || index < 0) {
        // Out-of-range index handling
