        ue->allocatedBandwidth = allocatedBandwidth;

        // Update the network settings
        totalBandwidth -= allocatedBandwidth;
        currentPriority = ue->priority;

        printf("Configured UE %d with frequency band: %s, priority: %d, and bandwidth allocation: %d\n", 
