#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void manage_crc_indications(int num_crc_indications, NFAPI_CRC_INDICATION_PDU_T **crc_indications) {
    // Initialize the total number of processed CRC indications
    int total_crc_indications = 0;

    // Sort the array to ensure efficient lookup by RNTI
    qsort(*crc_indications, num_crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    while (1) {
        printf("Enter operation:\n");
        printf("1. Add CRC indication\n");
        printf("2. Update CRC indication\n");
        printf("3. Remove CRC indication\n");
        printf("4. Generate performance report and exit\n");
        int op;
        scanf("%d", &op);

        switch (op) {
            case 1:
                // Add a new CRC indication
                add_crc_indication(crc_indications, &num_crc_indications);
                break;
            case 2:
                // Update an existing CRC indication
                update_crc_indication(crc_indications, &num_crc_indications);
                break;
            case 3:
                // Remove a CRC indication
                remove_crc_indication(crc_indications, &num_crc_indications);
                break;
            case 4:
                // Generate the performance report and exit
                generate_performance_report(total_crc_indications);
                free(*crc_indications);
                *crc_indications = NULL;
                return;
            default:
                printf("Invalid operation. Please try again.\n");
        }
    }

    return;

}

int compare_rnti(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *indication_a = (NFAPI_CRC_INDICATION_PDU_T *) a;
    NFAPI_CRC_INDICATION_PDU_T *indication_b = (NFAPI_CRC_INDICATION_PDU_T *) b;

    if (indication_a->RNTI < indication_b->RNTI) {
        return -1;
    } else if (indication_a->RNTI > indication_b->RNTI) {
        return 1;
    } else {
        return 0;
    }
}

void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T **crc_indications, int *num_crc_indications) {
    // Check for duplicate RNTI
    NFAPI_CRC_INDICATION_PDU_T *new_indication = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    printf("Enter RX_UE_INFORMATION_TAG and RNTI for new CRC indication:\n");
    scanf("%d %d", &new_indication->RX_UE_INFORMATION_TAG, &new_indication->RNTI);
    if (binary_search(*crc_indications, *num_crc_indications, new_indication)) {
        printf("Duplicate RNTI detected. Operation cancelled.\n");
        free(new_indication);
        return;
    }

    // Add the new CRC indication
    (*num_crc_indications)++;
    *crc_indications = (NFAPI_CRC_INDICATION_PDU_T **)realloc(*crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (*num_crc_indications));
    (*crc_indications)[*num_crc_indications - 1] = new_indication;
}

int binary_search(NFAPI_CRC_INDICATION_PDU_T *crc_indications, int num_crc_indications, NFAPI_CRC_INDICATION_PDU_T *new_indication) {
    int left = 0;
    int right = num_crc_indications;

    while (left <= right) {
        int mid = (left + right) / 2;

        if (crc_indications[mid]->RNTI == new_indication->RNTI) {
            return 1; // Duplicate RNTI found
        } else if (crc_indications[mid]->RNTI < new_indication->RNTI) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return 0; // No duplicate RNTI found
}

void update_crc_indication(NFAPI_CRC_INDICATION_PDU_T **crc_indications, int *num_crc_indications) {
    printf("Enter the RNTI of the CRC indication to be updated:\n");
    int rnti;
    scanf("%d", &rnti);

    // Find the CRC indication with the given RNTI
    NFAPI_CRC_INDICATION_PDU_T *target_indication = find_crc_indication(crc_indications, num_crc_indications, rnti);
    if (target_indication == NULL) {
        printf("CRC indication not found.\n");
        return;
    }

    // Update the CRC indication
    printf("Enter the new RX_UE_INFORMATION_TAG and RNTI for the updated CRC indication:\n");
    int new_rx_ue_information_tag, new_rnti;
    scanf("%d %d", &new_rx_ue_information_tag, &new_rnti);
    target_indication->RX_UE_INFORMATION_TAG = new_rx_ue_information_tag;
    target_indication->RNTI = new_rnti;

}

NFAPI_CRC_INDICATION_PDU_T *find_crc_indication(NFAPI_CRC_INDICATION_PDU_T **crc_indications, int num_crc_indications, int rnti) {
    // Perform a binary search to find the CRC indication with the given RNTI
    int left = 0;
    int right = num_crc_indications;

    while (left <= right) {
        int mid = (left + right) / 2;

        if (crc_indications[mid]->RNTI == rnti) {
            return crc_indications[mid]; // Found the CRC indication with the given RNTI
        } else if (crc_indications[mid]->RNTI < rnti) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return NULL; // No CRC indication found with the given RNTI
}

void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T **crc_indications, int *num_crc_indications) {
    printf("Enter the RNTI of the CRC indication to be removed:\n");
    int rnti;
    scanf("%d", &rnti);

    // Find the CRC indication with the given RNTI
    NFAPI_CRC_INDICATION_PDU_T *target_indication = find_crc_indication(crc_indications, *num_crc_indications, rnti);
    if (target_indication == NULL) {
        printf("CRC indication not found.\n");
        return;
    }

    // Remove the CRC indication
    int i;
    for (i = 0; i < *num_crc_indications - 1; i++) {
        crc_indications[i] = crc_indications[i + 1];
    }
    free(target_indication);
    (*num_crc_indications)--;

}

void generate_performance_report(int total_crc_indications) {
    printf("Total CRC indications processed: %d\n", total_crc_indications);
}
