    }

    // Initialize current time and last update time
    clock_t start_time = clock();
    clock_t last_update_time = start_time;

    while (1) {
        // Check if maximum size is reached
        if (total_crcs >= max_size) {
            printf("Maximum list size reached. Aborting...\n");
            break;
        }

