                if (rnti > 0 && rnti <= 1000) {
                    unique_rntis++;
                }

                // Update last update time
                last_update_time = clock();

                break;
            case 2:
                // Update existing CRC indication based on RNTI
                int rnti_to_update;
                printf("Enter the RNTI to update: ");
                scanf("%d", &rnti_to_update);

                for (int i = 0; i < max_size && crc_list[i] != NULL; i++) {
                    if (crc_list[i]->RNTI == rnti_to_update) {
