                        crc_list[i]->CRCFLAG = new_crcflag;

                        break;
                    }
                }

                if (i >= max_size) {
                    printf("RNTI not found. Cannot update.\n");
                }

                break;
            case 3:
                // Remove CRC indication based on RNTI
                int rnti_to_remove;
                printf("Enter the RNTI to remove: ");
                scanf("%d", &rnti_to_remove);

                for (int i = 0; i < max_size && crc_list[i] != NULL; i++) {
                    if (crc_list[i]->RNTI == rnti_to_remove) {
                        // Remove CRC indication structure
                        free(crc_list[i]);
                        crc_list[i] = NULL;

                        break;
                    }
                }

                if (i >= max_size) {
                    printf("RNTI not found. Cannot remove.\n");
                }

                break;
            case 4:
                // Generate report with CRC indication statistics
                printf("\nTotal CRC indications: %d\n", total_crcs);
                printf("Unique RNTI values: %d\n", unique_rntis);
                printf("Average CRCFLAG value: %.2f\n", (double)total_crcs / unique_rntis);
                printf("Minimum CRCFLAG value: %d\n", crc_list[0]->CRCFLAG);
                printf("Maximum CRCFLAG value: %d\n", crc_list[max_size-1]->CRCFLAG);

                // Update last update time
                last_update_time = clock();

                break;
            case 5:
                // Exit the program
                free(crc_list);
                return;
        }

        // Check if timeout reached
        if (clock() - start_time > timeout) {
            printf("Timeout reached. Aborting...\n");
            break;
        }
    }

    // Free allocated memory
    for (int i = 0; i < max_size && crc_list[i] != NULL; i++) {
        free(crc_list[i]);
    }
