#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <random>

struct record {
    const char* key;
    long offset;
    int value;
};

struct record* initialize_records(int key_size, int offset_size, int min_value, int max_value) {
    if (key_size <= 0 || offset_size <= 0 || min_value > max_value) {
        return NULL; // invalid input
    }

    struct record* records = (struct record*)malloc((key_size * offset_size) * sizeof(struct record));
    if (!records) {
        return NULL; // memory allocation failed
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min_value, max_value);

    for (int i = 0; i < key_size * offset_size; i++) {
        records[i].key = generate_key(i);
        records[i].offset = (long)i;
        records[i].value = dis(gen);
    }

    return records;
}
