public class UserProfiler {
    private Map<String, Long> userAvailabilityMap;
    private Map<String, UnionFind> groupMap;

    public void processUserProfiles(Map<String, String> profiles) {
        for (Map.Entry<String, String> entry : profiles.entrySet()) {
            String userId = entry.getKey();
            String groupId = entry.getValue();

            if (!userAvailabilityMap.containsKey(userId)) {
                userAvailabilityMap.put(userId, System.currentTimeMillis());
            }

            UnionFind unionFind = groupMap.get(groupId);
            if (unionFind == null) {
                unionFind = new UnionFind(groupId);
                groupMap.put(groupId, unionFind);
            }

            if (!isAvailable(userId)) {
                continue;
            }

            unionFind.union(userId);
        }
    }

    public void handleUserAvailability(String userId) {
        if (!userAvailabilityMap.containsKey(userId)) {
            return;
        }

        long availabilityTime = userAvailabilityMap.get(userId);
        if (System.currentTimeMillis() - availabilityTime > 1000 * 60 * 30) { // 30 minutes
            userAvailabilityMap.remove(userId);
        }
    }

    public void logMetrics() {
        System.out.println("Processing Time: " + processingTime());
        System.out.println("Memory Consumption: " + memoryConsumption());
        System.out.println("Group Stability: " + groupStability());
    }

