        PHY_LAYER_RX_STATS_T* new_cell = (PHY_LAYER_RX_STATS_T*)malloc(sizeof(PHY_LAYER_RX_STATS_T));
        new_cell->cell_id = cell_id;
        new_cell->tx_power_level = tx_power_level;
        new_cell->received_signal_strength = received_signal_strength;

        // Check for duplicate cell ID values
        if (*size > 0) {
            for (int i = 0; i < *size; i++) {
                if (array[i]->cell_id == cell_id) {
                    free(new_cell);
                    return;
                }
            }
        }

        // Dynamically allocate memory to the array and insert the new cell
        (*array) = (PHY_LAYER_RX_STATS_T**)realloc(*array, (*size + 1) * sizeof(PHY_LAYER_RX_STATS_T *));
        array[(*size)] = new_cell;
        (*size)++;
    }

