        for (int i = 0; i < *size; i++) {
            if (array[i]->tx_power_level < tx_power_level_threshold) {
                // Dynamically deallocate the cell that fails the filter condition
                free(array[i]);
                memmove(&array[i], &array[i + 1], (*size - i - 1) * sizeof(PHY_LAYER_RX_STATS_T *));
                (*size)--;
                i--;  // Decrement the index to re-scan the array after the move
