#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define N 50000
#define MAX_RNTI 0xFFFFFFFF

typedef struct {
    int rnti;
    char crcflag[1];
} NFAPI_CRC_INDICATION_PDU_T;

void sort_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t n) {
    qsort(array, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare);
}

int compare(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *x = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *y = (NFAPI_CRC_INDICATION_PDU_T *)b;

    if (x->rnti < y->rnti) {
        return -1;
    } else if (x->rnti > y->rnti) {
        return 1;
    }

    return 0;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    srand(time(NULL));

    for (size_t i = 0; i < N; i++) {
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1));
        if (!array) {
            printf("Memory allocation failed!\n");
            free(array);
            return 1;
        }

        array[i].rnti = rand() % MAX_RNTI;
        strcpy(array[i].crcflag, "CRCFLAG_");

        // Log each element's details
        printf("RNTI: %d, CRC FLAG: %s\n", array[i].rnti, array[i].crcflag);
    }

    // Sort the array
    sort_array(array, N);

    // Validate integrity of data after allocation and sorting
    for (size_t i = 0; i < N - 1; i++) {
        if (array[i].rnti > array[i + 1].rnti) {
            printf("Error: duplicate RNTI values found!\n");
            return 1;
        }
    }

    // Validate CRC indications
    for (size_t i = 0; i < N; i++) {
        if (array[i].crcflag != "CRCFLAG_") {
            printf("Error: incorrect CRC FLAG encountered!\n");
