void* nfa_pi_crc_indication_pdu_t_list_create(int N, void* (*func)(int), int(*free_func)(void*)) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Initialize head of the linked list
    node *head = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.rx_ue_info = func(i);
        data.RNTI = rand() % 1000;
        data.crc_indication_rel8_tag = malloc(sizeof(CRC_INDICATION_REL8_TAG));
