        if (rand() % 2) {
            data.CRCFLAG = 1;
        } else {
            data.CRCFLAG = 0;
        }
        node *new_node = create_node(data);
        pthread_mutex_lock(&mutex);
        if (head == NULL) {
            head = new_node;
        } else {
            node *temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
        pthread_mutex_unlock(&mutex);
