// Function to free the linked list nodes and data
void nfa_pi_crc_indication_pdu_t_list_free(void* node) {
    if (node == NULL)
        return;

    node *temp = node;

    while (temp != NULL) {
        NFAPI_CRC_INDICATION_PDU_T data = temp->data;
        free(data.rx_ue_info);
        free(data.crc_indication_rel8_tag);
        temp = temp->next;
    }
}

// Function to serialize the linked list into a binary file
int nfa_pi_crc_indication_pdu_t_list_serialize(void* node, FILE *file) {
