    while (temp != NULL) {
        NFAPI_CRC_INDICATION_PDU_T data = temp->data;
        fwrite(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        temp = temp->next;
    }
    return 1;
}

