#define TABLE_SIZE 1024
#define MAX_ENTRY 4096

typedef struct {
    uint32_t pdcp_pdu;
    L3_PDU* l3_pdu;
} Entry;

typedef struct {
    Entry** table;
    pthread_mutex_t mutex;
    int size;
    int count;
} HashTable;

void init_hash_table(HashTable* hash_table) {
    hash_table->size = TABLE_SIZE;
    hash_table->count = 0;
    hash_table->table = (Entry**)malloc(sizeof(Entry*) * hash_table->size);
    for (int i = 0; i < hash_table->size; i++) {
        hash_table->table[i] = NULL;
    }
    pthread_mutex_init(&hash_table->mutex, NULL);
}

void insert_pdcp_pdu(HashTable* hash_table, uint32_t pdcp_pdu, L3_PDU* l3_pdu) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->pdcp_pdu = pdcp_pdu;
    entry->l3_pdu = l3_pdu;
    int index = pdcp_pdu % hash_table->size;
    pthread_mutex_lock(&hash_table->mutex);
    if (hash_table->table[index] == NULL) {
        hash_table->table[index] = entry;
    } else {
        Entry* current = hash_table->table[index];
        while (current != NULL) {
            if (current->pdcp_pdu == pdcp_pdu) {
                free(current);
                break;
            }
            current = current->next;
        }
        if (current == NULL) {
            entry->next = hash_table->table[index];
            hash_table->table[index] = entry;
        }
    }
    pthread_mutex_unlock(&hash_table->mutex);
}

L3_PDU* get_pdcp_pdu(HashTable* hash_table, uint32_t pdcp_pdu) {
    int index = pdcp_pdu % hash_table->size;
    pthread_mutex_lock(&hash_table->mutex);
    Entry* entry = hash_table->table[index];
    while (entry != NULL) {
        if (entry->pdcp_pdu == pdcp_pdu) {
            L3_PDU* l3_pdu = entry->l3_pdu;
            free(entry);
            pthread_mutex_unlock(&hash_table->mutex);
            return l3_pdu;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&hash_table->mutex);
    return NULL;
}

void destroy_hash_table(HashTable* hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        Entry* current = hash_table->table[i];
        while (current != NULL) {
            Entry* next = current->next;
            free(current);
            current = next;
        }
    }
    free(hash_table->table);
    pthread_mutex_destroy(&hash_table->mutex);
}

void check_checksum(L3_PDU* l3_pdu) {
    // Implement checksum validation logic here
