    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_array(int n) {
    // Create memory pool for dynamic array
    size_t pool_size = 10000 * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void* pool = malloc(pool_size);

    if (!pool) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)pool;

    for (int i = 0; i < n; i++) {
        // Generate unique RNTI values
        uint16_t rnti = rand() % 65536;
        bool is_duplicate = false;

        for (int j = 0; j < i; j++) {
            if (array[j].rx_ue_info_tag.rnti == rnti) {
                is_duplicate = true;
                break;
            }
        }

        if (is_duplicate) {
            // Resolve conflict by incrementing RNTI value
            do {
                rnti = rand() % 65536;
            } while (array[j].rx_ue_info_tag.rnti == rnti);
        }

        array[i].rx_ue_info_tag.seq_num = i + 1;
        array[i].rx_ue_info_tag.rnti = rnti;
        array[i].crc_indication_rel8_tag.crcflag = rand() % 2;

        // Ensure thread safety when accessing shared resources
        pthread_mutex_lock();
        pthread_mutex_unlock();
    }

    return array;
}
