    char s1_ue_context_tag[17];
    time_t rrc_connection_setup_complete_timestamps[MAX_UES];
} lte_ue_context;

void *ue_context_array = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int array_size = 0;

void add_ue_context(int ue_id, char *s1_ue_context_tag) {
    pthread_mutex_lock(&lock);

    // Validate UE ID and S1 UE Context Tag
    if (ue_id < 0 || strlen(s1_ue_context_tag) > 16) {
        printf("Invalid UE ID or S1 UE Context Tag\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    lte_ue_context *new_ue_context = (lte_ue_context *) realloc(ue_context_array, sizeof(lte_ue_context) * ++array_size);
    if (!new_ue_context) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    ue_context_array = new_ue_context;

    new_ue_context->ue_id = ue_id;
    strcpy(new_ue_context->s1_ue_context_tag, s1_ue_context_tag);

    // Initialize RRC Connection Setup Complete indicators with random timestamps
    for (int i = 0; i < MAX_UES; i++) {
        new_ue_context->rrc_connection_setup_complete_timestamps[i] = time(NULL);
    }

    pthread_mutex_unlock(&lock);
}

void remove_ue_context(int ue_id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        if (ue_context_array[i].ue_id == ue_id) {
            // Remove UE context from the array
            memmove(&ue_context_array[i], &ue_context_array[i + 1], sizeof(lte_ue_context) * (array_size - i - 1));
            free(ue_context_array);
            array_size--;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    // Initialize UE context array with initial capacity
    ue_context_array = (void *) calloc(UE_CONTEXT_STRUCTS, sizeof(lte_ue_context));

    // Example usage:
    add_ue_context(1, "12345678901234567");
    add_ue_context(2, "23456789012345678");

    // Remove UE context
    remove_ue_context(1);

    return 0;
}
