// Define the NetworkEvent structure
typedef struct {
    long Timestamp;
    int EventID;
    void* EventData;
} NetworkEvent;

// Define the dynamic array type
typedef struct {
    NetworkEvent** Events;
    int Capacity;
    int Size;
} DynamicArray;

// Initialize a new dynamic array
DynamicArray* initDynamicArray(int capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->Capacity = capacity;
    arr->Size = 0;
    arr->Events = (NetworkEvent**)calloc(capacity, sizeof(NetworkEvent*));
    return arr;
}

// Add a new event to the dynamic array
void addEvent(DynamicArray* arr, NetworkEvent* event) {
    if(arr->Size == arr->Capacity) {
        // Double the capacity when full
        int newCapacity = arr->Capacity * 2;
        arr->Events = (NetworkEvent**)realloc(arr->Events, newCapacity * sizeof(NetworkEvent*));
        arr->Capacity = newCapacity;
    }
    arr->Events[arr->Size] = event;
    arr->Size++;
}

// Iterate over all events in the dynamic array
void iterateEvents(DynamicArray* arr, void (*callback)(NetworkEvent*)) {
    for(int i = 0; i < arr->Size; i++) {
        callback(arr->Events[i]);
    }
}

// Free the resources of a dynamic array
void freeDynamicArray(DynamicArray* arr) {
    if(arr != NULL) {
        for(int i = 0; i < arr->Size; i++) {
            free(arr->Events[i]->EventData);
        }
        free(arr->Events);
        free(arr);
    }
}

// Main function to manage the dynamic array
int main() {
    DynamicArray* arr = initDynamicArray(5);

    // Add some events
    addEvent(arr, (NetworkEvent*)malloc(sizeof(NetworkEvent)));
    NetworkEvent event2;
    event2.Timestamp = 12345; event2.EventID = 1; event2.EventData = "EventData";
    addEvent(arr, &event2);

    // Iterate over the events
    iterateEvents(arr, (void (*)(NetworkEvent*))printf);

    // Free the resources
    freeDynamicArray(arr);

    return 0;
}

