// Function to initialize the LTE UE Context Array
lte_ue_context_array* init_lte_ue_context_array(int initial_capacity) {
    lte_ue_context_array* array = (lte_ue_context_array*)malloc(sizeof(lte_ue_context_array));
    array->contexts = (lte_ue_context*)malloc(initial_capacity * sizeof(lte_ue_context));
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Function to add a new LTE UE Context to the array
int add_lte_ue_context_array(lte_ue_context_array* array, int ue_id, char s1_ue_context_tag[], time_t timestamp, int rrc_connection_setup_complete) {
    if (array->size >= array->capacity) {
        // Resize the array if it's full
        array->contexts = (lte_ue_context*)realloc(array->contexts, (array->capacity + 16) * sizeof(lte_ue_context));
        array->capacity += 16;
    }
    pthread_mutex_lock(&array->mutex);
    lte_ue_context* new_context = &array->contexts[array->size++];
    new_context->ue_id = ue_id;
    strcpy(new_context->s1_ue_context_tag, s1_ue_context_tag);
    new_context->timestamp = timestamp;
    new_context->rrc_connection_setup_complete = rrc_connection_setup_complete;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Function to retrieve an LTE UE Context from the array
int get_lte_ue_context_array(lte_ue_context_array* array, int ue_id, lte_ue_context* context) {
    for (int i = 0; i < array->size; i++) {
        if (array->contexts[i].ue_id == ue_id) {
            *context = array->contexts[i];
            return 0;
        }
    }
    return -1;
}

