// Structure to represent LTE UE context
typedef struct {
    int ue_id;
    time_t last_modified;
    struct grant *grants;
} ue_context;

// Structure to represent downlink grant
typedef struct {
    int grant_id;
    time_t timestamp;
    // Additional grant-specific data (e.g., QoS, bandwidth allocation)
} grant;

// Function to add a new grant to the UE context
void add_grant(ue_context *ue_ctx, grant *new_grant) {
    if (ue_ctx->grants == NULL) {
        ue_ctx->grants = malloc(sizeof(grant));
        ue_ctx->grants->grant_id = new_grant->grant_id;
        ue_ctx->grants->timestamp = new_grant->timestamp;
        // Initialize last modified time
        ue_ctx->last_modified = time(NULL);
    } else {
        grant *curr_grant = ue_ctx->grants;
        while (curr_grant != NULL) {
            if (curr_grant->grant_id == new_grant->grant_id) {
                // Update existing grant instead of adding a new one
                curr_grant->timestamp = new_grant->timestamp;
                curr_grant->last_modified = time(NULL);
                return;
            }
            curr_grant = curr_grant->next;
        }
        // Add the new grant to the end of the list
        grant *new_grant_node = malloc(sizeof(grant));
        new_grant_node->grant_id = new_grant->grant_id;
        new_grant_node->timestamp = new_grant->timestamp;
        new_grant_node->next = NULL;
        if (ue_ctx->grants == NULL) {
            ue_ctx->grants = new_grant_node;
        } else {
            grant *curr_node = ue_ctx->grants;
            while (curr_node->next != NULL) {
                curr_node = curr_node->next;
            }
            curr_node->next = new_grant_node;
        }
    }
}

// Function to remove outdated grants from the UE context
void remove_outdated_grants(ue_context *ue_ctx, time_t current_timestamp) {
    grant *curr_grant = ue_ctx->grants;
    while (curr_grant != NULL) {
        if (current_timestamp - curr_grant->timestamp > 60) { // Remove grants older than 1 minute
            grant *next_grant = curr_grant->next;
            free(curr_grant);
            ue_ctx->grants = next_grant;
            break;
        }
        curr_grant = curr_grant->next;
    }
}

// Function to update the last modified time of each grant
void update_last_modified_time(ue_context *ue_ctx) {
    ue_ctx->last_modified = time(NULL);
    if (ue_ctx->grants != NULL) {
        grant *curr_grant = ue_ctx->grants;
        while (curr_grant != NULL) {
            curr_grant->last_modified = time(NULL);
            curr_grant = curr_grant->next;
        }
    }
}

// Function to integrate with the external network management system
void check_health_and_update_status(ue_context *ue_ctx) {
    // Send periodic health checks and status updates to the external system
    // Ensure minimal disruption during these operations
}

// Function to handle potential network interruptions gracefully
void handle_network_interruption(ue_context *ue_ctx) {
    // Recover gracefully upon reconnection, minimizing system downtime
}

int main() {
    ue_context ue_ctx;
    // Initialize UE context with unique ID and grant list
    ue_ctx.ue_id = 12345;
    ue_ctx.grants = NULL;

    // Add new grants to the UE context
    grant new_grant1;
    new_grant1.grant_id = 1;
    new_grant1.timestamp = time(NULL);
    add_grant(&ue_ctx, &new_grant1);

    grant new_grant2;
    new_grant2.grant_id = 2;
    new_grant2.timestamp = time(NULL) - 60; // Outdated grant
    add_grant(&ue_ctx, &new_grant2);

    // Remove outdated grants from the UE context
    remove_outdated_grants(&ue_ctx, time(NULL));

    // Update last modified time of each grant
    update_last_modified_time(&ue_ctx);

    // Integrate with external network management system
    check_health_and_update_status(&ue_ctx);

    return 0;
}

