        // Handle out-of-bounds error
        printf("Invalid product index.\n");
    } else {
        pthread_mutex_lock(&lock);
        memmove(products + index, products + index + 1, sizeof(Product) * (product_count - index - 1));
        product_count--;
        pthread_mutex_unlock(&lock);
