            prev = current;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&lock);

    // Integrate with an external data source for periodic updates
    while (1) {
        // Update the list from the external data source

        // Periodically clean up unused entries in the list based on the configured timeout threshold
        pthread_mutex_lock(&lock);
        current = head;
        prev = NULL;

        while (current != NULL && current->data->CRCFLAG < n) {
            if (time(NULL) - current->data->RX_UE_INFORMATION_TAG > timeout) {
                prev->next = current->next;
                free(current);
                current = current->next;
                prev = current;
            } else {
                current = current->next;
            }
        }

        pthread_mutex_unlock(&lock);

        // Ensure reliable synchronization of the list with external changes
        if (current == NULL) break; // Exit the loop when the list is empty

    }
}

// Function to insert a new node at the end of the linked list
void NFAPI_CRC_INDICATION_PDU_T_Insert(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = createNode(data);
    if (*head == NULL || newNode->data->CRCFLAG > (*head)->data->CRCFLAG) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->data->CRCFLAG <= newNode->data->CRCFLAG)
            current = current->next;

        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to print the linked list
void NFAPI_CRC_INDICATION_PDU_T_Print(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%p %d\n", current->data, current->data->RNTI);
        current = current->next;
    }
}

