    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* data1 = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_CRC_INDICATION_PDU_T* data2 = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_CRC_INDICATION_PDU_T* data3 = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

