    int i;
    int rnti_min = 0;
    int rnti_max = 100; // Assume a maximum RNTI value of 100
    int unique_rntis = 0;
    int *rnti_values;
    int rnti_value_count = 0;
    int strategy = 0;

    // Initialize the random number generator
    srand(time(NULL));

    if ((rnti_values = (int *)malloc((rnti_max + 1) * sizeof(int))) == NULL) {
        printf("Memory allocation for RNTI values failed.\n");
        return;
    }

    for (i = rnti_min; i <= rnti_max; i++) {
        rnti_values[i] = i;
        rnti_value_count++;
    }

    // Fill the pdu list with structures
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        int rnti;

        // Ensure RNTI diversity
        if (unique_rntis < rnti_value_count) {
            do {
                rnti = rand() % (rnti_max - rnti_min + 1) + rnti_min;
            } while (!check_rnti_diversity(rnti, &pdu_list[i], unique_rntis));
        } else {
            // Reuse RNTI values to fill the list
            do {
                rnti = rnti_values[rand() % (unique_rntis + 1)];
            } while (!check_rnti_diversity(rnti, &pdu_list[i], unique_rntis));
        }

        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rnti;
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2;

        (*pdu_list)[i] = pdu;
        if (check_rnti_diversity(rnti, &pdu_list[i], unique_rntis)) {
            unique_rntis++;
        }
    }

    // Log the number of unique RNTI values used
    printf("Unique RNTI values: %d\n", unique_rntis);

    free(rnti_values);
}

int check_rnti_diversity(int rnti, NFAPI_CRC_INDICATION_PDU_T *pdu, int unique_rntis) {
    for (int i = 0; i < unique_rntis; i++) {
        if ((*pdu_list)[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}
