#define RX_UE_INFORMATION_TAG sizeof(struct RX_UE_INFORMATION_TAG)
#define RNTI sizeof(int32_t)
#define CRC_INDICATION_REL8_TAG sizeof(struct CRC_INDICATION_REL8_TAG)

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int32_t RNTI;
    uint16_t CRCFLAG;
    RX_UE_INFORMATION_TAG UE_INFO;
    CRC_INDICATION_REL8_TAG REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* nfa_nxt_node = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
size_t nxt_idx = 0;

void insert(NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&list_lock);
    if (nxt_idx == 0) {
        nfa_nxt_node = malloc(NFAPI_CRC_INDICATION_PDU_T);
        memcpy(nfa_nxt_node, new_entry, NFAPI_CRC_INDICATION_PDU_T);
    } else {
        NFAPI_CRC_INDICATION_PDU_T* cur_ptr = (NFAPI_CRC_INDICATION_PDU_T*)nfa_nxt_node;
        while (cur_ptr->next != NULL) {
            cur_ptr = cur_ptr->next;
        }
        cur_ptr->next = malloc(NFAPI_CRC_INDICATION_PDU_T);
        memcpy(cur_ptr->next, new_entry, NFAPI_CRC_INDICATION_PDU_T);
    }
    pthread_mutex_unlock(&list_lock);
}

void delete(NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&list_lock);
    if (nfa_nxt_node != NULL && nfa_nxt_node == entry) {
        nfa_nxt_node = entry->next;
        free(entry);
    } else {
        NFAPI_CRC_INDICATION_PDU_T* cur_ptr = (NFAPI_CRC_INDICATION_PDU_T*)nfa_nxt_node;
        while (cur_ptr != NULL && cur_ptr->next != entry) {
            cur_ptr = cur_ptr->next;
        }
        if (cur_ptr->next == entry) {
            cur_ptr->next = entry->next;
            free(entry);
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void nfa_cleanup() {
    NFAPI_CRC_INDICATION_PDU_T* cur_ptr = (NFAPI_CRC_INDICATION_PDU_T*)nfa_nxt_node;
    while (cur_ptr != NULL) {
        cur_ptr = cur_ptr->next;
        if (cur_ptr == NULL)
            break;
        cur_ptr = cur_ptr->next;
        free(cur_ptr);
    }
    nfa_nxt_node = NULL;
}

int main() {
    pthread_t thread;
    int32_t RNTI, CRCFLAG;
    RX_UE_INFORMATION_TAG UE_INFO;
    CRC_INDICATION_REL8_TAG REL8_TAG;

    // Initialize variables
    NFAPI_CRC_INDICATION_PDU_T entry;
    entry.RNTI = 0x12345678;
    entry.CRCFLAG = 0x01;
    entry.UE_INFO = { /* RX_UE_INFORMATION_TAG */ };
    entry.REL8_TAG = { /* CRC_INDICATION_REL8_TAG */ };

    // Call insert function
    insert(&entry);

    // Simulate concurrent read operations and thread-safe insertion/deletion
    pthread_create(&thread, NULL, (void*)nfa_thread_func, NULL);
    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(NFAPI_CRC_INDICATION_PDU_T);
        insert(new_entry);
        // Simulate data inconsistencies
        if (i % 2 == 1)
            entry.RNTI++;
        sleep(1);
    }
    pthread_join(thread, NULL);

    return 0;
}

void* nfa_thread_func(void*) {
    while (nxt_idx > 0) {
        NFAPI_CRC_INDICATION_PDU_T* cur_ptr = (NFAPI_CRC_INDICATION_PDU_T*)nfa_nxt_node;
        while (cur_ptr != NULL) {
            printf("%d: %x, %d\n", cur_ptr->RNTI, cur_ptr->CRCFLAG, nxt_idx);
            cur_ptr = cur_ptr->next;
        }
    }
    nfa_cleanup();
}
