#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int id;
    int status;
} DataPacket;

// Lock-free dynamic array of DataPackets
typedef struct {
    DataPacket* packets;
    size_t capacity;
    size_t size;
    pthread_spinlock_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->packets = (DataPacket*)calloc(initial_capacity, sizeof(DataPacket));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_spin_init(&arr->lock, PTHREAD_PROCESS_PRIVATE);
    return arr;
}

void add_packet(DynamicArray* arr, DataPacket packet) {
    if (arr->size >= arr->capacity) {
        // Double the capacity
        size_t new_capacity = arr->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(arr->packets, new_capacity * sizeof(DataPacket));
        arr->packets = new_packets;
        arr->capacity = new_capacity;
    }
    pthread_spin_lock(&arr->lock);
    arr->packets[arr->size] = packet;
    arr->size++;
    pthread_spin_unlock(&arr->lock);
}

DataPacket* find_packet_by_id(DynamicArray* arr, int id) {
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->packets[i].id == id) {
            return &arr->packets[i];
        }
    }
    return NULL;
}

void update_packet_by_id(DynamicArray* arr, int id, DataPacket new_packet) {
    DataPacket* packet = find_packet_by_id(arr, id);
    if (packet != NULL) {
        pthread_spin_lock(&arr->lock);
        *packet = new_packet;
        pthread_spin_unlock(&arr->lock);
    }
}

DataPacket* get_packets_in_range(DynamicArray* arr, int start_time, int end_time) {
    DataPacket* result = (DataPacket*)malloc(sizeof(DataPacket) * (arr->size));
    size_t count = 0;
    for (size_t i = 0; i < arr->size; i++) {
        if (start_time <= arr->packets[i].timestamp && arr->packets[i].timestamp <= end_time) {
            result[count] = arr->packets[i];
            count++;
        }
    }
    return result;
}

void destroy_dynamic_array(DynamicArray* arr) {
    free(arr->packets);
    pthread_spin_destroy(&arr->lock);
    free(arr);
}
