typedef struct {
    int valid_ue_context;
    int mac_transport_context;
    void* user_data;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T* messages;
    int size;
    int capacity;
} NFAPIMessageList_T;

void nfapi_message_list_init(NFAPIMessageList_T* list, int initial_capacity) {
    list->messages = (NFAPI_MESSAGE_T*)calloc(initial_capacity, sizeof(NFAPI_MESSAGE_T));
    list->size = 0;
    list->capacity = initial_capacity;
}

void nfapi_message_list_free(NFAPIMessageList_T* list) {
    free(list->messages);
    list->messages = NULL;
    list->size = 0;
    list->capacity = 0;
}

int nfapi_message_list_add(NFAPIMessageList_T* list, NFAPI_MESSAGE_T message) {
    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2 + 1;
        void* new_messages = realloc(list->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
        list->messages = new_messages;
        list->capacity = new_capacity;
    }
    list->messages[list->size++] = message;
    return 0;
}

void nfapi_message_list_print(NFAPIMessageList_T* list) {
    for (int i = 0; i < list->size; i++) {
        printf("Message %d: valid_ue_context=%d, mac_transport_context=%d, user_data=0x%p\n", i, list->messages[i].valid_ue_context, list->messages[i].mac_transport_context, list->messages[i].user_data);
    }
}
