import networkx as nx
import matplotlib.pyplot as plt

def generate_network_topology(network_config_list):
    G = nx.DiGraph()

    for config in network_config_list:
        node_id = config['node_id']
        node_size = config['node_size']
        node_color = config['node_color']

        if 'parent_node' in config:
            parent_node_id = config['parent_node']
            G.add_edge(parent_node_id, node_id, weight=config['edge_weight'], style='solid')

        for edge_config in config.get('edges', []):
            target_node_id = edge_config['target_node']
            G.add_edge(node_id, target_node_id, weight=edge_config['weight'], style=edge_config.get('style', 'dashed'))

    pos = nx.spring_layout(G)
    node_sizes = [node_size for _ in range(len(G.nodes))]
    node_colors = [node_color for _ in range(len(G.nodes))]

    nx.draw_networkx_nodes(G, pos, node_size=node_sizes, node_color=node_colors)

    edge_labels = {}
    for (u, v) in G.edges:
        if 'edge_label' in G[u][v]:
            edge_labels[(u, v)] = G[u][v]['edge_label']

    nx.draw_networkx_edges(G, pos, edgelist=list(G.edges), arrowsize=20)
    nx.draw_networkx_edge_labels(G, pos, edge_labels)

    plt.show()

# Example usage:
network_config_list = [
    {'node_id': 0, 'node_size': 100, 'node_color': 'blue', 'parent_node': None},
    {'node_id': 1, 'node_size': 50, 'node_color': 'red'},
    {'node_id': 2, 'node_size': 200, 'node_color': 'green', 'edges': [{'target_node': 0, 'weight': 3, 'style': 'dashed'}]}
]

generate_network_topology(network_config_list)
