    while (1) { // handle dynamic addition of new packet headers based on events
        add_packet_header(&headers, &size);
    }
}

void init_packet_headers(struct packet_header **headers, int *size) {
    FILE *config_file = fopen("packet_config.txt", "r");
    if (!config_file) {
        printf("Failed to open configuration file.\n");
        return;
    }

    int num_packets = 0;
    fscanf(config_file, "%d\n", &num_packets);

    *headers = (struct packet_header *)malloc(num_packets * sizeof(struct packet_header));
    *size = num_packets;

    for (int i = 0; i < num_packets; i++) {
        struct packet_header header;
        fscanf(config_file, "TCP:%u %u %zu\n", &header.src_ip, &header.dst_ip, &header.payload_len);
        if (fscanf(config_file, "%c", &header.protocol) != 1) { // handle enum conversion
            printf("Invalid protocol type.\n");
            return;
        }
        headers[i] = &header;
    }

    fclose(config_file);
}

int add_packet_header(struct packet_header **headers, int *size) {
    if (*size >= 1000) { // prevent excessive memory allocation
        printf("Maximum number of packets reached. Cannot add more.\n");
        return -1;
    }

    struct packet_header *new_headers = (struct packet_header *)realloc(*headers, (*size + 1) * sizeof(struct packet_header));
    if (!new_headers) {
        printf("Memory allocation failed.\n");
        return -1;
    }
    *headers = new_headers;
    (*size)++;

    // dynamically generate a random protocol type and other packet header fields
    struct packet_header header;
    header.protocol = (protocol_type)(rand() % 5);
    header.src_ip = rand() % 4294967296u;
    header.dst_ip = rand() % 4294967296u;
    header.payload_len = rand() % 1000;

    headers[*size - 1] = &header;

    return 0;
}
