typedef enum {
    CRC_ALG_POLY_REMAINDER,
    CRC_ALG_KERMIT,
    CRC_ALG_JONES
} CRC_ALGORITHM;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int list_size = 0;
struct node* head = NULL;

void init_list() {
    pthread_mutex_init(&lock, NULL);
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = head;
    head = new_node;
    list_size++;
}

NFAPI_CRC_INDICATION_PDU_T get_from_list() {
    if (head == NULL) return (NFAPI_CRC_INDICATION_PDU_T){0};
    struct node* temp = head;
    head = head->next;
    free(temp);
    list_size--;
    return temp->data;
}

void release_resources() {
    while (head != NULL) {
        struct node* temp = head;
        head = head->next;
        free(temp);
    }
}

int serialize_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return -1;

    // Write data to file
    fwrite(&list_size, sizeof(int), 1, file);
    while (head != NULL) {
        fwrite(&head->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        head = head->next;
    }
    fclose(file);
    return 0;
}

int deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return -1;

