// Predefined CRC values table
const uint8_t crc_values[256] = {
    0x00, 0x07, 0x04, 0x09, 0x01, 0x02, 0x03, 0x08,
    // ...
};

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int created_count = 0;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int n) {
    srand(time(NULL));
    int rnti_pool[1000] = {0};
    int i;
    NFAPI_CRC_INDATION_PDU_T* puds = (NFAPI_CRC_INDATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDATION_PDU_T));

    for (i = 0; i < n; i++) {
        pthread_mutex_lock(&lock);
        int rnti = rand() % 1000;
        while (rnti_pool[rnti]) {
            rnti = rand() % 1000;
        }
        rnti_pool[rnti] = 1;

        NFAPI_CRC_INDATION_PDU_T* pdu = &puds[i];
        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256);
        pdu->CRCFLAG = crc_values[pdu->CRC_INDICATION_REL8_TAG];

        pthread_mutex_unlock(&lock);
    }

    // Sorting structures by RNTI in ascending order
    qsort(puds, n, sizeof(NFAPI_CRC_INDATION_PDU_T), compare_rnti);

    return puds;
}

int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDATION_PDU_T* pa = (NFAPI_CRC_INDATION_PDU_T*)a;
    NFAPI_CRC_INDATION_PDU_T* pb = (NFAPI_CRC_INDATION_PDU_T*)b;

    return (pa->RNTI > pb->RNTI) ? 1 : ((pa->RNTI < pb->RNTI) ? -1 : 0);
}

int main() {
    int n = 1000;
    NFAPI_CRC_INDATION_PDU_T* puds = create_crc_indication_pdu(n);

    // Print the structures
    for (int i = 0; i < n; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", puds[i].RX_UE_INFORMATION_TAG, puds[i].RNTI, puds[i].CRC_INDICATION_REL8_TAG, puds[i].CRCFLAG);
    }

    // Free the memory
    free(puds);

    return 0;
}
