    pthread_mutex_lock(&mutex);
    if (array_size >= MAX_ARRAY_SIZE) {
        printf("Array size exceeded the maximum limit!\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    array[array_size] = *pdu;
    array_size++;
    pthread_mutex_unlock(&mutex);
