struct node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct node* next;
};

typedef struct node Node;

Node* head = NULL;

void insert_node(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T* new_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = new_data;
    new_node->next = (*head_ref);
    *head_ref = new_node;
}

int is_valid(NFAPI_CRC_INDICATION_PDU_T* data) {
    // validate the integrity of the CRC indications
    if (!validate_crc(data)) {
        return 0;
    }
    return 1;
}

void delete_node(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* current = *head_ref;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->data == data) {
            if (previous == NULL) {
                *head_ref = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

void free_list(Node** head_ref) {
    Node* current = *head_ref;
    Node* next_temp;

    while (current != NULL) {
        next_temp = current->next;
        free(current);
        current = next_temp;
    }
    *head_ref = NULL;
}
