#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define a structure for points with coordinates (x, y) and color index
typedef struct {
    int x, y;
    int color_index;
} Point;

// Define a structure for colors represented by RGB values (r, g, b)
typedef struct {
    int r, g, b;
} Color;

// Function to calculate Euclidean distance between two points
double euclidean_distance(Point p1, Point p2) {
    return sqrt(pow(p1.x - p2.x, 2) + pow(p1.y - p2.y, 2));
}

// Function to identify points sharing the same color
void find_shared_colors(Point* points, int n_points, Color** colors, int* n_colors) {
    for (int i = 0; i < n_points; i++) {
        for (int j = i + 1; j < n_points; j++) {
            if (points[i].color_index == points[j].color_index) {
                printf("Points %d and %d share the same color.\n", i, j);
            }
        }
    }
}

// Function to manage dynamic memory allocation and initialization for points and colors
void* allocate_points_and_colors(int n_points, int n_colors) {
    // Allocate memory for points
    Point* points = (Point*)malloc(n_points * sizeof(Point));
    if (!points) {
        printf("Memory allocation failed for points.\n");
        return NULL;
    }

    // Initialize points with default values
    for (int i = 0; i < n_points; i++) {
        points[i].x = rand() % 100;
        points[i].y = rand() % 100;
        points[i].color_index = rand() % n_colors;
    }

    // Allocate memory for colors
    Color** colors = (Color**)malloc(n_colors * sizeof(Color*));
    if (!colors) {
        printf("Memory allocation failed for colors.\n");
        free(points);
        return NULL;
    }

    // Initialize colors with default values
    for (int i = 0; i < n_colors; i++) {
        colors[i] = (Color*)malloc(sizeof(Color));
        if (!colors[i]) {
            printf("Memory allocation failed for color %d.\n", i);
            free(points);
            free(colors);
            return NULL;
        }
        colors[i]->r = rand() % 256;
        colors[i]->g = rand() % 256;
        colors[i]->b = rand() % 256;
    }

    // Calculate Euclidean distances between points
    double* distances = (double*)malloc((n_points * (n_points - 1)) / 2 * sizeof(double));
    if (!distances) {
        printf("Memory allocation failed for distances.\n");
        free(points);
        free(colors);
        return NULL;
    }

    int index = 0;
    for (int i = 0; i < n_points; i++) {
        for (int j = i + 1; j < n_points; j++) {
            distances[index++] = euclidean_distance(points[i], points[j]);
        }
    }

    // Identify points sharing the same color
    find_shared_colors(points, n_points, colors, &n_colors);

    return distances;
}

int main() {
    int n_points = 5;
    int n_colors = 3;

    double* distances = (double*)allocate_points_and_colors(n_points, n_colors);
    if (!distances) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Free allocated memory
    free(distances);

    return 0;
}
