// Function to initialize the hash table
RNTIHashTable* initRNTIHashTable() {
    RNTIHashTable* hashTable = (RNTIHashTable*)malloc(sizeof(RNTIHashTable));
    hashTable->size = 256;
    for (int i = 0; i < 256; i++) {
        hashTable->buckets[i] = NULL;
    }
    return hashTable;
}

// Function to insert a new RNTI into the hash table
void insertRNTIIntoHashTable(RNTIHashTable* hashTable, int rnti) {
    int index = rnti % 256;
    if (hashTable->buckets[index] == NULL) {
        hashTable->buckets[index] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        hashTable->buckets[index]->rnti = rnti;
    } else {
        // Handle RNTI conflict resolution
        printf("RNTI Conflict: %d already exists in the hash table.\n", rnti);
    }
}

// Function to validate RX_UE_INFORMATION_TAG and RNTI before inclusion
int isValidPDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Validate RX_UE_INFORMATION_TAG and RNTI here
    if (pdu->rx_ue_information_tag && pdu->rnti > 0) {
        return 1; // PDU is valid
    } else {
        return 0; // PDU is not valid
    }
}

// Function to insert a new PDU into the linked list, ensuring data integrity and preventing duplicates
void insertPDUIntoLinkedList(NFAPI_CRC_INDICATION_PDU_T* pdu, NFAPI_CRC_INDICATION_PDU_T** head) {
    if (isValidPDU(pdu)) {
        // Check for RNTI conflicts using the hash table
        int rnti = pdu->rnti;
        RNTIHashTable* hashTable = initRNTIHashTable();
        insertRNTIIntoHashTable(hashTable, rnti);
        // Insert PDU into the linked list
        NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        *newNode = *pdu;
        if (*head == NULL || pdu->rnti > (*head)->rnti) {
            newNode->next = *head;
            *head = newNode;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = *head;
            while (current->next && current->next->rnti >= rnti) {
                current = current->next;
            }
            newNode->next = current->next;
            current->next = newNode;
        }
    } else {
        printf("Invalid PDU: RX_UE_INFORMATION_TAG or RNTI is invalid.\n");
    }
}

// Function to iterate over the linked list in both forward and reverse directions
void printPDUList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        printf("RNTI: %d, RX_UE_INFORMATION_TAG: %s, CRCFLAG: %d\n", current->rnti, current->rx_ue_information_tag, current->crcflag);
        current = current->next;
    }
}

