void filter_and_aggregate(NFAPI_RX_MESSAGE_T* messages, int n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        if (messages[i].priority > 2) { // Filter out low-priority metrics
            sum += messages[i].magnitude;
        }
    }
    double mean = sum / (n - filter_out_low_priority); // Calculate the mean of filtered metrics
}

int find_highest_metric(NFAPI_RX_MESSAGE_T* messages, int n) {
    int max_index = 0;
    for (int i = 1; i < n; i++) {
        if (messages[i].magnitude > messages[max_index].magnitude) {
            max_index = i;
        }
    }
    return max_index;
}

void print_highest_metric(NFAPI_RX_MESSAGE_T* messages, int index) {
    printf("Highest metric value: %f at timestamp %ld\n", messages[index].magnitude, messages[index].timestamp);
}

