NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N) {
    // Initialize logging
    FILE *log_file = fopen("allocation_log.txt", "w");
    if (!log_file) {
        perror("Error opening log file");
        return NULL;
    }

    int* array_ptr = (int*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array_ptr) {
        fclose(log_file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)array_ptr;

    int failures = 0;
    for (int i = 0; i < N; i++) {
        if (!array[i].rx_ue_information_tag ||
            !array[i].RNTI || 
            !array[i].CRC_INDICATION_REL8_TAG) {
            failures++;
            continue;
        }

        array[i].CRCFLAG = rand() % 2;

        // Log allocation
        time_t timestamp = time(NULL);
        fprintf(log_file, "Allocated structure at %lu with RNTI: %d, CRCFLAG: %d\n", 
                timestamp, array[i].RNTI, array[i].CRCFLAG);

        if (i > 0) {
            // Log any failures
            if (failures > 0) {
                fprintf(log_file, "Failed allocations: %d\n", failures);
            }
        }
    }

    fclose(log_file);

    return array;
}
