#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int nfapi_crc_indication_pdu_alloc(int n, int threshold) {
    // Initialize lock-free data structure
    static NFAPI_CRC_INDICATION_PDU_T* pool = NULL;
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (pool == NULL) {
        // Create memory pool with initial size 'n'
        pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pool == NULL) {
            return -ENOMEM;
        }
    }

    // Initialize random number generator
    static uint32_t seed = time(NULL);

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = &pool[i % n];
        p->RX_UE_INFORMATION_TAG = rand_r(&seed) % 256;
        p->RNTI = rand_r(&seed) % (1 << 32);
        p->CRC_INDICATION_REL8_TAG = rand_r(&seed) % 256;
        p->CRCFLAG = rand_r(&seed) % 2;

        if (i >= threshold) {
            // Perform garbage collection every 'threshold' structures
            pthread_mutex_lock(&mutex);
            for (int j = i - threshold; j < i; j++) {
                free(&pool[j]);
            }
            pthread_mutex_unlock(&mutex);
        }
    }

    return 0;
}
