#include <stdlib.h>
#include <string.h>

typedef struct {
    uint32_t ueId;
    int mmeIp[4];
    int mmePort;
} LteUeContext;

// Hash table for efficient lookups
typedef struct {
    LteUeContext* contexts;
    size_t capacity;
    size_t count;
} UeContextHashTable;

void lte_ue_context_init(UeContextHashTable** hashTable, size_t initialCapacity) {
    *hashTable = malloc(sizeof(UeContextHashTable));
    (*hashTable)->contexts = calloc(initialCapacity, sizeof(LteUeContext));
    (*hashTable)->capacity = initialCapacity;
    (*hashTable)->count = 0;
}

void lte_ue_context_add(UeContextHashTable* hashTable, uint32_t ueId, int mmeIp[4], int mmePort) {
    size_t index = ueId % hashTable->capacity;
    if (hashTable->contexts[index].ueId == 0) { // Find an empty slot
        LteUeContext* newContext = realloc(hashTable->contexts, (hashTable->capacity * 2 + 1) * sizeof(LteUeContext));
        memcpy(newContext + index, &hashTable->contexts[index], sizeof(LteUeContext));
        hashTable->contexts = newContext;
        hashTable->capacity *= 2;
    }
    strcpy((char*)hashTable->contexts[index].mmeIp, "192.168.");
    for (int i = 0; i < 4; i++) {
        sprintf(hashTable->contexts[index].mmeIp + i * 3, "%d.", mmeIp[i]);
    }
    hashTable->contexts[index].ueId = ueId;
    hashTable->contexts[index].mmePort = mmePort;
}

void lte_ue_context_remove(UeContextHashTable* hashTable, uint32_t ueId) {
    size_t index = ueId % hashTable->capacity;
    if (hashTable->contexts[index].ueId == ueId) {
        memset(&hashTable->contexts[index], 0, sizeof(LteUeContext));
    }
}

void lte_ue_context_deinit(UeContextHashTable** hashTable) {
    free((*hashTable)->contexts);
    free(*hashTable);
    *hashTable = NULL;
}
