int nfast_add_structure(RX_UE_INFORMATION_TAG rx_ue_info, RNTI rnti, int crc_flag) {
    pthread_mutex_lock(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T* new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_struct) {
        // Handle memory allocation failure
        return -1;
    }

    new_struct->rx_ue_info = rx_ue_info;
    new_struct->rnti = rnti;
    new_struct->crc_indication.crc_flag = crc_flag;

    // Check for CRC error
    if (new_struct->crc_indication.crc_flag >= 1000) {
        // Handle high number of CRC errors
        free(new_struct);
        pthread_mutex_unlock(&list_lock);
        return -2; 
    }

    // Add structure to the list
    int* size = (int*)malloc(sizeof(int));
    *size = sizeof(NFAPI_CRC_INDICATION_PDU_T) / sizeof(NFAPI_CRC_INDICATION_PDU_T[1]);
    NFAPI_CRC_INDICATION_PDU_T** structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < *size; i++) {
        structures[i] = &nfast_list[i];
    }

    // Validate the structure before adding it to the list
    if (!validate_structure(new_struct)) {
        free(structures);
        free(size);
        pthread_mutex_unlock(&list_lock);
        return -3;
    }

    nfast_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfast_list, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfast_list[*size] = *new_struct;

    free(new_struct);
    free(size);
    free(structures);
    pthread_mutex_unlock(&list_lock);
    return 0;
}

// Function to validate a structure
int validate_structure(NFAPI_CRC_INDICATION_PDU_T* struct_to_validate) {
    // Validate the structure's integrity
    if (!struct_to_validate || !struct_to_validate->rx_ue_info || !struct_to_validate->rnti || !struct_to_validate->crc_indication.crc_flag >= 0 && 
        !struct_to_validate->crc_indication.crc_flag <= 1000) {
        return -1;
    }

    // Validate QoS level
    if (struct_to_validate->rx_ue_info.qos_level < 0 || struct_to_validate->rx_ue_info.qos_level > 10) {
        return -2;
    }

    return 0;
}

void nfast_list_free(void) {
    pthread_mutex_lock(&list_lock);
    free(nfast_list);
    pthread_mutex_unlock(&list_lock);
}
