void manageMemory(int numTemperatureReadings, int numSensorIDs) {
    // Initialize arrays and linked list with initial memory allocation
    double* temperatureArray = (double*)malloc(sizeof(double) * 5000);
    char** sensorIDArray = (char**)calloc(3000, sizeof(char*));
    sensorData* sensorDataList = (sensorData*)malloc(sizeof(sensorData) * 1000);

    // Initialize linked list with random temperature values
    for (int i = 0; i < 1000; i++) {
        sensorDataList[i].temperature = (double)(rand() / (double)RAND_MAX * (100 - (-50)) + (-50));
        sensorDataList[i].next = &sensorDataList[(i + 1) % 1000];
    }

    // Initialize arrays with initial memory allocation
    timeStamp* timeStamps = (timeStamp*)malloc(sizeof(timeStamp) * (numTemperatureReadings < numSensorIDs ? numTemperatureReadings : numSensorIDs));

    // Periodic cleanup mechanism to release unused memory and optimize performance
    void periodicCleanup() {
        // Release unused memory for temperature array
        free(temperatureArray);
        temperatureArray = NULL;

        // Release unused memory for sensor ID array
        for (int i = 0; i < numSensorIDs; i++) {
            free(sensorIDArray[i]);
            sensorIDArray[i] = NULL;
        }
        free(sensorIDArray);
        sensorIDArray = NULL;

        // Release unused memory for linked list and time stamps
        while (sensorDataList) {
            sensorData* temp = sensorDataList;
            sensorDataList = sensorDataList->next;
            free(temp);
        }
        free(sensorDataList);

        for (int i = 0; i < numTemperatureReadings; i++) {
            free(&timeStamps[i]);
        }
        free(timeStamps);

        // Reallocate memory with updated sizes
        numTemperatureReadings /= 2;
        numSensorIDs /= 2;

        // Reinitialize arrays and linked list with new memory allocation
        temperatureArray = (double*)malloc(sizeof(double) * numTemperatureReadings);
        sensorIDArray = (char**)calloc(numSensorIDs, sizeof(char*));
        sensorDataList = (sensorData*)malloc(sizeof(sensorData) * (numTemperatureReadings < numSensorIDs ? numTemperatureReadings : numSensorIDs));

        // Reinitialize linked list with random temperature values
        for (int i = 0; i < (numTemperatureReadings < numSensorIDs ? numTemperatureReadings : numSensorIDs); i++) {
            sensorDataList[i].temperature = (double)(rand() / (double)RAND_MAX * (100 - (-50)) + (-50));
            sensorDataList[i].next = &sensorDataList[(i + 1) % (numTemperatureReadings < numSensorIDs ? numTemperatureReadings : numSensorIDs)];
        }

        // Reinitialize arrays with new memory allocation
        timeStamps = (timeStamp*)malloc(sizeof(timeStamp) * ((numTemperatureReadings < numSensorIDs ? numTemperatureReadings : numSensorIDs) / 2));
    }
