#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    int id;
    char ip_address[16];
    char **protocols;
    int protocol_count;
} Device;

Device *devices = NULL;
int device_count = 0;
pthread_mutex_t devices_mutex = PTHREAD_MUTEX_INITIALIZER;

void parse_device(char *line) {
    Device *device;
    char *token, *remaining;

    if ((device = (Device *)malloc(sizeof(Device))) == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    token = strtok(line, ":");
    device->id = atoi(token);
    token = strtok(NULL, ":");
    strcpy(device->ip_address, token);

    token = strtok(NULL, ",");
    device->protocol_count = 0;

    token = strtok(NULL, ",");
    while (token != NULL) {
        device->protocols = (char **)realloc(device->protocols,
                (device->protocol_count + 1) * sizeof(char *));
        if (device->protocols == NULL) {
            printf("Memory allocation failed.\n");
            free(device);
            return;
        }
        device->protocols[device->protocol_count++] = strdup(token);
        token = strtok(NULL, ",");
    }

    pthread_mutex_lock(&devices_mutex);
    devices = (Device *)realloc(devices, (device_count + 1) * sizeof(Device));
    if (devices == NULL) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&devices_mutex);
        free(device);
        return;
    }
    devices[device_count++] = device;
    pthread_mutex_unlock(&devices_mutex);
}

void *iterate_devices(void *arg) {
    int i;

    for (i = 0; i < device_count; i++) {
        printf("Device ID: %d, IP Address: %s, Protocols: ", devices[i].id,
               devices[i].ip_address);
        for (int j = 0; j < devices[i].protocol_count; j++) {
            printf("%s", devices[i].protocols[j]);
            if (j < devices[i].protocol_count - 1) {
                printf(", ");
            }
        }
        printf("\n");
    }

    return NULL;
}

int main() {
    FILE *fp = fopen("devices.cfg", "r");
    if (fp == NULL) {
        printf("Configuration file not found.\n");
        return 1;
    }

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';
        parse_device(line);
    }

    fclose(fp);

    pthread_t thread;
    pthread_create(&thread, NULL, iterate_devices, NULL);
    pthread_join(thread, NULL);

    return 0;
}
