struct record {
    int value;
};

void manage_memory(struct record** records, size_t* num_records, int* min_value, int* max_value) {
    if (*num_records > 100 || *min_value >= *max_value) {
        printf("Invalid input size or range. Aborting.\n");
        return;
    }

    // Allocate memory for offsets
    long* offsets = (long*)malloc((*num_records) * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failure for offsets. Terminating.\n");
        return;
    }

    for (size_t i = 0; i < *num_records; i++) {
        offsets[i] = (long)i;
    }

    // Allocate memory for keys
    int* keys = (int*)malloc((*num_records) * sizeof(int));
    if (!keys) {
        free(offsets);
        printf("Memory allocation failure for keys. Terminating.\n");
        return;
    }

    for (size_t i = 0; i < *num_records; i++) {
        keys[i] = (int)(i * i);
    }

    // Allocate memory for records
    struct record* record_array = (struct record*)malloc(*num_records * sizeof(struct record));
    if (!record_array) {
        free(offsets);
        free(keys);
        printf("Memory allocation failure for records. Terminating.\n");
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < *num_records; i++) {
        record_array[i].value = rand() % (*max_value - *min_value) + *min_value;
    }

    // Initialize output parameters
    *records = record_array;
    *num_records = *num_records;

    // Free allocated memory
    free(offsets);
    free(keys);

    return;
}
