        Node* newNode = (Node*)malloc(sizeof(Node));
        if(newNode == NULL){
            printf("Memory allocation failed\n");
            return NULL;
        }
        newNode->data = data;
        newNode->next = head;
        head = newNode;
    }
    fclose(file);
    return head;
}

// Function to free the linked list and its nodes
void freeList(Node* head) {
    Node* current = head;
    while(current != NULL){
