void insert_node(NFAPI_CRC_INDICATION_PDU_T* new_node, NFAPI_CRC_INDICATION_PDU_T* head, NFAPI_CRC_INDICATION_PDU_T* tail) {
    // Iterate over the list to find the correct position for the new node
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != tail) {
