    clock_t last_gc_time = clock();
    while (1) {
        clock_t current_time = clock();
        if ((current_time - last_gc_time) / CLOCKS_PER_SEC > CLEANUP_THRESHOLD) break;

        pthread_mutex_lock(&lock);

        NFAPI_CRC_INDICATION_PDU_T* current_node = list_head;
        NFAPI_CRC_INDICATION_PDU_T* previous_node = NULL;

