// Shared memory pool
void **memory_pool = NULL;
int num_blocks = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Thread-safe linked list
typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct node *next;
} node_t;

node_t *head = NULL;
