// Function to create a new `NFAPI_CRC_INDICATION_PDU_T` structure
NFAPI_CRC_INDICATION_PDU_T *create_pdu() {
    void **new_block;
    int block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_lock(&lock);
    if (num_blocks == 0) {
        new_block = malloc(block_size);
        memory_pool = &new_block;
        num_blocks++;
    } else {
        new_block = memory_pool;
        memory_pool = ((void **)memory_pool) + 1;
    }
    pthread_mutex_unlock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)*new_block;
    pdu->ue_info = getRandomRXUEInformation();
    pdu->rnti = getRandomRNTI();
    pdu->crc_indication = getRandomCRCINDICATIONREL8TAG();
    pdu->crcflag = rand() % 2;

