}

// Function to add a new `NFAPI_CRC_INDICATION_PDU_T` structure to the list
void add_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    new_node->pdu = pdu;
    new_node->next = head;
    pthread_mutex_lock(&list_lock);
    head = new_node;
    pthread_mutex_unlock(&list_lock);
}

// Function to print the contents of each `NFAPI_CRC_INDICATION_PDU_T` structure
void print_pdu_list() {
    node_t *current = head;
    while (current != NULL) {
        printf("RXUEInformation: %x, RNTI: %d, CRCINDICATIONREL8TAG: %x, CRCFLAG: %d\n",
               current->pdu->ue_info, current->pdu->rnti, current->pdu->crc_indication, current->pdu->crcflag);
        current = current->next;
    }
}

// Function to clear the list and free allocated memory
void clear_pdu_list() {
    node_t *current = head;
    node_t *next = NULL;

    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&list_lock);

    pthread_mutex_lock(&lock);
    num_blocks = 0;
    memory_pool = NULL;
    pthread_mutex_unlock(&lock);
}

