void* init_ue_network(int num_ue, int* channel_frequencies, int** rntis) {
    // Initialize UE instances array
    RX_UE_INFORMATION_TAG* ue_instances = (RX_UE_INFORMATION_TAG*)malloc(num_ue * sizeof(RX_UE_INFORMATION_TAG));

    for (int i = 0; i < num_ue; i++) {
