        if (!validate_config(channel_frequencies[i], rntis[i])) {
            // Log warning and fall back to default settings
            log_warning("Invalid UE configuration. Falling back to default.");
            ue_instances[i].channel_frequency = DEFAULT_CHANNEL_FREQUENCY;
            ue_instances[i].RNTI = DEFAULT_RNTI;
        }

        // Allocate memory buffer for temporary data storage
        ue_instances[i].data_buffer = malloc(DEFAULT_BUFFER_SIZE);
    }

    return ue_instances;
}

// Define a function to validate UE configurations
int validate_config(int channel_frequency, int RNTI) {
    // Check if the channel frequency is within the valid range
    if (channel_frequency < MIN_CHANNEL_FREQUENCY || channel_frequency > MAX_CHANNEL_FREQUENCY) {
        return 0; // Invalid configuration
    }

    // Check if the RNTI value is unique and within the valid range
