#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MAX_LONG_OFFSET 10000
#define MAX_KEY 255
#define MIN_RANDOM_VALUE 1
#define MAX_RANDOM_VALUE 1000
#define AGE_THRESHOLD 3600 // 1 hour in seconds

typedef struct {
    int record;
    long long_offset[MAX_LONG_OFFSET];
    int key[MAX_KEY];
    time_t timestamp;
    int accessed;
    char crc_tag[3];
} Record;

Record* records = NULL;
int record_count = 0;
int max_records = MAX_RECORDS;

void init_pool(int max_size) {
    if (max_size > max_records) {
        max_records = max_size;
    }
}

void cleanup_records(time_t current_time, int age_threshold) {
    time_t now = current_time;
    for (int i = 0; i < record_count; i++) {
        if ((now - records[i].timestamp) > age_threshold) {
            // Perform periodic cleanup of unused records
            free(records[i]);
            records[i] = NULL;
            record_count--;
            i--;
        }
    }
}

Record* create_record() {
    Record* new_rec = (Record*)malloc(sizeof(Record));
    if (!new_rec) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize record fields
    new_rec->record = rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1) + MIN_RANDOM_VALUE;
    for (int i = 0; i < MAX_LONG_OFFSET; i++) {
        new_rec->long_offset[i] = rand() % MAX_LONG_OFFSET;
    }
    for (int i = 0; i < MAX_KEY; i++) {
        new_rec->key[i] = rand() % MAX_KEY;
    }

    // Set timestamp and access status
    time_t now = time(NULL);
    new_rec->timestamp = now;
    new_rec->accessed = 0;

    for (int i = 0; i < 3; i++) {
        new_rec->crc_tag[i] = rand() % 2 == 0 ? '0' : '1';
    }

    return new_rec;
}

void destroy_pool(time_t current_time) {
    cleanup_records(current_time, AGE_THRESHOLD);
    for (int i = record_count - 1; i >= 0; i--) {
        if (!records[i]->accessed) {
            // Free inactive records
            free(records[i]);
            record_count--;
        }
    }
}

void set_record_access(int index) {
    if (index < record_count) {
        records[index]->accessed = 1;
    } else {
        printf("Error: Record out of bounds\n");
    }
}

int get_record_index(time_t timestamp, int age_threshold) {
    for (int i = 0; i < record_count; i++) {
        if ((timestamp - records[i]->timestamp) <= age_threshold) {
            return i;
        }
    }
    return -1; // Record not found
}
