        free(records[i].value_ptr);
    }
    free(records);
}

long* dynamic_memory_allocation(int n, int min, int max) {
    if (n <= 0 || min > max) {
        printf("Invalid input. Please ensure 'n' is positive and 'min' is less than or equal to 'max'.\n");
        return NULL;
    }

    long* offsets = allocate_offsets(n);
    if (!offsets) {
        printf("Memory allocation failed for 'offsets'. Terminating.\n");
        return NULL;
    }

    int* keys = allocate_keys(n);
    if (!keys) {
        printf("Memory allocation failed for 'keys'. Terminating.\n");
        free(offsets);
        return NULL;
    }

    struct record* records = malloc(n * sizeof(struct record));
    if (!records) {
        printf("Memory allocation failed for 'records'. Terminating.\n");
        free(offsets);
        free(keys);
        return NULL;
    }
