#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    char RX_UE_INFORMATION_TAG[16];
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with random CRCFLAG
Node* createNode(int RNTI) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        return NULL; // Memory allocation failed
    }
    strcpy(newNode->data.RX_UE_INFORMATION_TAG, "Random tag");
    strcpy(newNode->data.CRC_INDICATION_REL8_TAG, "Random tag");
    newNode->data.RNTI = RNTI;
    srand(time(NULL)); // Ensure random seed is updated for each new node
    newNode->data.CRCFLAG = rand() % 2; // Randomly set CRC flag (0 or 1)
    return newNode;
}

// Function to insert a new node into the linked list, ensuring no duplicate RNTI values
Node* insertNode(Node* head, int RNTI) {
    Node* newNode = createNode(RNTI);
    if (!head || head->data.RNTI != RNTI) {
        // Insert at the beginning of the list or after a node with a different RNTI
        newNode->next = head;
        return newNode;
    } else {
        // Duplicate RNTI found; update CRC flag for existing node and return original head
        head->data.CRCFLAG ^= 1; // Flip CRC flag
        return head;
    }
}

// Function to serialize the linked list to a binary file
void serializeList(Node* head, FILE* file) {
    Node* current = head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
}

// Function to deserialize the linked list from a binary file
Node* deserializeList(FILE* file) {
    Node* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* newNode = (Node*) malloc(sizeof(Node));
        if (!newNode) {
            return NULL; // Memory allocation failed
        }
        newNode->data = data;
        newNode->next = head;
        head = newNode;
    }
    return head;
}
