// Function to create a new node with initialized data and return the pointer
NFAPI_CRC_INDICATION_PDU_T* create_node() {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    node->RNTI = rand() % 100; // Random RNTI for demonstration
    strcpy(node->RX_UE_INFORMATION_TAG, "Dummy RX Tag"); // Initialize with a dummy tag
    node->CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC indicator for demonstration
    node->CRCFLAG = rand() % 2; // Randomly set CRC flag for demonstration
    return node;
}

// Function to add a new node to the list and check for duplicates
void add_node(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (*head == NULL || node->RNTI > (*head)->RNTI) {
        node->next = *head;
        *head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head;
        while (current->next && current->next->RNTI >= node->RNTI)
            current = current->next;
        if (node->RNTI == current->next->RNTI) { // Check for duplicate RNTI
            printf("Duplicate RNTI entry detected.\n");
            return;
        }
        node->next = current->next;
        current->next = node;
    }
}

// Function to sort the list by RNTI in ascending order
void sort_list(NFAPI_CRC_INDICATION_PDU_T** head) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    NFAPI_CRC_INDICATION_PDU_T* next_node;
    int swapped;
    do {
        swapped = 0;
        current = *head;
        while (current && current->next) {
            if (current->RNTI > current->next->RNTI) {
                // Swap the nodes
                NFAPI_CRC_INDICATION_PDU_T* temp_node = current->next;
                current->next = temp_node->next;
                temp_node->next = current;
                *head = temp_node; // Update the head node if necessary
                swapped = 1;
            } else {
                current = current->next;
            }
        }
    } while (swapped);
}

// Function to filter the list based on CRC indicator thresholds
void filter_list(NFAPI_CRC_INDICATION_PDU_T** head, int min_threshold) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    NFAPI_CRC_INDICATION_PDU_T* next_node = NULL;
    while (current) {
        if (current->CRC_INDICATION_REL8_TAG >= min_threshold)
            printf("RNTI: %d, RX UE Tag: %s, CRC Indicator: %d, CRC Flag: %d\n",
                   current->RNTI, current->RX_UE_INFORMATION_TAG, current->CRC_INDICATION_REL8_TAG, current->CRCFLAG);
        next_node = current->next;
        free(current); // Deallocate memory for the node
        current = next_node;
    }
    *head = NULL; // Reset the head pointer to avoid dangling references
}

int main() {
    srand(time(NULL)); // Initialize random number generator

    // Create a new list with initialized data
    NFAPI_CRC_INDICATION_PDU_T* head = create_node();
    if (head) {
        add_node(&head, create_node());
        add_node(&head, create_node());
        sort_list(&head);

        // Filter the list based on CRC indicator thresholds (e.g., min_threshold = 100)
        filter_list(&head, 100);
    }

    return 0;
}
