            }
        }
    }
    for (i = 0; i < nfaPiCount; i++) {
        temp[i] = nfaPiList[i];
    }
    for (i = 0; i < nfaPiCount; i++) {
        free(nfaPiList[i]);
    }
    for (i = 0; i < nfaPiCount; i++) {
        nfaPiList[i] = &temp[i];
    }
    free(temp);
    pthread_mutex_unlock(&lock);
}

void filterNFAPIList(int threshold) {
    pthread_mutex_lock(&lock);
    int count = 0;
    for (int i = 0; i < nfaPiCount; i++) {
