        for (int j = 1; j <= count - i - 1; j++) {
            nfaPiList[j] = nfaPiList[j + 1];
        }
        free(tempNode);
    }
    pthread_mutex_unlock(&lock);
}

void mergeArrays(long* offsetArray, int keyArray[], int leftLength, int rightLength) {
    long* mergedArray;
    int i, j, k;

    if (leftLength > 0 && rightLength > 0) {
        mergedArray = (long*)malloc((leftLength + rightLength) * sizeof(long));
        for (k = 0; k < leftLength; k++) {
            mergedArray[k] = offsetArray[k];
        }
        i = leftLength;
        for (j = 0; j < rightLength; j++) {
            while (i > 0 && keyArray[i - 1] > keyArray[j]) {
                i--;
            }
            mergedArray[i + j] = offsetArray[leftLength + j];
        }
    } else if (leftLength > 0) {
        mergedArray = (long*)malloc(leftLength * sizeof(long));
        for (k = 0; k < leftLength; k++) {
            mergedArray[k] = offsetArray[k];
        }
    } else if (rightLength > 0) {
        mergedArray = (long*)malloc(rightLength * sizeof(long));
        for (k = 0; k < rightLength; k++) {
            mergedArray[k] = offsetArray[leftLength + k];
        }
    }

    free(offsetArray);
}
