// Function to insert a new node into the linked list
void insert_node(int n, NFAPI_CRC_INDICATION_PDU_T** head_ref, int rnti, char crcflag) {
    NFAPI_CRC_INDICATION_PDU_T* newNode = new_node(rnti, crcflag);
    if (*head_ref == NULL || rnti < (*head_ref)->rnti) {
        newNode->next = *head_ref;
        *head_ref = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head_ref;
        while (current->next && current->next->rnti > rnti)
            current = current->next;
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to delete a node from the linked list
void delete_node(NFAPI_CRC_INDICATION_PDU_T** head_ref, int rnti) {
    if (*head_ref == NULL)
        return;
    else if ((*head_ref)->rnti == rnti) {
        NFAPI_CRC_INDICATION_PDU_T* temp = *head_ref;
        *head_ref = (*head_ref)->next;
        free(temp);
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head_ref;
        while (current->next && current->next->rnti != rnti)
            current = current->next;
        if (current->next) {
            temp = current->next;
            current->next = current->next->next;
            free(temp);
        }
    }
}

// Function to print the linked list
void print_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    while (temp) {
        printf("RNTI: %d, CRC FLAG: %c\n", temp->rnti, temp->crcflag);
        temp = temp->next;
    }
}

// Function to validate the integrity of the linked list
int validate_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current && current->next) {
        if (current->rnti >= current->next->rnti)
            return 0; // List is not sorted
        current = current->next;
    }
    return 1; // List is sorted
}

// Function to cleanup the linked list
void cleanup_list(NFAPI_CRC_INDICATION_PDU_T** head_ref) {
    NFAPI_CRC_INDICATION_PDU_T* temp = *head_ref;
    NFAPI_CRC_INDICATION_PDU_T* next = NULL;
    while (temp) {
        next = temp->next;
        free(temp);
        temp = next;
    }
    *head_ref = NULL;
}
