        return 0; // Connection is invalid or incomplete
    }
    return 1; // Connection is valid and intact
}

// Function to manage the dynamic linked list of TCP connections
void manage_tcp_conn_list(tcp_conn** head, int new_src_port, int new_dest_port) {
    tcp_conn* new_conn = create_tcp_conn(new_src_port, new_dest_port);
    if (!*head) {
        *head = new_conn;
    } else {
        tcp_conn* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_conn;
    }
}

