    (*records) = (record *)malloc(sizeof(record) * *size);
    (*keys) = (int *)malloc(sizeof(int) * *size);
    (*offsets) = (long *)malloc(sizeof(long) * *size);
    fread(*records, sizeof(record), *size, file);
    fread(*keys, sizeof(int), *size, file);
    fread(*offsets, sizeof(long), *size, file);

    fclose(file);
}

