typedef struct {
    int SessionID;
    char* RX_UE_INFORMATION_TAG;
    int RNTI;
} SessionContext;

typedef struct {
    size_t capacity;
    size_t size;
    SessionContext** contexts;
    pthread_mutex_t lock;
} SessionCollection;

SessionCollection* session_collection_create(size_t initial_capacity) {
    SessionCollection* collection = (SessionCollection*)malloc(sizeof(SessionCollection));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->contexts = (SessionContext**)calloc(initial_capacity, sizeof(SessionContext*));
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void session_collection_destroy(SessionCollection* collection) {
    for (int i = 0; i < collection->size; i++) {
        free(collection->contexts[i]->RX_UE_INFORMATION_TAG);
        free(collection->contexts[i]);
    }
    free(collection->contexts);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void session_collection_add(SessionCollection* collection, int SessionID, char* RX_UE_INFORMATION_TAG, int RNTI) {
    if (collection->size >= collection->capacity) {
        collection->capacity *= 2;
        collection->contexts = (SessionContext**)realloc(collection->contexts, sizeof(SessionContext*) * collection->capacity);
    }
    SessionContext* new_context = (SessionContext*)malloc(sizeof(SessionContext));
    new_context->SessionID = SessionID;
    new_context->RX_UE_INFORMATION_TAG = strdup(RX_UE_INFORMATION_TAG);
    new_context->RNTI = RNTI;
    pthread_mutex_lock(&collection->lock);
    collection->contexts[collection->size] = new_context;
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

int main() {
    SessionCollection* collection = session_collection_create(2);
    // Add sessions...
    session_collection_add(collection, 1, "RX_INFO_TAG_1", 10);
    session_collection_add(collection, 2, "RX_INFO_TAG_2", 20);
    // Destroy the collection...
    session_collection_destroy(collection);
    return 0;
}
