NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    uint16_t rx_ue_tag;
    int rnti_val, temp_rnti_val;
    enum { CRCFLAG_0, CRCFLAG_1 } crcflag;

    // Initialize random number generator
    srand(time(NULL));

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        rx_ue_tag = i;
        rnti_val = rand() % 10000; // Generate random RNTI
        crcflag = (rand() & 1) ? CRCFLAG_1 : CRCFLAG_0; // Randomly set CRCFLAG

        pdu_list[i].tag = rx_ue_tag;
        pdu_list[i].rnti = rnti_val;
        pdu_list[i].crcflag = crcflag;

        // Check for duplicate RNTI values and retry if needed
        temp_rnti_val = rnti_val;
        while (temp_rnti_val > 0) {
            int j, found_duplicate = 0;
            for (j = 0; j < i; j++) {
                if (pdu_list[j].rnti == temp_rnti_val) {
                    found_duplicate = 1;
                    break;
                }
            }

            if (!found_duplicate) {
                break;
            } else {
                rnti_val = rand() % 10000; // Generate new random RNTI
            }
        }

        pdu_list[i].rnti = rnti_val;

        // Log the number of retries required to generate unique RNTI values
        printf("Retries for RNTI generation: %d\n", temp_rnti_val);
    }

    return pdu_list;
}

