        printf("RX_UE_INFORMATION_TAG: %hu, RNTI: %d, CRCFLAG: %s\n",
               pdu_list[i].tag,
               pdu_list[i].rnti,
               (pdu_list[i].crcflag == CRCFLAG_1) ? "1" : "0");
