typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createCRCList(int N, int LOG_LEVEL) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;
    int flagProbability = 0.5; // default probability

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* newElement = malloc(sizeof(NFAPI_CRC_INDATION_PDU_T));
        if (!newElement) {
            printf("Memory allocation failed. Reducing number of elements.\n");
            N--;
            break;
        }
        newElement->RX_UE_INFORMATION_TAG = rand() % 1000;
        newElement->RNTI = rand() % 256;
        newElement->CRC_INDICATION_REL8_TAG = rand() % 1024;
        if ((double)rand() / RAND_MAX < flagProbability)
            newElement->CRCFLAG = 1;

        if (head == NULL) {
            head = newElement;
            tail = newElement;
        } else {
            tail->next = newElement;
            tail = newElement;
        }
    }

    printf("Created CRC list with %d elements.\n", N);

    return head;
}

void freeCRCList(NFAPI_CRC_INDICATION_PDU_T* head) {
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        head = head->next;
        free(temp);
    }
}
