typedef struct {
    int TransportChannelID;
    int CellIdentity;
    float Frequency;
} LTE_PhyLayer_TransportChannelConfig;

void read_config_file(const char* filename, LTE_PhyLayer_TransportChannelConfig** config_list, size_t* num_configs) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    // Parse configuration file
    int line_count = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        // Parse line and validate data
        LTE_PhyLayer_TransportChannelConfig* config = malloc(sizeof(LTE_PhyLayer_TransportChannelConfig));
        if (sscanf(buffer, "%d %d %f", &config->TransportChannelID, &config->CellIdentity, &config->Frequency) != 3) {
            printf("Invalid line format: %s\n", buffer);
            free(config);
            continue;
        }

        // Validate frequency range
        if (config->Frequency < 0.1 || config->Frequency > 2.7) {
            printf("Invalid frequency: %f\n", config->Frequency);
            free(config);
            continue;
        }

        *num_configs += 1;
        (*config_list)[line_count] = config;
        line_count++;
    }
    fclose(file);
}

void adjust_config_for_network_topology(LTE_PhyLayer_TransportChannelConfig** config_list, size_t num_configs) {
    // Adjust configuration for different network topologies
    for (size_t i = 0; i < num_configs; i++) {
        if (config_list[i]->CellIdentity > 5) {
            config_list[i]->Frequency += 0.1;
        }
    }
}

void print_config(LTE_PhyLayer_TransportChannelConfig** config_list, size_t num_configs) {
    for (size_t i = 0; i < num_configs; i++) {
        printf("Transport Channel ID: %d, Cell Identity: %d, Frequency: %.2f\n", 
               config_list[i]->TransportChannelID, config_list[i]->CellIdentity, config_list[i]->Frequency);
    }
}

int main() {
    size_t num_configs = 0;
    LTE_PhyLayer_TransportChannelConfig* config_list = NULL;

    read_config_file("config1.txt", &config_list, &num_configs);
    read_config_file("config2.txt", &config_list, &num_configs);

    adjust_config_for_network_topology(&config_list, num_configs);

    print_config(&config_list, num_configs);

    for (size_t i = 0; i < num_configs; i++) {
        free(config_list[i]);
    }
    free(config_list);
    return 0;
}
