// Function to create a new node
NFAPI_CRC_INDICATION_PDU_T* createNode(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    node->CRCFLAG = (rand() % 2); // Randomly set CRCFLAG
    return node;
}

// Function to create a linked list with N nodes
NFAPI_CRC_INDICATION_PDU_T* createLinkedList(int N) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    for (int i = 0; i < N; i++) {
        if (i == 0) {
            head = createNode(i, i, i);
            current = head;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* newNode = createNode(i, i, i);
            current->next = newNode;
            current = newNode;
        }
    }

    return head;
}

// Function to free the linked list
void freeLinkedList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    NFAPI_CRC_INDICATION_PDU_T* next = NULL;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int N = 5; // Number of nodes in the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = createLinkedList(N);

    // Print the contents of the linked list
    for (NFAPI_CRC_INDICATION_PDU_T* current = head; current != NULL; current = current->next) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRC_INDICATION_REL8_TAG, current->CRCFLAG);
    }

    // Free the linked list
    freeLinkedList(head);

    return 0;
}
