void* initializeDataStructures(int numRecords) {
    // Initialize error handling variables
    int allocationError = 0;

    // Calculate the total size needed for the offset array, key array, and record array
    int totalSize = sizeof(long) * numRecords + sizeof(int) * numRecords + sizeof(Record) * numRecords;

    // Dynamically allocate memory for the offset array
    long* offsets = (long*)malloc(totalSize);
    if (!offsets) {
        allocationError = 1;
    }

    // Validate each offset to ensure it does not exceed the maximum value representable by a standard long
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = (long)i % ((long)1 << 31 - 1);
    }

    // Derive keys from the offsets using bitwise operations (e.g., shifting or masking)
    int* keys = (int*)malloc(sizeof(int) * numRecords);
    for (int i = 0; i < numRecords; i++) {
        keys[i] = (int)(offsets[i] >> 31);
    }

    // Initialize record array with random values and derived keys
    Record* records = (Record*)malloc(totalSize);
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = (double)rand() / RAND_MAX;
        records[i].key = keys[i];
    }

    // Manage dependencies between structures and handle potential memory allocation failures
    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        allocationError = 1;
    }

    return (void*)records;
}

// Example usage of the function
