```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define LIST_THRESHOLD 1000
#define RNTI_MAX 65535

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node* head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
int rnti_counter = 0;

void init_list() {
    head = NULL;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

int insert_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) {
        return -1; // Memory allocation failed
    }
    pthread_mutex_lock(&list_lock);

    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    int rnti = data.RNTI;
    while (rnti <= RNTI_MAX && find_rnti(rnti)) {
        rnti++;
    }
    if (rnti > RNTI_MAX) {
        free(new_node);
        pthread_mutex_unlock(&list_lock);
        return -1; // No more unique RNTIs available
    }

    new_node->data.RNTI = rnti;
    rnti_counter++;

    if (rnti_counter >= LIST_THRESHOLD) {
        resize_list();
    }

    pthread_mutex_unlock(&list_lock);
    return 0;
}

int find_rnti(int rnti) {
    Node* current = head;
    while (current) {
        if (current->data.RNTI == rnti) {
            return 1; // RNTI already exists
        }
        current = current->next;
    }
    return 0; // RNTI not found
}

void free_list() {
    Node* current = head;
    Node* next = NULL;
    while (current) {
        next = current->next;
        pthread_mutex_destroy(&current->lock);
        free(current);
        current = next;
    }
    head = NULL;
}

void resize_list() {
    // Atomic and non-blocking resizing code here
}
