typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

void* create_list(void* arg) {
    Node** head = (Node**)arg;
    Node* current = NULL;
    Node* tail = NULL;
    for(int i=0; i<MAX_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 256;
        do {
            data.RNTI = rand() % MAX_RNTI;
        } while (data.RNTI == 0);
        data.CRCFLAG = rand() % 2;

        Node* new_node = (Node*)malloc(sizeof(Node));
        if(new_node == NULL) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        new_node->data = data;
        new_node->prev = current;
        new_node->next = tail;
        if(tail != NULL)
            tail->prev = &new_node;
        else
            *head = &new_node;
        if(current == NULL)
            tail = &new_node;
        else
            current = &new_node;
    }
    return (void*)tail;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, create_list, &head);
    pthread_join(thread, NULL);
    return 0;
}
