#include <stdint.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG;
    uint8_t CRC_INDICATION_REL8_TAG;
    int16_t CRCFLAG;
} Report;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    Report* reports;
} ReportQueue;

ReportQueue* report_queue_init(size_t initial_capacity) {
    ReportQueue* queue = (ReportQueue*)malloc(sizeof(ReportQueue));
    queue->capacity = initial_capacity;
    queue->size = 0;
    queue->reports = (Report*)calloc(queue->capacity, sizeof(Report));
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void report_queue_free(ReportQueue* queue) {
    pthread_mutex_destroy(&queue->lock);
    free(queue->reports);
    free(queue);
}

int report_queue_enqueue(ReportQueue* queue, Report report) {
    if (queue->size == queue->capacity) {
        // Dynamic resizing
        size_t new_capacity = queue->capacity * 2;
        Report* new_reports = (Report*)realloc(queue->reports, new_capacity * sizeof(Report));
        queue->reports = new_reports;
        queue->capacity = new_capacity;
    }
    // Enqueue the report
    pthread_mutex_lock(&queue->lock);
    queue->reports[queue->size++] = report;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int report_queue_dequeue(ReportQueue* queue, Report* dequeued_report) {
    if (queue->size == 0) {
        // Underflow
        return -1;
    }
    pthread_mutex_lock(&queue->lock);
    *dequeued_report = queue->reports[--queue->size];
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void report_queue_print(ReportQueue* queue) {
    for (int i = 0; i < queue->size; i++) {
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %d\n",
               queue->reports[i].RNTI, queue->reports[i].RX_UE_INFORMATION_TAG,
               queue->reports[i].CRC_INDICATION_REL8_TAG, queue->reports[i].CRCFLAG);
    }
}

int main() {
    ReportQueue* queue = report_queue_init(16);

    // Enqueue some reports
    for (int i = 0; i < 100; i++) {
        Report report;
        // Fill the report structure with random data
        report.RNTI = rand();
        report.RX_UE_INFORMATION_TAG = rand() % 256;
        report.CRC_INDICATION_REL8_TAG = rand() % 256;
        report.CRCFLAG = rand() % 32768 - 16384;
        report_queue_enqueue(queue, report);
    }

    // Dequeue some reports
    for (int i = 0; i < 50; i++) {
        Report dequeued_report;
        if (report_queue_dequeue(queue, &dequeued_report)) {
            printf("Underflow detected!\n");
            break;
        } else {
            printf("Dequeued report: %u, %u, %u, %d\n",
                   dequeued_report.RNTI, dequeued_report.RX_UE_INFORMATION_TAG,
                   dequeued_report.CRC_INDICATION_REL8_TAG, dequeued_report.CRCFLAG);
        }
    }

    report_queue_free(queue);
    return 0;
}
