    enum { CRCFLAG_ON, CRCFLAG_OFF } CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_indications(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N must be a positive integer.\n");
        return NULL; // or handle error as needed
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T* p = realloc(array, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (p == NULL) {
            // Handle allocation failure and release partially allocated resources
            for (int j = 0; j < i; j++) {
                free(&array[j]);
            }
            free(array);
            array = NULL;
            pthread_mutex_unlock(&mutex);
            break;
        } else {
            array = p;
            NFAPI_CRC_INDICATION_PDU_T* new_p = &array[i];
            new_p->RX_UE_INFORMATION_TAG[0] = 'T';
            new_p->RNTI = i % 100; // random
            new_p->CRCFLAG = (rand() % 2 == 0) ? CRCFLAG_ON : CRCFLAG_OFF;
            printf("[%s] Allocated index: %d, RNTI: %d, CRCFLAG: %s\n", 
                   asctime(localtime(&time(NULL))), i, new_p->RNTI, new_p->CRCFLAG == CRCFLAG_ON ? "ON" : "OFF");
            pthread_mutex_unlock(&mutex);
        }
    }

    if (array) {
        pthread_mutex_lock(&mutex);
        free(array);
        pthread_mutex_unlock(&mutex);
    } else {
        // Handle error
        printf("Error: unable to allocate memory.\n");
    }

    return array;
}
