#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define OFFSET_RANGE 1000
#define KEY_RANGE 256
#define RECORD_MAX_VALUE 65536
#define MAX_RECORDS 1024

typedef struct {
    int value;
} record_t;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int unique_long_offset() {
    static long offset = -1;
    while (offset < 0 || offset >= OFFSET_RANGE) {
        offset = rand() % OFFSET_RANGE;
    }
    return offset;
}

int unique_int_key() {
    int key = rand() % KEY_RANGE;
    while (key < 0 || key >= KEY_RANGE) {
        key = rand() % KEY_RANGE;
    }
    return key;
}

record_t* new_record(int value) {
    record_t* rec = my_malloc(sizeof(record_t));
    rec->value = value;
    return rec;
}

void manage_memory_resources() {
    // Allocate and initialize arrays
    long* offsets = my_malloc(OFFSET_RANGE * sizeof(long));
    for (int i = 0; i < OFFSET_RANGE; i++) {
        offsets[i] = unique_long_offset();
    }

    int* keys = my_malloc(KEY_RANGE * sizeof(int));
    for (int i = 0; i < KEY_RANGE; i++) {
        while (keys[i] > 0) {
            keys[i] = unique_int_key();
        }
    }

    record_t** records = my_malloc(MAX_RECORDS * sizeof(record_t*));

    // Initialize and fill array of records
    for (int i = 0; i < MAX_RECORDS; i++) {
        int value = rand() % RECORD_MAX_VALUE;
        while (value > 0) {
            value = rand() % RECORD_MAX_VALUE;
        }
        records[i] = new_record(value);
    }

    // Free allocated memory
    for (int i = 0; i < MAX_RECORDS; i++) {
        my_free(records[i]);
    }
    my_free(records);

    my_free(keys);
    my_free(offsets);
}

int main() {
    srand(time(NULL)); // seed random number generator

    manage_memory_resources();

    return 0;
}
