#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to hold LTE PHY Layer Statistics
typedef struct {
    int cell_id;
    long timestamp;
    long downlink_traffic;
    long uplink_traffic;
} LTE_PHY_Stats;

// Function to initialize and sort the list of LTE PHY Layer Statistics
LTE_PHY_Stats* init_phy_stats(int num_stats, LTE_PHY_Stats** phy_stats_ptr) {
    *phy_stats_ptr = (LTE_PHY_Stats*)malloc(num_stats * sizeof(LTE_PHY_Stats));

    for (int i = 0; i < num_stats; i++) {
        (*phy_stats_ptr)[i].cell_id = i;
        (*phy_stats_ptr)[i].timestamp = time(NULL);
        // Randomly generate downlink and uplink traffic statistics
        (*phy_stats_ptr)[i].downlink_traffic = rand() % 1000;
        (*phy_stats_ptr)[i].uplink_traffic = rand() % 500;
    }

    qsort(*phy_stats_ptr, num_stats, sizeof(LTE_PHY_Stats), compare_phy_stats);

    return *phy_stats_ptr;
}

// Function to calculate and store the average throughput for each time interval
void calc_avg_throughput(LTE_PHY_Stats* phy_stats, int num_stats) {
    long total_downlink = 0, total_uplink = 0;

    for (int i = 0; i < num_stats; i++) {
        total_downlink += phy_stats[i].downlink_traffic;
        total_uplink += phy_stats[i].uplink_traffic;
    }

    // Calculate and store the average throughput
    long avg_downlink = total_downlink / num_stats;
    long avg_uplink = total_uplink / num_stats;

    printf("Average Downlink Throughput: %ld\n", avg_downlink);
    printf("Average Uplink Throughput: %ld\n", avg_uplink);
}

// Comparison function for sorting LTE PHY Layer Statistics
int compare_phy_stats(const void* a, const void* b) {
    LTE_PHY_Stats* stat_a = (LTE_PHY_Stats*)a;
    LTE_PHY_Stats* stat_b = (LTE_PHY_Stats*)b;

    if (stat_a->cell_id < stat_b->cell_id)
        return -1;
    else if (stat_a->cell_id > stat_b->cell_id)
        return 1;
    else {
        if (stat_a->timestamp < stat_b->timestamp)
            return -1;
        else if (stat_a->timestamp > stat_b->timestamp)
            return 1;
    }

    return 0;
}

int main() {
    int num_stats = 10; // Number of LTE PHY Layer Statistics
    LTE_PHY_Stats* phy_stats;

    init_phy_stats(num_stats, &phy_stats);

    calc_avg_throughput(phy_stats, num_stats);

    free(phy_stats);

    return 0;
}
