#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int measurement_id;
    int cell_id;
    int measurement_quality; // Randomly initialized quality score between 0 and 100
} LTE_MEASUREMENT_REPORT;

// Node structure for the linked list
typedef struct Node {
    LTE_MEASUREMENT_REPORT data;
    struct Node* next;
} Node;

// Linked list representation
typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock; // Mutex for thread safety
} LinkedList;

// Function to create a new node with random quality score
Node* create_node(int measurement_id, int cell_id) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->data.measurement_id = measurement_id;
    node->data.cell_id = cell_id;
    node->data.measurement_quality = rand() % 101; // Randomly initialized quality score between 0 and 100
    node->next = NULL;
    return node;
}

// Function to add a new node to the linked list
void add_node(LinkedList* list, int measurement_id, int cell_id) {
    Node* new_node = create_node(measurement_id, cell_id);

    pthread_mutex_lock(&list->lock); // Lock the linked list for thread safety

    if (list->head == NULL) { // Handle first node insertion
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock); // Unlock the linked list for thread safety
}

// Function to update an existing node by ID
void update_node(LinkedList* list, int measurement_id, int cell_id) {
    Node* current = list->head;
    Node* previous = NULL;

    pthread_mutex_lock(&list->lock); // Lock the linked list for thread safety

    while (current != NULL && current->data.measurement_id != measurement_id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) { // Node not found
        printf("Node with ID %d not found.\n", measurement_id);
    } else {
        current->data.cell_id = cell_id;
        pthread_mutex_unlock(&list->lock); // Unlock the linked list for thread safety
    }
}

// Function to remove a node by ID
void remove_node(LinkedList* list, int measurement_id) {
    Node* previous = NULL;
    Node* current = list->head;

    pthread_mutex_lock(&list->lock); // Lock the linked list for thread safety

    while (current != NULL && current->data.measurement_id != measurement_id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) { // Node not found
        printf("Node with ID %d not found.\n", measurement_id);
    } else {
        if (previous == NULL) { // Remove first node
            list->head = current->next;
        } else {
            previous->next = current->next;
        }

        if (current == list->tail) { // Update tail pointer
            list->tail = previous;
        }

        free(current);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock); // Unlock the linked list for thread safety
}

// Function to print the linked list
void print_list(LinkedList* list) {
    Node* current = list->head;

    printf("Linked List Size: %d\n", list->size);

    while (current != NULL) {
        printf("Measurement ID: %d, Cell ID: %d, Quality Score: %d\n", 
               current->data.measurement_id, current->data.cell_id, current->data.measurement_quality);
        current = current->next;
    }
}

// Function to initialize the linked list
LinkedList* init_list() {
    LinkedList* list = (LinkedList*) malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to free the linked list
void free_list(LinkedList* list) {
    Node* current = list->head;
    Node* next = NULL;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock); // Unlock the linked list for thread safety
}
