    char* errorMessage;
} ErrorStruct;

// Function to initialize and manage a linked list of NFAPI_CRC_INDICATION_PDU_T structures
ErrorStruct* LinkedListManager(int N) {
    // Initialize the head node
    Node* head = NULL;
    Node** tail = &head;

    for (int i = 0; i < N; i++) {
        // Allocate memory for a new node
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            // Handle memory allocation failure
            ErrorStruct* error = malloc(sizeof(ErrorStruct));
            error->errorCode = -1;
            error->errorMessage = "Memory allocation failed";
            return error;
        }

        // Initialize the new node's fields with random values
        newNode->rx_ue_info_tag = rand() % 1000; // Random RX_UE_INFORMATION_TAG value
        newNode->rnti = (rand() % 2) ? "RNTI1" : "RNTI2"; // Random RNTI value
        newNode->crc_ind_rel8_tag = malloc(strlen("CRC_IND_REL8_TAG") + 1);
        strcpy(newNode->crc_ind_rel8_tag, "CRC_IND_REL8_TAG");
        newNode->crcflag = rand() % 2; // Random CRCFLAG value

        // Check for circular references during population
        if (*tail && (*tail)->next == newNode) {
            free(newNode); // Free the newly allocated node to prevent circular reference
            ErrorStruct* error = malloc(sizeof(ErrorStruct));
            error->errorCode = -1;
            error->errorMessage = "Circular reference detected";
            return error;
        }

        *tail = newNode; // Update the tail pointer
        tail = &newNode->next; // Prepare for the next node allocation
    }

    free(newNode); // Free the last allocated node to prevent memory leaks

    return NULL; // No errors occurred
}

// Node structure
typedef struct {
    int rx_ue_info_tag;
    char* rnti;
    char* crc_ind_rel8_tag;
    int crcflag;
    Node* next;
} NFAPI_CRC_INDICATION_PDU_T;

