    ErrorStruct* error = LinkedListManager(10);
    if (error) {
        printf("Error code: %d, Message: %s\n", error->errorCode, error->errorMessage);
        free(error); // Free the custom error structure
    } else {
        printf("Linked list initialization successful!\n");
    }

    return 0;
}
