// Configurable noise figure (dB)
int N0 = 5; // Default value in dB

// Dynamic array of UplinkMeasurementReport structures
UplinkMeasurementReport** uplinkMeasurements;

// Function to initialize and manage the dynamic array
void initAndManageUplinkMeasurements(int numUes) {
    int i;

    // Allocate memory for the dynamic array
    uplinkMeasurements = (UplinkMeasurementReport**)malloc(numUes * sizeof(UplinkMeasurementReport*));

    // Initialize each element in the array
    for (i = 0; i < numUes; i++) {
        uplinkMeasurements[i] = (UplinkMeasurementReport*)malloc(sizeof(UplinkMeasurementReport));

        // Validate and set default values for CellIdentity, RSSI, and SINR
        uplinkMeasurements[i]->cellIdentity = -1;
        uplinkMeasurements[i]->rssi = 0;
        uplinkMeasurements[i]->sinr = 0;
    }
}

// Function to update an individual element in the dynamic array
void updateUplinkMeasurement(int ueIndex, int cellIdentity, int rssi, int sinr) {
    if (ueIndex < 0 || ueIndex >= sizeof(uplinkMeasurements)/sizeof(UplinkMeasurementReport*))
        // Handle out-of-range error for UE index
        return;

    uplinkMeasurements[ueIndex]->cellIdentity = cellIdentity;
    uplinkMeasurements[ueIndex]->rssi = rssi;
    uplinkMeasurements[ueIndex]->sinr = sinr;

    // Calculate and store SNR value based on the formula
    uplinkMeasurements[ueIndex]->snr = sinr + N0;
}

// Function to free memory allocated for the dynamic array
void freeUplinkMeasurements() {
    int i;

    // Free each element in the array
    for (i = 0; i < sizeof(uplinkMeasurements)/sizeof(UplinkMeasurementReport*); i++) {
        free(uplinkMeasurements[i]);
    }

    // Free the dynamic array itself
    free(uplinkMeasurements);
}
