#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define LOG_LINE_MAX 1024
#define REPORT_INTERVAL 1000 // in milliseconds

typedef struct {
    char timestamp[LOG_LINE_MAX];
    char method[LOG_LINE_MAX];
    char url[LOG_LINE_MAX];
    int response_code;
    char client_ip[LOG_LINE_MAX];
} LogEntry;

typedef struct {
    char url[LOG_LINE_MAX];
    long total_requests;
    double avg_response_time;
} ReportEntry;

void process_log_file(const char* log_file_path);
void generate_report(ReportEntry report_entries[], int num_entries);

int main() {
    const char* log_file_path = "path_to_your_log_file.log";
    process_log_file(log_file_path);
    return 0;
}

void process_log_file(const char* log_file_path) {
    FILE* file = fopen(log_file_path, "r");
    if (file == NULL) {
        printf("Error opening log file.\n");
        return;
    }

    LogEntry log_entry;
    ReportEntry report_entries[1024]; // Initial capacity
    int num_report_entries = 0;

    while (1) {
        if (fscanf(file, "%s %s %s %d %s\n", log_entry.timestamp, log_entry.method, log_entry.url, &log_entry.response_code, log_entry.client_ip) != 5) {
            break; // End of file
        }

        // Validate and process log entry
        if (strlen(log_entry.url) > LOG_LINE_MAX || strlen(log_entry.client_ip) > LOG_LINE_MAX) {
            printf("Ignoring malformed log entry: %s\n", log_entry.url);
            continue;
        }

        ReportEntry report_entry;
        int i = 0;
        for (; i < num_report_entries; i++) {
            if (strcmp(report_entries[i].url, log_entry.url) == 0) {
                break; // Found matching URL
            }
        }

        if (i >= num_report_entries) {
            report_entry.total_requests = 1;
            report_entry.avg_response_time = log_entry.response_code / 100.0;
            strcpy(report_entry.url, log_entry.url);
            num_report_entries++;
            if (num_report_entries > 1024) { // Resize array
                ReportEntry* new_array = realloc(report_entries, sizeof(ReportEntry) * (num_report_entries + 512));
                report_entries = new_array;
            }
        } else {
            report_entry.total_requests++;
            report_entry.avg_response_time += log_entry.response_code / 100.0;
        }

        // Print real-time summary report every REPORT_INTERVAL milliseconds
        if (++num_report_entries % (REPORT_INTERVAL / 10) == 0) {
            generate_report(report_entries, num_report_entries);
        }
    }

    fclose(file);
}

void generate_report(ReportEntry report_entries[], int num_entries) {
    printf("Total requests: %d\n", num_entries);
    double successful_responses = 0.0;
    for (int i = 0; i < num_entries; i++) {
        if (report_entries[i].response_code >= 200 && report_entries[i].response_code <= 299) {
            successful_responses++;
        }
        printf("URL: %s, Total requests: %d, Average response time: %.2f\n", report_entries[i].url, report_entries[i].total_requests, report_entries[i].avg_response_time);
    }
    printf("Percentage of successful responses: %.2f%%\n", (successful_responses / num_entries) * 100.0);
}
