void* allocate_array(int n) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int* array_size = (int*)malloc(sizeof(int));
    *array_size = 0;

    void** array = NULL;
    while (*array_size < n && (array = (void**)realloc(array, (*array_size + 1) * sizeof(void*))) != NULL) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu) {
            free(array);
            free(array_size);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 2000;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 3000;
        pdu->CRCFLAG = (rand() % 2) ? 1 : 0;

        array[*array_size] = pdu;
        (*array_size)++;

        pthread_mutex_unlock(&mutex);
    }

    free(array_size);
    return array;
}

int write_array_to_file(void** array, int size, const char* filepath) {
    FILE* file = fopen(filepath, "wb");
    if (!file) {
        for (int i = 0; i < size; i++) {
            free((void*)array[i]);
        }
        free(array);
        return -1;
    }

    for (int i = 0; i < size; i++) {
        fwrite(&((NFAPI_CRC_INDICATION_PDU_T*)array[i]), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
    return 0;
}

int main() {
    int n = 1000; // adjust this to your desired array size
    const char* filepath = "output.bin";

    void** array = allocate_array(n);

    if (!array) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    int written_size = write_array_to_file(array, n, filepath);

    if (written_size < 0) {
        printf("Error writing to file: %s\n", filepath);
    } else {
        printf("Wrote %d structures to file.\n", written_size);
    }

    for (int i = 0; i < n; i++) {
        free((void*)array[i]);
    }

    free(array);

    return 0;
}
