} record;

record *create_record_list(int num_records, int min_value, int max_value) {
    if (num_records <= 0) {
        printf("Invalid number of records.\n");
        return NULL;
    }

    srand(time(NULL)); // seed random number generator

    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].offset = i;
        records[i].key = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        if (!records[i].offset || !records[i].key || !records[i].value) {
            printf("Error initializing record.\n");
            free(records);
            return NULL;
        }
    }

    return records;
}

void destroy_record_list(record *records, int num_records) {
    if (records && num_records > 0) {
        for (int i = 0; i < num_records; i++) {
            free(&records[i]);
        }
        free(records);
    }
}

record *get_record(record *records, int index) {
    if (!records || index < 0) {
        printf("Error getting record.\n");
        return NULL;
    }

    return &records[index];
}
