NFAPI_CRC_INDICATION_PDU_T *createPDU(int RNTI, int RX_UE_INFORMATION_TAG) {
    // Calculate CRCFLAG based on RNTI's parity
    int CRCFLAG = (RNTI & 0x1) ? 0x1 : 0x0;

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    strcpy(pdu->CRC_INDICATION_REL8_TAG, "CRCFLAG"); // Initialize with CRCFLAG

    return pdu;
}

void *createPDUThread(void *arg) {
    int numPDUs = *((int *)arg);
    pthread_exit(NULL);
}

int managePDUList(int N, double RNTIProbability, int maxPdusPerCall) {
    if (N <= 0 || RNTIProbability < 0 || RNTIProbability > 1 || maxPdusPerCall <= 0)
        return -1;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *pdulist = NULL;
    int numPDUs = 0;
    double randomVal;

    while (numPDUs < N) {
        randomVal = (double)rand() / RAND_MAX;
        if (randomVal <= RNTIProbability && numPDUs < maxPdusPerCall) {
            pthread_t thread;
            int *numPdusPtr = &numPDUs;

            pthread_create(&thread, NULL, createPDUThread, numPdusPtr);
            pthread_join(thread, NULL);

            NFAPI_CRC_INDICATION_PDU_T *pdu = createPDU(numPDUs, numPDUs + 1);
            if (!pdu) return -2;

            pdulist = (NFAPI_CRC_INDICATION_PDU_T **)realloc(pdulist, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * ++numPDUs);
            if (!pdulist) return -3;
            pdulist[numPDUs - 1] = pdu;
        }
    }

    // Adjust logging frequency based on system load
    if (numPDUs > MAX_PDU / LOG_FREQ) {
        LOG_FREQ /= 2;
        // Implement dynamic adjustment logic here
    }

    pthread_mutex_unlock(&lock);

    return numPDUs;
}

int main() {
    int N = 100; // Desired number of PDUs
    double RNTIProbability = 0.5; // Probability of including a particular RNTI
    int maxPdusPerCall = 10; // Maximum number of PDUs per call

    int result = managePDUList(N, RNTIProbability, maxPdusPerCall);
    return result;
}

