    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* struct_pointer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Generate unique RNTI
        int rnti = rand() % 1000000;
        struct_pointer->RNTI = rnti;

        // Set valid RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
        char rx_tag[] = "VALID_RX_UE_INFORMATION_TAG";
        strcpy(struct_pointer->RX_UE_INFORMATION_TAG, rx_tag);
        char crc_tag[] = "CRC_INDICATION_REL8_TAG_VALID";
        strcpy(struct_pointer->CRC_INDICATION_REL8_TAG, crc_tag);

        // Randomly set CRCFLAG
        struct_pointer->CRCFLAG = rand() % 2;

        list[i] = struct_pointer;
    }

    pthread_mutex_destroy(&lock);

    return (void*)list;
}

