    for (size_t i = 0; i < n; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T* pdu = list[i];

        if (validate_crc_indication(pdu) != 0) {
            reacquire_rnti(pdu);
        }
    }

    free(list);

    return 0;
}
