// Function to dynamically populate a list of LTE_RRC_RECONFIGURATION_COMPLETE structures
void* generate_list(int num_elements, FILE *log_file) {
    // Initialize the list and its size
    LTE_RRC_RECONFIGURATION_COMPLETE **list = NULL;
    int list_size = 0;

    // Create a lock for thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop through the desired number of elements
    for (int i = 0; i < num_elements; i++) {
        // Allocate memory for the structure
        LTE_RRC_RECONFIGURATION_COMPLETE *new_element = NULL;

        // Attempt to allocate memory for the structure
        while ((new_element = (LTE_RRC_RECONFIGURATION_COMPLETE *)malloc(sizeof(LTE_RRC_RECONFIGURATION_COMPLETE))) == NULL) {
            // Log an error if allocation fails
            fprintf(log_file, "Error allocating memory for LTE_RRC_RECONFIGURATION_COMPLETE: %s\n", strerror(errno));

            // If the allocation failed, exit the function
            return NULL;
        }

        // Initialize the structure with a unique S-TMSI and random QoS_INDICATION
        new_element->S_TMSI = i;  // Unique S-TMSI value for each element
        new_element->QoS_INDICATION = rand() % 100 + 1;  // Random QoS INDICATION

        // Set the UE_IDENTITY_TAG to a unique identifier and the NAS_MESSAGE to a random string
        sprintf(new_element->UE_IDENTITY_TAG, "UE_%d", i);
        for (int j = 0; j < 64; j++) {
            new_element->NAS_MESSAGE[j] = (char)(rand() % 26 + 'a');
        }

        // Add the new element to the list
        pthread_mutex_lock(&mutex);
        if (list == NULL) {
            list = &new_element;
            list_size = 1;
        } else {
            int* temp_list_size = &list_size;
            LTE_RRC_RECONFIGURATION_COMPLETE** temp_list = list;

            // Dynamically resize the list to accommodate the new element
            while (*temp_list_size <= i) {
                *temp_list_size *= 2;
                temp_list = (LTE_RRC_RECONFIGURATION_COMPLETE**)realloc(*temp_list, sizeof(LTE_RRC_RECONFIGURATION_COMPLETE*) * (*temp_list_size));
                if (temp_list == NULL) {
                    // Log an error if reallocation fails
                    fprintf(log_file, "Error reallocating memory for LTE_RRC_RECONFIGURATION_COMPLETE list: %s\n", strerror(errno));

                    // If the reallocation failed, exit the function
                    return NULL;
                }
            }

            // Add the new element to the list
            *temp_list = (LTE_RRC_RECONFIGURATION_COMPLETE*)realloc(*temp_list, sizeof(LTE_RRC_RECONFIGURATION_COMPLETE) + (*temp_list_size - 1) * sizeof(LTE_RRC_RECONFIGURATION_COMPLETE));
            if (*temp_list == NULL) {
                // Log an error if reallocation fails
                fprintf(log_file, "Error reallocating memory for LTE_RRC_RECONFIGURATION_COMPLETE list: %s\n", strerror(errno));

                // If the reallocation failed, exit the function
                return NULL;
            }

            (*temp_list)[i] = *new_element;
        }

        pthread_mutex_unlock(&mutex);
    }

    // Return the populated list
    return (void*)list;
}
