typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* prev;
    struct node* next;
} Node;

Node* head = NULL;
int rnti_count = 0;

void add_node(NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed!\n");
        return;
    }
    new_node->data = new_data;
    new_node->prev = NULL;
    new_node->next = head;

    if (head != NULL) {
        head->prev = &new_node->data;
    } else {
        rnti_count++;
    }

    head = new_node;
}

void remove_node(int rnti) {
    Node* current = head;
    while (current && current->data.RNTI != rnti) {
        current = current->next;
    }
    if (!current) {
        printf("RNTI not found!\n");
        return;
    }

    if (current == head) {
        head = head->next;
    } else {
        current->prev->next = current->next;
    }

    if (current == tail()) {
        tail()->prev = NULL;
    } else {
        current->next->prev = current->prev;
    }

    free(current);

    rnti_count--;
}

NFAPI_CRC_INDICATION_PDU_T* find_node(int rnti) {
    Node* current = head;
    while (current && current->data.RNTI != rnti) {
        current = current->next;
    }
    if (!current) {
        printf("RNTI not found!\n");
        return NULL;
    }

    return &current->data;
}

int is_empty() {
    return head == NULL;
}

Node* tail() {
    Node* current = head;
    while (current && current->next != NULL) {
        current = current->next;
    }
    return current;
}

