    if (!arr) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    return arr;
}

int init_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t n) {
    *array = alloc_array(n);
    if (*array == NULL)
        return -1;

    for (size_t i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = &(*array)[i];
        p->RX_UE_INFORMATION_TAG = rand();
        p->RNTI = rand();
        p->CRC_INDICATION_REL8_TAG = rand();
    }
    return 0;
}

int resize_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* n) {
    *n *= 2;
    void* arr = realloc(*array, (*n) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) {
        printf("Memory reallocation failed!\n");
        return -1;
    }
    *array = arr;
    return 0;
}

int reset_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* n) {
    free(*array);
    *n = 0;
    return 0;
}

