#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define M 1000 // maximum number of sessions allowed

typedef struct {
    int id;
    char** devices; // array of device MAC addresses
    time_t timestamp;
    int status; // active (1) or inactive (0)
} Session;

Session* create_session(int id, int num_devices);
void add_device(Session* session, const char* mac);
int find_device(Session* session, const char* mac);
void update_timestamp(Session* session);
void set_status(Session* session, int new_status);

Session* sessions[M];
int num_sessions = 0;

void manage_sessions() {
    int choice;
    while (1) {
        printf("1. Create a new session\n");
        printf("2. Add device to existing session\n");
        printf("3. Update last activity timestamp for all active sessions\n");
        printf("4. Set status of an existing session\n");
        printf("5. Exit\n");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                if (num_sessions >= M) {
                    printf("Error: Maximum number of sessions reached.\n");
                } else {
                    int id;
                    printf("Enter the session ID: ");
                    scanf("%d", &id);
                    sessions[num_sessions] = create_session(id, 0);
                    num_sessions++;
                }
                break;
            case 2:
                if (num_sessions > 0) {
                    int index;
                    printf("Enter the existing session ID: ");
                    scanf("%d", &index);
                    Session* session = &sessions[index];
                    if (session->status == 1) {
                        char mac[18];
                        printf("Enter the device MAC address: ");
                        scanf("%17s", mac);
                        add_device(session, mac);
                    } else {
                        printf("Error: Session is inactive.\n");
                    }
                } else {
                    printf("Error: No active sessions found.\n");
                }
                break;
            case 3:
                if (num_sessions > 0) {
                    for (int i = 0; i < num_sessions; i++) {
                        Session* session = &sessions[i];
                        if (session->status == 1) {
                            update_timestamp(session);
                        }
                    }
                } else {
                    printf("Error: No active sessions found.\n");
                }
                break;
            case 4:
                if (num_sessions > 0) {
                    int index;
                    printf("Enter the existing session ID: ");
                    scanf("%d", &index);
                    Session* session = &sessions[index];
                    if (session->status == 1) {
                        int new_status;
                        printf("Enter the new status (1 for active, 0 for inactive): ");
                        scanf("%d", &new_status);
                        set_status(session, new_status);
                    } else {
                        printf("Error: Session is inactive.\n");
                    }
                } else {
                    printf("Error: No sessions found.\n");
                }
                break;
            case 5:
                return;
        }
    }
}

Session* create_session(int id, int num_devices) {
    Session* session = (Session*)malloc(sizeof(Session));
    session->id = id;
    session->devices = (char**)malloc((num_devices + 1)*sizeof(char*));
    session->timestamp = time(NULL);
    session->status = 1; // default status: active
    return session;
}

void add_device(Session* session, const char* mac) {
    int i;
    for (i = 0; i <= session->num_devices; i++) {
        if (!session->devices[i]) {
            break;
        }
    }
    session->devices[i] = (char*)malloc((strlen(mac) + 1)*sizeof(char));
    strcpy(session->devices[i], mac);
}

int find_device(Session* session, const char* mac) {
    int i;
    for (i = 0; i < session->num_devices; i++) {
        if (!strcmp(session->devices[i], mac)) {
            return i;
        }
    }
    return -1; // device not found
}

void update_timestamp(Session* session) {
    session->timestamp = time(NULL);
}

void set_status(Session* session, int new_status) {
    session->status = new_status;
}
