#define MAX_MEMORY_POOL_SIZE 1024*1024 // 1MB
#define MEMORY_COMPACTION_THRESHOLD 0.5 // 50% used memory before compaction is triggered
#define SEED 42 // default seed for generating random CRCFLAG values

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_memory_pool(int N, int* total_allocations, int* total_failures) {
    if (N <= 0 || MAX_MEMORY_POOL_SIZE < sizeof(NFAPI_CRC_INDICATION_PDU_T) * N) {
        return NULL;
    }

    unsigned char* memory_pool = malloc(MAX_MEMORY_POOL_SIZE);
    if (!memory_pool) {
        (*total_failures)++;
        return NULL;
    }

    srand(SEED); // initialize random seed

    for (int i = 0; i < N; i++) {
        int offset = rand() % (MAX_MEMORY_POOL_SIZE - sizeof(NFAPI_CRC_INDICATION_PDU_T));
        void* allocation = &memory_pool[offset];

        if (allocation) {
            NFAPI_CRC_INDICATION_PDU_T* ptr = (NFAPI_CRC_INDICATION_PDU_T*)allocation;
            ptr->RX_UE_INFORMATION_TAG = rand();
            ptr->RNTI = i;
            ptr->CRC_INDICATION_REL8_TAG = 1234; // some arbitrary value
            ptr->CRCFLAG = rand() & 0x1; // toggle CRCFLAG randomly

            (*total_allocations)++;
        } else {
            (*total_failures)++;
        }
    }

    return (NFAPI_CRC_INDICATION_PDU_T*)memory_pool;
}

void deallocate_memory_pool(NFAPI_CRC_INDICATION_PDU_T* memory_pool, int N) {
    if (!memory_pool || !N) {
        return;
    }

    free((void*)memory_pool);
}
