// Function to manage the dynamic array
void* lte_phy_rxueinfo_array_create(int initial_size) {
    // Create a custom allocator
    void (*malloc_allocator)(size_t, int*) = malloc;
    void (*free_allocator)(void*, int*) = free;

    // Initialize the array and its size
    LTE_PHY_RXUEINFO_TAG** array = (LTE_PHY_RXUEINFO_TAG**)malloc_allocator(sizeof(LTE_PHY_RXUEINFO_TAG*) * initial_size, NULL);
    int* size = (int*)malloc_allocator(sizeof(int), NULL);
    *size = 0;

    // Initialize the last allocated index
    int* last_allocated_index = (int*)malloc_allocator(sizeof(int), NULL);
    *last_allocated_index = -1;

    return (void*)array;
}

// Function to insert a new entry into the array
void lte_phy_rxueinfo_array_insert(void** array, int* size, int* last_allocated_index, LTE_PHY_RXUEINFO_TAG* new_entry) {
    // Resize the array if necessary
    if (*size >= *last_allocated_index + 1) {
        *array = (LTE_PHY_RXUEINFO_TAG**)realloc(array, sizeof(LTE_PHY_RXUEINFO_TAG*) * (*size * 2), NULL);
        *last_allocated_index = *size - 1;
    }

    // Copy the new entry into the array
    array[(*size)++] = new_entry;

    return;
}

// Function to delete an entry from the array
void lte_phy_rxueinfo_array_delete(void** array, int* size) {
    // Check if the array is empty
    if (*size == 0) {
        printf("Error: Array is empty.\n");
        return;
    }

    // Free the last allocated index and decrement the size
    free(array[--(*size)]);
    array[*size] = NULL;

    return;
}

// Function to retrieve an entry from the array
LTE_PHY_RXUEINFO_TAG* lte_phy_rxueinfo_array_get(void** array, int* size, int index) {
    // Check if the index is within bounds
    if (index >= *size || index < 0) {
        printf("Error: Index out of range.\n");
        return NULL;
    }

    // Return the entry at the specified index
    return array[index];
}

// Function to free the array and its resources
void lte_phy_rxueinfo_array_free(void** array, int* size, void (*free_allocator)(void*, int*) , int* last_allocated_index) {
    // Free each entry in the array
    for (int i = 0; i < *size; i++) {
        free_allocator(array[i], NULL);
    }

    // Free the array itself and its resources
    free_allocator(array, NULL);

    // Reset the size and last allocated index
    *size = 0;
    *last_allocated_index = -1;

    return;
}
