#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CAPACITY 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct list_node *next;
};

struct list {
    struct list_node *head;
    pthread_mutex_t mutex;
    size_t capacity;
};

void* custom_allocator(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        return NULL;
    }
    if (!is_aligned(ptr, size)) {
        free(ptr);
        return custom_allocator(size);
    }
    return ptr;
}

int is_aligned(void* addr, size_t alignment) {
    return ((size_t)addr % alignment) == 0;
}

struct list* create_list(size_t capacity) {
    struct list* list = (struct list*)custom_allocator(sizeof(struct list));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->capacity = capacity;
    return list;
}

void destroy_list(struct list* list) {
    struct list_node* current = list->head;
    struct list_node* next = NULL;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insert_list(struct list* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL || list->head->next != NULL) {
        struct list_node* new_node = (struct list_node*)custom_allocator(sizeof(struct list_node));
        new_node->data = data;
        new_node->next = list->head;
        list->head = new_node;

        if (++list->capacity > MAX_CAPACITY) {
            printf("List capacity exceeded. Truncating.\n");
            list->capacity = MAX_CAPACITY;
        }
    } else {
        printf("Error: List is full.\n");
        return -1;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int main() {
    // Initialize the list with a capacity of 100
    struct list* my_list = create_list(100);

    // Insert data into the list
    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data->RX_UE_INFORMATION_TAG = i;
        data->RNTI = i * 2;
        data->CRC_INDICATION_REL8_TAG = i * 3;
        // Set CRCFLAG randomly
        data->CRCFLAG = rand() % 2;

        insert_list(my_list, data);
    }

    destroy_list(my_list);

    return 0;
}
