    // Handle external monitoring service
    time_t current_time = time(NULL);
    for (int i = 0; i < connections_count; i++) {
        if (difftime(current_time, connections[i].last_activity) > 60) { // Inactive after 1 minute
            // Mark as idle or closed
            // Notify application of connection status change
            // ...
        }
    }

    // Periodic cleanup
    for (int i = connections_count - 1; i >= 0; i--) {
        if (difftime(current_time, connections[i].last_activity) > 3600) { // Inactive after 1 hour
            free(connections + i);
            connections_count--;
        } else if (connections_count >= max_size) {
            // Truncate excess connections or mark them as inactive
            free(connections + i);
            connections_count--;
        }
    }

    // Reallocate memory for updated connections list
    connections = realloc(connections, sizeof(Connection) * connections_count);
}

int add_connection(int id) {
