struct lru_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct lru_node* prev;
    struct lru_node* next;
};

struct memory_pool {
    size_t capacity;
    size_t used;
    struct lru_node* head;
    struct lru_node* tail;
    pthread_mutex_t lock;
};

void init_memory_pool(struct memory_pool* pool) {
    pool->capacity = MAX_POOL_SIZE;
    pool->used = 0;
    pool->head = NULL;
    pool->tail = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_pool(struct memory_pool* pool) {
    NFAPI_CRC_INDICATION_PDU_T* ret = NULL;

    pthread_mutex_lock(&pool->lock);

    if (pool->head == NULL) {
        ret = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool->used++;
    } else {
        struct lru_node* node = pool->head;
        pool->head = node->next;
        node->next = NULL;
        pool->used--;
        ret = node->data;
        free(node);
    }

    pthread_mutex_unlock(&pool->lock);

    return ret;
}

void put_to_pool(struct memory_pool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    struct lru_node* new_node = (struct lru_node*)malloc(sizeof(struct lru_node));
    new_node->data = data;

    pthread_mutex_lock(&pool->lock);

    if (pool->head == NULL) {
        pool->head = new_node;
        pool->tail = new_node;
    } else {
        pool->tail->next = new_node;
        pool->tail = new_node;
    }

    pool->used++;
    pthread_mutex_unlock(&pool->lock);
}

void free_pool(struct memory_pool* pool) {
    struct lru_node* current = pool->head;

    while (current != NULL) {
        struct lru_node* next = current->next;
        free(current);
        current = next;
    }

    pool->used = 0;
    pool->head = NULL;
    pool->tail = NULL;
}

