    // Initialize the head of the list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    int successful_additions = 0;

    // Loop through 'n' times to populate the linked list
    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Dynamically allocate memory for RNTI
        new_node->RNTI[0] = 'R';
        strcpy(new_node->RNTI + 1, "UE Information Tag");

        // Randomly set CRCFLAG and calculate the corresponding CRC value
        new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        if (new_node->CRC_INDICATION_REL8_TAG.CRCFLAG == 0) {
            // Simulate a correct CRC check
            printf("Valid CRC: New node added successfully.\n");
            successful_additions++;
        } else {
            // Handle the error gracefully and return an empty list
            printf("Invalid CRC. Aborting operation.\n");
            free(new_node);
            return head;
        }

        // Check if this is the first node in the list
        if (head == NULL) {
            head = new_node;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp = head;
            while (temp->next != NULL)
                temp = temp->next;
            temp->next = new_node;
        }
    }

    // Log the successful additions
    printf("Added %d nodes successfully.\n", successful_additions);

