#include "nfa_api_crc_indication_pdu_t.h"
#include "logging_framework.h"
#include "random_number_generator.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t lock;
} CRCIndicationList;

void crcIndicationListInit(CRCIndicationList* list, size_t initialCapacity) {
    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->lock = PTHREAD_MUTEX_INITIALIZER;
}

int crcIndicationListAdd(CRCIndationList* list, NFAPI_CRC_INDICATION_PDU_T* newEntry) {
    pthread_mutex_lock(&list->lock);

    // Check for duplicate RNTI
    int foundDuplicate = 0;
    for (size_t i = 0; i < list->data->length; i++) {
        if (newEntry->RNTI == list->data[i].RNTI) {
            foundDuplicate = 1;
            break;
        }
    }

    if (foundDuplicate) {
        LOG_ERROR(" Duplicate RNTI detected. Aborting.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Add new entry
    size_t newSize = list->data->length + 1;
    NFAPI_CRC_INDICATION_PDU_T* newData = realloc(list->data, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newData) {
        LOG_ERROR("Memory allocation failed.");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    list->data = newData;
    list->data[newSize-1] = *newEntry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void crcIndicationListDestroy(CRCIndicationList* list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}
