    char CRC_INDICATION_REL8_TAG[16];
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a hash table to store unique RX_UE_INFORMATION_TAG values
typedef struct {
    int* tags;
    int size;
    int capacity;
} HashTable;

HashTable* create_hash_table(int initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->tags = (int*)calloc(initial_capacity, sizeof(int));
    table->size = 0;
    table->capacity = initial_capacity;
    return table;
}

void free_hash_table(HashTable* table) {
    free(table->tags);
    free(table);
}

// Initialize an NFAPI_CRC_INDICATION_PDU_T structure with unique RX_UE_INFORMATION_TAG and RNTI
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_indication_pdu(int n, HashTable* hash_table) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Ensure unique RX_UE_INFORMATION_TAG values
    int tag;
    do {
        tag = rand() % 10000; // Generate a random RX_UE_INFORMATION_TAG
        if (!hash_table_lookup(hash_table, &tag)) { // Check for duplicate tags
            pdu->RX_UE_INFORMATION_TAG = tag;
            pdu->RNTI = rand() % 256; // Randomly set RNTI
            sprintf(pdu->CRC_INDICATION_REL8_TAG, "0x%08X", rand()); // Randomly set CRC_INDICATION_REL8_TAG and CRCFLAG
            pdu->CRCFLAG = rand();
            return pdu;
        }
    } while (1);
