    srand(time(NULL));

    // Initialize number of structures
    printf("Enter the number of structures (max 1000): ");
    scanf("%d", &n);

    // Dynamic memory allocation for arrays
    long *offsets = malloc(n * sizeof(long));
    int *keys = malloc(n * sizeof(int));
    double *values = malloc(n * sizeof(double));

    // Initialize arrays with random values
    for (i = 0; i < n; i++) {
        offsets[i] = rand() % 10000000L;
        keys[i] = rand() % 1000;
        values[i] = (double)rand() / RAND_MAX;
    }

    // Merge function to combine arrays
    int merge[n];
    for (i = 0; i < n; i++) {
        merge[i] = keys[i];
    }
    qsort(merge, n, sizeof(int), compare);

    // Print merged array
    for (i = 0; i < n; i++) {
        printf("%d ", merge[i]);
    }
    printf("\n");

    return 0;
}

// Comparison function for qsort()
int compare(const void *a, const void *b) {
    int fa = *(const int *)a;
    int fb = *(const int *)b;
    if (fa < fb)
        return -1;
    else if (fa > fb)
        return 1;
    return 0;
}
