void* operator new(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle memory allocation failure
        printf("Memory allocation failed!\n");
    }
    return ptr;
}

int populateNFAPI_CRC_INDICATION_PDU_T_array(int maxElements, int *arraySize, NFAPI_CRC_INDICATION_PDU_T **array) {
    srand(time(NULL));
    *arraySize = 0;

    // Pre-allocate memory to minimize reallocations
    NFAPI_CRC_INDICATION_PDU_T *tempArray = new NFAPI_CRC_INDICATION_PDU_T[maxElements];
    if (!tempArray) {
        printf("Memory allocation failed!\n");
        return -1; // Fail silently
    }

    for (int i = 0; i < maxElements; i++) {
        tempArray[i].RNTI = i;
        strcpy(tempArray[i].RX_UE_INFORMATION_TAG, "RX_INFO_TAG_");
        sprintf(tempArray[i].CRC_INDICATION_REL8_TAG, "REL8_TAG_%d", i);
        if (rand() & CRCFLAG_BITMASK) {
            tempArray[i].CRCFLAG = 1;
        } else {
            tempArray[i].CRCFLAG = 0;
        }

        // Check for duplicate RNTI values
        bool duplicateFound = false;
        for (int j = 0; j < *arraySize; j++) {
            if (tempArray[i].RNTI == (*array)[j]->RNTI) {
                duplicateFound = true;
                break;
            }
        }

        if (!duplicateFound) {
            (*arraySize)++;
            (*array) = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (*arraySize));
            (*array)[*arraySize - 1] = &tempArray[i];
        } else {
            // Handle duplicate RNTI value
            printf("Duplicate RNTI found! Skipping this iteration.\n");
        }
    }

    free(tempArray);
    return 0;
}

int main() {
    int maxElements = MAX_ELEMENTS;
    int arraySize = 0;
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    populateNFAPI_CRC_INDICATION_PDU_T_array(maxElements, &arraySize, &array);

