#include "nfa_api_crc_indication_pdu_t.h"
#include "logging_framework.h"
#include "message_queue_system.h"

void create_and_populate_nfapi_crc_indication_pdu_ts(size_t n, double probability, size_t max_pdu_limit) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    RNTI rnti = 0;

    // Initialize the logging framework
    LOG_INIT();

    if (pthread_mutex_init(&lock, NULL) != 0) {
        LOG_ERROR("Failed to initialize lock");
        return;
    }

    // Create a message queue for PDU processing tasks
    message_queue_t* pq = message_queue_create();
    pthread_mutex_lock(&lock);

    while (rnti < n) {
        if (rand() % 100 <= probability * 100) {
            pdus[rnti].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_valid;
        } else {
            pdus[rnti].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_invalid;
        }

        rnti++;
    }

    pthread_mutex_unlock(&lock);

    if (pthread_join(pq, NULL) != 0) {
        LOG_ERROR("Failed to join PDU processing thread");
    }

    message_queue_destroy(pq);
}
