            printf("Structure %d: RNTI=%u, CRCFLAG=%d\n", i, pds[i].rnti, pds[i].crcflag);
        }
    }

    if (log_enabled && log_level > 0) {
        printf("Total structures created: %d\n", log_total);
    }

    return pds;
}

int serialize_and_write_to_file(NFAPI_CRC_INDICATION_PDU_T* pds, int num_structures, const char* file_path, int compress) {
    int fd = open(file_path, O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        printf("Error: Unable to open file\n");
        return -1;
    }

    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    int ret = deflateInit2(&strm, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 31, Z_DEFAULT_CHUNK, Z_DEFAULT_MEM);
    if (ret != Z_OK) {
        printf("Error: Unable to initialize compression\n");
        close(fd);
        return -1;
    }

    char* buffer = (char*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(buffer, pds, num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (compress) {
        strm.next_in = (void*)buffer;
        strm.avail_in = num_structures * sizeof(NFAPI_CRC_INDATION_PDU_T);
        strm.total_out = 0;

        do {
            uint32_t len = Z_BUFSIZE;
            strm.next_out = buffer + strm.total_out;
            strm.avail_out = len;

            ret = deflate(&strm, Z_FINISH);
            if (ret != Z_STREAM_END) {
                printf("Error: Unable to compress data\n");
                free(buffer);
                deflateEnd(&strm);
                close(fd);
                return -1;
            }
        } while (ret == Z_OK);

        write(fd, buffer, strm.total_out);
    } else {
        write(fd, buffer, num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    free(buffer);
    deflateEnd(&strm);
    close(fd);

    return 0;
}
