#define NRCELLCONFIG_MAX 1000
#define BWP_RANGE_MIN 1
#define BWP_RANGE_MAX 1000000

typedef struct {
    int bwp;
    int subcarrier_spacing;
    int frequency;
} NRCellConfig;

pthread_mutex_t cell_config_lock = PTHREAD_MUTEX_INITIALIZER;
NRCellConfig *cell_configs[NRCELLCONFIG_MAX];
int num_cells = 0;

void *get_cell_config(int idx) {
    return &cell_configs[idx];
}

void add_cell_config(NRCellConfig *config) {
    pthread_mutex_lock(&cell_config_lock);
    cell_configs[num_cells] = config;
    num_cells++;
    pthread_mutex_unlock(&cell_config_lock);
}

int get_num_cells() {
    return num_cells;
}

NRCellConfig *get_cell_config(int idx) {
    if (idx >= 0 && idx < num_cells)
        return &cell_configs[idx];
    return NULL;
}

void update_cell_config(NRCellConfig *config, int idx) {
    pthread_mutex_lock(&cell_config_lock);
    if (idx >= 0 && idx < num_cells) {
        cell_configs[idx] = config;
        // conflict detection and resolution mechanism
        for (int i = 0; i < num_cells; i++) {
            NRCellConfig *other_config = &cell_configs[i];
            if (other_config->bwp != config->bwp &&
                other_config->frequency <= config->frequency + BWP_RANGE_MAX &&
                other_config->frequency >= config->frequency - BWP_RANGE_MIN) {
                // adjust overlapping BWPs to non-overlapping regions
                int new_bwp = other_config->bwp;
                while (new_bwp == config->bwp) {
                    new_bwp++;
                    if (new_bwp > BWP_RANGE_MAX)
                        break;
                }
                other_config->frequency += BWP_RANGE_MIN;
            }
        }
    }
    pthread_mutex_unlock(&cell_config_lock);
}

void *stress_test_thread(void *arg) {
    for (int i = 0; i < NRCELLCONFIG_MAX; i++) {
        NRCellConfig config;
        config.bwp = rand() % BWP_RANGE_MAX + BWP_RANGE_MIN;
        config.subcarrier_spacing = rand() % 100 + 1;
        config.frequency = rand() % 1000000 + 1;
        add_cell_config(&config);
    }
    return NULL;
}

int main() {
    pthread_t threads[NRCELLCONFIG_MAX];
    for (int i = 0; i < NRCELLCONFIG_MAX; i++) {
        pthread_create(&threads[i], NULL, stress_test_thread, NULL);
    }
    for (int i = 0; i < NRCELLCONFIG_MAX; i++)
        pthread_join(threads[i]);
    return 0;
}
