void* mac_context_array_manager() {
    // Initialize the total count of allocated instances
    static uint32_t total_instances_allocated = 0;

    // Allocate and deallocate memory for MAC_CONTEXT_T instances
    void** context_array = NULL;
    uint32_t current_capacity = 0;
    uint32_t current_size = 0;
    int is_shrink_required = 0;

    while (1) {
        // Track the total number of allocated instances
        total_instances_allocated++;

        // Allocate memory for a new MAC_CONTEXT_T instance
        void* context_ptr = malloc(sizeof(MAC_CONTEXT_T));
        if (context_ptr == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Consolidate contiguous blocks of memory to reduce fragmentation and improve cache locality
        if (current_size == current_capacity) {
            current_capacity *= 2;
            context_array = realloc(context_array, sizeof(void*) * current_capacity);
            is_shrink_required = 1;
        }

        // Reuse existing memory where possible
        int reused_memory = 0;
        for (int i = 0; i < current_size; i++) {
            if ((context_array[i]->ref_count > 0) && (context_array[i]->last_usage_timestamp == current_size)) {
                context_ptr = context_array[i];
                reused_memory = 1;
                break;
            }
        }

        // Update the reference count and timestamp
        if (!reused_memory) {
            ((MAC_CONTEXT_T*)context_ptr)->ref_count = 0;
            ((MAC_CONTEXT_T*)context_ptr)->last_usage_timestamp = current_size++;
        } else {
            ((MAC_CONTEXT_T*)context_ptr)->ref_count--;
            ((MAC_CONTEXT_T*)context_ptr)->last_usage_timestamp = current_size - 1;
