// Define the NFAPI_CRC_INDICATION_PDU_T struct collection type
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    unsigned int size;
    unsigned int capacity;
} NFAPI_CRC_INDICATION_PDU_T_COLLECTION;

// Function to create a new collection with initial capacity
NFAPI_CRC_INDICATION_PDU_T_COLLECTION* nfaapi_crc_indication_pdu_t_collection_create(unsigned int initial_capacity) {
    NFAPI_CRC_INDICATION_PDU_T_COLLECTION* collection = (NFAPI_CRC_INDICATION_PDU_T_COLLECTION*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_COLLECTION));
    if (!collection) return NULL;
    collection->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    collection->size = 0;
    collection->capacity = initial_capacity;
    return collection;
}

// Function to resize the collection
void nfaapi_crc_indication_pdu_t_collection_resize(NFAPI_CRC_INDICATION_PDU_T_COLLECTION* collection, unsigned int new_size) {
    if (collection->data == NULL || new_size <= collection->size) return;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        free(collection->data);
        collection->data = NULL;
    } else {
        collection->data = new_data;
        collection->capacity = new_size;
    }
}

// Function to add a new structure to the collection
int nfaapi_crc_indication_pdu_t_collection_add(NFAPI_CRC_INDICATION_PDU_T_COLLECTION* collection, NFAPI_CRC_INDICATION_PDU_T new_struct) {
    if (collection->size >= collection->capacity) {
        nfaapi_crc_indication_pdu_t_collection_resize(collection, collection->capacity * 2);
    }
    memcpy(&collection->data[collection->size], &new_struct, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    collection->size++;
    return 0;
