// Define a structure to hold NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_list(int N) {
    // Initialize a pointer to the start of the list
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize a random number generator
    srand(time(NULL));

    int min_RNTI = 0;  // Define the minimum valid RNTI value
    int max_RNTI = 65535;  // Define the maximum valid RNTI value

    for (int i = 0; i < N; i++) {
        // Randomly set CRCFLAG
        list[i].CRCFLAG = rand() % 2;

        // Generate a random RNTI within the valid range
        int rnti = rand() % ((max_RNTI - min_RNTI) + 1) + min_RNTI;

        while (rnti < min_RNTI || rnti > max_RNTI) {
            rnti = rand() % ((max_RNTI - min_RNTI) + 1) + min_RNTI;
        }

        // Set the RNTI and RX_UE_INFORMATION_TAG for each structure
        list[i].RNTI = rnti;
        list[i].RX_UE_INFORMATION_TAG = i;

        // Validate uniqueness of RNTI values
        int unique = 1;
        for (int j = 0; j < i; j++) {
            if (list[j].RNTI == list[i].RNTI) {
                unique = 0;
                break;
            }
        }

        while (!unique) {
            // Regenerate the RNTI value until it is unique
            rnti = rand() % ((max_RNTI - min_RNTI) + 1) + min_RNTI;

            while (rnti < min_RNTI || rnti > max_RNTI) {
                rnti = rand() % ((max_RNTI - min_RNTI) + 1) + min_RNTI;
            }

            list[i].RNTI = rnti;
            unique = 1;

            for (int j = 0; j < i; j++) {
                if (list[j].RNTI == list[i].RNTI) {
                    unique = 0;
                    break;
                }
            }
        }
    }

    return list;
}

// Function to iterate over the list and print the contents of each NFAPI_CRC_INDICATION_PDU_T structure
void print_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
