// Define structure
typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[100];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically manage a linked list and an array of NFAPI_CRC_INDICATION_PDU_T structures
void* nfapi_crc_indication_pdu_allocator(int n) {
    // Initialize variables
    int i, j;
    void* ptr = NULL;
    NFAPI_CRC_INDICATION_PDU_T* data_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data_array) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize linked list
    struct node {
        NFAPI_CRC_INDICATION_PDU_T data;
        struct node* next;
    };
    struct node* head = (struct node*)malloc(sizeof(struct node));
    if (!head) {
        printf("Error: Memory allocation failed.\n");
        free(data_array);
        return NULL;
    }
    head->next = NULL;

    // Create array of NFAPI_CRC_INDICATION_PDU_T structures and add to linked list
    for (i = 0; i < n; i++) {
        data_array[i].RNTI = rand() % 100 + 1; // Randomly set RNTI
        strcpy(data_array[i].RX_UE_INFORMATION_TAG, "Random UE Information Tag"); // Initialize RX_UE_INFORMATION_TAG
        data_array[i].CRCFLAG = (rand() % 2 == 0) ? 0 : 1; // Randomly set CRCFLAG

        struct node* new_node = (struct node*)malloc(sizeof(struct node));
        if (!new_node) {
            printf("Error: Memory allocation failed.\n");
            for (j = i - 1; j >= 0; j--) {
                free(&data_array[j]);
            }
            free(head);
            free(data_array);
            return NULL;
        }

        new_node->data = data_array[i];
        new_node->next = head->next;
        head->next = new_node;
    }

    // Periodically clean up unused nodes in the linked list
    for (i = 0; i < n; i++) {
        if (head->next == NULL) break;

        struct node* temp = head->next;
        head->next = temp->next;
        free(temp);
    }

    // Return pointer to dynamically allocated memory
    return data_array;
}

